  2758: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「アッラーゆえにハッジを行い、そこにおいて淫らな言動や罪深い行いを犯さなかった者は、母親がその者を生んだ日（のような無垢な状態）に戻るであろう。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）は言った：私は預言者（アッラーからの祝福と平安あれ）が、こう言うのを聞いた： 「アッラーゆえにハッジを行い、そこにおいて淫らな言動や罪深い行いを犯さなかった者は、母親がその者を生んだ日（のような無垢な状態）に戻るであろう。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、「アッラーゆえにハッジを行い、淫らな言動や罪深い行いを犯さなかった者」について説明している。ここで言う「淫らな言動」とは、性交を始め、接吻や触れ合う行為といった性行為のことであり、その他にも卑猥な言葉も含む。「罪深い行い」とは罪や悪行のことである。 また、イフラームの禁忌行為を破ることも、「罪深い行い」の一部である。以上のことを行うことなくアッラーゆえにハッジした者は、赤ん坊が罪から無垢な状態で生まれたように、罪を赦された状態に戻ることになる。",
    "hints": [
          "罪深い行いはあらゆる状況下において禁じられているが、ハッジにおいてはハッジの宗教儀礼に対する尊重により、その禁止令がより強調される。",
          "人はそもそも罪から無垢な状態で生まれる。他人の罪を負うこともない。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  2941: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「最大の大罪をあなたたちに教えようか？",
    "hadeeth": "アブー・バクラ（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は３回、こう言った： 「最大の大罪をあなたたちに教えようか？」人びとは言った：「ええ、アッラーの使徒よ。」預言者（アッラーからの祝福と平安あれ）は言った：「アッラーに対してシルクを犯すこと。そして両親への親不孝である。」それまで寄りかかっていたが、座り直し、そして言った：「そして偽りの言葉である。」アブー・バクラ（アッラーのご満悦あれ）は言った：「もう口を閉じて下さったらよいのに、と私たちが言うまで、彼は繰り返しそう語り続けました。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は教友たちに、最大の大罪について伝え、これらの３つのことを述べた：\n\n１．アッラーに対するシルク：これはいかなる種類のものであったとしても、崇拝行為をアッラー以外のものに向けることであり、アッラーの神性、主性、美名と属性において、アッラー以外のものをアッラーに並べることである。\n\n２．両親への親不孝：言葉や行為による両親に対する害悪であり、彼らによいことをしないことである。\n\n３．偽りの言葉：噓の証言はその一部であり、つまり財産や尊厳の侵害などによって損害を与えることを意図した、あらゆる噓の言葉のことである。\n\n預言者（アッラーからの祝福と平安あれ）は嘘の言葉に対する警告を繰り返したが、それはその醜さと、社会への悪影響のためだった。教友たちはついに「もう口を閉じて下さったらよいのに」と言ったが、それは預言者の憤りを気遣い、忌避したためであった。",
    "hints": [
          "最大の罪はアッラーに対してシルクを犯すこと。アッラーはそれを最大の罪のうちの筆頭とされた。それはクルアーンの次のアーヤの中でも強調されている：「本当にアッラーは、かれと共に（何かが）並べられること（シルク）をお赦しになることはないが、それ以外のことは、御心に適う者にお赦しになる。」",
          "両親の権利の大きさ。それがゆえに、アッラーの権利と並置されている。",
