    "explanation": "預言者（アッラーからの祝福と平安あれ）は大罪について説明している。大罪とは、現世と来世における厳しい罰を警告されているようなもののことである。\n\n最初に挙げられているのが、アッラーに対するシルクである。それはイバーダ（崇拝行為）をアッラー以外のものに向けることであり、アッラーだけが専有する神性、主性、美名と属性といったことにおいて、アッラーとアッラー以外のものを並べることである。\n\n２番目が親不孝である。親不孝とは、両親の害になるようなあらゆる言動のことであり、両親への親切の放棄のことである。\n\n３番目が殺人である。つまり不正や侵害による、不当な殺害のことである。\n\n４番目が嘘の誓いである。それは知っていながら嘘の誓いをすることである。原語では「アル＝ヤミーン・アル＝ガムース」（浸漬の誓い）だが、それはそのような誓いを行う者を罪や地獄の中に浸漬させてしまうためである。",
