  3272: {
    "category_id": 3,
    "category": "神学",
    "title": "ムハンマドの魂がその御手に委ねられているお方にかけて。このウンマ（共同体）の内のユダヤ教徒でもキリスト教徒でも、私について耳にし、それから私が携えて来たもの（啓示）を信仰しない状態のまま死んだ者は、例外なく地獄の徒となる。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの平安と祝福あれ）が、このように語ったと伝えている：「ムハンマドの魂がその御手に委ねられているお方にかけて。このウンマ（共同体）の内のユダヤ教徒でもキリスト教徒でも、私について耳にし、それから私が携えて来たもの（啓示）を信仰しない状態のまま死んだ者は、例外なく地獄の徒となる。」",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）はアッラーに誓って、こう言った：\n「このウンマ（共同体）」とは、預言者の存命していた時期、およびそれ以後、復活の日までに至る、全ての者たちのこと。\n「ユダヤ教徒でもキリスト教徒でも、私について耳にし・・・」とは、ユダヤ教徒、キリスト教徒、またはそれ以外の者たちで、預言者（彼にアッラーからの平安と祝福あれ）の伝道が届いた者たちのこと。それらの者たちの内、それを信仰しない状態のまま死んだ者は、例外なく地獄の徒となり、永遠にその中に留まることになる。\nここで特にユダヤ教徒とキリスト教徒が言及されているのは、それ以外の者たちに対する喚起の意味である。ユダヤ教徒もキリスト教徒も啓典を授かっているが、啓典の民がそのような状況であれば、啓典を授かっていない者たちについては尚更であり、預言者ムハンマド（彼にアッラーからの平安と祝福あれ）の宗教を信じ従うことが求められる。",
    "hints": [
          "預言者ムハンマド（彼にアッラーからの平安と祝福あれ）について耳にすることもなく、イスラームの伝道が到達しなかった者は、赦される。",
          "預言者ムハンマド（彼にアッラーからの平安と祝福あれ）に従う義務と、彼がもたらした教えによって、全ての教えが撤回されたこと。預言者ムハンマド（彼にアッラーからの平安と祝福あれ）を否定する者は、他の預言者たち（彼ら全員にアッラーの祝福あれ）を信仰していても、その信仰が益することはない。",
          "死が訪れる前であれば、イスラームを受け入れることで救われる。たとえ重病にあったとしても、死を眼前にしない限りは間に合うのである。",
          "預言者ムハンマド（彼にアッラーからの平安と祝福あれ）がもたらした教えの内、確実な文言により確定し、イスラーム共同体の学者らが合意した教えを一部でも否定する者は、不信仰に陥ったと見なされる。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  3279: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「口ひげを短く切り、あごひげを伸ばすのだ。」",
    "hadeeth": "イブン・ウマル（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は言った： 「口ひげを短く切り、あごひげを伸ばすのだ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は口ひげを短くし、放ったらかしにするのではなく、短く切ることを命じた。\n\nそれに反して、あごひげはそのままにしておき、長くしておくことを命じた。",
    "hints": [
          "あごひげを剃ることの禁止。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  3313: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "私のこのウドゥーのようにウドゥーをし、それから雑念なく２ラクアの礼拝をする者は、アッラーによってそれ以前の罪をゆるされよう。",
    "hadeeth": "ウスマーンの解放奴隷フムラーンによれば、彼はウスマーン（アッラーのご満悦あれ）が水入れを持って来させ、容器から両手に水を注ぐのを見た。彼は両手を３回洗うと、右手を水入れに入れ、うがいをし、鼻に水を入れてはそれを噴き出した。それから顔を３回、両腕を肘まで３回洗い、頭を撫で、そして両足を３回洗った。それから言った：「私は、私がウドゥーしたように預言者（アッラーからの祝福と平安あれ）がウドゥーするのを見た。彼は言ったのだ：“私のこのウドゥーのようにウドゥーをし、それから雑念なく２ラクアの礼拝をする者は、アッラーによってそれ以前の罪をゆるされよう。”」",
    "explanation": "ウスマーン（アッラーのご満悦あれ）は、預言者（アッラーからの祝福と平安あれ）のウドゥーのやり方を明確に説明するために、身をもってそれを教示した。まず容器を持って来させ、両手に水を注ぎ、両手を３回洗った。それから右手を水入れに入れ、水をすくって口に入れ、また出した。そして鼻に水を吸い込んでは、噴き出した。それから顔を３回、両腕を肘まで３回洗い、頭を濡れた手で１度だけ撫でた。そして両足を３回洗った。\n\nウスマーン（アッラーのご満悦あれ）はウドゥーを終えると、預言者（アッラーからの祝福と平安あれ）がそのようにウドゥーをしたのだということを伝えた。また彼が、そのようにウドゥーをし、それからアッラーの御前で気持ちをこめて謹んで２ラクアの礼拝をする者は、その完全なウドゥーと真摯な礼拝ゆえに、アッラーによってそれ以前の罪をゆるされるのだ、という吉報を伝えた。",
    "hints": [
          "たとえ眠りから目覚めたのではなかったとしても、ウドゥーを始める際、水の容器に手を入れる前に両手を洗うことの勧め。もし夜の眠りから目覚めたのであれば、両手を洗うことは義務となる。",
          "教師は学ぶ者にとってなるべく分かりやすく、知識がしっかりと身につくような手段を用いるべきである。その一つが、身をもって教えることである。",
          "礼拝する者は、現世の諸事への執着心を遠ざけなければならない。気持ちを込めることによって礼拝は完全なものとなり、余計な考え事はそれを損ねることになる。ゆえに礼拝の際は、余計なことを考えることから、自分自身を遠ざけるよう努力しなければならない。",
          "ウドゥーで右手を用いることの勧め。",
          "うがい、鼻に水を吸い込むこと、鼻から水を噴き出すこと、という順番を守ること。",
          "顔、両手、両足を３回洗うことの勧め。最低１回洗うことが義務となる。",
          "過去の罪に対するアッラーの赦しは、２つのことが揃うことで実現する：つまり、伝承の中で表されている形でウドゥーと２ラクアの礼拝をすることである。",
          "ウドゥーで清める身体箇所には、それぞれ範囲がある。顔の範囲は、縦は額の髪の生え際からあごひげとあごの先まで、横は耳から耳まで。腕の範囲は指先から肘まで。頭の範囲は額の髪の生え際から首の最上部まで。耳を撫でることは、頭部を撫でることに含まれる。足の範囲は足のくるぶし以下の全てである。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  3330: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーがユダヤ教徒とキリスト教徒を呪われるよう。彼らは、彼らの預言者たちの墓をマスジドにしたのだ。",
    "hadeeth": "アーイシャとイブン・アッバース（アッラーのご満悦あれ）は言った： アッラーの使徒（アッラーからの祝福と平安あれ）は、自身に死が近づいた時、自分の顔に布をかけた。そして苦しくなると、それを外してこう言った：「アッラーがユダヤ教徒とキリスト教徒を呪われるよう。彼らは、彼らの預言者たちの墓をマスジドにしたのだ。」彼らが行ったことに対して注意を喚起しているのだった。",
    "explanation": "アーイシャとイブン・アッバース（アッラーのご満悦あれ）は、このように伝えている：預言者（アッラーからの祝福と平安あれ）は、自身に死期が訪れた時、自分の顔に布の一片をかけたが、死の苦しみで苦しくなると、それを顔から外し、大変な状況のなかでこう言った。「アッラーがユダヤ教徒とキリスト教徒を呪われるよう。」つまり、彼らがアッラーの慈悲から遠ざけられるよう、という意味である。そしてその原因は、彼らが彼らの預言者たちの墓をマスジドとしたためである。そのことが非常に重要でなかったならば、そのような大変な状況のなかでそのようなことを言わなかったであろう。預言者（アッラーからの祝福と平安あれ）は自らの共同体に、同様のことを行うことを禁じた。それは彼らの行いであり、アッラーに対するシルクにつながるものだからである。",
    "hints": [
          "預言者や正しい者たちの墓を、アッラーのために礼拝するためのマスジドとすることの禁止。なぜなら、それはシルクにつながるためである。",
          "タウヒードに対するアッラーの使徒（アッラーからの祝福と平安あれ）の関心の高さと、墓が偉大視されることの恐れ。墓の偉大視はシルクにつながる。",
          "墓をマスジドにしてしまうことに関し、ユダヤ教徒とキリスト教徒を呪うことの合法性。",
          "墓に建物を建てるのは、ユダヤ教徒とキリスト教徒の習いである。この伝承の中には、彼らと同様のことをすることの禁止が含まれる。",
          "墓で礼拝すること、墓に向かって礼拝することもまた、墓をマスジドにすることの意味に含まれる。たとえそこにマスジドが建設されなかったとしても、である。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  3331: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「破滅をもたらす７つの物事を避けなさい。",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は、こう言った： 「破滅をもたらす７つの物事を避けなさい。」人々は言った：「アッラーの使徒よ、それは何ですか？」預言者は言った：「アッラーに対してシルクを犯すこと。魔法。権利もないのに、アッラーが侵さざるべきものとした人間を殺害すること。利子を取ること。孤児の財産を貪ること。戦いの日の逃亡。無頓着で貞節な\n信仰者女性を姦淫で名誉毀損すること。」",
    "explanation": "アッラーの使徒（アッラーからの祝福と平安あれ）は、破滅をもたらす７つの罪から遠ざかるよう、その共同体に命じている。そしてそれらが何か尋ねられ、このように答えている：\n\n１．アッラーに対してシルクを犯すこと。それはどのような形かを問わず、アッラーに同等のものを認めたり、アッラー以外のものに崇拝行為を向けたりすることである。シルクが冒頭に来ているのは、それが最大の罪であるため。\n\n２．魔法。これは、紐の結び目、まじない、薬、煙などを利用して、魔法をかける対象に死、病、夫婦間の分断などをもたらす行為のことである。これはシャイターンの所為であり、多くの場合シルクや、邪悪な心を持った存在に何らかの捧げ物をしたりすることを介して達成される。\n\n３．侵害を禁じられた人間の命を奪うこと。ただし、イスラーム法によって正当化され、統治者が実行するものは別である。\n\n４．利子をむさぼったり、あらゆる形においてそこから利益をえたりすること。\n\n５．成人前に父親を失った年少者の財産に、不当に手をつけること。\n\n６．不信仰者らとの戦いにおいて逃亡すること。\n\n７．貞節な自由民女性を姦淫で名誉毀損すること。男性の場合でも同様。",
    "hints": [
          "大罪は７つだけではないが、ここではその罪の大きさと危険性ゆえにこれらのものが取り上げられている。",
          "報復刑、背教、既婚者の姦通など正当な理由があり、イスラーム法上の統治者がそれを実行するのであれば、生命の侵害とはならない。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  3336: {
    "category_id": 3,
    "category": "神学",
    "title": "「アッラーよ、私の墓を偶像とはしないでください",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は、こう言った： 「アッラーよ、私の墓を偶像とはしないでください。自分たちの預言者の墓をマスジドとしてしまった民に、アッラーの呪いがありますよう。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はその主に対し、自分の墓が人々によって、自分を偉大視するがゆえに崇拝され、サジダされる偶像のようなものとはならないよう祈った。それから預言者（アッラーからの祝福と平安あれ）は、預言者たちの墓をマスジドとしてしまった者が、アッラーによってその慈悲から放逐されてしまったことを伝えた。なぜならば墓をマスジドとすることは、その崇拝やその信仰への足がかりとなってしまうからである。",
    "hints": [
          "預言者や清廉な者たちの墓においてイスラーム法の則を超えてしまえば、それらがアッラーを差し置いて崇拝されるものとなってしまうことにつながる。シルクへとつながる道には注意しなければならない。",
          "偉大視や崇拝ゆえに墓へと向かうことは非合法である。墓に埋葬された者が、いかにアッラーに近しい者だったとしてもである。",
          "墓にマスジドを建てることの禁止。",
          "マスジドがそこになかったとしても、墓でサラーすることの禁止。ただし、まだ行われていない葬儀のサラーをする場合は、 その限りではない。",
        ],
    "grade": "صحيح",
    "attribution": "رواه أحمد",
  },
  3339: {
    "category_id": 3,
    "category": "神学",
    "title": "まことに褒美の大きさは、試練の大きさによるものである。至高のアッラーは、ある民を愛する時、彼らを試練におかけになる。それに満足する者には満足があり、それを憎悪する者には憎悪があるのだ。",
    "hadeeth": "アナス・ブン・マーリク（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼はこう言った：「まことに褒美の大きさは、試練の大きさによるものである。至高のアッラーは、ある民を愛する時、彼らを試練におかけになる。それに満足する者には満足があり、それを憎悪する者には憎悪があるのだ。」",
    "explanation": "このハディースの中で預言者（彼にアッラーからの祝福と平安あれ）は、以下のことを伝えている：信仰者は、生命や財産などにおいて災難に出遭うが、それに忍耐すればアッラーは褒美を授けてくれること。災難が大きければ大きいほど、その危険度が高ければ高いほど、アッラーからの褒美も大きくなること。災難は信仰者に対するアッラーの愛の表れであり、アッラーの定めは必ず実現すること。そしてそれに忍耐し、満足して受け入れるのであれば、アッラーはそれゆえにその者に褒美を授け、満足されること。しかしアッラーの定めを嫌うのであれば、アッラーはそれゆえにその者をお嫌いになり、罰でもって報われるということ。",
    "hints": [
          "災難は、それに対しての義務を放棄したり、禁止事項を行ったりしない限り、それを被った者の罪滅ぼしとなる。義務の放棄の例としては、忍耐しないこと、禁止事項としては、災難ゆえに衣服を裂いたり自分の頬を叩いたりすることである。",
          "アッラーには、かれに相応しい形において、愛という属性があることの確証。",
          "信仰者の試練は、信仰のあかしの一つであること。",
          "アッラーには、かれに相応しい形において、満足や憎悪という属性があることの確証。",
          "アッラーの定めに満足することの奨励。",
          "アッラーの定めを嫌悪することの禁止。",
          "災難に対して忍耐することの勧め。",
          "人は時に、自分にとってよいことを嫌ってしまうこともあること。",
          "アッラーの御業における英知の確証。",
          "報いは、その行いと同種のもの。",
        ],
    "grade": "真正",
    "attribution": "イブン・マージャの伝承 - アッ＝ティルミズィーの伝承",
  },
  3342: {
    "category_id": 3,
    "category": "神学",
    "title": "われは最もシルクを必要としないものである。われ以外のものにシルクを犯しつつ何らかの行為を行う者は、われがその行いと彼のシルクを放棄しよう。",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「祝福にあふれた至高なるアッラーはこう仰せられた：われは最もシルクを必要としないものである。われ以外のものにシルクを犯しつつ何らかの行為を行う者は、われがその行いと彼のシルクを放棄しよう。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、祝福にあふれた至高なるアッラーがこう仰せられたと伝えている：「かれは最もシルクを必要としないものであり、何も必要とはしない十分なお方である。もし人間が何らかの服従行為を行い、そこにアッラー以外のものを並べてシルクを犯すのであれば、アッラーはその者を放棄し、お受け入れにならない。そしてその行いを、その者へと突き返されるのである。」 ゆえに行為は、アッラーのために真摯に行わなければならない。アッラーはかれのお顔を真摯に求めて行われたものしか、お受け入れにはならないからである。",
    "hints": [
          "あらゆる形のシルクに対する警告。それは行いが受け入れられることを阻んでしまう。",
          "アッラーが何ものも必要とはしない十分なお方であり、偉大なことを実感すること。それは行為における真摯さの助力となる。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  3347: {
    "category_id": 3,
    "category": "神学",
    "title": "私に、あなた方の内からハリール（親愛な者）があるなどということから、私はアッラーに潔白を求める。なぜならアッラーは、イブラーヒームをかれのハリールにしたのと同様に、私をハリールとしたからである。",
    "hadeeth": "ジュンダブ（アッラーのご満悦あれ）は言った： 私は、預言者（彼にアッラーからの祝福と平安あれ）が亡くなる５日前に、こう言うのを聞いた：「私に、あなた方の内からハリール（親愛な者）があるなどということから、私はアッラーに潔白を求める。なぜならアッラーは、イブラーヒームをかれのハリールにしたのと同様に、私をハリールとしたからである。 そして、もし私が私の共同体の内からハリールを選ぶとしたら、きっとアブー・バクルをハリールとして選んだだろう。かつてあなた方以前の人々は、彼らの預言者や正しい者たちの墓をマスジドとした。墓をマスジドとしてはならない。私はそのことをあなた方に禁じる。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、アッラーのもとにおける自らの地位について、ちょうどイブラーヒーム（彼に平安あれ）がそうだったように、アッラーの愛における最高の位にまで達したことを語った。それゆえに、アッラー以外には自分にハリール（親愛な者）などない、と言ったのであるである。というのも彼の心はアッラーに対する愛情、かれを偉大視する気持ち、かれについての知識で満ち溢れており、アッラー以外のいかなる者に対しても向けられてはいないからである。 そしてもし彼にハリールがあったとしたら、それはきっとアブー・バクル（アッラーのご満悦あれ） だっただろう。 ユダヤ教徒やキリスト教徒は、彼らの預言者や正しい者たちの墓をアッラーをよそにして崇拝する神々とし、墓の上に建築してマスジドや崇拝の場としてしまったが、そのように愛情の定められた一線を越えることの警告。預言者（彼にアッラーからの祝福と平安あれ）は自分の共同体に対し、彼らのようなことをしないようにと禁止した。",
    "hints": [
          "アブー・バクル（アッラーのご満悦あれ）の徳。彼は最良の教友であり、アッラーの使徒（アッラーからの祝福と平安あれ）の逝去後に彼の後継者となるにあたって、最優先される人物である。",
          "墓の上にマスジドを建設することは、過去の民が行っていた悪事の一つである。",
          "墓を、そこで礼拝したり、そこに向かって礼拝したり、その上にマスジドやドームを建てたりして、崇拝のための場所とすることの禁止。それはそうすることによって、シルクに陥ることへの注意のためである。",
          "正しい者たちに関することで行き過ぎてしまうことに対する警告。それはシルクに陥ってしまう恐れが高いためである。",
          "預言者（彼にアッラーからの祝福と平安あれ）が警告したことの危険性。彼は他界の5日前にこのことを強調したのである。",
