    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  3350: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「あなた方の家を墓にはするな。私の墓をイードにはするな。そして私のために祈願するのだ。あなた方の祈願は、あなた方がいる場所からでも私に届くのだから。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「あなた方の家を墓にはするな。私の墓をイードにはするな。そして私のために祈願するのだ。あなた方の祈願は、あなた方がいる場所からでも私に届くのだから。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、家で礼拝が行われなくなり、その結果、礼拝が行われない墓場のような状態になってしまうことをを禁じた。 また、それがシルクへの道となってしまうため、彼の墓を繰り返し訪問したり、そこで集まりの場を定期的に持ったりすることを禁じた。 そして地上のどこにあろうと、彼に祝福と平安を祈ることを命じた。なぜならそれは遠い場所でも近い場所でも等しく彼に届くためであり、彼の墓を頻繁に訪れる必要はないからである。",
