    "category": "神学",
    "title": "まことに至高のアッラーは、自恃（じじ）の念をお持ちである。そして至高のアッラーの自恃とは、アッラーが禁じた物事を人が侵すことである。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの平安と祝福あれ）が、このように語ったと伝えている：「まことに至高のアッラーは、自恃（じじ）の念をお持ちである。そして至高のアッラーの自恃とは、アッラーが禁じた物事を人が侵すことである。」",
    "explanation": "このハディースは、アッラーが、かれの禁じた物事を侵されることに関して自恃の念をお持ちであり、かれが決めた規定の違反をお嫌いになるということを説明している。アッラーが禁じた物事としては、姦淫がある。姦淫は醜悪かつ低劣な行為であり、アッラーはしもべに対してそれ自体だけでなく、そこにつながる物事をも禁じた。しもべが姦淫を犯せば、アッラーはそれ以外の禁止事項が侵されるよりも、激しい怒りでもってお怒りになる。\nまた、窃盗や飲酒、それ以外の禁止事項を侵すことも同様に、アッラーの自恃の念を侵害する。ただし、それらはその害悪の程度によって、アッラーのお怒りの程度も違ってくる。",
