    "category": "神学",
    "title": "「アッラー以外のものにおいて誓った者は、不信仰に陥ったか、またはシルクを犯したのだ。」",
    "hadeeth": "イブン・ウマル（アッラーのご満悦あれ）は、ある男がこう言うのを聞いた：「いや、カァバ神殿にかけて。」それでイブン・ウマルは言った：「アッラー以外にかけて誓ってはならない。私はアッラーの使徒（アッラーからの祝福と平安あれ）が、このように言うのを聞いたのだ： 「アッラー以外のものにおいて誓った者は、不信仰に陥ったか、またはシルクを犯したのだ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、アッラーとその美名、属性以外のものにおいて誓った者は、アッラーに対する不信仰に陥ったか、またはシルクを犯したことになる、と語っている。これは、誓いというものには、そこにおいて誓った対象を偉大視する意味があるためである。しかし偉大さは、アッラーのみに属する。ゆえにアッラーとその美名、属性以外のものにおいて誓ってはならない。 そしてこの種類の誓いは、小シルクと見なされる。ただし、そのような誓いをする者が、それにおいて誓った対象を、アッラーを偉大視するのと同等に、またはそれ以上に偉大視した場合、それは大シルクとなる。",
