    "category": "神学",
    "title": "「偽信者たちにとって最も難儀に感じられるのが、イシャーとファジュルの礼拝である。もしその２つの中にあるものを知ったならば、彼らは這いつくばったとしても、そこにやって来ただろう",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「偽信者たちにとって最も難儀に感じられるのが、イシャーとファジュルの礼拝である。もしその２つの中にあるものを知ったならば、彼らは這いつくばったとしても、そこにやって来ただろう。本当に私は礼拝を命じて開始させ、誰かに命じて人々の礼拝の先導をさせておき、私はといえば薪を携えた者たちを従えて外に出て行き、礼拝をしない者たちの家に火をつけて燃やしてしまおうと思ったほどなのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は偽信者と、彼らが礼拝－特にイシャーとファジュルの礼拝－を面倒くさく感じている様子について語っている。もしそれらの礼拝をムスリムたちと共に行うことの報奨のほどについて知ったならば、彼らはちょうど幼児がそうするように、這ってでもそこにやって来たのである。\n\n預言者（アッラーからの祝福と平安あれ）は礼拝を命じて開始させ、誰かに命じて自分の代わりに人々の礼拝の先導をさせておき、薪を携えた者たちを従えて外に出て行き、集団礼拝をしない者たちの家に火をつけて燃やしてしまおうと決意したほどだった。それは、彼らが犯している罪の大きさのためである。しかし預言者（アッラーからの祝福と平安あれ）は、そうはしなかった。そこには女性や子供たちもおり、彼らには罪がないためである。",
