    "hadeeth": "アブドッラー・ブン・マスウード（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの祝福と平安あれ）からの言葉として、こう語った：「まことに最悪の者たちとは、墓をマスジドとしている状態で、復活の日を生きたまま迎えた者たちである。」",
