    "hadeeth": "マフムード・ブン・ラビード（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの祝福と平安あれ）からの言葉として、こう語った：「私があなた方に関して最も恐れることは、小さなシルクである。」彼はそれについて尋ねられると、こう答えた：「見せかけの行為だ。」",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）はこのハディースの中で、彼が私たちに関して恐れており、そして私たちに関して最も恐れていることが「小さなシルク」であると語っている。このことは、イスラーム共同体に対する預言者（彼にアッラーからの平安と祝福あれ）の思いやりと慈悲の念、その正しい状態の維持についての彼の熱心さを示している。そして見せかけの行為である「小さなシルク」の原因の根強さ、その動機の多様性、それがムスリムたちの知らない内に入り込んできてしまい、彼らを害する可能性があることを知っているからこそ、このような警告を放ったのである。",
