          "シルクは大シルクと小シルクに分類される。大シルクは、アッラーのみが有する特性において、アッラー以外のものを並べることである。小シルクは、イスラームのテクストにおいてシルクであるという記述はあるものの、大シルクの域にまでは達していないものである。両者の違いは、以下の通りである：",
