  3384: {
    "category_id": 3,
    "category": "神学",
    "title": "彼らはアッラーが合法としたものを禁じ、それであなた方もそれを禁じているのではないか？また、彼らはアッラーが禁じたものを合法とし、それであなた方もそれを合法としているのではないか？",
    "hadeeth": "アディー・ブン・ハーティム（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの祝福と平安あれ）が『彼ら（啓典の民）はアッラーを差しおいて、彼らの学者や修道僧たちを、彼らの主としたのだ。また、マルヤムの子マスィーフも（主とした） 。彼らは、唯一の神（アッラー）のみを崇拝することしか、命じられてはいなかったというのに。かれ以外に、（真に）崇拝すべきものなど存在しない。彼らがシルクを犯しているものから（無縁な）、アッラーに称えあれ。』（悔悟章３１）というクルアーンの一節を読むのを聞いた。彼（アディー）は言った：「私は彼に言った：『私たちは彼らを崇拝しているわけではありません。』預言者は言った：『彼らはアッラーが合法としたものを禁じ、それであなた方もそれを禁じているのではないか？また、彼らはアッラーが禁じたものを合法とし、それであなた方もそれを合法としているのではないか？』私は言った：『はい、そうです。』預言者は言った：『それこそが、彼らを崇拝することなのだ。』」",
    "explanation": "この偉大な教友は、預言者（彼にアッラーからの祝福と平安あれ）がクルアーンのこの一節を読誦した時、その意味に疑問を持った。読誦されたクルアーンは、ユダヤ教徒とキリスト教徒たちが、彼らの学者たちや崇拝行為に専念する者たちを彼らの神とした、というものだった。それらの者たちは、アッラーが定めたものではない教えを彼らに定め、彼らはそれに従っていたのだ。教友アディーは崇拝行為が、サジダ（平伏す形の祈り）のような行為に限定されるものと考えていた。そこで預言者（彼にアッラーからの祝福と平安あれ）は彼に、アッラーとその使徒（彼にアッラーからの祝福と平安あれ）が決めたことに反して、学者や修道僧たちがハラール（合法）なものをハラーム（禁止）とすること、ハラーム（禁止）なものをハラール（合法）とすることに従うのは、彼らへの崇拝行為に相当するのだ、ということを説明した。",
    "hints": [
          "アッラーの法規定の改ざんにおいて、学者、またはそれ以外の被造物に従うことは大シルクである。ただし従っている者が、それがアッラーの法規定に反していることを知っている限りにおいて、である。",
          "何かをハラール（合法）としたりハラーム（禁止）としたりするのは、至高のアッラーのみに属する権利である。",
          "シルクの一種、つまり「服従によるシルク」についての説明。",
          "無知な者には教えるということ。",
          "崇拝行為（イバーダ）とは：アッラーが愛し、お喜びになる、あらゆる外面的・内面的言動を包括する、広範な意味を持つものである。",
          "ハディースで取り上げられているような学者や修道僧らの迷妄についての説明。",
          "ユダヤ教徒とキリスト教徒のシルクの確証。",
          "使徒たちの宗教の起源は一つであり、それがタウヒード（唯一神信仰）であるということ。",
          "創造主への反抗を伴う被造物への服従は、崇拝行為であること。",
          "規定が不明瞭であることについて、知識ある者に尋ねることの義務性。",
          "知識に対するサハーバの熱心さ。",
        ],
    "grade": "真正",
    "attribution": "アッ＝ティルミズィーの伝承",
  },
  3390: {
    "category_id": 3,
    "category": "神学",
    "title": "あなたは啓典の民のもとへと赴く。だから彼らのものに行ったら、彼らを”アッラー以外に崇拝すべきものはなく、ムハンマドはアッラーの使徒である”という証言へと招くのだ",
    "hadeeth": "イブン・アッバース（アッラーのご満悦あれ）は言った： アッラーの使徒（アッラーからの祝福と平安あれ）はムアーズ・ブン・ジャバルをイエメンに派遣した際、彼にこう言った：「\nあなたは啓典の民のもとへと赴く。だから彼らのものに行ったら、彼らを”アッラー以外に崇拝すべきものはなく、ムハンマドはアッラーの使徒である”という証言へと招くのだ。そしてもし彼らがそこにおいてあなたに従ったのであれば、アッラーが彼らに、毎昼夜の５回の礼拝を義務付けたということを、彼らに伝えよ。そしてもし彼らがそこにおいてあなたに従ったのであれば、アッラーが彼らに、彼らのうちの豊かな者たちから取られ、彼らのうちの貧しい者たちへと返される施しを義務付けたということを、彼らに伝えよ。そしてもし彼らがそこにおいてあなたに従ったのであれば、彼らの財産の高価なものに手をつけるのではない。また、不正を被っている者の祈りを恐れよ。その者とアッラーの間を阻む障壁はないのだから。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はムアーズ・ブン・ジャバル（アッラーのお喜びあれ）を、アッラーへと招く者、教師としてイエメン地方に派遣した際、以下のように彼に説明した：彼はキリスト教徒の人々と対面することになるので、そのための準備が出来ていなければならない。彼らへの布教に関しては、より重要性の高いものから始めて行かなければならない。 ゆえにまずは彼らを、信仰を正すことへと招くのだ。つまり、”アッラー以外に崇拝すべきものはなく、ムハンマドはアッラーの使徒である”という証言のことである。 というのも、それによって彼らはイスラームに入ることになるからである。もし彼らがそこにおいて従ったのであれば、礼拝を行うことを命じるのだ。というのも、それはタウヒードの後に次ぐ偉大な義務だからである。 そしてもし彼らがそれを行うようになったのであれば、彼らのうちの豊かな者たちが、彼らのうちの貧しい者たちに対して喜捨を支払うことを命じるのだ。それから預言者はムアーズに、彼らの最も高価な財産を取ることについて、注意した。なぜなら義務として支払うのは平均的なものだからである。 それから彼に、不正を避けるよう命じた。それは不正を被った者が彼に対して悪いことを祈らないようにするためであり、そのような者の祈りが受け入れられるためなのだ。",
    "hints": [
          "「アッラー以外に崇拝すべきものはなし」という証言の意味は、アッラーのみを崇拝し、アッラー以外のものの崇拝を放棄することである。",
          "「ムハンマドはアッラーの使徒である」という証言の意味は、彼と彼がもたらしたものを信じ、彼が真実を語ったこと、彼が人類に対するアッラーからの最後の使徒であることを信じることである。",
          "学識ある者や、疑念を持っている者に対する話し方は、無知な者に対する話し方とは異なる。預言者がムアーズに、「あなたは啓典の民のもとへと赴く」と注意したのは、そういったわけである。",
          "疑念を投げかけてくる者たちによる疑念から無事であるため、ムスリムが自らの宗教に対して深い理解を持っていることの重要性。",
          "アッラーの使徒（アッラーからの祝福と平安あれ）が送られた後、それ以前の啓典の民の宗教が無効化されたということ。彼らはイスラームに入り、預言者ムハンマド（アッラーからの祝福と平安あれ）を信仰するまで、審判の日に救われる者たちとはならない。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  3402: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーの使徒（彼にアッラーからの祝福と平安あれ）は魔術による治療について尋ねられ、言った：「それはシャイターンの行いである。」",
    "hadeeth": "ジャービル（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は魔術による治療について尋ねられ、言った：「それはシャイターンの行いである。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、魔術をかけられた者を同じ魔術で治療するといったジャーヒリーヤ時代（イスラーム以前の無明時代）によるやり方で行うことを尋ねられ、それを「シャイターンの行い」あるいは「シャイターンを通して行うもの」とした。なぜなら、それは魔術の一種、シャイターンの利用であるためで、そのようなことはシルクであり、禁じられるからである。\n魔術の治療として合法なのは、ルクヤ（クルアーンの読誦や合法な祈願などによる治療法）や、魔術に用いられたものを見つけ、それをクルアーンの読誦や合法な薬品を用いて手でほどくことにより、解除することである。",
    "hints": [
          "禁じられている物事に陥らないよう、決まりがよく分からないことに関しては学者に質問すること。",
          "ジャーヒリーヤ時代のやり方で魔術の解除を行うことの禁止。魔術自体が不信仰な物事なので、魔術の解除を魔術でもって行うことは許されない。",
          "シャイターンの行いは全て禁じられる。",
