  },
  3406: {
    "category_id": 3,
    "category": "神学",
    "title": "「キリスト教徒がマルヤムの子の讃美において度を越したように、私のことを度を越して称えてはならない。私はかれ のしもべに過ぎないのだ。それゆえ（私のことを）こう言うがよい：アッラーのしもべ、アッラーの使徒、と。」",
    "hadeeth": "ウマル・ブン・アル＝ハッターブ（アッラーのご満悦あれ）は言った：私は預言者（アッラーからの祝福と平安あれ）が、こう言うのを聞いた： 「キリスト教徒がマルヤムの子の讃美において度を越したように、私のことを度を越して称えてはならない。私はかれ のしもべに過ぎないのだ。それゆえ（私のことを）こう言うがよい：アッラーのしもべ、アッラーの使徒、と。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はキリスト教徒がマルヤムの子イーサーに対してそうしたように、自分が過度に賛美されたり、アッラーが専有する属性や行為で描写されたり、不可知の領域を知っていると言われたり、アッラーと並べて祈願されたりすることを禁じた。 そして彼がアッラーのしもべの一人であることを説明し、私たちが彼のことを「アッラーのしもべ、アッラーの使徒」と言うよう命じた。",
    "hints": [
          "イスラームの決まりを超えて過度に賛美したり偉大視したりすることに対する警告。なぜならそれはシルクの原因となるからである。",
          "預言者（アッラーからの祝福と平安あれ）が警告したことは、既にこの共同体に起こっている。あるグループはアッラーの使徒（アッラーからの祝福と平安あれ）に対して、別のグループはその一族に対して、また別のグループはワリー(宗教的に特別な徳がある者)たちに対して行き過ぎたことをし、その結果シルクに陥ったのである。",
          "アッラーの使徒（アッラーからの祝福と平安あれ）は自らをアッラーの使徒と描写した。それは彼がアッラーを主とするしもべであり、アッラーが専有するいかなる特徴も自分に帰させることは許されない、ということを明らかにするためであった。",
          "アッラーの使徒（アッラーからの祝福と平安あれ）が自らをアッラーの使徒と描写したのは、彼がアッラーから遣わされた使徒であり、彼が信仰され、踏襲されなければならないことを明らかにするためであった。",
        ],
    "grade": "صحيح",
    "attribution": "رواه البخاري",
  },
  3414: {
    "category_id": 3,
    "category": "神学",
    "title": "審判の日、私の執り成しにおいて最も幸運な者は“ラー・イラーハ・イッラッラーと心から、または精神から純粋に唱えた者である。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）は、言った： アッラーの使徒（アッラーからの祝福と平安あれ）に、こう言われた:「アッラーの使徒よ、審判の日、あなたの執り成しにおいて最も幸運な者は誰ですか？」アッラーの使徒（アッラーからの祝福と平安あれ）は、言った:「アブー・フライラよ、あなたが誰よりも先にこの話について尋ねるだろうと思っていた。私は話に対するあなたの熱心さを見出していたのだから。審判の日、私の執り成しにおいて最も幸運な者は“ラー・イラーハ・イッラッラーと心から、または精神から純粋に唱えた者である。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、「審判の日、彼の執り成しにおいて最も幸運な者は“ラー・イラーハ・イッラッラーと心から純粋に唱えた者である」と言った。つまりそれは、アッラー以外に崇拝すべきいかなるものもなく、アッラーはシルクや見せかけを意識した行いから無縁であるべきだという意味である。",
    "hints": [
          "来世における預言者（アッラーからの祝福と平安あれ）の執り成しが存在し、それはアッラーだけを崇拝した者にしか与えられないということの確証。",
          "預言者（アッラーからの祝福と平安あれ）の執り成しとは、本来地獄行きだったはずのタウヒードの徒がそこに入らないようにし、またそこに入ってしまったタウヒードの徒がそこから出られるよう、アッラーに仲介することである。",
          "アッラーに対して真摯なタウヒードの言葉の徳と、その偉大なる効果。",
          "タウヒードの言葉の実現はその意味に関する知識と、それが要求することの実践による。",
          "アブー・フライラ(アッラーのご満悦あれ)の徳と、知識への熱心さ。",
