    "attribution": "رواه البخاري",
  },
  3416: {
    "category_id": 3,
    "category": "神学",
    "title": "「ティヤラゆえに、何らかの必要な物事を行うことを止めてしまう者は、シルクを犯しているのである。」人々は言った：「その贖罪は何ですか？」彼は言った：「『アッラーフンマ・ラー・ タイラ・イッラー・タイルカ。ワ・ラー・ハイラ・イッラー・ハイルカ。ワ・ラー・イラーハ・ガイルカ』と言うことである。」",
    "hadeeth": "アブドッラー・ブン・アムル・ブン・アル＝アース（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの祝福と平安あれ）は言った：「ティヤラ（鳥その他の被造物と吉兆を結びつける迷信）ゆえに、何らかの必要な物事を行うことを止めてしまう者は、シルクを犯しているのである。」人々は言った：「その贖罪は何ですか？」彼は言った：「『アッラーフンマ・ラー・ タイラ・イッラー・タイルカ。ワ・ラー・ハイラ・イッラー・ハイルカ。ワ・ラー・イラーハ・ガイルカ（アッラーよ、あなたを差し置いて、吉凶の原因となるようなものはありません。あなたの善の他に、善はありません。あなた以外に真に崇拝すべきものは、ありません。）』と言うことである。」",
    "explanation": "アッラーの使徒（彼にアッラーからの祝福と平安あれ）はこのハディースの中で、こう言っている：何かを不吉に感じることゆえに、決心したことの実行を止めてしまう者は、一種のシルクを犯したのである、と。サハーバがその大きな罪の贖罪について尋ねると、彼はハディースの中にある貴い言葉を、彼らに教示した。その言葉の中には、アッラーに物事を委ね、アッラー以外の何ものにも力などは備わってはいないことへの示唆が含まれている。",
    "hints": [
          "何かを不吉に感じることゆえに、物事の実行を止めてしまう者は、シルクを犯しているということ。",
          "シルクを犯してしまった者の悔悟は受け入れられること。",
          "ティヤラを行ってしまった者が言うべき言葉の教示。",
          "善も悪も至高のアッラーによって定められたものである、ということ。",
        ],
    "grade": "真正",
    "attribution": "アハマドの伝承",
  },
  3417: {
    "category_id": 3,
    "category": "神学",
    "title": "「いかなる共同者もいない唯一のアッラー以外に崇拝すべきものはなく、ムハンマドはアッラーのしもべかつ使徒であること。イーサーはアッラーのしもべかつ使徒であり、アッラーがマルヤムへと吹き込まれた御言葉かつ魂であること。天国は真実であり、地獄は真実であること」を証言した者は、その行為に応じて、アッラーによって天国に入れられる。",
    "hadeeth": "ウバーダ・ブン・アッ＝サーミト（彼にアッラーのご満悦あれ）は、アッラーの使徒（彼にアッラーからの祝福と平安あれ）がこう言ったと語った：「『いかなる共同者もいない唯一のアッラー以外に崇拝すべきものはなく、ムハンマドはアッラーのしもべかつ使徒であること。イーサー（イエス）はアッラーのしもべかつ使徒であり、アッラーがマルヤム（マリア）へと吹き込まれた御言葉かつ魂であること。天国は真実であり、地獄は真実であること』を証言した者は、その行為に応じて、アッラーによって天国に入れられる。」",
    "explanation": "このハディースは、以下の状態でこの世を去る者が、その行いに応じて天国に入ることを伝えている：タウヒード（唯一神信仰）の言葉を唱え、その意味を知り、それが要求するものを実践すること。ムハンマド（彼にアッラーからの祝福と平安あれ）がアッラーの僕であり、使徒であることの証言。イーサーがアッラーの僕であり、使徒であり、「あれ」というアッラーの御言葉によってマルヤムの内に創造されたことを認め、彼の母マルヤムに対して敵対するユダヤ教徒たちの虚偽の訴えを否定すること。信仰者には天国があり、不信仰者には地獄があるという信仰。",
    "hints": [
          "２つの信仰証言が、宗教の根本であるということ。",
          "タウヒードの徳と、アッラーがそれによって罪をお赦し下さるということ。",
          "至高なるアッラーの徳と善の偉大さ。",
          "タウヒード信仰が、ユダヤ教徒、キリスト教徒、偶像崇拝者、無神論者などの他の集団とは一線を画すること。",
          "２つの信仰証言は、その意味の理解とそれが要求する物事の実践を伴わなければ、有効とはならない。",
          "アッラーはムハンマド（彼にアッラーからの祝福と平安あれ）を、僕とし、使徒とした。これは、彼に関して両極端に走る人々に対する反証である。",
          "預言者たちや正しい者たちにおいて、両極端に走ることの回避の義務。つまり、彼らの徳を否定もしなければ、過度の讃美もしてはならない。無知な者たち、迷った者たちがするように、彼らに崇拝行為を捧げたりしてはいけない。",
          "イーサーが僕であり使徒であることの確証。これは彼がアッラーの御子だと思い込んでいるキリスト教徒たちへの、反証である。",
          "イーサーが父親なしに、「あれ」という御言葉によってマルヤムの内に創造されたこと。これは、マルヤムを姦淫で訴えたユダヤ教徒たちへの反証である。",
          "罪深い者であっても、タウヒードの徒が地獄に永住することはないこと。",
          "至高のアッラーが言葉をお話になるという性質の確証。",
          "復活の確証。",
          "天国と地獄の確証。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  3418: {
    "category_id": 3,
    "category": "神学",
    "title": "「アッラーに何も並べることない状態でアッラーと拝謁した者は天国に入る。そしてかれに何か並べた状態で拝謁した者は、地獄に入る。」",
    "hadeeth": "ジャービル・ブン・アブドッラー（彼らにアッラーのご満悦あれ）は言った：「私は、アッラーの使徒（彼にアッラーからの祝福と平安あれ）がこう言うのを聞いた： 「アッラーに何も並べることない状態でアッラーと拝謁した者は天国に入る。そしてかれに何か並べた状態で拝謁した者は、地獄に入る。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、アッラーに何も並べることない状態で死んだ者の行き先は、たとえ彼が犯したある種の罪ゆえに罰されたとしても、天国だと言った。一方、アッラーに何か並べた状態で死んだ者は、地獄に永遠に入ることになると言った。",
    "hints": [
          "タウヒードの徳と、それが永遠の地獄からの救いの要因だということ。",
          "しもべにとっての天国と地獄の近さ。その間を分けるのは死のみである。",
          "その多少に関わらずシルクに注意することの必要性。なぜならその回避によってこそ、地獄からの救いがあるからである。",
          "考慮すべきは、行いの締めくくりである。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  3419: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーを差し置いて何らかの同位者に祈っている状態で死を迎えた者は、地獄行きである。",
    "hadeeth": "アブドッラー・ブン・マスウード（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「アッラーを差し置いて何らかの同位者に祈っている状態で死を迎えた者は、地獄行きである。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）はこのハディースの中で、私たちにこのように伝えている：アッラーが専有する何かをアッラー以外のものに与え、それに固執した状態で死を迎えた者は、地獄行きである、と。",
    "hints": [
          "シルクを犯している状態で死を迎えた者は、地獄に入る。それが大シルクであれば、地獄に永住することになる。小シルクであれば、アッラーはその者をお望みになるまで罰され、その後そこから解放して下さる。",
          "行いにおいて真に考慮すべきは、その締めくくり方である。",
