        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承",
  },
  3420: {
    "category_id": 3,
    "category": "神学",
    "title": "「厳しくし過ぎる者たちは、破滅しよう。",
    "hadeeth": "アブドッラー・ブン・マスウード（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った： 「厳しくし過ぎる者たちは、破滅しよう。」そう3回言った。",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、知識も正しい導きもなく、宗教や現世的諸事や言動において、預言者がもたらしたイスラームの法を超えて厳しくし過ぎる者たちの破滅と損失について語った。",
