  3421: {
    "category_id": 3,
    "category": "神学",
    "title": "「また、彼らは言いました。『あなた方は絶対に、あなた方の神々を捨て去ってはならないぞ。そして絶対に、ワッド、スワーウ、ヤグース、ヤウーク、ナスルを捨て去ってはならない。』」（ヌーフ章２３）イブン・アッバース（彼らにアッラーのご満悦あれ）はこのアッラーの御言葉について、こう語った：「これらは、ヌーフの民の正しい人々の名前である。」",
    "hadeeth": "イブン・アッバース（彼らにアッラーのご満悦あれ）は、アッラーの御言葉「また、彼らは（弱者たちに）言いました。『あなた方は絶対に、（アッラーだけを崇拝することで、）あなた方の神々を捨て去ってはならないぞ。そして絶対に、ワッド、スワーウ、ヤグース、ヤウーク、ナスルを捨て去ってはならない。』」（ヌーフ章２３）について、こう語った：「これらは、ヌーフの民の正しい人々の名前である。彼らが他界した時、シャイターンが彼らの民に、『彼ら（正しい人々）が座っていた居場所に像を立て、彼らの名前をつけよ』と吹き込んだのだ。そして彼らはそのようにしたが、それら（の像）は崇拝されることはなかった。しかし彼らが死んだ後、知識は忘れられ、それらが崇拝され出したのである。」",
    "explanation": "イブン・アッバース（彼らにアッラーのご満悦あれ）はこのアーヤ（節）を説明し、以下に示すことを語っている：アッラーが言及したこれらの神々は、預言者ヌーフ（彼に平安あれ）がその民にシルクを禁止した後に及んで、彼らが継続して崇拝することを互いに勧め合ったものだということ。これらの神々はもともと彼らの民の正しい者たちの名前だったが、シャイターンが彼らに吹き込んで極端な道に歩ませ、彼らの像を立てさせたということ。そしてその像がしまいには、アッラーをよそに崇拝される偶像となってしまったこと。",
    "hints": [
