    "category": "宣教と勧善懲悪",
    "title": "「あなた方に首長たちが任命され、あなた方は彼らを知り、否認するであろう。嫌った者は無実であり、否認した者は無事となる。しかし（非難されるべきは彼らに）満足し、追従した者なのだ。」彼らは言った：「アッラーの使徒よ、私たちは彼らと戦ってもよいでしょうか？」彼は言った：「いや。彼らがあなた方に対して（義務の）礼拝を遂行し続ける限りは。」",
    "hadeeth": "ウンム・サラマ・ヒンド・ビント・アビー・ウマイヤ・フザイファ（彼女にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼は言った：「あなた方に首長たちが任命され、あなた方は彼らを知り、否認するであろう。（彼らの内の罪深い者を）嫌った者は無実であり、否認した者は無事となる。しかし（非難されるべきは彼らに）満足し、追従した者なのだ。」彼らは言った：「アッラーの使徒よ、私たちは彼らと戦ってもよいでしょうか？」彼は言った：「いや。彼らがあなた方に対して（義務の）礼拝を遂行し続ける限りは。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、私たちに対して、統治者から首長が任命されることになること、そして私たちが彼らの行いの内、イスラームの教えに則ったものを知り、それに反したものについては、否認するであろうと述べている。しかし、彼らに対して正面から否認すれば暴虐を受ける怖れがあるため、そうすることが出来ず、心の中でそれを否認する者は、罪からは無実である。そして言葉や力でそれを抑えることが出来、そうするのであれば、その者は無事となる。しかし彼らの悪行に心で満足し、その行いに追従した者は、彼ら同様滅んでしまうだろう。\nそれから預言者（彼にアッラーからの祝福と平安あれ）は彼らに、「私たちは彼らと戦ってもよいでしょうか？」と聞かれ、こう答えている：「いや。彼らがあなた方に対して（義務の）礼拝を遂行し続ける限りは。」",
    "hints": [
