          "このハディースの中には、能力に応じて、悪事を戒めることの義務の根拠がある。また、礼拝を放棄していない限りは、統治者に反逆してはならない。（義務の）礼拝を遂行するかどうかは、イスラームと不信仰の分れ目となる。",
