    "category": "法学と法源学",
    "title": "アッラーは、もしあなた方が汚れた状態になったら、浄めをするまで、あなた方の礼拝を受け入れない。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「アッラーは、もしあなた方が汚れた状態になったら、浄めをするまで、あなた方の礼拝を受け入れない。」",
    "explanation": "アッラーは、礼拝を意図する者が、よい状態と美しい外観をまとわない限り、礼拝に入ってはならないことを示した。というのも礼拝は主と僕との間の緊密な関係であり、主との対話への道であるからである。ゆえにアッラーは礼拝のために、ウドゥー（小浄）と清浄な状態を命じたのであり、清浄な状態でなくしては礼拝は受け入れられないということを述べたのである。",
    "hints": [
          "礼拝というものの偉大さ。アッラーは清浄な状態でなくしては、礼拝をお受け入れにはならない。",
          "汚れた状態にある者の礼拝は、大浄と小浄の２つの汚れから清められない限り、受け入れられない。",
          "汚れた状態に陥ったら、ウドゥーによって得られた清浄な状態は失われる。もし礼拝中であったら、それは礼拝を無効化する。",
          "礼拝が受け入れられないという意味は、礼拝が有効ではなく、それによって褒美も得られない状態を指す。",
          "このハディースは、礼拝にも有効なものと無効なものがあることを示している。イスラーム法に沿って行われたものは受け入れられ、そうでないものは受け入れられない。これは、その他全ての崇拝行為にも言えることである。預言者（彼にアッラーからの平安と祝福あれ）は言っている：「私たちのものではない行いを行う者は、受け入れられない。」",
          "汚れた状態にある者の礼拝は、ウドゥーをするまで禁じられる。アッラーがそれを受け入れないからである。アッラーが受け入れないやり方でアッラーのお近づきを得ようとするのは、アッラーに対する反抗であり、悪ふざけの一種である。",
          "ある礼拝のためにウドゥーをし、その後、清浄な状態のまま別のサラーの時間を迎えた者は、再びウドゥーをする必要はない。",
          "汚れた状態にある者の礼拝は、義務のものであれ任意のものであれ、葬儀の礼拝であれ、受け入れられない。もし忘れていたとしても、ウドゥーをやり直さなければならない。大きな汚れの状態にある者も同様で、グスルをする前だったり、浄めを忘れてしまっている状態で礼拝してしまったら、清浄な状態でやり直すことが義務となる。",
        ],
