    "title": "「例えクルアーンの１句でもよいから、私から（の言葉を人々に）伝えるのだ。イスラーイールの民からの話を伝えても、問題はない。そして私が言ってもいないことを故意に嘘をついて言う者には、地獄の業火にその座を占めさせよ。」",
    "hadeeth": "アブドッラー・ブン・アムル（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は言った： 「例えクルアーンの１句でもよいから、私から（の言葉を人々に）伝えるのだ。イスラーイールの民からの話を伝えても、問題はない。そして私が言ってもいないことを故意に嘘をついて言う者には、地獄の業火にその座を占めさせよ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はクルアーンやスンナから、たとえそれがアーヤ一つやハディース一つのように少しのものであったとしても、知識を伝達することを命じた。ただしそれは、自分が伝達し、招くところのものを知っている限りにおいてである。 また預言者（アッラーからの祝福と平安あれ）は、イスラーイールの民に起こった話を伝えても、問題はないと説明した。ただしそれは、イスラームの教えと矛盾しない範囲においての話である。 また、彼が言ってもいないことを故意に嘘をついて言うことについて注意をし、そのようなことをする者は地獄の業火に居場所を見出すことになる、と言った。",
    "hints": [
          "アッラーの教えを伝達することの勧め。人間には、たとえわずかなものであっても、自分が記憶し理解したものを遂行する義務がある。",
          "イスラームの知識を追求することの義務。それはアッラーを崇拝し、正しい形でその教えを伝達するためである。",
          "伝達し広める前に、ハディースの信憑性を確認する義務。それは厳しい警告に該当しないようにするためである。",
          "言葉における誠実さと、話における注意の勧め。それは特にアッラーの教えにおいて、嘘を口にしてしまわないようにするためである。",
        ],
    "grade": "صحيح",
    "attribution": "رواه البخاري",
  },
  3701: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "ムスリムに降りかかる、いかなる疲労、病気、悩み、悲しみ、害、心配でも、アッラーがそれによってその者の罪滅ぼしとしてくれないことはない。たとえそれが、ささった棘であったとしても、である。",
    "hadeeth": "アブー・サイードとアブー・フライラ（彼らにアッラーのご満悦あれ）によると、預言者（彼にアッラーからの祝福と平安あれ）は言った：「ムスリムに降りかかる、いかなる疲労、病気、悩み、悲しみ、害、心配でも、アッラーがそれによってその者の罪滅ぼしとしてくれないことはない。たとえそれが、ささった棘であったとしても、である。」",
    "explanation": "このハディースの意味は、次の通りである：ムスリムに降りかかる、いかなる病気、悩み、悲しみ、苦悩、災難、逆境、恐怖、心配でも、アッラーがそれらによって、その者の罪滅ぼしとしてくれないことはない。そしてそこにおいて忍耐と、褒美を望む意図が加われば、この上に褒美を授かることになる。\nつまり、災難に関しては２つの場合がある：\n１．災難が降りかかった時、褒美のことを想起し、アッラーの為にその災難を耐え忍ぶ場合。そうすれば、２つの利益がある。罪を赦されることと、善行の増加である。\n２．上記のことに不注意な場合。そして気を悪くし、うんざりしてしまったりすること。この場合でも、罪の赦しにはなる。つまり、いずれの場合でも災難を受けた者は、得をする。\n何も意図せず、忍耐することも褒美を望むこともなくても、罪の赦しを得ることは出来る。そして罪の赦しと、アッラーからの褒美を得ることも可能なのである。\n以上のことから、人はたとえ棘一本が刺さる災難であったとしても、その災難ゆえにアッラーから褒美を得ることが可能なことを想起すべきである。そうすることによって、罪の赦しと共に褒美を頂けるのだ。\nこのように、試練ゆえに罪の赦しと褒美を授かることが出来るのは、信仰者に対するアッラーからの恩恵であり、寛容さであり、優しさである。\n注意：ここで赦されるのは、小さな罪のみである。大罪は、真摯な悔悟によってでしか赦されない。",
    "hints": [
          "信仰者に降りかかる病気などの試練は、たとえそれが些細なものであったとしても、その者の罪滅ぼしとなる。",
          "ここにはムスリムにとっての、偉大な吉報がある。ムスリムは必ず、これらの災難に出遭うことになるからである。",
          "これらの物事により、位階は上がり、善行は増加する。",
          "ここで罪が赦されるのは、小罪のみである。大罪には悔悟が必要となる。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  3702: {
