    "category": "諸々の徳と礼儀作法",
    "title": "「地獄は欲望によって覆われ、天国は苦難によって覆われている。」",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言いました： 「地獄は欲望によって覆われ、天国は苦難によって覆われている。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、このように説明した：地獄は、非合法な物事を行ったり、義務をおろそかにしたりするようなことなど、人間の欲望にかなうような物事に囲まれている。 ゆえに欲望に従えば、地獄がふさわしい者となる。 天国は義務をきちんと遂行することや、非合法な物事を放棄すること、そこにおいて忍耐することなど、人の心が嫌に思うような物事に囲まれている。ゆえにそこに突入し、そこにおいて奮闘した者は、天国に入るにふさわしい。",
    "hints": [
          "欲望に陥ることの原因としては、シャイターンによる悪事や醜行の美化がある。それにより人にはそのような物事が美しいものと映り、そこへと傾いてしまうのである。",
          "非合法な欲望から遠ざかることの命令。それは地獄への道である。また、自分が嫌に思うことにおいて忍耐することの命令。それは天国への道である。",
          "自我との奮闘、崇拝行為における努力、嫌に思うことや服従行為に関連する困難における忍耐の徳。",
