    "title": "ムスリムのムスリムに対する５つの権利：挨拶を返すこと。病人を見舞うこと。葬儀に参列すること。招待に応じること。くしゃみをした者に祈願してやること。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は言った：「私はアッラーの使徒（彼にアッラーからの平安と祝福あれ）がこう言うのを聞いた： ムスリムのムスリムに対する５つの権利：挨拶を返すこと。病人を見舞うこと。葬儀に参列すること。招待に応じること。くしゃみをした者に祈願してやること。",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、同胞であるムスリムに対してのムスリムの諸権利について、説明した。 1番目の権利は、サラームの挨拶をしてきた者に、サラームの挨拶を返すことである。\n\n2番目の権利は、病人をお見舞いし、訪問することである。\n\n3番目の権利は、葬儀に参列することである。つまり故人の家から礼拝の場まで、そして墓場に埋葬されるまで同伴することである。\n\n4番目の権利は、披露宴の食事やその他の物事に招待されたら、それに応じることである。\n\n5番目の権利は、くしゃみをした者に祈ってやることである。つまり、その者が「アルハムドゥリッラー（アッラーに讃えあれ）」と言ったら、「ヤルハムカッラー（アッラーがあなたを慈しんで下さいますよう）」と唱えることである。そしてくしゃみをした者は、それを聞いたら、「ヤハディークムッラーフ・ワ・ユスリフ・バーラクム（アッラーがあなた方を導き、あなた方の物事を正して下さいますよう）」と唱える。",
