    "hadeeth": "ジャービル（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った： 「買う時、売る時、返済の時に寛大な者を、アッラーが慈しんで下さいますよう。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、売買において物事を簡単にし、寛大で大目に見る全ての者に、慈悲を祈った。 ゆえに売買を行う者に対して値段を厳しくしてはならず、よい品格でもって付き合わなければならない。 売買の際に、物事を簡単にし、寛大で大目に見るということは、商品の値段を不当に下げたりしないことである。 債務を遂行するよう要求する時に、物事を簡単にし、寛大で大目に見るということは、貧しい者や恵まれない者に対して厳しくせず、むしろやさしさをもって対処し、債務に苦しむ者には猶予を与えることである。",
