    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「ある者は人々にお金を貸し、（自分の使用人である）若者に、こう言っていたものだった：「債務に苦しむ者が来たら、大目に見てやれ。アッラーが私たちを大目に見てくれるだろう。،」こうして彼はアッラーと謁見し、アッラーは彼を大目に見たのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、人々にお金を貸す取引をするか、あるいは後払いで売買する者について語った。 その男は人々から債権を請求する若者に、このように言っていた： もし債務を遂行することが不可能な負債者のところに行ったら、猶予を与えるか、厳しく請求しないことによって、「大目に見てやれ」と。 あるいは、不足分を大目に見て、返済できる分だけを受領するように、と。彼がそのようなことをしていたのは、アッラーが彼のことを大目に見て、赦してくれることを望んでのことだった。 そして彼が死んだ時、アッラーは彼をお赦しになり、その罪を大目に見られたのである。",
