    "hadeeth": "アブドッラー・ブン・アムル（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は言った： 「（真に ）近親との良い関係を保つ者というのは、自分がされたことに対して報いる者のことを言うのではない。その関係が途絶えた時に、それをつなぎとめるような者のことを言うのだ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は語っている： 近親との良い関係の維持と、彼らに対する善行において完全な者というのは、自分がよくされたことに対して報いる者のことではない。 そうではなく、近親との良い関係の維持において完全な者というのは、その関係が途絶えた時に、それをつなぎとめるような者のことである。そしてたとえ彼らから悪くされたとしても、彼らに善でもって対する者のことなのである。",
