  4186: {
    "category_id": 3,
    "category": "神学",
    "title": "債務に苦しむ者を猶予し、またはそれを免じてやる者を、アッラーは審判の日、その御座（みくら）の陰に入れて下さる。その日、その陰のほかに陰はない。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「債務に苦しむ者を猶予し、またはそれを免じてやる者を、アッラーは審判の日、その御座（みくら）の陰に入れて下さる。その日、その陰のほかに陰はない。」",
    "explanation": "アブー・フライラ（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの祝福と平安あれ）が次のように言ったと伝えている：\n「債務に苦しむ者を猶予し・・」つまり、貧しい債務者に猶予を与えることである。猶予とは期限の延期である。\n「それを免じてやる」とは、債務を軽減することである。アブー・ヌアイムの伝承では、「あるいは彼に贈与してやる」という記述もある。\nそしてこの褒美として「アッラーは審判の日、その御座（みくら）の陰に入れて下さる。」文字通り、かれの御座の陰に入れてくれる、または天国に入れて下さる。そうすることにより、審判の日の酷熱から守って下さるのである。\nこの報いは、「その日、その陰のほかに陰はない」日において頂くことになる。その陰とはアッラーの陰であり、それは債権者が債務者を自分のことよりも優先し、楽にさせてやったことによるものである。報いは行いと同種のものによるのであり、アッラーはそのような者を楽にして下さるのだ。",
    "hints": [
          "よい貸金と、債務者に対するやさしい対応の勧め。",
