    "title": "誉れの夜（ライラトゥル＝カドゥル）を、信仰と褒美への望みをもって礼拝する者は、それ以前に犯した罪を赦される。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの祝福と平安あれ）の言葉として、このように伝える：「誉れの夜（ライラトゥル＝カドゥル）を、信仰と褒美への望みをもって礼拝する者は、それ以前に犯した罪を赦される。」",
    "explanation": "このハディースは、誉れの夜（ライラトゥル＝カドゥル）の徳と、それを求めることの推奨についてのものである。誉れの夜（ライラトゥル＝カドゥル）とその徳を信じ、それによってアッラーからの褒美を望み、体面や評判など真摯さや褒美への期待の気持ちを損ねる不純なものが入り込むことなしに礼拝できた者は、それ以前に犯した全ての小さな罪を赦される。なお、アッラーの権利に関する大罪については、誠実な悔悟が必要である。他人の権利に関することであれば、悔悟することはもちろんのこと、その人物の権利を満たす必要がある。",
    "hints": [
          "誉れの夜（ライラトゥル＝カドゥル）の徳と、その夜に礼拝することの勧め。",
          "褒美への望みと真摯な意図なしには、善行は純粋なものとならず、受け入れられることもない。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  4204: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーは、かれが良いことを望まれる者を、災難に遭わせる。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「アッラーは、かれが良いことを望まれる者を、災難に遭わせる。」",
    "explanation": "アッラーは、その僕たちによいものを望む時、その生命や財産や子供において試練にかける。それは、それが彼らの罪滅ぼしと、彼らの位階の上昇の原因となるためである。理知的な者が試練の結末を熟考する時、そこには現世と来世におけるよいものがある。試練が降りかかった者は現世において、アッラーへの祈願、哀願、必要の訴えに駆られるし、来世においては結果的に罪の赦しと位階の上昇を得ることが出来る。\nなお、アッラーは仰っている：『われらは、いくばくかの恐怖や飢え、財産や生命や果実の損失によって、必ずやあなた方を試練にかける。忍耐する者たちには、吉報を伝えよ。』（雌牛章１５５）また、この非限定の形のハディースは、他の複数のハディースによって限定の意味を帯びている。つまり、「アッラーは、かれが良いことを望まれる者に忍耐と褒美への期待を与え、試練にかけるべく災難に遭わせる」といった意味である。もし忍耐が無ければ、多くの試練にあったとしても、そこに良いことはない。つまり、アッラーはその者に良いことを望まれなかったことになる。不信仰者は多くの災難が降りかかっても、この世を去るまで不信仰に留まり続ける。そのような者たちに、アッラーが良いことをお望みになったとは言わないのである。",
    "hints": [
          "信仰者は宗教のことであれ財産のことであれ、様々な種類の試練に遭遇する。",
          "ここには、ムスリムにとっての偉大な吉報がある。いかなるムスリムも、何らかの害を受けないことはないからである。",
          "試練は、それによって位階が上がり、罪が赦されるための、僕に対するアッラーの愛の表れかもしれない。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承",
  },
  4211: {
    "category_id": 3,
    "category": "神学",
    "title": "「私は、“アッラー以外に崇拝すべきものはなし、そしてムハンマドはアッラーの使徒である”と証言し、礼拝を遂行し、浄財を支払うようになるまで、人々と戦うことを命じられた",
    "hadeeth": "イブン・ウマル（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「私は、“アッラー以外に崇拝すべきものはなし、そしてムハンマドはアッラーの使徒である”と証言し、礼拝を遂行し、浄財を支払うようになるまで、人々と戦うことを命じられた。もし彼らがそうするならば、彼らは彼らの生命、財産を私から守られる。ただし、イスラームの権利に関するものは別であるが。彼らの清算は、アッラーにのみ委ねられる。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、このように言っている：私は、並ぶものなきアッラー以外に真に崇拝に値するものはなし、そしてムハンマド（アッラーからの祝福と平安あれ）はアッラーの使徒である”と証言し、一日５回の礼拝を遂行し、義務の浄財をその受給資格者に支払うといった、その証言が要求するものを行うようになるまで、人々と戦うことを命じられた。 もし彼らがそれらのことを行うならば、彼らはイスラームによって、彼らの生命、財産を守られる。イスラーム法によって殺害が認められた犯罪や傷害などを犯さない限り、彼らの生命は保証される。そして彼らの清算は審判の日、内実をご存知のアッラーに委ねられることになる。",
    "hints": [
          "法規定は表面的なものをもって適用する。内面的なものはアッラーが引き受けられる。",
          "タウヒードの教えへと招くことの重要性。それが布教において第一にすべきことである。",
          "このハディースは、シルクの徒を無理矢理イスラームに改宗させることを意味するのではない。彼らにはイスラームかジズヤかの選択を提示される。もし彼らがそれらを拒み、イスラームへの布教を禁じるのであれば、イスラームの法規定に則り、戦いが最終手段となる。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  4295: {
    "category_id": 3,
    "category": "神学",
    "title": "「私があなた方のために留めたものに留めておくのだ。というのも、あなた方以前の者たちは、質問のしすぎと自分たちの預言者らに対する異論ゆえに滅亡したのだから",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は、こう言った： 「私があなた方のために留めたものに留めておくのだ。というのも、あなた方以前の者たちは、質問のしすぎと自分たちの預言者らに対する異論ゆえに滅亡したのだから。私があなた方に禁じた物事は遠ざけよ。そして私があなた方に命じたことは、出来る限り、それを行うのだ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、イスラームの法規定が３つに分類されるとした：言及されていないもの。禁じられたもの。命令されたもの。\n\n１番目は、イスラーム法が言及していないものである。これには特に規定はなく、かつ物事の基本は義務ではない。 預言者（アッラーからの祝福と平安あれ）時代においては、まだ起きていないことについて質問するべきではなかった。そうすることにより、義務や禁止の規定が下ってしまわないためである。アッラーはそれらの物事を、しもべたちへの慈悲から放っておかれた。 しかし預言者（アッラーからの祝福と平安あれ）の他界後、宗教的物事に関して必要なことはファトワーや学習の形で質問することが合法であり、むしろそれが要求される。一方、質問が厳しさや余計な負担を求めるようなものであれば、それこそがこのハディースで言われている放棄すべき質問となる。というのもそれは、イスラーイールの子らに起こったようなことへと帰結するかもしれないからである。彼らは一頭の雌牛を屠畜するよう命じられた時、どんな雌牛でも屠畜すればそれでよかったわけだが、物事を厳しくしたために、自分たちも厳しくされてしまったからである。\n\n２番目は、禁止行為である。これは、それを放棄した者は報奨を得るが、それを行なった者は罰されるというものである。ゆえにこのような物事は回避しなければならない。\n\n３番目は、命令行為である。これは、それを行なった者は報奨を得るが、それを放棄した者は罰されるというものである。ゆえにこのような物事は可能な限り、遂行しなければならない。",
    "hints": [
          "必要な物事の内の最重要項目に勤しみ、必要でない物事はすぐに放棄するべきである。そして、まだ起こっていないような物事に関する質問に勤しむべきではない。",
          "物事の複雑化や、多くの異論の引き金となるような紛らわしい物事に関する質問の禁止。",
          "禁じられた物事は全て放棄しなければならないという命令。というのもその放棄には何の困難もないためである。禁止が非限定的であるのは、そのためである。",
          "命じられた物事は可能な限り行わなくてはならないという命令。というのもそこには困難や、能力の不足が伴うかもしれないからである。命令が可能な限りと限定されているのは、そのためである。",
          "やたらと質問することの禁止。学者らは質問を２種類に分類した：1つ目は宗教的物事の内、必要なものを学習する上での質問である。これは求められることであり、教友らの質問もこの類いのものであった。2つ目は厳しさや余計な負担を求める類いのものであり、これは禁じられる。",
          "預言者に異論を呈することの警告。これは過去の共同体にも起きたことである。",
          "やたらと不必要な質問をし、預言者たちに異論を呈することは、破滅の原因である。特に、アッラーしか知らない不可知の領域のことや、復活の日の状況など、到達不可能な領域に関することがこれに該当する。",
          "物事を困難化させるような質問の禁止。アル＝アウザーイーは言う：「アッラーは、そのしもべに知識の祝福を禁じようとする時、その言葉に間違いを投じる。あなたは彼らが、最も知識の少ない者たちであるのを目にするだろう。」イブン・ワハブは言う：「私は、マーリクがこう言うのを聞いた：『学問における言い争いは、人の心から知識の光を消し去ってしまう。』」",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  4303: {
    "category_id": 3,
    "category": "神学",
    "title": "あなたは私に、大変なことを尋ねた。そしてそれは、アッラーによってたやすくされた者にとって、たやすいものである",
    "hadeeth": "ムアーズ・ブン・ジャバル（アッラーのご満悦あれ）は言った： 私は預言者（アッラーからの祝福と平安あれ）と共に旅にあったが、ある日、彼に近いところを歩いていた。私は言った：「アッラーの使徒よ、私を天国に入れ、地獄から遠ざける行いについて教えてください。」彼は言った:「あなたは私に、大変なことを尋ねた。そしてそれは、アッラーによってたやすくされた者にとって、たやすいものである。アッラーを崇拝し、かれに何も並べるな。礼拝を遵守せよ。浄財を支払え。ラマダーンを断食せよ。館へとハッジせよ。」それから言った:「あなたに善の扉を教えてやろうか？断食は盾。施しは水が火を消すように罪を消す。真夜中の礼拝。」そして「彼らの脇腹は彼らの寝床から離れる…」から「…知らない」まで読誦した。それから言った:「すべての物事の要、その柱、その瘤の頂について教えてやろうか？」私は言った:「ええ、アッラーの預言者よ。」彼は言った:「物事の要はイスラーム、その柱は礼拝、その瘤の頂はジハードである。」それから言った:「それらすべてを掌握するりものを教えてやろうか？」私は言った:「ええ、アッラーの使徒よ。」彼は舌をつかんで言った:「これを慎むのだ。」それで私は言った:「アッラーの預言者よ、私たちは自分が語ることでお咎めを受けるのですか？」彼は言った:「ムアーズよ、あなたの母親があなたに先立たれるよう。人々が顔から、または鼻先から真っ逆さまに地獄にひっくり返されるのは、自分の舌で稼いだものゆえに他ならないのではないか？」",
    "explanation": "ムアーズ（アッラーのご満悦あれ）は言った：私は預言者（アッラーからの祝福と平安あれ）と共に旅にあったが、ある日歩んでいる時、彼の近くになった。それで私は言った：「アッラーの使徒よ、私を天国に入れ、地獄から遠ざける行いについて教えてください。」 彼は言った:「あなたは私に、その実行が人にとって大変なことを尋ねた。そしてそれは、アッラーによってたやすくされた者にとって、たやすいものである。イスラームの義務を遂行せよ：\n\n１．アッラーだけを崇拝し、かれに何も並べるな。\n\n２．一日５回の義務の礼拝を遵守せよ。つまり、ファジュル、ズフル、アスル、マグリブ、イシャーのことであり、それらを礼拝の条件、根幹、義務を守りつつ行うのだ。\n\n３．義務の浄財を支払え。それはイスラーム法で定められた一定量に達したあらゆる財産に課せられ、その受給資格者へと与えられる、財産による義務の崇拝行為である。\n\n４．ラマダーンを断食せよ。それは崇拝行為を意図しつつ、ファジュルから日没まで、飲食などを断つことである。\n\n５．アッラーを崇拝し、その宗教儀礼を果たすことを目的として、マッカのカァバ神館を目指してハッジせよ。\n\nそれから預言者（アッラーからの祝福と平安あれ）は言った:「あなたに、善の扉へと到達させてくれる方法を教えてやろうか？それは義務行為を行いつつ、任意の行為で補うことである」：\n\n１．任意の断食。それは罪に陥ることの予防であり、欲望を弱め、力を抑える。\n\n２．任意の施し。それは犯してしまった罪を消し、その跡もろとも抹消してしまう。\n\n３．夜の最後の３分の１の礼拝。それから預言者（アッラーからの祝福と平安あれ）は読誦した：「（懲罰）を怖れ、（褒美を）望みつつ、その主に祈りながら…」つまり、礼拝、ズィクル（念唱）、クルアーン読誦、祈願をしながら。「…彼らの脇腹は寝床から遠ざかる。そして彼らは、われらが授けたものから（施しのために）費やすのだ。また、いかなる者も、彼ら（信仰者たち）が行っていた（善い）ことゆえの報いとして、彼らのために秘蔵された喜びを知らない。」つまり、審判の日、そして天国において、彼らの目を喜ばせる物事を知らない。\n\nそれから預言者（アッラーからの祝福と平安あれ）は言った：「宗教の基盤、そこにおいて依拠する柱、その瘤の頂について教えてやろうか？」\n\nムアーズ（アッラーのご満悦あれ）は言った：「ええ、アッラーの預言者よ。」\n\n預言者（アッラーからの祝福と平安あれ）は言った:「物事の要はイスラーム、つまりそれによって人間の宗教の基礎となるところの、二つの信仰証言である。 その柱は礼拝である。礼拝のないイスラームはない。それはちょうど、柱なしには家が成り立たないようなものである。礼拝を守る者の宗教は堅固になり、高きに至る。また、その瘤の頂と高みはジハードである。それはアッラーの言葉を高く掲げるために、敵と戦うことにおいて尽力することである。\n\nそれから預言者（アッラーからの祝福と平安あれ）は言った:「今述べた物事を完全なものとし、極めるものを教えてやろうか？」そう言うと、彼（アッラーからの祝福と平安あれ）は舌をつかんで言った:「これを慎み、余計なことを話さないようにせよ。」 ムアーズは言った:「私たちの主は、私たちが語ることゆえに私たちをお咎めになったり、それを悪行と数えて私たちを罰されたりするのですか？」\n\n預言者（アッラーからの祝福と平安あれ）は言った：「ムアーズよ、あなたの母親があなたに先立たれるよう。」なお、これはムアーズに災いを祈っているわけではなく、知っておくべきことに注意を向ける際に用いられる、アラブ人の言い回しである。彼は言った：「人々が顔から真っ逆さまに地獄にひっくり返され、転落させられるのは、不信仰、名誉毀損、罵詈雑言、陰口、悪い噂を広めること、嘘といった、自分の舌で稼いだものゆえに他ならないのではないか？」",
    "hints": [
          "学びに対する教友たち（アッラーのご満悦あれ）の熱心さ。預言者（アッラーからの祝福と平安あれ）に頻繁に質問をしたのは、それによるものである。",
          "行いこそが天国に入るための要因であるということを知っている、教友たち（アッラーのご満悦あれ）の宗教理解。",
          "ムアーズ（アッラーのご満悦あれ）のした質問の偉大さ。なぜなら実際のところ、それは人生と存在の秘密であり、この世に存在する人間とジンの行き着くところは天国か地獄だからである。この質問の偉大さは、そこに潜んでいる。",
          "イスラームの５行、つまり二つの信仰証言、礼拝、浄財、断食、ハッジを行うことは、天国に入ることの必要条件である。",
          "いかなる共同者も認めることなく、アッラーだけを唯一の崇拝対象とすることは、宗教の要、最も価値ある任務、最大の義務である。",
          "報奨を増やし、罪の赦しを得るために善の扉を開いてくれた、しもべたちに対するアッラーのご慈悲。",
          "義務行為を遂行した上で任意の行為によってお近づきを求めることの徳。",
          "イスラームにおける礼拝はテントの柱のようなものである。柱が倒れればテントが倒れるように、礼拝がなくなればイスラームもなくなってしまう。",
          "宗教において人を害することから、口を慎むことの義務。",
          "口を慎み、律することはあらゆる善の源泉である。",
        ],
    "grade": "صحيح بمجموع طرقه",
    "attribution": "رواه الترمذي وابن ماجه وأحمد",
  },
  4304: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "２人のムスリムが剣をもって対峙し（戦っ）たら、殺した方も殺された方も地獄行きである。",
    "hadeeth": "アブーバクラ・ヌファイウ・ブン・アル＝ハーリス・アッ＝サカフィー（彼にアッラーのご満悦あれ）によると、預言者（彼にアッラーからの祝福と平安あれ）は言った：「２人のムスリムが剣をもって対峙し（戦っ）たら、殺した方も殺された方も地獄行きである。」私（アブーバクラ）は言った：「アッラーの使徒よ、殺した方はともかく、殺された方はどういうことでしょうか？」彼は言った：「彼も相手を殺そうと躍起になったのである。」",
    "explanation": "２人のムスリムが剣をもって対峙し、互いに殺害を意図して戦ったら、殺した方は相手を殺害したかどで地獄行きである。殺された方も、同じことをしようとしたために地獄行きである。これはアッラーが彼らをお赦しにもならず、その戦いが正当なものではなかった限りにおいてである。アッラーは仰っている：『そして、もしその一方が（呼びかけに応じずに、）他方を侵犯したのであれば、侵犯する方に対し、彼らがアッラーのご命令に立ち返るまで戦え。』（部屋章９）",
    "hints": [
          "罪を犯すことを心で決心し、そのために行動に移す者には、その罪が実行されたかどうかは別に罰がある。ただし、それはアッラーがお赦しにならない限りのことである。一方、そのようなことを心で望み、行動には移さなかった場合、罪には問われない。",
          "ムスリム同士の戦いへの警告。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  4308: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「善とはよい品性、罪とはあなたにとって胸騒ぎがするものであり、人々がそれを見ることをあなたが嫌うようなもののことである。」",
    "hadeeth": "アン＝ナウワース・ブン・サムアーン（アッラーのご満悦あれ）は言った： 私はアッラーの使徒（アッラーからの平安と祝福あれ）に、善と罪について尋ねた。すると彼は言った：「善とはよい品性、罪とはあなたにとって胸騒ぎがするものであり、人々がそれを見ることをあなたが嫌うようなもののことである。」",
    "explanation": "預言者（アッラーからの平安と祝福あれ）は善と罪について尋ねられ、こう言った：\n\n善の中でも最大のものの一つが、よい品性である。それはアッラーには敬虔さをもって対し、人々に対しては以下のような性格をもって接することである：害悪に対する忍耐。怒りの制御。柔らかい表情。良い言葉。良好な関係性。従順さ。善行。やさしさ。よい付き合い。\n\n他方、罪とは以下のような性質を帯びたものである：疑心暗鬼から胸騒ぎがすること。安心できず、心が落ち着かないこと。心に疑念を生じさせるようなこと。罪の恐れを感じるようなこと。品性がある高貴な人々の目に醜く映るものゆえに、それが人目に晒されるのを望まないようなこと。というのも人間はその性質上、人にはよいものを見せたいからである。つまり人から見られたくない行為はよいものではなく、罪なのである。",
    "hints": [
          "よい品性の勧め：それは善の最大の特徴の一つである。",
          "真理と虚妄が信仰者にとって紛らわしくなることはない。真理については心の中の光で認知し、虚妄についてはそれを回避し、否認するのである。",
          "罪の印のものとしては、心の不安、胸のざわめき、人から見られることを厭うことなどがある。",
          "アッ＝スィンディーは言う：「これは、いずれの側なのか明確ではないような曖昧な事柄に関することである。そうでなければ、イスラーム法で命じられていることは、その反証がない限り善であり、禁じられていることは罪である。このような場合、自分の心に相談したり、その安心を確認したりする必要はない。」",
          "このハディースで語りかけられている対象は、健全な天性を有した者であり、自分の欲に沿ったものでない限りは善を善として認め、悪を否認することのないような逆行した心の持ち主ではない。",
          "アッ＝ティービーは言う：「ハディースにおける“善”は、様々な形で説明されている。場合によって、それは魂と心に平安をもたらすことであるとか、信仰とか、アッラーのお近づきを求める行為といった具合に説明されるが、このハディースでは、よい性格と説明されている。そしてよい性格は、害に耐えること、怒りを慎むこと、明るい表情、よい言葉といった風に解釈されているが、それらはすべて似通った意味である。」",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  4309: {
    "category_id": 6,
    "category": "宣教と勧善懲悪",
    "title": "「宗教とは誠実さである。",
    "hadeeth": "タミーム・アッ＝ダーリー（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの祝福と平安あれ）はこう言った： 「宗教とは誠実さである。」私たちは言った：「誰に対してのものですか？」彼（アッラーからの祝福と平安あれ）は言った：「アッラー、その啓典、その使徒、そしてムスリムの指導者たち、および一般の者たちに対する誠実さである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は言った：宗教とは、誠実さと真摯さの上に成立するものである。そのようにして、アッラーから命じられたものを不足やごまかしなく、十全な形で遂行することができるのである。\n\nすると預言者（アッラーからの祝福と平安あれ）に、こう尋ねられた：誠実さとは誰に対するものですか？それで彼は答えた：\n\n第一に。アッラーに対する誠実さである。つまりアッラーに対して行いを純粋なものとし、シルクを犯さず、その主性、神性、美名と属性を信じ、アッラーの関する物事を偉大視し、かれへのイーマーン（信仰）へといざなうことである。\n\n第二に。アッラーの啓典、つまりクルアーンへの誠実さである。それはそれがアッラーの言葉であり、最後の啓典であり、それ以前の全ての天啓宗教を廃棄するものであることを信じ、偉大視し、正しく読誦し、その意味が明確なものに則って行い、意味が不明確なものについてはそのまま受け入れ、それを改変しようとする者たちの手から守り、その戒めを熟考し、その知識を広め、そこへと人々をいざなうことである。\n\n第三に。アッラーの使徒ムハンマド（アッラーからの祝福と平安あれ）への誠実さ。これは彼が最後の使徒であること、彼がもたらしたものを信じ、彼の命令に従い、禁じたことは回避し、アッラーを崇拝するにあたっては彼のやり方以外ではそうせず、彼の権利を偉大視し、彼を敬い、彼の宣教と教えを広め、彼に対する言われもない訴えから彼を援護することである。\n\n第四に。ムスリムの指導者たちに対する誠実さ。これは真理において彼らに協力すること、彼らの権威を奪ったりしないこと、アッラーの服従において彼らに聞き、従うことである。\n\n第五に。ムスリム一般に対する誠実さ。これは彼らに善行をほどこし、彼らをいざない、彼らを害悪から遠ざけ、彼らによいことを望み、善と敬虔さにおいて彼らと協力することである。",
    "hints": [
          "あらゆる対象に対する誠実さの命令。",
          "宗教における誠実さの地位の高さ。",
          "宗教は信仰だけでなく、言行をも含むということ。",
          "相手に善を望み、自分自身を偽りから清めることもまた、誠実さの一部である。",
          "預言者（アッラーからの祝福と平安あれ）の教育法の秀逸さ。彼はまず大まかに述べてから、それを細かく説明した。",
          "重要なものから順に説明すること。預言者（アッラーからの祝福と平安あれ）はまずアッラーに始まり、その啓典、その使徒（アッラーからの祝福と平安あれ）、ムスリムの指導者たち、一般のムスリムという順番で取り上げていった。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  4314: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「合法的なものは明らかであり、非合法なものも明らかである",
    "hadeeth": "アン＝ヌゥマーン・ブン・バシール（アッラーのご満悦あれ）は言った：私はアッラーの使徒（アッラーからの祝福と平安あれ）がこう言うのを聞いた：−そう言って、アン＝ヌゥマーンは両指で自分の両耳を指した− 「合法的なものは明らかであり、非合法なものも明らかである。そしてその間には、多くの者が知らない紛らわしい物事がある。ゆえにそういった紛らわしい物事から身を慎む者は、自らの宗教と尊厳を守ることになろう。そして紛らわしい物事に陥る者は、禁じられた領域に足を踏み入れてしまうことになろう。それはまるで、禁じられた領域の周辺で（家畜の）番をする牧童のようなものであり、それらは今にもそこに踏み入ってしまいそうである。実に全ての王には、（他の者に）禁じられた領域がある。そして実にアッラーが禁じられた領域とは、かれの禁じられた物事なのである。そして実に体には、それさえ健全であれば体全体も健全であり、それが悪ければ体全体も悪くなるところの1個の肉塊がある。そして実にそれが、心なのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は物事における一般原理を説明し、イスラーム法が３つの範疇に分類されるとした：明らかに合法的なもの。明らかに非合法なもの。合法なのか非合法なのか、多くの者がその規定を知らない紛らわしい物事の３つである。\n\nゆえにそういった紛らわしい物事を放棄する者は、自らの宗教が非合法なものに陥ってしまうことから遠ざけることになる。また、そのような紛らわしい物事に立ち入ってしまうことで、他人から非難の言葉を向けられることから、自らの尊厳を守ることにもなる。 他方、紛らわしい物事を回避しない者は、自らを禁じられた領域に陥れてしまったり、他人からその自尊心を傷つけられてしまったりすることになる。 アッラーの使徒（アッラーからの祝福と平安あれ）は、紛らわしい物事に陥る者に対する例えとして、土地の所有者が禁区とした領域の周辺で家畜番をする牧童の例を挙げた。それらの家畜は禁区に近い場所で放牧されているために、今にもそこに踏み入ってしまいそうである。同様に、紛らわしい物事に立ち入ってしまう者は、禁じられた物事に近づき、その中に陥ってしまいそうな状況にあるのである。 預言者（アッラーからの祝福と平安あれ）はそのように説明した後、こう言った：体には、それが正しければ体全体も正しくあり、それが悪ければ体全体も悪くなるところの1個の肉塊がある。そしてそれが、心なのである。",
    "hints": [
          "その法規定が不明確な紛らわしい物事を放棄することへの勧め。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  4316: {
    "category_id": 3,
    "category": "神学",
    "title": "「まことに至高のアッラーはよいお方であり、よいものしかお受け入れにはならない。まことにアッラーは信者たちに、使徒たちに命じたのと同じものをお命じになり、こう仰った",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「まことに至高のアッラーはよいお方であり、よいものしかお受け入れにはならない。まことにアッラーは信者たちに、使徒たちに命じたのと同じものをお命じになり、こう仰った：“使徒たちよ、善きものの内から食べ、正しい行いを行え。”（信仰者たち章５１）また、こう仰った：“信仰する者たちよ、われらがあなた方に授けた善いものから食べ、アッラーに感謝せよ。”（雌牛章１７２）」それから彼は、髪をバサバサにして埃だらけになりながら、長い旅をしている男について話をされた。”わが主よ、わが主よ”と男は（祈りつつ）両手を天に伸ばしている。しかし彼の食べ物はハラーム、飲み物もハラーム、着るものもハラームであり、ハラームなもので養われている。どうして彼（の祈り）に応じられようか？」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は伝えている：まことに至高のアッラーは、完全さで特徴づけられ、不足や欠点からは無縁なよいお方であり、行いでも言葉でも信条でも、よいものしかお受け入れにはならない。つまりアッラーのみに捧げられ、預言者（アッラーからの祝福と平安あれ）のスンナに則った物事のことである。アッラーのお近づきはそれら以外によって、なされることはない。また、信仰者にとって、行いがよくなるための最も重要な要因の一つが、食べ物がハラールで良質であることである。それによって行いは清められたものとなる。アッラーが信仰者たちに、使徒たちに命じたのと同様、ハラールな食べ物を食べて善行に励むことを命じたのは、そういったわけである。アッラーはこう仰った：“使徒たちよ、善きものの内から食べ、正しい行いを行え。”（信仰者たち章５１）また、こうも仰った：“信仰する者たちよ、われらがあなた方に授けた善いものから食べ、アッラーに感謝せよ。”（雌牛章１７２）」\n\nそれから預言者（アッラーからの祝福と平安あれ）は、ハラームな食事について警告した。それは行いを駄目にしてしまい、それが受け入れられるためにどんなに表面的な手段を尽くしたとしても、受け入れられることから阻んでしまうものである。男が払った表面的な努力は、以下の物事に現れている：\n\n１．ハッジ、ジハード、親戚との良好な関係の維持など、服従行為における長旅。\n\n２．髪を梳かしていないため、髪の毛がバサバサになっていること。髪の毛や衣服の色が埃で変色してしまっていること。これらは全て、男の行き詰まった状況ゆえのものである。\n\n３．両手を天に伸ばして祈っていること。\n\n４．「わが主よ、わが主よ」とアッラーの美名によって、アッラーに懸命に祈っていること。\n\nこのように祈りが受け入れられるための手段を尽くしているものの、男の祈りは聞き入れられない。なぜなら彼の食べ物はハラーム、飲み物もハラーム、着るものもハラームであり、ハラームなもので養われているためである。このような性質の者は、祈りが叶えられにくいものであり、むしろどうしてその祈りが受け入れられるようなことがあろうか？",
    "hints": [
          "アッラーのその本質、属性、行為、法規定における完全性。",
          "行いをアッラーだけに真摯に捧げ、そこにおいて預言者（アッラーからの祝福と平安あれ）に追従することの命令。",
          "行いへと奨励する手法を用いること。それは預言者（アッラーからの祝福と平安あれ）が、「まことにアッラーは信者たちに、使徒たちに命じたのと同じものをお命じになり…」と言った通りである。使徒たちもまた同じように命じられていたということを知る時、信仰者はその模倣へと促されるのである。",
          "祈願を受け入れることを阻む物事の一つが、ハラームな食事である。",
          "祈願を受け入れられる要因として、５つの物事がある：１．長い旅行：祈願が受け入れられる最大の要因の一つである、弱く哀れな状態がそれによって生じる。２．祈らずにはいられないような切迫した状態。３．両手を天に伸ばすこと。４．アッラーの主性を繰り返し念じつつ、念を入れて祈ることは、祈願が受け入れられるにあたって最も必要な物事の一つである。５．飲食物がよいものであること。",
          "ハラールでよいものを食することは、善行への助力の要因の一つである。",
          "アル＝カーディーは言う：「”よさ”の反対は”悪さ”である。アッラーがそれによって描写される時、それはアッラーが、あらゆる欠点や汚点から無縁で崇高なお方であることを意味する。そして特に限定なく、人間がそれによって描写される時、それはその者が悪い性格や醜い行いから縁遠く、その反対の性質を備えていることを表す。また、財産がそれによって描写される時、それはそれが最善な種類のものであり、ハラールであることを示している。」",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  4319: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「まことにアッラーは、あらゆる物事においてイフサーン（善処）を命じた",
    "hadeeth": "シャッダード・ブン・アウス（アッラーのご満悦あれ）は言った：私はアッラーの使徒（アッラーからの祝福と平安あれ）から、２つのものを覚えた。彼は、こう言った： 「まことにアッラーは、あらゆる物事においてイフサーン（善処）を命じた。ゆえに殺す時にはよい殺し方をし、屠畜する時にはよい屠畜をせよ。自分の刃物をよく研ぎ、屠畜される動物を楽にさせるのだ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、アッラーが私たちに、あらゆる物事においてイフサーン（善処）を命じた、と言った。イフサーン（善処）とは、崇拝行為であれ、善を行うときであれ、被造物を害悪から守るときであれ、いつもアッラーを想念している状態のことである。ゆえに殺したり屠畜したりしなくてはならない状況においても、イフサーン（善処）は求められる。\n\n報復刑で死刑を執行しなければならない状況におけるイフサーン（善処）は、最も簡単で、受刑者にとって最も軽く、最も早く楽になれる方法を選ぶことである。\n\n屠畜におけるイフサーン（善処）は、刃物をよく研ぐことによって家畜に優しくし、家畜の前で刃物を研いだり、他の家畜の前で別の家畜を屠畜する光景を見せたりしないことである。",
    "hints": [
          "被造物に対するアッラーの慈悲とお優しさ。",
          "殺したり屠畜したりする際のイフサーン（善処）は、イスラーム法に即したやり方でなければならない。",
          "イスラーム法の包括性と完全性。そこにはあらゆる善行が包含されており、動物に対する慈悲と優しさも含まれている。",
          "死んだ人間の遺体を損傷することの禁止。",
          "動物をいじめることにつながるあらゆる物事の禁止。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  4322: {
    "category_id": 3,
    "category": "神学",
    "title": "まことにアッラーは善行と悪行を定め、それらを説明した。一つの善行をしようと思ってもそれを行わなかった者には、アッラーはそれをかれの御許で一つの完全な善行として記録する。そしてもしそれをしようと思って行ったのであれば、アッラーはそれをかれの御許で１０倍、７００倍、それ以上にまでたくさん倍増して記録する。一方、一つの悪行を思い立ってもそれを行わなかった者には、アッラーはそれをかれの御許で一つの完全な善行として記録する。そしてもしそれを思い立って行ったのであれば、アッラーはそれを一つの悪行として記録する。」",
    "hadeeth": "イブン・アッバース（アッラーのご満悦あれ）によれば、 預言者（アッラーからの祝福と平安あれ）はその主から伝えて、このように言った：「まことにアッラーは善行と悪行を定め、それらを説明した。一つの善行をしようと思ってもそれを行わなかった者には、アッラーはそれをかれの御許で一つの完全な善行として記録する。そしてもしそれをしようと思って行ったのであれば、アッラーはそれをかれの御許で１０倍、７００倍、それ以上にまでたくさん倍増して記録する。一方、一つの悪行を思い立ってもそれを行わなかった者には、アッラーはそれをかれの御許で一つの完全な善行として記録する。そしてもしそれを思い立って行ったのであれば、アッラーはそれを一つの悪行として記録する。」",
    "explanation": "使徒（アッラーからの祝福と平安あれ）は、アッラーが善行と悪行を定め、それからそれらをどのようにして記録するかについて、２人の天使にこう説明したと語った：\n\n一つの善行をしようと思い、決心しても、それを行わなかった者には、それが一つの善行として記録される。もしそれ行ったのであれば、それは１０倍、７００倍、それ以上にまでたくさん倍増される。その倍増の程度は、心の中の純粋さや、その利益が他者にまで及んだりすることによって決定される。\n\n一方、一つの悪行を思い立ち、それをしようと決心しても、それをアッラーゆえに放棄した者には、それが一つの善行として記録される。もし忙しくて、それを行うためのお膳立てをしなかったために放棄したという場合には、何も記録されない。また、ただ単にそうすることが出来なかったという場合には、その意図だけが記録される。そしてもしそれを行ったのであれば、それは一つの悪行として記録される。",
    "hints": [
          "善行は倍増し、その御許に記録され、悪行は倍増されないという、この共同体に対するアッラーの偉大な恩恵。",
          "行いにおける意図の重要性とその影響。",
          "善行を行おうとしてやらなかったとしても、アッラーがそれを一つの善行として記録してくださるという、アッラーの恩恵とやさしさと善。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
