    "title": "まことにアッラーは、あなた方の身体や姿形をご覧になるのではない。しかしかれは、あなた方の心と行いをご覧になるのだ。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は、アッラーの使徒（彼にアッラーからの祝福と平安あれ）から伝えて、こう言った：「まことにアッラーは、あなた方の身体や姿形をご覧になるのではない。しかしかれは、あなた方の心と行いをご覧になるのだ。」",
