  4556: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「まことにアッラーとその使徒は、酒、動物の死体、豚、偶像の取引を禁じた",
    "hadeeth": "ジャービル・ブン・アブドッラー（アッラーのご満悦あれ）は、アッラーの使徒（アッラーの祝福と平安あれ）が勝利の年（マッカ開城の年）にマッカで次のように語ったと伝えている： 「まことにアッラーとその使徒は、酒、動物の死体、豚、偶像の取引を禁じた。すると人びとはこう言った：“アッラーの使徒よ、動物の死体の脂についてはどうですか？それは舟に塗装されたり、革に塗布されたりしますし、人びとはそれを明かりにも用いますが？”すると（預言者は）言った：“いや、それはハラーム（禁じられていること）だ。”それから、アッラーの使徒（アッラーの祝福と平安あれ）は言った：“アッラーがユダヤ教徒を征伐するように。彼らはアッラーがその脂を禁じたにもかかわらず、それを溶かして売り、その代金を得たのだから。”」",
    "explanation": "ジャービル・ブン・アブドッラー（アッラーのご満悦あれ）は、預言者（アッラーの祝福と平安あれ）が勝利の年（マッカ開城の年）にマッカで次のように言うのを聞いた：まことにアッラーとその使徒は、酒、動物の死体、豚、偶像の取引を禁じた。すると人びとはこう言った：「アッラーの使徒よ、動物の死体の脂を売買することは許されますか？それは舟に塗装されたり、革に塗布されたりしますし、人びとはそれを明かりを灯すためにも用いますが？」すると（預言者は）言った：「いや、その売買はハラーム（禁じられていること）だ。」それから、アッラーの使徒（アッラーの祝福と平安あれ）は言った：「アッラーがユダヤ教徒を滅ぼし、呪うように。彼らはアッラーがその脂を禁じたというのに、それを溶かして売り、その代金を得たのだから。」",
    "hints": [
          "アン＝ナワウィーは言う:「動物の死体、酒、豚の売買が禁じられることにおいて、ムスリムたちは意見の一致を見ている。」",
          "カーディーは言う:「このハディースは以下のような意味を含む:食用、利用が許されないものは、その売買やそれを売った利益を手に入れることも許されない。ちょうどハディースの中で取り上げられた、死体の脂がそれである。」",
          "イブン・ハジャルは言う:「ハディースの文脈は、“それはハラームだ”という言葉の意味が、大多数の学者がそのように解釈しているように、売買であり、利用ではないことを強く示している。」",
          "ハラームなものを合法化しようとする手段は全て虚妄である。",
          "アン＝ナワウィーは言う:「学者たちは言う:動物の死体の売買の一般的禁止は、遺体の売買の禁止をも含み得る。ナウファル・ブン・アブドッラー・アル＝マフズーミーが塹壕の戦いで殺された時、敵軍は預言者（アッラーの祝福と平安あれ）に、その遺体を一万ディルハムで買い取ることを申し出たが、預言者はそれを受け取らずに引き渡した。",
        ],
