  4558: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「アッラーはあなた方のために、あなた方が施すものを授けて下さったのではないか？各タスビーハ（「スブハーナッラー」と称えること）には一つのサダカが、各タクビーラ（「アッラーフ・アクバル（アッラーは最も偉大なり）と唱えること）には一つのサダカが、各タフミーダ（「アルハムドゥリッラー」と称賛すること）には一つのサダカが、各タフリーラ（「ラーイラーハイッラッラー（アッラー以外に崇拝すべきものはなし）」と唱えること）には一つのサダカがある。善を命じることはサダカであり、悪事を禁じることはサダカであり、あなた方の性の営みにもサダカがあるのだ。」",
    "hadeeth": "アブー・ザッル（アッラーのご満悦あれ）は、言った： アッラーの使徒（アッラーからの平安と祝福あれ）の教友たちの内のある人々が、預言者（アッラーからの平安と祝福あれ）にこう言った：「アッラーの使徒よ、裕福な人々は報奨を持って行ってしまいます。彼らは私たちが礼拝するように礼拝をし、私たちが断食するように断食し、彼らの財産の余分なものからサダカ（施し）をします。」彼は言った：「アッラーはあなた方のために、あなた方が施すものを授けて下さったのではないか？各タスビーハ（「スブハーナッラー」と称えること）には一つのサダカが、各タクビーラ（「アッラーフ・アクバル（アッラーは最も偉大なり）と唱えること）には一つのサダカが、各タフミーダ（「アルハムドゥリッラー」と称賛すること）には一つのサダカが、各タフリーラ（「ラーイラーハイッラッラー（アッラー以外に崇拝すべきものはなし）」と唱えること）には一つのサダカがある。善を命じることはサダカであり、悪事を禁じることはサダカであり、あなた方の性の営みにもサダカがあるのだ。」教友たちは言った：「アッラーの使徒よ、私たちが自らの欲に応じることで、報奨があるのですか？」彼は言った：「見てみよ。あなた方がそれをハラームなことに用いれば、その者にとってそれは罪となる。同様に、それをハラールなことに用いれば、それはその者にとっての報奨となるのである。」",
    "explanation": "ある貧しい教友たちが、預言者（アッラーからの平安と祝福あれ）に彼らの貧しい状態と、財産を施すことによって偉大な報奨を得ることができない不満を訴えた。そして裕福な人々は彼らと同じように礼拝をし、彼らと同じように断食するというのに、彼らの財産の余分なものからサダカ（施し）までして偉大な報奨を得ることができるのに、自分たちには施しをすることができないのだ、と言った。 それで預言者（アッラーからの平安と祝福あれ）は、彼らでも出来るようなサダカ（施し）を示して、このように言った： 「アッラーはあなた方のために、あなた方が施せるものを授けて下さったのではないか？タスビーハ（「スブハーナッラー」と称えること）には一つのサダカの報奨があり、タクビーラ（「アッラーフ・アクバル（アッラーは最も偉大なり）と唱えること）も一つのサダカ、タフミーダ（「アルハムドゥリッラー」と称賛すること）も一つのサダカ、タフリーラ（「ラーイラーハイッラッラー（アッラー以外に崇拝すべきものはなし）」と唱えること）も一つのサダカなのである。善を命じることもサダカであり、悪事を禁じることもサダカであり、あなた方が妻と性の営みを持つことも一つのサダカなのだ。」 教友たちは驚いて言った：「アッラーの使徒よ、私たちが自らの欲に応じることで、報奨があるのですか？」 彼は言った：「見てみよ。あなた方がそれを姦淫などのハラームなことに用いれば、その者にとってそれは罪となるのではないか？同様に、それをハラールなことに用いれば、それはその者にとっての報奨となるのである。」",
    "hints": [
          "善行における教友たちの競争と、アッラーからの偉大な報奨と恩寵を得ることにおける熱心さ。",
          "善行の種類の多様性。善行は、ムスリムが正しくよい意図で行うあらゆる行いを包含する。",
          "イスラームのやさしさ。どんなムスリムでもアッラーに服従するための行いを見出すことが出来る。",
          "アン＝ナワウィーは言う：「このハディースには、合法な物事は誠実な意図によって服従行為となる根拠が含まれている。性交渉であっても、アッラーが命じているところの妻への義務の遂行や親密なよい付き合いを求めたり、またはそこにおいてよい子供、自分や妻の貞淑さ、ハラームな物事への関心や考えや衝動の抑制などを求めたりするといった、よい意図を持つことによって崇拝行為になり得るのである。」",
          "話を聞く者によってより明確かつ印象が強いものとなるために、たとえや類推を用いること。",
        ],
