    "attribution": "رواه مسلم",
  },
  4559: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「人びとが知っている初期の預言の言葉の内のものに、（こうある）：恥ずかしくないのなら、好きなことをせよ。」",
    "hadeeth": "アブー・マスウード（アッラーのご満悦あれ）は言った：預言者（アッラーからの祝福と平安あれ）は、こう言った： 「人びとが知っている初期の預言の言葉の内のものに、（こうある）：恥ずかしくないのなら、好きなことをせよ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は伝えている：人びとが知っている先代の預言者たちから伝わる箴言で、人々に世代を超えて語り継がれ、この共同体の先人たちにまで届いたものの中に、このようなものがある：「あなたの行おうとしていることを見て、もしそれが恥ずかしさを感じないようなものであるならば、それを行え。もし恥ずかしさを覚えるようなものであれば、それを放棄せよ。羞恥心は醜業から人を阻むものの一つであり、羞恥心がない者は、あらゆる下品な物事や悪行に身をやつすものだからである。」",
    "hints": [
          "羞恥心は優れた品性の基本である。",
          "羞恥心は預言者たち（彼らに平安あれ）の特徴の一つであり、それは彼らから引き継がれてきているものである。",
          "羞恥心はムスリムを美しくし、飾る物事へと促し、汚し、醜くする物事から手を引かせるものである。",
          "アン＝ナワウィーは言う：「ここでの命令は、合法のことである。つまり、何かしようと思った時、それをしたら人々にもアッラーに対しても羞恥心を覚えさせないような種類のものである場合、それをすることが可能である。もし羞恥心を覚えるのであれば、してはいけない。これはイスラームの基礎であり、義務付けられ、推奨されているものは、その放棄に対して羞恥心を感じるものである。一方、禁じられ、嫌われているものは、それを行うことに対して羞恥心を感じるものである。また、許容されているものは、それを行うことを恥ずかしく思うものを行うことも、放棄することも、許される。このように、このハディースには５つの法規定が含まれている。別の一説によれば、これは、”羞恥心を失ったならば、望むことを何でも行うがよい。アッラーがそれに報いることになるのだから”という、脅迫的な命令である。また別説によれば、”羞恥心がない者は、好きなことをする”という、事実の描写の意味である。」",
        ],
    "grade": "صحيح",
    "attribution": "رواه البخاري",
  },
  4560: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "行為とは意志にもとづくものであり、人はみな自らの意図したものを得ることになる。",
    "hadeeth": "ウマル・ブン・アル＝ハッターブ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った: 「行為とは意図にもとづくものであり、人は自らの意図したものを得ることになる。したがってアッラーとその使徒のために移住した者の移住は、アッラーとその使徒のための移住であり、現世の利益、または女性との結婚のために移住した者の移住は、彼がそれを目的として行なった移住なのである。」アル＝ブハーリーの伝承には、こうある：「行為とは意志にもとづくものであり、人はみな自らの意図したものを得ることになる。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は説明する：すべての行為は、その意図によって意味をなす。この規定は崇拝行為、取引など、あらゆる行為における一般的なものである。ゆえに自分の行いによって単なる利益を意図した者は、その利益しか得ることがなく、宗教的報奨を得ることはない。一方、自分の行いによってアッラーのお近づきを求める者は、たとえそれが飲食などの普通の行為であったとしても、それによって宗教的報奨を得ることになる。\n\nそれから預言者（アッラーからの祝福と平安あれ）は、一見同じような行いでも意図がいかに影響するかを説明するにあたり、このような例えを挙げている：主アッラーのお喜びを求め、それを目的として移住し、故郷を後にする者の移住はイスラームの教えに沿った移住であり、その純真な意図によってその者は報奨を得ることになる。一方、移住によって財産、地位、商売、配偶者といった現世的利益を意図する者は、自分が意図したものしか得ることはなく、宗教的な報奨の取り分はない。",
    "hints": [
          "真摯さのすすめ。アッラーは、アッラーのお顔を求めて行われた行いしかお受け入れにはならない。",
          "アッラーのお近づきを求める行為は、もし人がそれを習慣的形で行うのならば、そこに宗教的な報奨はない。アッラーのお近づきを意図して初めて、それを得ることができる。",
        ],
    "grade": "صحيح",
