  },
  4563: {
    "category_id": 3,
    "category": "神学",
    "title": "イスラームは、「 ラー・イラーハ・イッラッラー、ムハンマドゥッラスールッラー （アッラーの他に真に崇拝すべきものはなく、ムハンマドはその使徒である）」と証言し、 サラー （礼拝）し、ザカー （浄財）を施し、ラマダーン月にサウム（断食）をし、それが可能であるならばカァバ神殿を目指してハッジ （大巡礼）を行うことである。",
    "hadeeth": "ウマル・ブン・アル＝ハッターブ（アッラーのご満悦あれ）は言った: 「私たちがある日アッラーの使徒（アッラーからの祝福と平安あれ）と共にある時、純白の衣服をまとい、漆黒の髪の一人の男が私たちのもとに現れた。彼に旅の形跡はなく、私たちの誰一人として彼を知る者はいなかった。彼は預言者（アッラーからの祝福と平安あれ）のもとまでやって来ると、彼の両膝を両膝につき合わせるようにして座り、彼の両手をその両腿の上に置いた。そして言った：”ムハンマドよ、イスラームについて教えてくれ。”それでアッラーの使徒（アッラーからの祝福と平安あれ）は言った：“イスラームは、「 ラー・イラーハ・イッラッラー、ムハンマドゥッラスールッラー （アッラーの他に真に崇拝すべきものはなく、ムハンマドはその使徒である）」と証言し、 サラー （礼拝）し、ザカー （浄財）を施し、ラマダーン月にサウム（断食）をし、それが可能であるならばカァバ神殿を目指してハッジ （大巡礼）を行うことである。”（男は）言った：“その通り。”私たちは自分で尋ねておきながら、答えを承認するその男に驚いた。（男は続けて質問して）言った：“それではイーマーンについて教えてくれ。（アッラーの使徒は）言った：“アッラーとその天使たち、その諸啓典、その諸使徒、最後の日を信じること。そして良いことであれ悪いことであれ定命を信じることである。”（男は）言った：“その通り。” （男は続けて）言った：“それではイフサーンについて教えてくれ。”（アッラーの使徒は）言った：“アッラーをまるで見ているかのように、かれを崇めることだ。そして例えかれが見えなくとも、かれはあなたをご覧になられる。”（男はまた）言った：“それでは審判の日について教えてくれ。”」（アッラーの使徒は）言った：“質問を受けた者はそれについて、質問者よりも知っているわけではない。”（男はまた）言った：“それではその諸々の予兆について教えてくれ。”（アッラーの使徒は）言った：“あなたは（その諸々の予兆として）奴隷女がその主人を産むのを見るだろう。また裸足で裸の貧しい羊飼いたちが、競って高い建築物を建て合うのを見るだろう。”それから（男は）去って行った。私（ウマル） は暫くそのまま留まっていたが、すると（アッラーの使徒は）私にこう言った：“ウマルよ、あの質問者が誰だか分かるか？”私は言った：“アッラーとその使徒がよくご存知です。”（アッラーの使徒は）言った：“彼はジブリールだ。あなた方の宗教を教えるために、あなた方のもとへやって来たのである。”」",
    "explanation": "ウマル・ブン・アル＝ハッターブ（アッラーのご満悦あれ）は言っている:ジブリール（平安あれ）が教友たち（アッラーのご満悦あれ）のところに、誰も知らない男性の姿をしてやって来た。彼は純白の衣服をまとい、漆黒の髪をしていた。彼にはやつれ、埃、髪の毛の乱れ、服の汚れといった旅の形跡はなく、そこにいた誰も彼を知る者はいなかった。彼らは預言者（アッラーからの祝福と平安あれ）と一緒に座っていたが、その男はものを学ぶ者の座り方で預言者（アッラーからの祝福と平安あれ）の前に座った。そしてイスラームについて尋ねた。アッラーの使徒（アッラーからの祝福と平安あれ）は、２つの信仰証言の承認、５回のサラー（礼拝）の遵守、ザカー （浄財）をその受給資格者に施すこと、ラマダーン月にサウム（断食）をすること、それが可能ならハッジ （大巡礼）を行うこと、といった物事を含むこれらの根幹要素によって回答した。\n\nそれで質問者は言った：「その通り。」教友たちは、彼が分からなさそうにして質問しておきながら、預言者の言葉を承認するのを見て、驚いた。\n\nそれから男は、イーマーンについて質問した。アッラーの使徒はそれに答え、以下の６つの根幹要因について説明した：アッラーとその存在、属性、創造などの行為における唯一性、崇拝行為を向ける対象としての唯一性に関する信仰。天使たちがアッラーによって光から創造され、アッラーに反抗することなく、かれから命じられたことを遂行する高貴なしもべたちであるという信仰。クルアーン、トーラー、インジールといったものを含む、アッラーの御許から使徒たちに下された諸啓典に対する信仰。ヌーフ、イブラーヒーム、ムーサー、イーサー、そして最後の預言者ムハンマド（アッラーからの祝福と平安あれ）など、アッラーの教えを伝えるすべての使徒と預言者に対する信仰。死後の墓の中の世界、復活までの境界線上の人生、死後の復活と清算、天国と地獄という２つの終着点などを含む、最後の日に対する信仰。アッラーがすべての物事を既にご存じになり、それらが英知に則っており、既に書き記され、それが起こることをアッラーがお望みになり、そしてそれは定め通りに起き、アッラーがそれを創造されるのだということを信じる、定命に対する信仰である。 それから男はイフサーンについて尋ねた。アッラーの使徒はそれが、アッラーをまるで見ているかのように崇拝することだと言った。そしてもしかれがその境地に到達することができなかったとしても、アッラーが自分をご覧になっている気持ちでアッラーを崇拝せよ、と。前者が後者よりも高い境地であり、ムシャーハダ（見ること）の領域である。後者はムラーカバ（自己監視）の領域である。\n\nそれから審判の日について尋ねた。預言者（アッラーからの祝福と平安あれ）は言った：それに関する知識はアッラーの専有であり、被造物の何ものもそれを知ることはできない。質問された側はそのことについて、質問者よりも知っているわけではない。\n\nそれから男は、審判の日の諸々の予兆について尋ねた。それでアッラーの使徒は言った：その諸々の予兆の一つとして、奴隷女とその子供の増加がある。あるいは子供が自分の母親を奴隷のように扱う、親不孝の増加がある。また、世の末には貧しい羊飼いたちに現世の恩恵が授けられ、建築物の美しさや豪奢さを誇り合うようになるといったことがある。\n\nそれから預言者（アッラーからの祝福と平安あれ）は言った：その質問者はジブリールで、教友たちにこの純正な宗教を教えるためにやって来たのである、と。",
    "hints": [
          "預言者（アッラーからの祝福と平安あれ）のよい品性。彼は教友らと共に座っていた。",
          "質問者にやさしくし、近づくこと。それは質問者が億劫することも、怖がることもないようにするためである。",
          "教師に対する礼儀作法。ちょうどジブリール（彼に平安あれ）がしたように、預言者（アッラーからの祝福と平安あれ）から学ぶため、彼の前に礼儀正しく座ったようにである。",
          "イスラームの根幹は５つ、イーマーンの根幹は６つである。",
          "イスラームとイーマーンが並列される時、前者は外面的諸事、後者は内面的諸事と解釈される。",
          "宗教には様々なレベルがあるという説明：最初のレベルがイスラーム、２番目のレベルがイーマーン、３番目のレベルがイフサーンである。",
          "質問者はそもそも知識がないものであり、無知こそが人に質問させるものである。教友たちが驚いたのは、彼が質問しておきながら、答えを承認したことだった。",
          "重要な物事から始めること。というのも預言者（アッラーからの祝福と平安あれ）はイスラームを説明するにあたっては、まず信仰証言から、イーマーンを説明するにあたっては、まずアッラーへの信仰から始めたからである。",
          "知らないわけではないことを学がある者が質問するのは、他者にそれを教える目的があるためである。",
          "審判の日に関する知識は、アッラーが専有する知識である。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  4564: {
