    "explanation": "預言者（アッラーからの祝福と平安あれ）は、禁じられたものなのかどうか、ハラームなのかハラールなのか、疑わしいような言葉や行いを放棄することを命じた。そしてそうではなく、その善性と合法性に疑念の余地がなく、確信の域に達しているものへと向かうことを命じた。というのも心はそこへと安らぎ落ち着くものであり、疑念のあるものに対して心は不安になり、乱れた状態になるものなのである。",
    "hints": [
