    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「人間のあらゆる骨は、日が昇るあらゆる日においてサダカを課せられている。二人の間を公正に分けるのもサダカ、人を家畜において助け、彼をそこに乗せてやるか、または彼のためにその上に荷物を載せてやるのもサダカ、よい言葉もサダカ、サラーへと歩いて行く一歩一歩にもサダカがあり、路上から有害なものを取り除けるのもサダカなのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はこのように説明している：宗教義務を有する全てのムスリムには毎日、骨のあらゆる関節の数だけサダカを課せられている。それは無事安泰な状態と、骨が関節によって伸びたり曲がったりすることに関し、アッラーに感謝する意味で任意に行うものである。 サダカはお金によるものに限定されず、あらゆる善行によって行うことができる。例えば： 争い合う者たちの間を公正に調停することは、サダカである。 乗り物に乗ることが出来ない者を助けて乗せてやったり、荷物を載せてやったりすることはサダカである。 ズィクル、ドゥアー、挨拶といったよい言葉はサダカである。 サラー（礼拝）へ赴く一歩一歩はサダカである。 路上から有害なものを除去することは、サダカである。",
    "hints": [
          "人間の骨の構造とそれが健全である状態は、アッラーからの最大の恩恵の一つである。その恩恵に対する感謝をするため、全ての骨のためにサダカをしなければならない。",
          "恩恵が継続するよう、毎日感謝を改めることの勧め。",
          "毎日任意の行いやサダカを続けることの勧め。",
          "人々の間を調停することの徳。",
          "同胞を援助することの勧め。それはサダカである。",
          "集団のサラー（礼拝）に参加し、そこに歩いて赴くこと、およびマスジドの建設や管理の勧め。",
          "ムスリムの公道を大切にし、そこにおいて迷惑となるものや有害なものを除去することの義務。",
