    "attribution": "متفق عليه",
  },
  4704: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「この世では異邦人か旅人のようであれ。",
    "hadeeth": "アブドッラー・ブン・ウマル（アッラーのご満悦あれ）は言った：アッラーの使徒（アッラーからの祝福と平安あれ）は私の肩に手をやり、こう言った： 「この世では異邦人か旅人のようであれ。」イブン・ウマルはこう言ったものだった：「夕には朝を待つな。朝には夕を待つな。あなたの健康をあなたの病にあて、あなたの人生をあなたの死にあてよ。」",
    "explanation": "アブドッラー・ブン・ウマル（アッラーのご満悦あれ）は、預言者（アッラーからの祝福と平安あれ）が彼の肩に手を置いて、このように仰ったと伝えている：この世では、住むための家も、なぐさめとなる住人もなく、創造主以外のことに勤しませるような家族、扶養対象、人間関係などもない国を訪れた、異邦人のようであれ。むしろ異邦人よりももっとその土地には馴染みがなく、故郷を求めて道を通過するだけの旅人のようであれ、と。というのも異邦人は馴染みのない国に居住し滞在するかもしれないが、旅人は別の国を目指して通過するだけであり、目的地への到達に熱心なあまり、そこに滞在もせず、執着もしないからである。また、旅人は旅の目的地に到達させてくれるものよりも多くのものを、必要とはしない。このように信仰者は、目的の場に到達するため以外の余計なものを、現世で必要とはしないものだ。\n\nイブン・ウマルはこのアドバイスを実践し、こう言ったものだった：「夕には朝を待つな。朝には夕を待つな。あなた自身を墓場の民と見なせ。なぜなら人生は健康か病気いずれかの状態でしかないからだ。 ゆえに病気になった時のため、健康な時には服従行為に勤しめ。病気になってそうすることができなくなってしまった時のために、健康を善行に活用せよ。また、現世における人生を活用し、死後に役立つことに勤しめ。」",
    "hints": [
          "親近感と関心をひくため、教示する際に教える者が学ぶ者の肩に手を置くこと。",
          "求められてもいない者に対してアドバイスと教導を始めること。",
          "預言者（アッラーからの祝福と平安あれ）の優れた教育法：「この世では異邦人か旅人のようであれ」という言葉で、説得力のあるたとえを示した。",
          "来世における人々の歩みの違い：旅人は現世に対する態度において、異邦人よりも高い境地にある。",
          "楽観的希望を慎むことと、死への準備の説明。",
          "このハディースは与えられた糧を放棄し、現世の楽しみを禁じることを意味するわけではなく、現世欲を抑えることを促している。",
          "病気や死によって、それが出来なくなってしまう前に、善行へと急ぐこと。",
          "アブドッラー・ブン・ウマル（アッラーのご満悦あれ）の徳：彼は預言者（アッラーからの祝福と平安あれ）のこの戒めを活かすことができた。",
          "信仰者の故郷は天国であるため、彼は現世において異邦人であり、来世に向かう旅人である。彼の心はこの異国に執着せず、戻るべき故郷に結び付けられている。現世での滞在はそこでの必要事を果たし、故郷へ戻るための準備のために他ならない。",
        ],
    "grade": "صحيح",
    "attribution": "رواه البخاري",
  },
  4706: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「妬み合ってはいけない。値を吊り上げ合ってもいけない。憎み合ってもいけない。背を向け合ってもいけない。商談に割り込んでもならない。アッラーの僕たちよ、同胞であれ",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「妬み合ってはいけない。値を吊り上げ合ってもいけない。憎み合ってもいけない。背を向け合ってもいけない。商談に割り込んでもならない。アッラーの僕たちよ、同胞であれ。ムスリムはムスリムの同胞である。不正を働かず、見捨てもせず、蔑みもしない。敬虔さとはここなのであるｰ彼は自分の胸を3回指した−。ムスリム同胞を蔑むのは人にとって十分な悪である。全てのムスリムはムスリムにとって、その生命、財産、尊厳が神聖なのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はムスリムがその同胞に対してよくすることを命じ、いくつかの義務や礼儀作法などを説明した。 命令１：お互いに嫉妬してはならない。相手が授かっている恩恵の消失を望んだりしてはならない。 命令２：値を吊り上げ合ってはならない。自分自身はその商品を買う気もないのに、売り手の得や買い手の損を目的にそのようなことをしてはならない。 命令３：憎み合ってはならない。つまり、それは相手に害悪を望んでいる状態であり、愛情の反対である。ただしアッラーゆえに憎むことはこの限りではなく、それはむしろ義務となる。 命令４：背を向け合ってはならない。つまり相手を忌避して、遠ざけてはならない。 命令５：商談に割り込んでもならない。たとえば買い手に対し、「自分には同じ商品でもっと安いのがある」とか「もっといいのがある」などと提示することである。 それから預言者（アッラーからの祝福と平安あれ）は、話のまとめとしてこう命令した：今述べたような物事を放棄し、その代わりに、愛情、やさしさ、思いやり、慰め合い、よいことにおける助け合いといったことにおいて努力する、同胞であれ。心は清い状態に保ち、あらゆる状況において助言をせよ。 この同胞愛は、以下のような物事を要求する： ムスリム同胞に不正を働いたり、侵害したりしない。 ムスリム同胞が不正を被っているのに、その不正を除去して助けることができるにも関わらず、見捨てない。 ムスリム同胞を蔑まず、軽んぜず、馬鹿にもしない。そのような態度は心の傲慢さから生じるのである。 それから預言者（アッラーからの祝福と平安あれ）は３回、敬虔さとは心にあるのだと説明した。そしてよい品性、アッラーへの畏れの念、アッラーから見られている意識といった状態を伴う敬虔さが心の中にある者は、ムスリムを蔑んだりしないのである。ムスリム同胞を蔑むのは人にとって十分な悪であり、醜い品性であり、それは心の驕りから来るものである。 預言者（アッラーからの祝福と平安あれ）はこうして、以下のことを強調した。全てのムスリムはムスリムにとって、その生命が神聖である：つまり殺害やそれ以下の傷害、殴打などにより侵害を禁じられている。また、その財産も不当に侵害することが許されない、神聖なものである。そしてその尊厳も、その者自身やその家柄などを傷つけることが許されない、神聖なものなのである。",
    "hints": [
          "信仰上の同胞愛に必要なあらゆる物事の命令と、それに反するあらゆる言動の禁止。",
          "敬虔さの主柱は、アッラーに関する知識、畏れの念、その監視への意識といった、心の中にあるものである。この敬虔さからこそ、正しい行いが生まれるのだ。",
          "外面的な逸脱は、心の敬虔さの脆弱さの印である。",
          "言葉によるか行いによるかを問わず、ムスリムを害することはあらゆる形において禁じられている。",
          "相手と同様の状態になりたいと望むことは、その者の恵まれた状況の変化を望まない限り、禁じられた嫉妬ではない。それは単にあやかりたいという、合法な範囲のものであり、善への競争を促すものである。",
          "人間には、誰かが自分に勝ることを嫌う性質がある。それで人が自分に勝っている部分が消失すればいいのにと望むのは、禁じられた嫉妬である。そうではなく、自分も同じようなものを授かろうとするのが、合法な嫉妬である。",
          "買い手に対し、「あなたは騙されて大損してしまいますよ」といった助言をすることは、それが事実である限り、同胞の商売に割り込むではない。むしろそれは助言の義務である。ただし、その意図は売り手に損させることではなく、買い手のムスリムに対する真摯なものでなければならない。全ての物事は意図によるのである。",
