    "hadeeth": "ウマル・ブン・アル＝ハッターブ（アッラーのご満悦あれ）は、預言者（彼にアッラーからの祝福と平安あれ）がこのように語ったと聞いた: 「もしあなた方がアッラーに真のタワックル(委任)をしたならば、鳥がアッラーから糧を授かるように、あなた方も糧を授かったであろう。それらは朝には空腹で出かけても、夕には満腹で帰って来るのだ。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、以下のようなことを勧めている：現世と宗教に関する物事において、利益を導き、害悪を阻むことにあたってアッラーに依拠すること。というのもアッラーこそが与え、禁じ、害と利をもたらすお方だからである。 また、真摯さとアッラーへの依拠とともに、利益を導き、害悪を阻むことにあたって必要な物事を行うこと。そのようにすれば、アッラーは私たちに糧を授けて下さる。ちょうど朝には空腹で出かけても夕には満腹で帰って来る鳥に、アッラーが糧を授けているようなものである。鳥のこの行動は、丸投げの態度や怠惰さもなしに、糧を求める努力をするという必要な手段をとることの例である。",
