    "hadeeth": "イブン・アッバース（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「人々が訴えによって与えられるのであれば、男たちは民の財産や生命まで主張しただろう。しかし原告には明白な証拠が必要であり、拒否する者には誓いが必要なのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は言う：人々が根拠も状況証拠もなく、単なる訴えだけで（主張するものを）与えられるのであれば、ある種の人々は民の財産や生命に対する権利まで主張しただろう。しかし原告には明白な証拠と、その主張を裏付ける根拠が必要なのである。そして証拠がなければ、それを被告へと提示するが、もし被告がそれを拒否するのであれば、被告は誓いを行わなければならない。そうすることにより、無実が確定する。",
