  4725: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "私が禁じたものは避け、私が命じたものは、あなた方のできる範囲でそれを行え。まことにあなた方以前の者たちを滅ぼしたのは、質問の多さと、預言者たちに対する彼らの相違だったからだ。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は言った：私はアッラーの使徒（彼にアッラーからの祝福と平安あれ）が、こう言うのを聞いた：「私が禁じたものは避け、私が命じたものは、あなた方のできる範囲でそれを行え。まことにあなた方以前の者たちを滅ぼしたのは、質問の多さと、預言者たちに対する彼らの相違だったからだ。」",
    "explanation": "アッラーの使徒（彼にアッラーからの祝福と平安あれ）は、以下のことを私たちに教示した：彼が私たちに禁じたことは、例外なく回避しなければならないこと。そして彼が私たちに命じたことは、出来る限り行わなければならないこと。\nそれから彼は、私たちが過去の民のようにならないため、私たちに注意をした。それは過去の民が彼らの預言者たちと意見を別にし、多くの質問をしたことにより、アッラーによって様々な形で滅ぼされたからである。私たちは彼らと同様のことをして、彼らが滅ぼされたように滅んでしまってはならない。",
    "hints": [
          "命令されたことを行い、禁じられたことを避ける命令。",
          "禁止項目に関しては、それらの物事の一部を行うことを免除されなかった。一方、命令項目については、可能ならば、と限定された。なぜなら放棄することは可能なことだが、何かを行うことには命じられたことをするという能力が必要だからである。",
          "多くの質問の禁止。学者は質問を２つの種類に分類している：１つ目は宗教的物事において必要な知識を請うためであり、これはむしろ義務である。教友たちの質問は、この類いのものだった。２つ目は頑迷さからの質問や無意味な質問であり、こちらが禁じられる部類となる。",
          "過去の民が陥っていたように、預言者と意見を別にすることについての、イスラーム共同体への警告。",
          "禁止は数量の多寡を問わない。回避に多寡は関係ないからである。たとえば私たちは利子を禁じられたが、それは多かろうが少なかろうが、同じである。",
          "禁止事項につながる原因の放棄。それも回避の意味の中に入って来るからである。",
          "人間には可能性と能力がある。ハディースには、「あなた方のできる範囲で」とあるからだ。この中には、「人間に可能性はない。行動を強制されているからだ」と主張するジャバリーヤ（定命による強制論主義者）への反証がある。彼らは話す時に手を動かす仕草をする時でさえ、その仕草が自分自身の力によるものではない、と主張する。このような主張は虚偽であることに疑念の余地はなく、そこには甚大な害悪が伴う。",
          "使徒（彼にアッラーからの祝福と平安あれ）の命令を聞いておきながら、「これは義務ですか、それとも勧められることですか？」などと言うべきではない。彼は「あなた方のできる範囲でそれを行え」と言っているのだから。",
          "預言者（彼にアッラーからの祝福と平安あれ）が命じ、禁じることは、イスラーム法である。それがクルアーンの中にも存在することかどうかは関係ない。クルアーンの中にはない命令事項や禁止事項も、付加されるスンナとして実行しなければならない。",
