  4801: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「信仰者から現世の悩みを一つやわらげてやる者に、アッラーは審判の日の悩みの一つをやわらげてくださる",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「信仰者から現世の悩みを一つやわらげてやる者に、アッラーは審判の日の悩みの一つをやわらげてくださる。困難にある者にやさしくしてやる者に、アッラーは現世と来世においてやさしくしてくださる。ムスリムを匿ってやる者を、アッラーは現世と来世で匿ってくださる。アッラーはしもべがその同胞を援助している限り、しもべの援助にあられる。知識を求めて道をゆく者に、アッラーは天国への道をたやすくしてくださる。人々がアッラーの館の一つに集まり、アッラーの書を読誦し、それを互いに学び合えば、静寂がくだり、慈悲に包まれ、その周りを天使たちに囲まれ、アッラーから、そのみもとにいる者たちと共に讃えられないことはない。そして行いを遅らせる者に、その血筋が早められることはないのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、こう説明した：ムスリムの報いはアッラーの御許において、彼が他のムスリムに対して行うものと同種のものとなる。ゆえに、信仰者から現世の悩みや辛さを一つやわらげたり、解消したりしてやる者に対し、アッラーは審判の日の悩みの一つをやわらげてくださることで、報いて下さるのである。 また、困難にある者に対してやさしくし、便宜をはかり、その困難を除去してやる者に対し、アッラーは現世と来世においてやさしくしてくださる。 また、ムスリムにとって公にすることが憚れるような過ちや落ち度を目にしても、それを隠しておいてやる者に対し、アッラーは現世と来世で匿ってくださる。 また、アッラーはしもべがその同胞を宗教的または現世的な福利の達成のために援助している限り、その者の援助にあられる。援助は身体、財産、祈願などによるものも含む。 また、アッラーの御顔を意図するがゆえに、イスラームの知識を求めて道をゆく者に対し、アッラーは天国への道をたやすくしてくださる。 そして人々がアッラーの館の一つに集まり、アッラーの書を読誦し、それを互いに学び合えば、彼らに静寂と厳かさがくだり、アッラーの慈悲に包みこまれ、その周りを天使たちに囲まれないことはない。またアッラーは彼らを、そのみもとにいる者たちと共に讃えてくださる。最高位にいる者たちと共にアッラーから讃えられることだけで、この上ない栄誉なのである。 そして十分な行いもせず、行いに励む者たちの地位にまで達することが出来ないでいる者たちは、自分の血筋の高貴さや父祖の徳をあてにして、行いを蔑ろにしているべきではない。",
    "hints": [
          "イブン・ダキーク・アル＝イードはこう述べている。「これは、様々な種類の知識、原則、礼儀作法を包含する素晴らしいハディースである。この中には知識、財産、援助、有益な指摘や助言など、そうすることが出来るあらゆるものを用いて、ムスリムのニーズを満たし、彼らに益をもたらすことの徳が含まれている。」",
          "困難にある者に対して物事をやさしくしてやることの勧め。",
          "ムスリムを援助することの勧め。その同胞を援助する援助の度合いに応じて、アッラーもまた援助してくださるのである。",
          "ムスリムを匿うことには、落ち度の詮索をしないことも含まれる。ある先人はこう言った：「何の落ち度もない人々がいた。しかし彼らは他人の落ち度について口外したため、人々もまた彼らの落ち度を口外した。他方、落ち度がある人々がいた。しかし彼らは他人の落ち度について口をつぐんだため、彼らの落ち度は忘れ去られた。」",
          "人を匿うことが悪事を隠蔽し、それを止めさせないことを意味するわけではない。むしろそれを止めさせた上で匿うことが、悪事や放縦さで知られてはいない者に対する義務である。しかしそのような状態で知られている者に関しては、匿うことは推奨されない。そうすることでその者を却って悪事へと促し、その者だけでなく他の悪い者たちまで、人々への害悪へとより大胆にさせてしまうためである。",
          "知識を探究し、クルアーンを読誦・学習することの勧め。",
