  },
  4810: {
    "category_id": 3,
    "category": "神学",
    "title": "わが僕たちよ、われは自らに不正を禁じた。そしてそれをあなた方の間でハラーム（非合法）とした。ゆえに不正を働き合ってはならない",
    "hadeeth": "アブー・ザッル（アッラーのご満悦あれ）は、言った： アブー・ザッル・アル＝ギファーリー（アッラーのご満悦あれ）によると、預言者（アッラーからの祝福と平安あれ）は至高で偉大なるアッラーがこう仰せられたと伝えた：「わが僕たちよ、われは自らに不正を禁じた。そしてそれをあなた方の間でハラーム（非合法）とした。ゆえに不正を働き合ってはならない。わが僕たちよ、あなた方は皆迷い人である。われが導いた者を除いては。ゆえにわれに導きを求めよ、われがあなた方を導いてやろう。わが僕たちよ、あなた方は皆飢えた者である。われが食べさせた者を除いては。ゆえにわれに食べ物を求めよ、われがあなた方に食べ物を与えてやろう。わが僕たちよ、あなた方は皆裸である。われが服を着せた者を除いては。ゆえにわれに衣服を求めよ、われがあなた方に衣服を与えてやろう。わが僕たちよ、あなた方は夜に昼に過ちを犯す。そしてわれは全ての罪を赦す。ゆえにわれに罪の赦しを求めよ、われがあなた方を赦してやろう。わが僕たちよ、あなた方はわれを害するに至らず、それでわれを害することもない。また、われを益するに至らず、それでわれを益することもない。わが僕たちよ、あなた方の内の最初の者、最後の者、人間の者、ジンの者が、あなた方の内の一人の最も敬虔な者の心であったとしても、それがわが王権に何も付け足しはしない。わが僕たちよ、あなた方の内の最初の者、最後の者、人間の者、ジンの者が、あなた方の内の一人の最も放埒な者の心であったとしても、それがわが王権から何も差し引きはしない。わが僕たちよ、あなた方の内の最初の者、最後の者、人間の者、ジンの者が、一つの地に立ち、われに求めたとしても、われは各人に求めるものを与えただろう。そしてそのことは、ちょうど海に針が入れられた時に差し引きされる程のものしか、われのもとにあるものから何も差し引きはしない。わが僕たちよ、われがあなた方のために数え上げるのは、あなた方の行いなのだ。そしてわれはあなた方にそれをきちんと報いる。ゆえによいものを見出した者はアッラーを称え、そうでないものを見出した者は、自分自身以外を咎めてはならない。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、至高で偉大なるアッラーが以下のように仰せられたと伝えた：アッラーはご自身に不正を禁じ、そしてそれを被造物の間でもハラーム（非合法）とした。ゆえに不正を働き合ってはならない。 被造物はすべて、真理から迷った状態にある。ただしアッラーの導きと成功によるものは別であり、アッラーにそれを求める者に対して成功と導きを与えるのである。 被造物はすべて飢えた状態にあり、あらゆる必要ごとにおいてアッラーを必要とする存在である。アッラーに願う者はその必要を満たされ、十分な状態にしてもらえるのである。 また彼らは、夜に昼に過ちを犯す。そしてアッラーはかれに罪の赦しを求めるしもべを覆い、大目に見てくださる。 また彼らはアッラーを少しも害することもできなければ、益することもできない。 また、もし彼らが最も敬虔な者の心であったとしても、その敬虔さがアッラーの王権に何も付け足しはしない。 また、もし彼らが最も放埒な者の心であったとしても、それがかれの王権から何も差し引きはしない。というのも彼らはアッラーを必要とする弱い存在であり、あらゆる状況、時間、場所においてアッラーが必要だからである。アッラーこそは豊かで十全なお方であられる。 また、もし彼ら人間の者、ジンの者、最初の者、最後の者が、一つの場所に立ち、アッラーに求めたとしたら、アッラーは彼らのそれぞれに求めるものを与えただろう。そしてそのことはアッラーの御許から、何も減らしはしない。ちょうど海に針を入れて引き上げた時、海から何も減ったりはしないのと同様である。アッラーは完全な豊かさを備えたお方である。\n\nアッラーは僕たちの行いを記録し、数え上げる。そして審判の日、彼らにそれらをきちんと報いる。ゆえによい報いを見出した者は、アッラーがそのような服従へと自分を導いてくれたことに対し、アッラーを称えよ。そしてそうではない報いを見出した者は、悪へと傾いて失敗へと導いた自分自身を咎めよ。",
    "hints": [
          "このハディースは、預言者（アッラーからの祝福と平安あれ）がその主アッラーから伝えるものであり、聖なるハディースと呼ばれるものである。これは文言も意味もアッラーからのものではあるが、クルアーンが専有する特徴を兼ね備えてはいないものである。つまり、その読誦が崇拝行為となったり、それを読む際にはタハーラ（清浄）の状態にある必要があったり、その模倣を挑まれていたり、その模倣が不可能であったりするようなクルアーンの特徴のことである。",
          "しもべが得る知識、導きは、アッラーの導きと教示によるものである。",
          "しもべが手にした善はアッラーの恩恵によるもの、手にした悪は自分自身と欲望によるものである。",
          "よいことを行えたのなら、それはアッラーからの成功によるものであり、その報いもまたアッラーの恩恵によるものである。ゆえにアッラーにこそ称賛がある。他方、悪事を行なった者は、自分自身を咎めなければならない。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  4811: {
    "category_id": 3,
    "category": "神学",
    "title": "少年よ、（よい）言葉を教えてやろう。アッラーを守れ。そうすればアッラーがあなたを守ってくださるだろう。アッラーを守れ。そうすればあなたは、アッラーをあなたの前に見出すだろう。求めるなら、アッラーにこそ求めよ。助けを求めるなら、アッラーにこそ助けを求めよ",
    "hadeeth": "イブン・アッバース（アッラーのご満悦あれ）は言った： 「ある日、私はアッラーの使徒（アッラーからの祝福と平安あれ）の後ろに座っていた。彼は言った：”少年よ、（よい）言葉を教えてやろう。アッラーを守れ。そうすればアッラーがあなたを守ってくださるだろう。アッラーを守れ。そうすればあなたは、アッラーをあなたの前に見出すだろう。求めるなら、アッラーにこそ求めよ。助けを求めるなら、アッラーにこそ助けを求めよ。そして知るのだ。人々が一丸となって、あなたのために何か役立とうとしても、アッラーが既に定めたこと以外には、あなたの役に立つことはできない。また、彼らが一丸となって、あなたに対して何か害しようとしても、アッラーが既に定めたこと以外には、あなたに対して害することはできない。ペンは上げられ、ページは乾いてしまったのだ。”」",
    "explanation": "イブン・アッバース（アッラーのご満悦あれ）は、このように伝えている：彼がまだ小さい頃、預言者（アッラーからの祝福と平安あれ）の後ろに座っていた。彼（アッラーからの祝福と平安あれ）は言った：「私はあなたに、アッラーがそれによってあなたの役に立ててくれるような物事を教えてやろう。\n\nアッラーの命令を遵守し、その禁止事項を回避することで、アッラーを守れ。つまり、服従行為とアッラーへのお近づきを求める行為に勤しみ、アッラーに対する反抗や罪深い行為を避けるのだ。そのようにすれば、その報いとして、現世と来世においてアッラーがあなたを諸々の悪から守ってくださる。そしてどこにあろうと、かれはあなたの任務において、あなたを助けてくださる。\n\nあなたが何かを求めるなら、アッラーにしか求めてはならない。アッラーだけが、求める者に応じるお方だからである。\n\nまた、助けを求めるなら、アッラー以外に助けを求めてはならない。\n\nそしてこのように確信せよ。地上の民が一丸となって、あなたのために何か役立とうとしても、アッラーが既に定めたこと以外には、あなたの役に立つことはできない。また、地上の民が一丸となって、あなたに対して何か害しようとしても、アッラーが既に定めたこと以外には、あなたに対して害することはできない。\n\nこれらの物事は、アッラーの英知と知識に基づいて前もって書かれ、定められたのだ。アッラーの定めに変更はない。",
    "hints": [
