    "title": "僕が罪を犯して、こう言った：「アッラーよ、私の罪をお赦し下さい。」それで至高のアッラーはこう仰った：「わが僕は罪を犯した。そして彼にはその罪を赦し、それゆえに罰する主があることを知った。」",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によると、預言者（彼にアッラーからの祝福と平安あれ）はその主（アッラー）から伝えるものとして、こう言った：僕が罪を犯して、こう言った：「アッラーよ、私の罪をお赦し下さい。」それで至高のアッラーはこう仰った：「わが僕は罪を犯した。そして彼にはその罪を赦し、それゆえに罰する主があることを知った。」それから、彼はまた罪を犯し、言った：「アッラーよ、私の罪をお赦し下さい。」それで至高のアッラーはこう仰った：「わが僕は罪を犯した。そして彼にはその罪を赦し、それゆえに罰する主があることを知った。われはわが僕を赦したぞ、望むことをするがよい。」",
    "explanation": "僕が罪を犯し、「アッラーよ、私の罪をお赦し下さい」と言えば、至高のアッラーは仰る：「わが僕は罪を犯した。そして彼にはその罪を赦し、それを覆い隠し、大目に見られる、あるいはそれゆえに罰する主があることを知った。」それから彼は、また罪を犯し、言う：「アッラーよ、私の罪をお赦し下さい。」それで至高のアッラーはこう仰る：「わが僕は罪を犯した。そして彼にはその罪を赦し、それを覆い隠し、大目に見られる、あるいはそれゆえに罰する主があることを知った。われはわが僕を赦したぞ、望むことをするがよい。罪を犯しても、その後に正しい悔悟をするのだ。そのようにする限り、罪を犯し、悔悟するならば、われは彼を赦す。悔悟はそれ以前のものを帳消しにするのである。」",
    "hints": [
          "主アッラーこそ、お望みになればお赦しになり、お望みになれば罰されるという権限を有すると信じている限り、アッラーの僕たちに対するご恩寵とご慈悲は偉大であること。",
          "正しい悔悟は罪滅ぼしとなる。",
