    "title": "まことに公平な者たちは、アッラーのもとで光の台座の上にある。彼らは彼らの裁決、彼らの家族、彼らが任されたことにおいて公正な者たちである。",
    "hadeeth": "アブドッラー・ブン・アムル・ブン・アル＝アース（彼らにアッラーの御満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「まことに公平な者たちは、アッラーのもとで光の台座の上にある。彼らは彼らの裁決、彼らの家族、彼らが任されたことにおいて公正な者たちである。」",
    "explanation": "このハディースには、自分の統治下と裁きの下にある者たちに対し、真理と公正さでもって裁く者たちへの吉報がある。また、彼らは審判の日、アッラーの御許での栄誉として、本当に光の台座の上に置かれる。この台座は慈悲あまねきお方アッラーの右手側にあるが、このことはアッラーに右側、手があることの根拠である。それを無効化したり、どのようなものなのかと想像したり、被造物のそれと同類と見なしたり、別なものと解釈したりしてはならない。",
