  4947: {
    "category_id": 3,
    "category": "神学",
    "title": "「私の共同体の者たちは、拒む者を除いてすべて天国に入る。」このような声が上がった：「アッラーの使徒よ、誰が拒むでしょうか？」彼（預言者）は言った：「誰であれ、私に従う者は天国に入り、私に反する者は（それを）拒んだのだ。」",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）はこう言った：「私の共同体の者たちは、拒む者を除いてすべて天国に入る。」このような声が上がった：「アッラーの使徒よ、誰が拒むでしょうか？」彼（預言者）は言った：「誰であれ、私に従う者は天国に入り、私に反する者は（それを）拒んだのだ。」",
    "explanation": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの祝福と平安あれ）はその共同体に吉報を伝えて、こう言った：「私の共同体の者たちは、すべて天国に入る。」私の共同体とは、つまりイスラーム共同体のことである。それから、それらの者たちから「拒む者」を除外した。つまり、それは天国に入る原因となる服従行為を放棄することによって、「反抗」する者たちのことである。なぜなら、何かを達成するために絶対に必要なことを放棄するのは、それを拒むのと同様だからである。この除外は、厳しい警告である。\nまた、この「共同体」が、イスラームへと呼びかけている共同体のことと解釈するのであれば、「拒む者」は「服従することを受け入れないことによって、不信仰の状態にある者」ということになる。\n教友たちはこう言った：「アッラーの使徒よ、誰が拒むでしょうか？」\nそれで預言者（彼にアッラーからの祝福と平安あれ）は、答えて言った：「誰であれ、私に従う者」つまり預言者がもたらしたものに服従する者は、天国に入ると。\n一方、「私に反する者」つまり信じず、禁じられた物事を行う者は、「（それを）拒んだ」つまり拒否したことにより、悪い帰着地がある。\n結論として、「拒んだ者」が不信仰だった場合、そもそも天国には入らない。一方、それがムスリムだった場合、地獄の焔で浄められるまでは天国には入れない、ということにある。ただし、アッラーのお赦しにより、多くの罪を犯していたとしても、罰されないということもあり得る。",
    "hints": [
          "アッラーは慈悲を授け、慈悲の世界へと入れるために、その僕たちを創造した。",
          "使徒（彼にアッラーからの祝福と平安あれ）は、その主からの伝達者である。",
          "使徒（彼にアッラーからの祝福と平安あれ）に反抗する者は、アッラーのご慈悲を拒否したのである。",
          "アッラーとその使徒に対する反逆は、地獄行きを原因づける。",
          "使徒（彼にアッラーからの祝福と平安あれ）の導きに従うことによって、人は現世と来世における成功を獲得する。",
          "このハディースには、この共同体の中の従順な者たちに対する、最も偉大な吉報がある。彼らは皆天国に入るが、アッラーとその使徒に反抗し、私欲や欲望に従う者だけがそうではないのである。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承",
  },
  4965: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "遺産相続までさせるのではないか、と私が思ってしまうほど、ジブリールは私に対し、隣人へ（の配慮を）命じ続ける。",
    "hadeeth": "アーイシャ（彼女にアッラーのご満悦あれ）とアブドッラー・ブン・ウマル（彼らにアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「遺産相続までさせるのではないか、と私が思ってしまうほど、ジブリールは私に対し、隣人へ（の配慮を）命じ続ける。」",
    "explanation": "隣人への遺産相続を命じる啓示をもたらすのではないか、と私（預言者）が思ってしまうほど、ジブリールは私に対し、隣人への配慮を命じ続けている。",
    "hints": [
