  },
  5273: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "まことに、まじない、お守り、ティワラの術はシルクである。",
    "hadeeth": "アブドッラー・ブン・マスウード（彼にアッラーのご満悦あれ）は言った：私は、アッラーの使徒（彼にアッラーからの平安と祝福あれ）がこう言うのを聞いた：「まことに、まじない、お守り、ティワラの術はシルクである。」",
    "explanation": "使徒（彼にアッラーからの平安と祝福あれ）は、害悪を阻止し、利益を導くために、アッラー以外のものであるこれらの物事を用いることはシルクだと述べている。なぜなら害悪を阻み利益をもたらすのは至高のアッラー以外にないからであり、この預言者の言葉は、これらの行為が禁じられていることを表している。\nまじない（ルクヤ）、お守り（タミーマ）、ティワラの術は、アッラーに対するシルクである。「お守り」とは、玉などでできたものを子供にかけるものであり、「ティワラの術」とは、夫婦が相手の愛情を得るために行う術である。尚、まじない（ルクヤ）については、３つの条件を満たしたものが合法とされる：つまり①それ自体が、アッラーをよそに役立つものだと考えないこと。もしそのように考えるのであれば、それはシルクであり禁じられる。それをアッラーのお許しなしには役に立たない、単なる原因の一つと考えなければならない。➁イスラーム法に反していないこと。アッラー以外のものへの祈願や、ジンなどの援助を乞うことなどを含む場合、これもシルクとなり、禁じられる。③理解可能なものであること。暗号や魔術の類であれば、それは許されない。",
    "hints": [
          "信条を、それを乱すものから維持することの奨励。たとえそれが、人々の間でまかり通っていることであったとしても、である。",
          "ここで言及されている物事の使用の非合法性。",
          "ハディースの中で描写されているシルクは、大シルクか小シルクか？それは当人の意図による。たとえば、ティワラの術において、愛情をもたらすのがアッラーであるという信条をもって行った場合、それは小シルクである。もしティワラの術そのものがそういった効果をもたらすと信じるのであれば、それは大シルクである。",
          "イスラーム法に則った形式のもの以外のまじない（ルクヤ）はシルクであり、禁じられる。",
        ],
    "grade": "真正",
    "attribution": "イブン・マージャの伝承 - アブー・ダーウードの伝承 - アハマドの伝承",
  },
  5326: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「陰口（ギーバ）を知っているか？」人々は言った：「アッラーとその使徒がよくご存じです。」預言者は言った：「あなたの同胞が嫌がることによって、彼について話すことである。」",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼はこう言った：「陰口（ギーバ）を知っているか？」人々は言った：「アッラーとその使徒がよくご存じです。」預言者は言った：「あなたの同胞が嫌がることによって、彼について話すことである。」すると、こう聞かれた：「もし私が言うことが、私の同胞にあてはまっていたら、どうですか？」預言者は言った：「あなたの言うことが彼にあてはまっているのなら、あなたは彼の陰口を言ったことになる。もしそうでないのなら、あなたは彼に対して嘘をついたのだ。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、「陰口（ギーバ）」の真実について説明する。陰口とは、その場にいないムスリムについて、彼が嫌に感じるようなことを語ることである。それが外見上のことか、内面上のことかは問わず、実際にその描写があてはまっていたとしても、それが陰口である。もしその描写があてはまっていなかったら、それは禁じられている陰口の上に、その無実な人に対する嘘やねつ造を擦り付けていることになる。",
    "hints": [
          "陰口の意味の説明。それはムスリムについて、彼が嫌に感じるようなことを語ることである。",
          "不信仰者については、権利上の陰口は禁じられない。なぜならハディースの中では陰口が「同胞」と限定されているためであり、それはムスリムのことだからである。",
          "その人には実際にはないようなことを陰口として語るのは、嘘である。",
          "アッラーの使徒（彼にアッラーからの祝福と平安あれ）の教育法の秀逸さ。彼は質問形式で、問題を取り上げた。",
          "使徒（彼にアッラーからの祝福と平安あれ）に対する、教友たちの礼儀作法。彼らは「アッラーとその使徒がよくご存じです」と言った。",
