    "explanation": "ハディースには、大小問わずムスリムの諸事を委任され、彼らに対して困難を課すような者に対する厳しい警告が含まれている。それは、アッラーがそれらの者たちに対して同様のもので報いることを、アッラーの使徒（彼にアッラーからの祝福と平安あれ）が祈っていることに表われている。",
