  5331: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "まことに、ある者たちはアッラーの財産において不当な振る舞いをしている。彼らには審判の日、火獄があろう。",
    "hadeeth": "ハウラ・アル＝アンサーリーヤ（彼女にアッラーのご満悦あれ）は言った：アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「まことに、ある者たちはアッラーの財産において不当な振る舞いをしている。彼らには審判の日、火獄があろう。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、ムスリムたちの財産において不当な振る舞いをし、それを不正に私物化する人々について語った。その中には孤児の財産、寄進された財産（ワクフ）を不当に貪ること、信託の無視、正当な権利や許可もなく公共財産に手を付けることなども含まれる。預言者（彼にアッラーからの祝福と平安あれ）はこれらの行いの報いが、審判の日の火獄であると述べている。",
