  5332: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "憶測をしてはいけない。憶測は最大の嘘の話だから。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼はこう言った：「憶測をしてはいけない。憶測は最大の嘘の話だから。」",
    "explanation": "このハディースには、根拠もない憶測に対する注意がある。つまり、単なる憶測に基づいて、諸々の決定を行うことの注意である。このようなことは悪い品性であり、最大の嘘である。なぜなら憶測する者が、根拠とはならないものに基づき、それを拠り所とし、事実であると確信してしまった時、それは嘘、それも最大の嘘になってしまうからである。",
    "hints": [
