  5335: {
    "category_id": 6,
    "category": "宣教と勧善懲悪",
    "title": "アッラーから人々の世話を任されたいかなる僕も、その世話すべき人々に対して欺いた状態のまま死ぬべき日に死んだ者は、アッラーから天国を禁じられる。",
    "hadeeth": "マァキル・ブン・ヤサール（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼はこう言った：「アッラーから人々の世話を任されたいかなる僕も、その世話すべき人々に対して欺いた状態のまま死ぬべき日に死んだ者は、アッラーから天国を禁じられる。」",
    "explanation": "マァキル・ブン・ヤサールが伝えるこのハディースには、世話を任された者を欺く者に対する警告が含まれている。「アッラーから人々の世話を任されたいかなる僕も」とは、つまり人々の世話を任されることであり、それらの者たちのために役立つことを行い、その諸事において指導する地位を与えられた保護者のことである。\n「その世話すべき人々に対して欺いた状態のまま死ぬべき日に死んだ者は」つまり、彼らを騙した状態で、悔悟することなく、魂が引き抜かれる時を迎えた者のことである。 欺きや至らなさについて悔悟する者は、この警告には該当しない。\n人々の監督において欺いた者は、それが公共的なものであれ、私的なものであれ、正直かつ信頼される預言者（彼にアッラーからの祝福と平安あれ）によって「アッラーから天国を禁じられる」と警告されている。その意図するところは、このような行為を合法と見なした者のことであり、また別の見解では、「先代の者たちと共に天国に入ること」が禁じられる。",
    "hints": [
          "自分の監督下にある者たちの諸事を軽んじる者への、厳しい警告。",
          "このハディースは、イスラーム共同体の長やその代理人らに限定されたものではない。そうではなく、アッラーが誰かの監督を任せたあらゆる者に適用される、一般的なものである。そこには父親、学校長なども入って来ることになる。",
          "死が訪れる前に欺きの行為から悔悟した者は、この警告の対象とはならない。",
          "統治下にある民の権利を軽んじ、彼らの諸事をおろそかにする統治者への警告。",
          "統治者が、民に忠告することにおいて最大限の努力を行うことの義務の説明。そしてそこにおいて怠る者が、勝利者たちと共に天国に入ることを禁じられること。",
          "イスラームにおける統治者の地位の重要性。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  5344: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "全てのアーダムの子らは過ちを犯すもの。そして過ちを犯す者で最善の者が、悔悟する者たちなのである。",
    "hadeeth": "アナス・ブン・マーリク（彼にアッラーのご満悦あれ）は言った：アッラーの使徒（彼にアッラーからの平安と祝福あれ）は、こう言った：「全てのアーダムの子らは過ちを犯すもの。そして過ちを犯す者で最善の者が、悔悟する者たちなのである。」",
    "explanation": "人は、罪を犯さずにはいられない。人間は生来弱く創られているものであり、命じられたことの遂行や禁じられたことの放棄において、なかなか主に従うことが出来ない。しかし至高のアッラーは僕たちに、悔悟の扉を開いて下さった。そして「過ちを犯す者で最善の者」が、頻繁に「悔悟する者たち」である、と仰っているのだ。",
    "hints": [
