    "title": "私はアッラーの使徒（彼にアッラーからの平安と祝福あれ）に尋ねた：「どの罪が最も大きいでしょうか？」彼は言った：「あなたを創造されたアッラーに、同位者を置くことである。」",
    "hadeeth": "アブドッラー・ブン・マスウード（彼にアッラーのご満悦あれ）は言った：私はアッラーの使徒（彼にアッラーからの平安と祝福あれ）に尋ねた：「どの罪が最も大きいでしょうか？」彼は言った：「あなたを創造されたアッラーに、同位者を置くことである。」私は言った：「その次は？」彼は言った：「次いで、あなたの子があなたの食いぶちを減らすことを怖れて、殺すことである。」私は言った：「その次は？」彼は言った：「次いで、隣人の妻と姦淫することである。」",
    "explanation": "教友たち（彼らにアッラーのご満悦あれ）は、どの罪が最も大きなものかを尋ね、それに対してアッラーの使徒（彼にアッラーからの平安と祝福あれ）は、それが大シルクであると答えた。大シルクは悔悟をもってでしか、アッラーが赦すことのないものである。その状態で死を迎えた者は、地獄に永遠に留まることになる。\nそれに次ぐ罪として、子供が自分の食いぶちを減らすことを怖れて、殺してしまうことが挙げられている。アッラーが禁じた生命を奪うことが、最大の罪の２番目として取り上げられている。それが自分の親族であれば、その罪は増加し、罰は倍増する。そしてその殺人の理由が、アッラーによる糧からその者を断つつもりだったならば、更にその罪悪に拍車をかけることになる。\n次いで挙げられたのが、隣人の妻との姦淫である。姦淫が大罪の３番目として取り上げられているが、その相手がイスラーム法において善行、親切、よい付き合いを命じられている隣人の妻である時、その罪は甚大なものとなるのだ。",
