    "title": "会えば互いに背き合うようにして、その同胞を３夜を超えて避け続けることは、ムスリムにとって許されない。そして彼らの内より優れているのが、先に挨拶を始める方なのだ。",
    "hadeeth": "アブー・アイユーブ・アル＝アンサーリー（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「会えば互いに背き合うようにして、その同胞を３夜を超えて避け続けることは、ムスリムにとって許されない。そして彼らの内より優れているのが、先に挨拶を始める方なのだ。」",
    "explanation": "ハディースにある通り、会えば互いに背き合い、挨拶も話もしないというような形で、ムスリム同胞を３夜を超えて避け続けることは、ムスリムにとって禁じられている。ここから理解できるのは、３夜までだったら、避けることは許されるということである。それは人間の性格を配慮したものであり、人間というものが生来怒りやすく、悪い性格になりがちなためである。そのような兆候を治めるために、３日以内のものは大目に見られるというわけだ。ここで「避ける」というのは、あくまで本人の考えを主体として避けることを意味し、アッラーゆえに避けることを意味するものではない。つまり、罪深い者や、宗教において新奇な物事を行う者や、悪友のことなどではない。それらの者たちを避けることに関しては特定の期間はなく、むしろそれらの状態が変わるまでの間となる。\nそしてお互いに避け合う者たちの内、より優れているのが、先に避けるのをやめ、挨拶を始める方なのだ。",
