    "explanation": "このハディースでは、近親関係の維持の勧めと、それがアッラーのお喜びの獲得を始めとした、いくつもの利益をもたらすことを説明している。たとえば、それは現世で僕が望む、最愛のものを獲得する原因ともなる。その１つが糧の増加と、長生きである。アッラーはクルアーンの中で、『アッラーは誰のことも、その（死という）期限が到来したら、延期して下さらない』（６３：１１）と仰っているが、この意味は、「長生きを原因づける諸要因を満たした後に到達する期限」ということである。たとえば、そもそもは５０年の寿命であっても、死の前に近親関係を改善することで６０年の寿命となることも定められている者は、決してその寿命が６０年以上になることはない。そしてこのようなことは最初からアッラーがご存じなのだが、ある種の天使たちには知らされていない。また、アッラーはクルアーンの別の箇所で、『アッラーはお望みのものを抹消され、また、定着させられる。そしてかれの御許には、書の母があるのだ』（１３：３９）と仰っている。アッラーは、「天使たちが扱うことのできる書」から、抹消したり、そのまま定着させたりもする。しかし「書の母」には、あらゆる詳細が記されており、そこにおいても何も変更は生じないのである。",
