    "category": "諸々の徳と礼儀作法",
    "title": "僕が彼の主に最も近付くのは、彼がサジダ（平伏礼）している時である。だから祈願を沢山するのだ。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼はこう言った：「僕が彼の主に最も近付くのは、彼がサジダ（平伏礼）している時である。だから祈願を沢山するのだ。」",
    "explanation": "アブー・フライラ（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼は言った：「僕が彼の主に最も近付くのは、彼がサジダ（平伏礼）している時である。」人間はサジダする時、身体器官の中で最も高貴な部分を、足が通る場所につける。また、身体の中で最も高い位置にある部分である顔を、身体で最も低い位置である足の高さまで落とす。こうして偉大なアッラーに屈従し、身を低め、謙虚になって、顔も足も同じ高さにするのである。サジダをする時に僕が主に最も近づくというのは、こういう所以である。預言者（彼にアッラーからの祝福と平安あれ）は、サジダの状態にある時に、沢山祈願をすることを命じた。こうしてアッラーに対する謙虚さが、その中に状態と言葉が揃った形で実現するのである。ゆえに人間はサジダした際、「スブハーナ・ラッビヤ・ル＝アァラー（至高のわが主に称えあれ）」と唱える。そこには、アッラーこそがその本質と属性において至高のお方であり、アッラーの荘厳さと偉大さに比べれば、人間は低く劣った存在であるという示唆が含まれている。",
    "hints": [
          "サジダにおいて祈願を沢山することの勧め。また、サジダしている時の祈願は、受け入れられやすいということ。",
          "服従行為は、僕のアッラーに対するお近づきを強める。",
          "僕が服従を増せば増すほど、アッラーはその祈願に応じて下さる。",
          "イスラーム共同体への善、その要因、その部門の教示における、アッラーの使徒（彼にアッラーからの祝福と平安あれ）の熱心さ。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  5435: {
