    "category": "法学と法源学",
    "title": "暁の礼拝を行った者は、アッラーの保護下にある。ゆえにその者の保護に関して、アッラーがあなた方に何らかの問責をするようなことがあってはならない。",
    "hadeeth": "ジュンダブ・ブン・アブドッラー（彼にアッラーのご満悦あれ）は言った：アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「暁の礼拝を行った者は、アッラーの保護下にある。ゆえにその者の保護に関して、アッラーがあなた方に何らかの問責をするようなことがあってはならない。かれ（アッラー）がその保護に関して問責した者は、逃れられない。そしてかれは、顔から地獄の炎へと投げ込まれることになるのだ。」",
    "explanation": "暁（ファジュル）の礼拝を行った者は、アッラーとの契約下に入ったようなものであり、いかなる悪からも守られるというアッラーとの契約を結んだようなものである。ゆえに、その者を害することは許されない。なぜなら、その者に対する害は実際のところアッラーに対する侵害であり、ファジュルの礼拝をした者にアッラーから授けられた保護を無視するものであるためだ。アッラーの契約を無視し、侵害する者は、自らをアッラーに歯向わせているようなものである。アッラーは、かれが保護下に入れた者を害する者に、報復される。",
    "hints": [
