    "explanation": "預言者（アッラーからの祝福と平安あれ）はこう言った：アッラーを信じ、そして自らの帰りどころであり、そこにおいて行いの報いを受けることになる最後の日を信じる者は、その信仰心によって、以下の特質が現れるものである：\n\n１．よいことを語ること：つまり、アッラーの賛美、タウヒードの言葉、勧善懲悪、人々の仲裁といったことである。もしこのような言葉を発せられないならば、口をつぐみ、害を与えるようなことから慎み、舌を守るべきである。\n\n２．隣人によくすること：善行をほどこしたり、危害を加えたりはしないことである。\n\n３．あなたを訪問する客人によくすること：つまりよい言葉を語ったり、食べ物をご馳走したりすることである。",
