  5456: {
    "category_id": 3,
    "category": "神学",
    "title": "アーダムの子よ、われに祈り、われを望むのであれば、われはあなたの内にあるものにも関わらず、あなたを赦し、気にはしない",
    "hadeeth": "アナス（アッラーのご満悦あれ）は言った： 私はアッラーの使徒（アッラーからの祝福と平安あれ）が、こう言うのを聞いた：「至高のアッラーは仰った：「アーダムの子よ、われに祈り、われを望むのであれば、われはあなたの内にあるものにも関わらず、あなたを赦し、気にはしない。アーダムの子よ、あなたの罪が天の高きにまで至ったとしても、われに罪の赦しを乞うならば、われはあなたを赦し、気にはしない。アーダムの子よ、大地いっぱいの過ちと共にわれのもとにやって来たとしても、われに何も並べない状態でわれに見えたならば、われはあなたのもとにそれといっぱいほどの赦しと共にやって来たであろう。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、神聖ハディースの中で、至高のアッラーがこう仰ったと伝えている：「アーダムの子よ、あなたがわれに祈り、われの慈悲を望み、絶望しない限り、われはあなたの罪を覆い隠し、帳消しにし、それを気にはしない。たとえその罪と反逆が大罪であったとしても、である。 アーダムの子よ、あなたの罪の余りの多さゆえに、それが天地を覆い、天の高きにまで至り、その隅々を埋め尽くしてしまうほどだったとしても、われに罪の赦しを乞うならば、われはその多さなど気にすることなく、あなたのためにそれを赦し、全て抹消してやる。\n\nアーダムの子よ、たとえあなたが死後、大地いっぱいの過ちと罪と共にわれのもとにやって来たとしても、われだけを神とし、われに何も並べない状態で死んだのであれば、われはあなたのそれらの罪に大地いっぱいの赦しで報いてやる。というのもわれは赦し深いのであり、シルク以外のあらゆる罪を赦すからである。」",
    "hints": [
