    "category": "諸々の徳と礼儀作法",
    "title": "ドゥアー（祈願）は崇拝行為である。",
    "hadeeth": "アン＝ヌゥマーン・ブン・バシール（彼らにアッラーのご満悦あれ）が預言者（彼にアッラーからの平安と祝福あれ）から伝えるところによれば、彼は言った：「ドゥアー（祈願）は崇拝行為である。」\nまた、アナス（彼にアッラーのご満悦あれ）の伝承では、このような言葉で伝えられている：「ドゥアーは崇拝行為の真髄である。」",
    "explanation": "「ドゥアー（祈願）は崇拝行為である。」これは、アッラーに祈願することが、被造物がアッラーを崇拝するにあたっての崇拝行為の基本であることを示している。なぜなら人間はアッラー以外のものに対する希望を断ち、無力さをさらけ出し、自分の主だけを祈願し、それ以外のものには心が向かわないような状態の時、アッラーの完全性と、かれが祈願に応じてくれるお方であることを認めるからである。また、かれが全てをお聞きになり、近くにおられるお方であり、全能のお方であることを認めるのである。これこそは崇拝行為の真実であり、タウヒード（アッラーの唯一性信仰）の真髄である。\n一方、「ドゥアーは崇拝行為の真髄である」という言葉は、崇拝行為がそれなしでは成立しないところの、崇拝行為の基軸であり魂であるという意味である。それはちょうど、人間が脳なしでは成立しないようなものである。",
