    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）がアッラーの使徒（彼にアッラーからの平安と祝福あれ）から伝えるところによれば、彼は言った：「舌に軽く、秤には重く、慈悲あまねきお方に愛される、２つの言葉：スブハーナッラーヒ・ワ・ビハムディヒ、スブハーナッラーヒ・アル＝アズィーム」",
