  5512: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "施しが財産を減らすことはない。僕は赦しによって、アッラーからその威光を増加させられる。アッラーに対して謙虚である者を、アッラーは高めずにはおかない。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「施しが財産を減らすことはない。僕は赦しによって、アッラーからその威光を増加させられる。アッラーに対して謙虚である者を、アッラーは高めずにはおかない。」",
    "explanation": "「施しが財産を減らすことはない」とは、施しは財産を減らすのではなく、むしろ増加させ、祝福し、そこから悪を防いでくれるということ。財産の増加は量的なものであったり、質的なものであったりする。前者は、アッラーが様々な糧の扉を僕のために開いてくれることであり、後者は施したものよりも多くの祝福を与えてくれるようなことである。\n「僕は赦しによって、アッラーからその威光を増加させられる」とは、赦しの心を知り、非難や叱責を放棄する者は、人々の心をつかみ、その威厳と尊さが増し、現世と来世における地位が高められるということである。\n「アッラーに対して謙虚である者を、アッラーは高めずにはおかない」とは、アッラーの御前に縋りつくようにして身を低め、被造物に対しては物腰が柔らかく、ムスリムたちに対しては気取りのないような者のことである。このような性質を持った者は、現世では高められ、人々の心においては愛される存在となり、天国においては高い位階を得ることになる。",
    "hints": [
