    "title": "アッラーは審判の日、同胞の尊厳を守ってやる者の顔を、地獄の炎から守って下さる。",
    "hadeeth": "アブー・アッ＝ダルダーゥ（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼は言った：「アッラーは審判の日、同胞の尊厳を守ってやる者の顔を、地獄の炎から守って下さる。」",
