  5516: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "＂スブハーナッラーヒ・ワ・ビハムディヒ＂と一日に１００回言う者は、その罪を落とされる。たとえそれが、海の泡ほどだったとしても、である。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの平安と祝福あれ）は言った：「＂スブハーナッラーヒ・ワ・ビハムディヒ＂と一日に１００回言う者は、その罪を落とされる。たとえそれが、海の泡ほどだったとしても、である。」",
    "explanation": "このハディースの中には、この形式によるタスビーフ（アッラーをあらゆる欠点から無縁として称える称賛の言葉）を含むこのズィクル（念唱）の徳が含まれている。また、一日に１００回「スブハーナッラーヒ・ワ・ビハムディヒ（いかなる欠損からも無縁なアッラーに称えあれ、かれの完全なる性質ゆえの賞賛と共に）」と唱える者の罪を、たとえそれが海の泡の数ほど多かったとしても、アッラーが帳消しにして下さることを述べている。これはアッラーをズィクルする者たちへの、アッラーからの恩寵である。\nこのズィクルはハディースに「一日に」とあるように、朝のズィクルであると同様、夕のズィクルでもある。アブー・フライラ（彼にアッラーのご満悦あれ）による別のハディースによれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言っている：「＂スブハーナッラーヒ・ワ・ビハムディヒ＂と朝を迎える時と夕を迎える時に１００回言う者よりも、審判の日によいものを携えて来る者はいない。ただしその者と同様に唱えた者、あるいはそれ以上唱えた者は、その限りではない。」（ムスリムの伝承）",
    "hints": [
          "アッラーに対するタスビーフ、つまりアッラーをかれに相応しくないあらゆる欠点や落ち度から無縁として称える称賛の言葉を含む、このズィクル（念唱）の徳。",
          "このハディースを表面的に解釈すれば、この褒美はこのズィクルをいかなる形であっても、一日に１００回唱えた者に対するものである。それを連続で唱えても断続的に唱えてもよいし、昼に一部を唱えて残りを夜に唱える、というやり方でもよいということである。",
          "このハディースの中には、僕には選択の余地がなく、行動を強制されているといった主張への反論がある。",
