    "hadeeth": "アブー・アイユーブ（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの祝福と平安あれ）から伝えるところによれば、彼は言った：「＂ラー・イラーハ・イッラッラーフ・ワフダフ・ラー・シャリーカ・ラフ、ラフ・アル＝ムルク、ワ・ラフ・アル＝ハムド、ワ・フワ・アラー・クッリ・シャイイン・カディール（いかなる共同者もない、唯一のアッラーの他に真に崇拝すべきものはなし。かれにこそ主権と全ての賛美は属し、かれこそは全能のお方である）＂と１０回唱えた者は、イスマーイールの子孫の内の者を４人解放したようなものである。」",
    "explanation": "このハディースの中には、タウヒード（アッラーの唯一性信仰）の承認を含む、このズィクル（念唱）の徳が示されている。また、このズィクルの意味を知り、それが要求するところのものを行いつつ、それを１０回唱えた者には、イブラーヒームの息子イスマーイール（彼らに平安あれ）の子孫の奴隷を４人解放したのと同様の褒美がある、としている。",
    "hints": [
