    "hadeeth": "ムアーウィヤ・ブン・アビー・スフヤーン（彼らにアッラーのご満悦あれ）は言った：アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「アッラーは、かれが良いことを望まれる者に、宗教における理解力を与える。」",
