    "title": "あなた方はあなた方の主を、あなた方がこの月を何の陰りもない状態で見るように、見ることになろう。",
    "hadeeth": "ジャリール・ブン・アブドッラー・アル＝バジャリー（彼にアッラーのご満悦あれ）は言った：私たちが預言者（彼にアッラーからの祝福と平安あれ）と一緒にいる時、彼は満月の夜の月を見て言った：「あなた方はあなた方の主を、あなた方がこの月を何の陰りもない状態で見るように、見ることになろう。ならば、太陽が昇る前の礼拝と、それが沈む前の礼拝をやり過ごさないようにできるならば、そうするがよい。」なお、別の伝承にはこうある：「彼は１４番目の夜の月を見て言った・・・」",
    "explanation": "ジャリール・ブン・アブドッラー・アル＝バジャリー（彼にアッラーのご満悦あれ）によれば、彼らが預言者（彼にアッラーからの祝福と平安あれ）と共にある時、彼は満月の夜－１４夜目－の月を見て、言った：「あなた方はあなた方の主を、あなた方がこの月を何の陰りもない状態で見るように、見ることになろう。」つまり、審判の日と天国において、信仰者たちはアッラーのことを満月の夜の月を見るように、目にすることになる。ただし、これはアッラーが月のようである、ということではない。アッラーに似ているものは何一つなく、かれはより偉大で崇高な存在である。しかし、ここで言わんとしているのは、見られる対象どうしの相似ではなく、見え方の相似である。満月の夜に月を実際に、まごうことなく目にすることが出来るのと同様、私たちは至高の主アッラーをこの月を見る時のように、まごうことなく目で実際に目にすることになる。そして天国の住民の最良かつ最大の快楽をもたらす恩恵こそが、アッラーのお顔を拝見することなのであり、それに匹敵するものはない。アッラーの使徒は、私たちが満月の夜に月を見るように主を見ることになると述べた後、このように言っている：「ならば、太陽が昇る前の礼拝と、それが沈む前の礼拝をやり過ごさないようにできるならば、そうするがよい。」つまり、それらの２つの礼拝を完全に遂行することである。そして、それらをやり過ごさずにできるのなら、集団での礼拝として行うことである。ここには、ファジュル（黎明）の礼拝とアスル（午後遅く）の礼拝の遵守が、至高のアッラーのお顔を見ることが出来る要因の１つであることの示唆がある。",
    "hints": [
          "預言者（彼にアッラーからの祝福と平安あれ）と一緒にいることにおける、教友たちの熱心さ。",
          "審判の日、至高のアッラーを目にすることが出来るという、信仰の民への吉報の確証。",
          "アッラーとその使徒が述べているように、アッラーを実際に見ることが出来ることの確証。たとえ、それを曲げて解釈したり、属性を無効視したりする見解があったとしても、である。",
          "ファジュル（黎明）の礼拝とアスル（午後遅く）の礼拝の徳と、それを遵守すべきこと。",
          "この２つの時間帯が特に取り上げられているのは、そこにおいて天使たちが集まり、僕たちの行いを天へと上げるからであり、その偉大な恩寵を逃してしまわないようにするためである。",
          "強調と、希望へと促すことは、伝道の手法の１つである。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
