    "title": "このクルアーンを遵守していよ。ムハンマドの魂がその手に委ねられているお方にかけて、まことにそれは足かせをつけられたラクダよりも、早く逃亡してしまうものなのかだから。",
    "hadeeth": "アブー・ムーサー・アル＝アシュアリー（彼にアッラーのご満悦あれ）によると、預言者（彼にアッラーからの祝福と平安あれ）は言った：「このクルアーンを遵守していよ。ムハンマドの魂がその手に委ねられているお方にかけて、まことにそれは足かせをつけられたラクダよりも、早く逃亡してしまうものなのかだから。」",
    "explanation": "「このクルアーンを遵守していよ」とは、つまりクルアーンの読誦を常日頃から行っておけということである。\n「ムハンマドの魂がその手に委ねられているお方にかけて、まことにそれは足かせをつけられたラクダよりも、早く逃亡してしまうものなのかだから。」\n「足かせ」とは、ラクダの足の真ん中にしばりつける紐のことであり、ここではクルアーンの暗記が足かせをつけられていても逃亡してしまうラクダにたとえられている。アッラーはそのお優しさゆえにクルアーンという偉大な恩恵を授けて下さったのだから、私たちはそれを日頃から遵守しなければならない。つまりそれを忘れてしまわないよう、毎日一定量を読むようにしておくべきである。自然と忘れてしまった者にお咎めはないが、それを暗記する恩恵を頂いていながら、なおざりにして忘れてしまった者に関しては、罰が下される恐れがある。それを心に留め続けられるよう、読誦に関心を払っていなければならない。また、クルアーンに則った行いにも注意を払う必要がある。それはクルアーンの暗記の保持につながるからである。",
    "hints": [
          "クルアーンの読誦と学習を日頃から行っておくことの勧め。",
          "クルアーン暗記者は、その読誦を繰り返せば繰り返すほど、それを心に留めることが出来る。むしろそうしなければ、それは心から立ち去り、忘れられてしまう。クルアーンはラクダよりも早く逃げてしまうのである。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  5913: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "あなた方の内で最善の者は、クルアーンを学び、教える者である。",
    "hadeeth": "ウスマーン・ブン・アッファーン（彼にアッラーのご満悦あれ）が預言者（彼にアッラーからの平安と祝福あれ）から伝えるところによれば、彼は言った：「あなた方の内で最善の者は、クルアーンを学び、教える者である。」",
    "explanation": "「あなた方の内で最善の者は、クルアーンを学び、教える者である。」これは、イスラーム共同体全体へと投げかけられた言葉である。最善の者とは、クルアーン学習、つまり他人からそれを学ぶこと、そしてクルアーン教授、つまり他人にそれを教えることという、２つの性質を備えた者である。なぜならクルアーンは最も高貴な学問だからである。ここでいう学習と教授は、文字上のものと、意味的なもの、いずれをも指す。たとえば前者のものとしては、人にクルアーン読誦を教えたり、暗記させたりすることが挙げられる。またクルアーンを暗記する者は、それを学習する者と見なされる。一方、後者のものとしては、クルアーンの意味の教授、つまり至高のアッラーの言葉の解釈を人に教えたり、クルアーン解釈学やそのルールについて教授することなどが挙げられる。",
    "hints": [
          "クルアーンとその読誦を学習し、教授する徳。",
          "クルアーンが示す法規定、礼儀作法、品性を守って実践することの徳。",
          "知識ある者は、学んだ後にその知識を教えるべきである。",
          "クルアーンについて学ぶ者への栄誉。そして学んだことによってその位階が高められること。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承",
  },
  5932: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "どこかに滞在する者で、「アウーズ・ビカリマーティッラーヒッターンマーティ・ミン・シャッリ・マー・ハラク（私はアッラーの完全なる御言葉に、かれが創造した悪からのご加護を乞う）」と唱える者は、その滞在場所から立ち去る時まで、いかなるものにも害を受けることはない。",
    "hadeeth": "ハウラ・ビント・ハキーム（彼女にアッラーのご満悦あれ）が預言者（彼にアッラーからの平安と祝福あれ）から伝えるところによれば、彼は言った：どこかに滞在する者で、「アウーズ・ビカリマーティッラーヒッターンマーティ・ミン・シャッリ・マー・ハラク（私はアッラーの完全なる御言葉に、かれが創造した悪からのご加護を乞う）」と唱える者は、その滞在場所から立ち去る時まで、いかなるものにも害を受けることはない。",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）はその共同体に、旅行先であれ行楽先であれ、あるいはそれ以外であれ、人がどこかに滞在する時に恐れるようなあらゆる悪事から守ってくれる有益な加護の言葉を、教えて下さった。それは、その滞在先に留まっている間中、あらゆる有害なものから安全でいられるよう、いかなる欠点や不足もないアッラーの完全なる言葉にご加護を求めることである。",
    "hints": [
          "ご加護を求めることは、イバーダ（崇拝行為）である。",
          "合法な形におけるご加護の祈願は、アッラーご自身、またはアッラーの美名や属性に向けられたものである。",
          "アッラーのお言葉は被造物ではないこと。アッラーはご加護の祈願を定めたが、被造物に対してご加護を求めることはシルクである。このことは、アッラーのお言葉が被造物ではないことを示している。",
          "この簡潔な祈願の言葉の徳。",
          "被造物の采配を握っているのはアッラーのみである。",
