    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  5934: {
    "category_id": 3,
    "category": "神学",
    "title": "私はあなたに、アッラーの使徒（彼にアッラーからの祝福と平安あれ）が私に託して遣わしたものを、託して遣わそうか？つまり（彼は私に、こう命じたのだ）：「像は、抹消せずにはおくな。盛り上げられた墓は、平坦にせずには放っておくな。」",
    "hadeeth": "アブー・アル＝ハイヤージュ・アル＝アサディーは言った：アリー（彼にアッラーのご満悦あれ）は私に言った：私はあなたに、アッラーの使徒（彼にアッラーからの祝福と平安あれ）が私に託して遣わしたものを、託して遣わそうか？つまり（彼は私に、こう命じたのだ）：「像は、抹消せずにはおくな。盛り上げられた墓は、平坦にせずには放っておくな。」",
    "explanation": "イスラームは、微妙なものでも露わなものでもシルクにつながるような扉を閉じてしまうことに、関心を払っている。アリー（彼にアッラーのご満悦あれ）は私たちに、アッラーの使徒（彼にアッラーからの祝福と平安あれ）が彼を派遣し、見つけた全ての像は、抹消してしまうよう命じたことを、伝えている。それは、そこに至高のアッラーの被造物に似せることと、それを偉大視することによって人々を偶像崇拝へと導いてしまう危険性があるためである。また、アリーは、墓の上に建てられた建築物や、許されている範囲を超えて盛り上げられた墓を、壊してしまうことも命じられたとしている。これは墓を高く盛ることによって人々が惑わされ、そこに埋葬されている者たちをアッラーに並べて崇拝したり、偉大視したりしないようにするためである。つまりムスリムがイスラームに留まり続け、その信条が純粋な状態を保つためなのだ。像の作成や墓の上の建築は、その偉大視や神聖視につながり、それを本来の地位よりも高めてしまい、アッラーの権利の一つを与えてしまうことにもつながる可能性があるのである。",
    "hints": [
          "あらゆる種類の像の作成の禁止と、その除去、抹消の義務。",
          "真理を勧め合い、善を命じて悪を禁じ、知識を伝達すること。",
          "それが建築物であってもなくても、墓を高くすることの禁止。なぜならそれは、シルクの原因となり得るためである。",
          "墓の上のドームを除去する義務。",
          "墓の上の建築など、像の作成はシルクの原因となる。",
          "上記の物事の他、墓に大きな墓標を置いたり、装飾されたカラフルな墓標を置いたりすることも禁じられる。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  5953: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「自分の親、子供、そして全ての人々よりも、私が最愛の者となるまで、誰も信仰したことにはならない。」",
    "hadeeth": "アナス（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は言った： 「自分の親、子供、そして全ての人々よりも、私が最愛の者となるまで、誰も信仰したことにはならない。」",
    "explanation": "アッラーの使徒（アッラーからの祝福と平安あれ）は、このように言う：ムスリムは、自分の母親、父親、息子、娘、そしてあらゆる人々に対する愛よりも、アッラーの使徒（アッラーからの祝福と平安あれ）への愛を優先させるようになるまで、完全な信仰には到達しない。そしてこの愛情は、彼に対する服従、援助、彼への反抗の放棄を要求する。",
    "hints": [
          "アッラーの使徒（アッラーからの祝福と平安あれ）への愛と、それをあらゆる被造物への愛に優先させることの義務。",
          "アッラーの使徒（アッラーからの祝福と平安あれ）のスンナを援助し、そのために生命と財産を費すことは、彼に対する完全なる愛の印である。",
          "アッラーの使徒（アッラーからの祝福と平安あれ）への愛は、彼が命じたことに従い、伝えたことを信じ、禁じかつ注意したことを回避し、彼を模範として踏襲し、ビドゥア(イスラームの教えではないものをイスラームの教えとする考えや行為)を放棄することを要求する。",
          "預言者（アッラーからの祝福と平安あれ）の権利は他のいかなる人間の権利よりも偉大で重要である。というのも彼こそが私たちを迷いから導き、地獄から救い、天国を獲得することを可能にする原因だからである。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  5981: {
    "category_id": 3,
    "category": "神学",
    "title": "何かを吉凶と結びつける者、またはそれをしてもらう者、占いをする者、またはそれをしてもらう者、魔術を持ちいる者、またはそれをしてもらう者は、私たちの仲間ではない。そして占い師のもとにやって来てその言うことを信じた者は、ムハンマド（彼 にアッラーからの祝福と平安あれ）に下されたものを確かに否定したことになるのだ。",
    "hadeeth": "イムラーン・ブン・フサインとイブン・アッバース（彼らにアッラーのご満悦あれ）によれば、預言者（彼 にアッラーからの祝福と平安あれ）は言った：「何かを吉凶と結びつける者、またはそれをしてもらう者、占いをする者、またはそれをしてもらう者、魔術を持ちいる者、またはそれをしてもらう者は、私たちの仲間ではない。そして占い師のもとにやって来てその言うことを信じた者は、ムハンマド（彼 にアッラーからの祝福と平安あれ）に下されたものを確かに否定したことになるのだ。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）のこの言葉は、何かを吉凶と結びつける者、占いをする者、魔術を持ちいる者、そしてそれらの物事をしてもらう者に対する厳しい警告である。そして、それが大罪の１つであることを示唆している。なぜならこれらの物事には、アッラーの専有である不可知の事象に関する知識の主張が含まれ、信条と理性にとって有害なものが潜んでいるからである。ゆえにこれらの物事を信じた者は、これらの無知なことを否定し、理性をそのようなことから守るために下された神的啓示を否定したことになる。これには、手相占い、コーヒーカップ占い、人の幸不幸や運勢を星座と関連付けることなども、含まれる。アル＝バガウィーとイブン・タイミーヤといった学者らは、アッラーフ（神秘的力により過去の謎を解くと主張する者）、占い師、星占い師、ランマール（地面上に線を描いたりして占う者）といった者たちについて説明しているが、総論としては、不可知の事象についての知識を主張する者は全て、占い師という名称で括るか、あるいはそれに準じる者だと言うことが可能である。占い師とは、悪魔たちの盗み聞きを利用しつつ、将来起こることを告げる者である。",
    "hints": [
          "不可知の事象の知識を主張することの禁止。それはタウヒード（唯一神信仰）に抵触するものである。",
          "占いであれその他のものであれ、そのようなことを信じることの禁止。それは不信仰である。",
          "占い師やそれに準じる者たちを、嘘とすることの義務。そのような者たちとその様な知識を回避する義務。",
          "使徒（彼にアッラーからの祝福と平安あれ）に下ったものを遵守し、それに反するものを放棄する義務。",
          "何かを吉凶と結びつけること、魔術、占いの禁止。",
          "上記の物事を依頼することの禁止。",
          "クルアーンは啓示されたものであり、被造物ではない。",
        ],
    "grade": "真正",
    "attribution": "アル＝バッザールの伝承 - アッ＝タバラーニーの伝承",
  },
  5986: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーフを訪れ、彼に何かを尋ねて信じた者は、４０日間その礼拝を受け入れられない。",
    "hadeeth": "ハフサ・ビント・ウマル・ブン・アル＝ハッターブ（彼女らにアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの祝福と平安あれ）は言った：「アッラーフ（神秘的力により過去の謎を解くと主張する者）を訪れ、彼に何かを尋ねて信じた者は、４０日間その礼拝を受け入れられない。」",
    "explanation": "アッラーの使徒（彼にアッラーからの祝福と平安あれ）はこのハディースの中で、このように言っている：アッラーフ（神秘的力により過去の謎を解くと主張する者）を訪れ、不可知の領域の物事について尋ね、その言うことを信じた者は、アッラーによって４０日間の礼拝の褒美を禁じられる。それは、その者が望んだ大きな罪に対する罰としてのものである。尚、別のハディースにもある通り、彼ら自身を信じてしまった場合、それは預言者ムハンマド（彼にアッラーからの祝福と平安あれ）に啓示されたものに対する不信仰となってしまう。このような報いが占い師に頼る者のものであれば、占い師自身の報いはいかなるものであろうか！アッラーにご加護と無事安泰を乞おう。",
    "hints": [
          "占い師を訪問し、不可知の事象について尋ね、信じることの禁止。それは不信仰である。",
          "占いの禁止。それは大罪である。",
          "罪深い行いへの罰として、服従行為の褒美を禁じられることもある。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  5989: {
    "category_id": 3,
    "category": "神学",
    "title": "占星術を少しでも学んだ者は、魔術の一部を学んだのだ。（一方の学びを）増せば、（もう一方の学びも）更に増すのである。",
    "hadeeth": "イブン・アッバース（彼らにアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「占星術を少しでも学んだ者は、魔術の一部を学んだのだ。（一方の学びを）増せば、（もう一方の学びも）更に増すのである。」",
    "explanation": "不可知の事象は、アッラーのみが専有する領域であることから、預言者（彼にアッラーからの祝福と平安あれ）はその秘密に足を踏み入れようとするあらゆる試みを、無効なものとした。天界の状況によって地上での出来事を推測する占星術も、その一つである。預言者（彼にアッラーからの祝福と平安あれ）は、占星術を学ぶことを魔術の一種とした。そしてそれを学べば学ぶほど、魔術への学びを増すことにつながるとしたのである。",
    "hints": [
