  6021: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "最も遂行するに値する条件とは、あなた方がそれでもって陰部を合法とするものである。",
    "hadeeth": "ウクバ・ブン・アーミル（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「最も遂行するに値する条件とは、あなた方がそれでもって陰部を合法とするものである。」",
    "explanation": "夫婦のいずれにも、結婚の契約へと向かわせる目的がある。ゆえに夫婦は互いに守るべき諸々の条件をつけ、その遂行を要求するが、これを結婚における条件と呼ぶ。結婚それ自体が正当なものとなるための条件もあるが、ここで取り上げる条件は、そこには含まれない外的な種類のものである。この種の条件の遂行について強調されているのは、それが結婚という、崇高で義務性の強いものに関するものであるためであり、陰部を用いた楽しみがその条件を伴って初めて合法化されたからである。",
    "hints": [
          "夫婦が互いに条件づけた物事を遂行する義務。たとえば、妻側からのものとしては、マハル（婚資金）の増額、住居場所の条件などがあり、夫側からのものとしては、処女性や家系の条件などがある。",
          "このハディースで言及されている条件の遵守義務は、一般的な意味合いのものであり、「女性が、自分の姉妹の離婚を求めることは禁じられる」といった他のハディースなどによる限定を受けることがある。",
          "結婚に関する条件は、それ以外の物事に関する条件よりも更にその遵守が強調される。それが陰部を合法化する代償であるためである。",
          "出費、快楽、共に晩を過ごすことといった夫婦間の条件に、特定の数量はない。その決定については慣習に立ち返ることになる。",
          "結婚における条件には２種類ある：①有効な条件：これは結婚の契約が要求することに反しておらず、夫婦間の正しい目的のためであるものである。➁無効な条件：これは結婚の契約が要求することに反しているものである。これらの条件の目安となるのは、預言者（彼にアッラーからの祝福と平安あれ）の次の言葉である：「ムスリムたちは条件に基づく。ただし、ハラール（合法なもの）をハラーム（非合法なもの）としたり、ハラーム（非合法なもの）をハラール（合法なもの）としたりする条件は、その限りではない。」尚、結婚に関する条件は、結婚の契約の前でも同時に行っても同じく有効である。",
