  6203: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "彼は各礼拝の後、タスリーム（礼拝の締めの動作）する際に、こう言ったものだった：「ラー・イラーハ・イッラッラーフ・ワハダフ・ラー・シャリーカラフ。ラフルムルク､ワ・ラフルハムドゥ、ワ・フワ・アラー・クッリシャイン・カディール｡ラー・ハウラ・ワ・ラー・クウワタ・イッラー・ビッラーヒ｡ラー・イラーハ・イッラッラーフ､ワ・ラー・ナァブドゥ・イッラー・イーヤーフ｡ラフンニァマトゥ・ワ・ラフルファドゥル・ワ・ラフッサナーウルハサニ｡ラー・イラーハ・イッラッラーフ・ムフリスィーナ・ラフッディーナ・ワ・ラウ・カリハル・カーフィルーナ。」",
    "hadeeth": "アブドッラー・ブン・アッ＝ズバイル（彼らにアッラーのご満悦あれ）は各礼拝の後、タスリーム（礼拝の締めの動作）する際に、こう言ったものだった：「ラー・イラーハ・イッラッラーフ・ワハダフ・ラー・シャリーカラフ。ラフルムルク､ワ・ラフルハムドゥ、ワ・フワ・アラー・クッリシャイン・カディール｡ラー・ハウラ・ワ・ラー・クウワタ・イッラー・ビッラーヒ｡ラー・イラーハ・イッラッラーフ､ワ・ラー・ナァブドゥ・イッラー・イーヤーフ｡ラフンニァマトゥ・ワ・ラフルファドゥル・ワ・ラフッサナーウルハサニ｡ラー・イラーハ・イッラッラーフ・ムフリスィーナ・ラフッディーナ・ワ・ラウ・カリハル・カーフィルーナ（唯一で並ぶ者無きお方､アッラー以外に真に崇拝すべきものはなし｡主権と讃美はかれのみにあり､かれは全能のお方｡至高至大のアッラーの他に、いかなる権能も威力もなし｡アッラー以外に真に崇拝すべきものはなく､私たちはかれ以外を崇拝しない｡恩恵と優位性はかれにこそ属し､そしてかれにこそよき誉れがある｡アッラー以外に真に崇拝すべきものはなし｡たとえ不信仰者たちが忌み嫌おうとも､私たちはアッラーに誠意を尽して仕える）｡」そして言った：「アッラーの使徒（彼にアッラーからの祝福と平安あれ）はこれでもって、各礼拝の後に賛美を唱えていたのだ。」",
    "explanation": "アブドッラー・ブン・アッ＝ズバイル（彼らにアッラーのご満悦あれ）は義務の礼拝の後、タスリーム（礼拝の締めの動作）する際に、この偉大なズィクル（念唱）を唱えたものだった。その中には、至高のアッラーのみを真の崇拝の対象とすることの確証、そこにおいて共同者が存在することの否定、形而下的および形而上的主権はアッラーのみに属することの確証、いかなる時でもアッラーには讃美が相応しいこと、アッラーの絶対的力の確証など、多くの崇高な意味が含まれている。また、その中には僕の主に対する自らの無力さ、至らなさ、いかなる権能や威力も有してはいないことの自認も含まれる他、アッラーによる以外には自分自身に悪を阻んだり、善を引き寄せたりするいかなる力も備わってはいないという承認も含まれている。また、この祝福にあふれたズィクルには、恩恵をそれを授ける主に結びつけ、完全さはアッラーにこそ属し、その本質と属性と主性と恩恵については、善と美をもってアッラーを称えるべきであることが示されている。ズィクルの最後は、「ラー・イラーハ・イッラッラーフ（アッラー以外に真に崇拝すべきものはなし）」というタウヒード（唯一性信仰）の言葉で締めくくられ、たとえ全ての不信仰者たちがそれを嫌ったとしても、アッラーの崇拝において誠意を尽くすことに注意を促している。\nそれからアブドッラー・ブン・アッ＝ズバイル（彼らにアッラーのご満悦あれ）は、アッラーの使徒（彼にアッラーからの祝福と平安あれ）の礼拝のタスリーム後における賛美の言葉が、この形式であったことに言及している。彼は共にいる者たちに教授すべく、声を上げてこのズィクルを唱えていたのである。",
    "hints": [
          "各義務の礼拝後、アッラーの完全さを称える多くの意味を含むこのズィクルを守ることの勧め。",
          "宗教の基軸は真摯さ（イフラース）と踏襲（ムターバア）であり、その２つはイスラームの両足のようなものである。",
          "スンナの実践と伝達における、教友たち（彼らにアッラーのご満悦あれ）の熱心さ。",
          "たとえ不信仰者たちの不興を買ったとしても、ムスリムは自らの宗教に矜持（きょうじ）を持ち、その儀礼を誇示すべきである。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  6208: {
