    "category": "クルアーンとその諸学",
    "title": "あなた方の家を墓にするのではない。まことにシャイターン（悪魔）は、雌牛章の読まれる家から退散するのだ。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「あなた方の家を墓にするのではない。まことにシャイターン（悪魔）は、雌牛章の読まれる家から退散するのだ。」",
    "explanation": "アブー・フライラ（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの祝福と平安あれ）が、家を墓にすることを禁じたと伝えている。それはつまり、そこで礼拝もクルアーン読誦も勤しまれることのないような家の状態を意味する。礼拝が行われない家が墓にたとえられているのは、墓場での礼拝が有効ではないためである。それから預言者（彼にアッラーからの祝福と平安あれ）は、シャイターン（悪魔）が、雌牛章の読まれる家から退散すると語っている。それはその家の者が、その章の読誦による祝福や、そこに含まれている教えを実践することによって、シャイターンが彼らを惑わせ、迷わせることから絶望するためである。",
