    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は言った：アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言った：「スブハーナッラー（いかなる欠点からも無縁なアッラーに称えあれ）、アル＝ハムドリッラー（完全なる属性ゆえの全ての讃美はアッラーにあり）、ラー・イラーハ・イッラッラーフ（アッラー以外に真に崇拝すべきものは無し）、アッラーフ・アクバル（アッラーは偉大なり）と唱えることは、太陽がその上に昇る全てのものよりも、私が愛することである。」",
    "explanation": "このハディースには、アッラーをかれに相応しくない全ての欠損から無縁で崇高な存在として称えたり、その完全な特性ゆえに称賛したり、かれの唯一性を称えたり、かれの偉大さを称揚したりすることによって、ズィクル（念唱）することへの推奨がある。そしてこれらのズィクルは、現世とそこにある全てのものよりも優れている。というのもこれらは来世の行いであり、永続する善行であるため、その褒美は失われることもなく、途切れることもない。他方、現世は消え去り、失われるものなのである。",
