  6255: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "これらの日々（ズルヒッジャ月の１０日間）よりも、そこにおける善行がアッラーから愛される日々はない。",
    "hadeeth": "アブドッラー・ブン・アッバース（彼らにアッラーのご満悦あれ）によれば、預言者（彼 にアッラーからの祝福と平安あれ）は言った：「これらの日々（ズルヒッジャ月の１０日間）よりも、そこにおける善行がアッラーから愛される日々はない。」人々は言った：「アッラーの使徒よ、アッラーの道における戦いもですか？」 彼は言った：「アッラーの道における戦いも、である。ただし、生命と財産と共に出征し、そこから帰って来なかった者はその限りではない。」",
    "explanation": "「これらの日々（ズルヒッジャ月の１０日間）よりも、そこにおける善行がアッラーから愛される日々はない。」人々は言った：「アッラーの使徒よ、アッラーの道における戦いもですか？」 彼は言った：「アッラーの道における戦いも、である。ただし、生命と財産と共に出征し、そこから帰って来なかった者はその限りではない。」\nこの「善行」の中には、礼拝、サダカ（施し）、断食、ズィクル（念唱）、タクビール（アッラーの偉大さを称揚すること）、クルアーン読誦、親孝行、親戚関係の維持、あらゆるものへの親切、隣人とのよい関係などが含まれる。ゆえにズルヒッジャ月の１０日間は、善行の一つとして断食することも勧められるが、ただしそうする場合は１０日目は除外される。なぜならイードの日の断食は禁じられるからである。\nまた、このハディースの中には、ズルヒッジャ月最初の１０日間の善行の徳の他、アッラーの道における戦いが最善の行いの一つであるという根拠も示されている。それがゆえに教友たちは、「アッラーの道における戦いもですか？」と言ったのである。また、このハディースは、生命と財産をかけて－つまり武器と乗用の家畜と共に－アッラーの道の戦いに出て殺され、武器も乗用の家畜も敵に奪われ、アッラーの道において生命と財産を失うという、稀有な状態の徳も示唆している。これは最良の戦士の一人であり、ズルヒッジャ月１０日間の善行よりも優れている。もしこの行いがズルヒッジャ月１０日間に起こったならば、その徳は倍増することになろう。",
    "hints": [
          "ズルヒッジャ月１０日間は、一年の他の日々よりも優れている。",
          "ズルヒッジャ月最初の１０日間における断食の勧め。",
          "イスラームにおける戦いの徳の偉大さ。",
          "他の時節に対するある時節の優越性。",
          "不明なことは尋ねるのが、導きを請う者の礼儀作法である。",
