  },
  6261: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "アスルの礼拝を放棄した者は、その行いが無に帰すのだ。",
    "hadeeth": "ブライダ・ブン・アル＝フサイブ（彼にアッラーのご満悦あれ）は言った：アッラーの使徒（彼にアッラーからの平安と祝福あれ）は、こう言った：「アスル（午後遅く）の礼拝を放棄した者は、その行いが無に帰すのだ。」",
    "explanation": "このハディースは、アスル（午後遅く）の礼拝を故意に行わなかった者に警告を放っている。アスルが特に取り上げられているのは、昼間の仕事の疲れのため、それが遅れがちになるためである。また、アスルをやり過ごすことが他の礼拝に比べて厭われるのは、それが「中間の礼拝」としてその遵守を命じられたものだからでもある。アッラーは仰っている：「礼拝を遵守せよ、そして中間の礼拝を。」（雌牛章２３８）アスルの礼拝の放棄に対する罰は、礼拝の褒美がなくなることによって、行いが無に帰すことである。また他説では、その放棄を合法と考えたり、その義務性を否定したりすることで放棄する者は不信仰に陥ることになり、それで行いが無駄になる。ここからある種の学者は、アスルの礼拝を放棄した者は不信仰に陥るとしている。行いが無駄になるのは、棄教以外にはないためである。また別の説では、それは警告の強調であり、つまりアスルの礼拝を放棄した者は、あたかも行いが無駄になったかのようである、という意味である。これはアスルの礼拝の徳を示すものであり、それをやらない者はその偉大さゆえに、行いが無に帰したのである。",
    "hints": [
          "アスルの礼拝を時間内に行うことを、遵守することの勧め。",
          "礼拝、特にアスルの礼拝を放棄することの禁止。",
          "アスルの礼拝を故意に放棄した者は、その褒美を逃したことになる。「故意」という制約は、別の同様の真正な伝承内に「故意に」という表現があるためである。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承",
