    "title": "ウドゥー（浄め）を行い、それを良い形でする者は、その身体から罪が流れ出るのである。",
    "hadeeth": "ウスマーン・ブン・アッファーン（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの祝福と平安あれ）は言った：「ウドゥー（浄め）を行い、それを良い形でする者は、その身体から罪が流れ出るのである。それは、その爪の内側から流れ出るのだ。」",
    "explanation": "このハディースは、ウドゥーが最善の崇拝行為の一つであることの根拠である。その徳の一つがこのハディースで取り上げられており、「ウドゥーを行い、それを良い形でする者」とは、ウドゥーのスンナと礼儀作法を遵守する者のことである。このようなウドゥーは、至高のアッラーに対して犯した小さな罪が「流れ出る」ことの、一つの原因となる。これらの罪や過ちは、爪の内側のような微小な箇所からも流れ出るのである。ゆえにウドゥーをする時には、アッラーへのお近づきを意図すべきであり、「あなた方が礼拝を意図した時には、自分たちの顔と、両腕を肘まで洗い、頭を撫で、両足をくるぶしまで（洗え） ・・・」（食卓章６）というアッラーの命令に自分が従っていることを実感すべきである。また、ウドゥーにおいて、アッラーの使徒（彼にアッラーからの祝福と平安あれ）のスンナに従っていることを感じ、「それを良い形でする」ことにより褒美を受けることを望んでいるのだと実感すべきである。",
    "hints": [
          "ウドゥーの礼儀作法や諸条件を学ぶことに関心を持ち、実践することの勧め。",
          "ウドゥーの徳と、それが罪滅ぼしとなること。",
          "罪が流れ出ることの条件は、ウドゥーを良い形で行うことであり、預言者（彼にアッラーからの祝福と平安あれ）がその共同体に説明したように行うことである。",
          "ウドゥーの諸条件、スンナ、礼儀作法を学ぶことに関心を持ち、実践することの勧め。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  6274: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "夜に雌牛章の最後の２節を読んだ者は、それで十分なのである。",
    "hadeeth": "アブー・マスウード・アル＝バドリー（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの平安と祝福あれ）は言った：「夜に雌牛章の最後の２節を読んだ者は、（あらゆる悪から守られるのに）それで十分なのである。」",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）は、夜寝る前に雌牛章の最後の２節を読んだ者が、アッラーによって悪から守られると述べている。また「それで十分なのである」とは、それだけで夜の任意の礼拝、あるいは、ウィルド（クルアーンの毎日の朗誦部分）の代わりになるのだとか、その読誦だけで夜の任意の礼拝の中の読誦としては十分なのだとかいった解釈もある。ハディースは、以上の全ての説を含みえる。",
    "hints": [
