        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  6275: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "アッラーの書から一文字でも読んだ者には、一つの善行がある。そしてその善行は、１０倍となる。",
    "hadeeth": "イブン・マスウード（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「アッラーの書（クルアーン）から一文字でも読んだ者には、一つの善行がある。そしてその善行は、１０倍となる。『アリフ・ラーム・ミーム』が一文字だとは、言わない。しかし『アリフ』が一文字、『ラーム』が一文字、『ミーム』が一文字なのだ。」",
    "explanation": "イブン・マスウード（彼にアッラーのご満悦あれ）が、このハディースの中でアッラーの使徒（彼にアッラーからの平安と祝福あれ）から伝えるところによれば、アッラーの書（クルアーン）から一文字でも読んだ者には一つの善行があり、そしてその善行は１０倍となる。『アリフ・ラーム・ミーム』（クルアーンのいくつかの章の冒頭に出現する節）は３つのアラビア文字から構成されているが、それら全部で一文字なのではない。しかし『アリフ』が一文字、『ラーム』が一文字、『ミーム』が一文字なのであり、つまりそれらを読んだ者は３０の善行によって褒美を受けることになる。これは偉大な恩恵であり、豊かな褒美である。ゆえにアッラーの書を多く読誦すべきである。",
    "hints": [
          "クルアーン読誦の勧め。",
