    "attribution": "アッ＝ティルミズィーの伝承",
  },
  6337: {
    "category_id": 3,
    "category": "神学",
    "title": "わがワリイに敵対する者には、われがその者に対して宣戦布告する。わがしもべがわれにお近付きを求める物事の内、われがわがしもべに対して義務付けたものよりも、われにとって愛すべきものはない",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）は、言った： アッラーの使徒（アッラーからの祝福と平安あれ）は、言った：「本当にアッラーは、こう仰った：” わがワリイに敵対する者には、われがその者に対して宣戦布告する。わがしもべがわれにお近付きを求める物事の内、われがわがしもべに対して義務付けたものよりも、われにとって愛すべきものはない。そしてわがしもべは、われがその者を愛するようになるまで、任意の行為によってわれにお近付きを求め続けるのである。われがその者を愛せば、われはその者の聞く聴覚となり、その者の見る視覚となり、その者がそれでもって制する手となり、その者がそれでもって歩む足となる。その者がわれに向かって何かを乞えば、われは必ずそれを与える。われに庇護を求めれば、われは必ず庇護してやる。そして死を厭う信仰者の魂ほど、われが行う物事の内で、われがためらうことはない。われはその者が嫌がる物事を厭うのだから。”」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は神聖ハディースの中で、アッラーがこう仰ったと伝えている： わがワリイの誰かに敵対し、怒らせ、嫌悪感を抱かせる者には、われがその者に対して敵対することを宣言する。\n\nワリイとは、敬虔な信仰者である。信仰心と敬虔さが強ければ強いほど、アッラーとの親愛な関係は強くなる。 ムスリムがその主アッラーにお近付きを求める物事の内、服従行為の遂行や禁止行為の放棄といった、アッラーがその者に対して義務付けたものよりも、アッラーにとって愛すべきものはない。そしてムスリムは、アッラーがその者を愛するようになるまで、義務行為に加えた任意の行為によって、アッラーにお近付きを求め続けるのである。 そしてアッラーがその者を愛せば、アッラーは以下の4つのことにおいてその者を正しく導いてくださる。\n\nアッラーはその者の聴覚を正しく導き、アッラーのご満足にかなうことしか耳にしなくなる。\n\nまた、その者の視覚を正しく導き、アッラーのご満足にかなうことしか見なくなる。\n\nまた、その者の手を正しく導き、アッラーのご満足にかなうことしか手を動かさなくなる。\n\nまた、その者の足を正しく導き、アッラーのご満足にかなうことにしか足を歩ませなくなる。つまり、よいことに向かってでしか努力しなくなる。\n\nその者がアッラーに向かって何かを乞えば、アッラーは必ずそれを与える。アッラーはそのような者の祈りに答えてくださるのである。また、アッラーに庇護を求めて避難すれば、アッラーは必ずその者が恐れていることから庇護して下さる。\n\nそしてアッラーは仰る：死を厭う信仰者の魂を召すことほど、われが行う物事の内で、われが慈悲ゆえにためらうことはない。なぜならそこには痛みがあり、アッラーは信仰者を痛めるものを嫌いになるからである。",
    "hints": [
          "このハディースは、預言者（アッラーからの祝福と平安あれ）がその主アッラーから伝えるものであり、聖なるハディースと呼ばれるものである。これは文言も意味もアッラーからのものではあるが、クルアーンが専有する特徴を兼ね備えてはいないものである。つまり、その読誦が崇拝行為となったり、それを読む際にはタハーラ（清浄）の状態にある必要があったり、その模倣を挑まれていたり、その模倣が不可能であったりするようなクルアーンの特徴のことである。",
          "アッラーのワリイを害することの禁止と、彼らに対する愛情とその徳の認識のすすめ。",
          "アッラーの敵に敵対することの命令と、そのような者たちと親愛な関係になることの禁止。",
          "イスラームの教えに従ってもいないのに自分がワリイだと主張する者は、その主張において嘘をつく者である。",
          "義務行為の遂行と禁止行為の放棄によってこそ、アッラーのワリイとなることができる。",
          "義務行為を遂行し、禁止行為を放棄した上で任意の行いに勤めることは、アッラーの愛情を獲得し、祈りを受け入れてもらえる要因である。",
          "ワリイの栄誉とその位の高さの証明。",
        ],
    "grade": "صحيح",
    "attribution": "رواه البخاري",
  },
