    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）はある旅行の最中、使いを送った。そして、邪視や害悪予防のためにラクダの首に付けられた首飾りを取り除くよう、人々に呼びかけさせた。なぜなら、それはシルクの一種であり、除去すべきことだからである。",
