  6763: {
    "category_id": 3,
    "category": "神学",
    "title": "何かにすがる者は、そこに委ねられるのだ。",
    "hadeeth": "アブドッラー・ブン・オカイム（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「何かにすがる者は、そこに委ねられるのだ。」",
    "explanation": "利益を手にすることや害悪の阻止を望みつつ、心や行動、またはその両方によって何かにすがりつく者は、アッラーによってそのすがりついているものへと任せられる。ゆえにアッラーにすがりつく者はそれだけで十分であり、あらゆる困難は容易いものとされる。他方、アッラー以外のものにすがりつく者は、そのものへと委ねられることになり、失意を味わわされることになる。",
    "hints": [
