  },
  6765: {
    "category_id": 3,
    "category": "神学",
    "title": "「ラー・イラーハ・イッラッラーフ（アッラー以外に崇拝すべきものはなし）」と唱え、アッラーをよそに崇拝されているものを否定する者は、その財産と生命を守られ、その清算をアッラーに委ねられる。",
    "hadeeth": "ターリク・ブン・アシュヤム・アル＝アシュジャイーによれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「『ラー・イラーハ・イッラッラーフ（アッラー以外に崇拝すべきものはなし）』と唱え、アッラーをよそに崇拝されているものを否定する者は、その財産と生命を守られ、その清算をアッラーに委ねられる。」",
    "explanation": "アッラーの使徒（彼にアッラーからの平安と祝福あれ）はこのハディースの中で、以下の２つの物事を満たした者の生命と財産は保障しなければならないと説明している：\n１．「ラー・イラーハ・イッラッラーフ（アッラー以外に崇拝すべきものはなし）」という言葉。\n２．アッラーをよそに崇拝されているものを否定すること。\nこれらの２つを満たした者は、表面上の物事に関しては保障され、内面的な物事については至高のアッラーに委ねられる。ただし、それは棄教などによって生命の保障が消失したり、ザカー（義務の浄財）の拒否などによって財産の保障が消失したり、債務支払いの故意の遅延などによって尊厳の保障が消失したりしない限りにおいてである。",
    "hints": [
          "「ラー・イラーハ・イッラッラーフ（アッラー以外に崇拝すべきものはなし）」の意味は、偶像や墓など、アッラーを差し置いて崇拝されているものを否定することである。",
          "アッラーをよそに崇拝されているものを否定せずに、単に「ラー・イラーハ・イッラッラーフ」と唱えても、その生命と財産の保障とはならない。アッラーをよそに崇拝されているものを否定しない限りは、たとえその言葉の意味を知り、それに基づいて行っていても、生命と財産の保障にはならないのである。",
          "タウヒード（アッラーの唯一性信仰）を奉じ、その教えを外面上遵守する者は、それに明らかに反しない限りは保護されなければならない。",
          "イスラームを受容した者は、それに反するものが明らかにならない限り、たとえ戦闘中であっても保護されなければならない。",
          "アッラーをよそに崇拝されているものを否定せずに、「ラー・イラーハ・イッラッラーフ」と唱える者がいる可能性。",
          "現世での裁決は表面的な物事を基準になされ、来世での裁決は意図と目的を基準としてなされる。",
          "ムスリムの財産と生命の侵害は正当な理由がない限り、禁じられる。",
          "信徒の生命と財産を保護する、イスラームの徳。",
          "ザカー（浄財）のようにイスラーム法で義務付けられたものや、物損に対する罰金のようなものでない限り、ムスリムの財産に手を付けることは禁じられる。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  8265: {
    "category_id": 7,
    "category": "預言者伝と歴史",
    "title": "預言者（彼にアッラーからの祝福と平安あれ）の性格は、クルアーンだった。",
    "hadeeth": "アーイシャ（彼女にアッラーのご満悦あれ）は言った：「預言者（彼にアッラーからの祝福と平安あれ）の性格は、クルアーンだった。」",
    "explanation": "このハディースは、預言者（彼にアッラーからの祝福と平安あれ）がクルアーンの性格を身につけていたこと、つまりアッラーに対する崇拝行為であれアッラーの僕たちとのやり取りであれ、クルアーンが命じることを行い、それが禁じることは避けていたことを示している。預言者（彼にアッラーからの祝福と平安あれ）の性格はクルアーンの実践であり、つまりこの中には「アッラーの使徒（彼にアッラーからの祝福と平安あれ）の性格を模倣したい者は、クルアーンによって性格を形作らなければならない」というアーイシャ（彼女にアッラーのご満悦あれ）からの示唆も伺える。",
    "hints": [
          "クルアーンによって性格を形作るという、預言者（彼にアッラーからの祝福と平安あれ）の模倣の勧め。",
          "アッラーの使徒（彼にアッラーからの祝福と平安あれ）の性格の賞賛と、その源泉が啓示であることの説明。",
          "イスラームにおける性格の地位。それはタウヒード（唯一性信仰）の言葉に不可欠なものであり、善行を実らせるに必要なものである。",
