    "category": "神学",
    "title": "「慈悲あまねきお方は、慈悲深い者たちを慈しまれる。地にあるものを慈しめ、そうすれば天にあるものがあなた方を慈しんで下さる。」",
    "hadeeth": "アブドッラー・ブン・アムル（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は言った： 「慈悲あまねきお方は、慈悲深い者たちを慈しまれる。地にあるものを慈しめ、そうすれば天にあるものがあなた方を慈しんで下さる。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、他人を慈しむ者には、慈悲あまねきお方が慈悲をおかけ下さる、と語っている。それは相応の報いであり、しかも慈悲あまねきお方の慈悲は、あらゆるものに広がっているほどの慈悲である。\n\n預言者（アッラーからの祝福と平安あれ）は、人、動物、鳥、その他、地上に属するあらゆる被造物に対しての慈悲を命じている。そしてその報いは、天上からのアッラーの慈悲なのである。",
