  8402: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "預言者（彼にアッラーからの祝福と平安あれ）はどんな時でもアッラーをズィクル（唱念）していた。",
    "hadeeth": "アーイシャ（彼女にアッラーのご満悦あれ）は言った：「預言者（彼にアッラーからの祝福と平安あれ）はどんな時でもアッラーをズィクル（唱念）していました。」",
    "explanation": "「預言者（彼にアッラーからの祝福と平安あれ）はどんな時でもアッラーをズィクル（唱念）していました」というハディースの中の「ズィクル」には、あらゆる種類のズィクルが含まれる。タスビーフ（アッラーをあらゆる欠点から無縁な存在として称える言葉）、タフリール（アッラーの唯一性を認め称える言葉）、タクビール（アッラーの偉大さを称える言葉）、タフミード（アッラーの完璧な属性を称える言葉）を始め、クルアーン読誦もその内の一つであり、それどころかそれは最良のズィクルでもある。\n「どんな時でも」とは、いつでも、大小の汚れの状態にある時でさえも、アッラーのことをズィクルしていたということである。但し学者たちは、大きな汚れの状態におけるクルアーン読誦を、ここから除外している。大きな汚れの状態にある時は、クルアーンを見ながらでも暗記しているものからでも、読んではならない。アリー（彼にアッラーのご満悦あれ）の伝えるハディースで、このようなものがある：「預言者（彼にアッラーからの祝福と平安あれ）は大きな汚れの状態にない限り、私たちにクルアーンを読んで聞かせたものだった。」（アフマドと４大スナン集収録の伝承）\n尚、月経中の女性と悪露の女性が、大きな汚れの状態と同様に見なされるかどうかで、学者たちには見解の相違がある。\n有力な見解は、それらの状態にある女性は暗記したものの内からクルアーンを読むことが出来る、というものである。というのもそれらの期間が長く、それらの状態は大きな汚れのように自ら選んだものではないからである。\nまた、クルアーン読誦に関しては大小の用便時、性交渉の最中、浴室やトイレなど、クルアーンの偉大さには相応しくないような場所、不浄な場所などで行うことが除外され、禁じられる。",
    "hints": [
          "大小の汚れの状態にある者に、アッラーのズィクルのために清めを行うことは条件づけられない。ゆえにムスリムはそのような状態下でも、タスビーフ（アッラーをあらゆる欠点から無縁な存在として称える言葉）、タフリール（アッラーの唯一性を認め称える言葉）、タクビール（アッラーの偉大さを称える言葉）、タフミード（アッラーの完璧な属性を称える言葉）を行うことが許されるが、大きな汚れの状態でのクルアーン読誦に関しては、そうすることを禁じるハディースの存在により、禁じられる。",
          "このハディースの一般的理解からは、月経中の女性と悪露の女性はムスハフ（書としてのクルアーン）に直接触れないことを条件に、クルアーンを読むことが許される。手袋などを着用すれば、ムスハフに触れることも可能である。",
          "預言者（彼にアッラーの祝福と平安あれ）は、常にアッラーをズィクルしていた。",
          "預言者（彼にアッラーからの祝福と平安あれ）の状況に関する、アーイシャ（彼女にアッラーのご満悦あれ）の知識。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーが伝承者を省略しつつも断言口調で伝える伝承 - ムスリムの伝承",
  },
  8914: {
