    "category": "法学と法源学",
    "title": "アッラーの使徒（彼にアッラーからの祝福と平安あれ）は、カザゥを禁じた。",
    "hadeeth": "イブン・ウマル（彼らにアッラーのご満悦あれ）は言った：「アッラーの使徒（彼にアッラーからの祝福と平安あれ）は、カザゥ（頭部の一部は剃り、別の部分は残しておくこと）を禁じた。」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、子供の頭部の一部を剃り、別の部分はそうせずに残しておくことを禁じた。これは、全ての者に対する一般的な教示である。",
