  8918: {
    "category_id": 3,
    "category": "神学",
    "title": "まことに天使たちは雲に下り、天で決定された物事について語り合う。その時、シャイターンが聞き耳を立ててそれを盗み聞きし、それを占い師たちに吹き込むのである。そうして彼らは、自分たちによる１００の嘘をそこに混ぜ込むのだ。",
    "hadeeth": "アーイシャ（彼女にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は人々から占い師について尋ねられ、こう言った：「彼らは何の正しさも持ち合わせてはいない。」彼らは言った：「アッラーの使徒よ、彼らは時に私たちに対して何かについて語り、それが真実であったりもします。」すると、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「それはジンがかすめ取る言葉であり、それを自分の信奉者の耳に入れるのだが、彼ら（占い師）はそこに１００の嘘を混ぜ込むのである。」\n尚、アル＝ブハーリーがアーイシャ（彼女にアッラーのご満悦あれ）から伝える伝承によれば、彼女はアッラーの使徒（彼にアッラーからの平安と祝福あれ）がこのように言うのを聞いた：「まことに天使たちは雲に下り、天で決定された物事について語り合う。その時、シャイターンが聞き耳を立ててそれを盗み聞きし、それを占い師たちに吹き込むのである。そうして彼らは、自分たちによる１００の嘘をそこに混ぜ込むのだ。」",
    "explanation": "アーイシャ（彼女にアッラーのご満悦あれ）は、アッラーの使徒（彼にアッラーからの平安と祝福あれ）が人々から、未来の不可視の領域のことを語る者たちについて尋ねられ、こう言ったと伝えている：彼らを気にしたり、彼らの言うことを聞いたりしてはならない。彼らの諸事に留意するのではない、と。\nすると人々は、言った：彼らの言うことは現実と一致します。これこれの月、これこれの日にまだ未知の何らかの物事が起こると言えば、その言葉通りにそれは起こるのです、と。それで、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：ジンが天の知らせを盗み聞きし、その後、彼らの信奉者である占い師たちのもとに下り、聞いたことを伝えるのだ。それからその占い師が、天からの情報に１００の嘘を付け加えるのだ、と。\nアル＝ブハーリーが伝える伝承の意味は、こうである：天使たちは天で、この世の者たちに起こる毎日の出来事について、アッラーが決定されたことを聞く。それから雲に下り、互いに話し合う。その時、シャイターンがそれを盗み聞きし、それを自分たちの信奉者である占い師たちのところに持って行って、吹き込むのである。それから占い師は聞いたものに、１００またはそれ以上の嘘を付け加えるのだ。",
    "hints": [
          "占い師を信じることの禁止。たとえ時に正しいことを言ったとしても、彼らの言葉が嘘であり、捏造であること。",
          "占い師の言葉で正しいものは、ジンが盗み聞きしたものである。預言者（彼にアッラーからの平安と祝福あれ）が遣わされる以前、彼らは天の最下層に座り、最上界の民の間で交わされる物事を耳にしていた。しかし、それは預言者（彼にアッラーからの平安と祝福あれ）が遣わされることによって無効化され、ジンたちはそこから阻まれた。それで彼らは盗み聞きをすれば、流星で撃たれるようになってしまったのだ。これがクルアーンの伝える話である。",
          "ジンには、人間の内に信奉者がある。",
          "シャイターンたちは盗み聞きし続けているが、しかしジャーヒリーヤ時代に比べれば、それはかなり希少化した。それは殆ど、起こらない位である。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承 - 二大真正集収録の伝承",
  },
  8945: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "私たちは、無理に何かすることを禁じられた。",
    "hadeeth": "ウマル（彼らにアッラーのご満悦あれ）は言った：「私たちは、無理に何かすることを禁じられた。」",
    "explanation": "ウマル（彼にアッラーのご満悦あれ）は、このハディースの中で、「私たちは、無理に何かすることを禁じられた」と伝えているが、禁じた者は、アッラーの使徒（彼にアッラーからの祝福と平安あれ）である。教友が「私たちは禁じられた」と言えば、それはアッラーの使徒（彼にアッラーからの祝福と平安あれ）に直接結びつけられる、と捉えられるからである。つまり、「アッラーの使徒（彼にアッラーからの祝福と平安あれ）は私たちに、無理に何かすることを禁じた」と言ったようなものである。\n「無理に何かすること」は原文では「タカッルフ」であり、それは本来ないようなことを他人の前で示そうとする、あらゆる言動のことである。\n言葉の例としては、イスラームの自明な教えに依拠するのではなく、多くの質問や、調べる必要もないような不明な物事を究明する態度が挙げられる。アナス（彼にアッラーのご満悦あれ）は、このように伝えている：私たちはウマルと共にいた。彼は、その背中に４枚の布片が継ぎ当てられている上衣をまとっていた。彼は『果実、牧草も（生育させた）』（クルアーン８０：３１）と読むと、言った：「私たちは、果実については知っている。しかし、『牧草（原語ではアッブ）』とは何か？」それから、こう言ったのである：「私たちは、無理に何かすることを禁じられたのだ。」\n一方、行為によるものとしては、以下のような例が挙げられる：泊まりに来た客人に対して過度に尽くし、返すあてもないような借金までしてしまい、結果的に現世と来世において自分自身を害するようなことをしてしまうこと。\nゆえにムスリムに無理は禁物であり、そうではなく物事においては預言者（彼にアッラーからの祝福と平安あれ）がそうであったように、中庸の状態にあるべきである。あるものを出し惜しみするのでもなく、ないものを無理に出そうともしない、そのような状態である。",
    "hints": [
          "無理に何かをすることの禁止と、あらゆる物事においてそこから遠ざかることの奨励。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承",
  },
  10044: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "小便から清浄であるようにせよ。まことに墓の懲罰の大半は、それによるものなのだから。",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「小便から清浄であるようにせよ。まことに墓の懲罰の大半は、それによるものなのだから。」",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）はこのハディースの中で、墓の懲罰の原因の一つであり、最も多く広まっているものを挙げている。それは小便の汚れを避けず、そこから清浄でない状態のことである。",
    "hints": [
          "小便が衣服や身体にかからないようにし、そこから無縁な清浄な状態であるように注意すること。",
          "もし小便がかかってしまったら、急いでそれを洗浄し、清めるのが最善である。そうすることで、汚れが自分につきまとわないようにするためである。礼拝の際には、それを除去することが義務となる。",
          "小便は汚れである。それが身体や衣服や場所にかかれば、汚れを被ったことになり、それによって礼拝することは有効ではなくなる。なぜなら汚れからの清浄性が、礼拝の一条件であるためである。",
          "小便からの清浄な状態を保たないことは、大罪の一つである。",
          "墓の懲罰の確証。それはクルアーン、スンナ、イジュマー（学者間の見解の一致）によって裏付けされている。",
          "来世における報いの確証。来世の第一段階が墓であり、墓は天国の楽園の一部となるか、地獄の穴の一つになるかのいずれかである。",
        ],
    "grade": "真正",
    "attribution": "アッ＝ダールクトニーの伝承",
  },
  10098: {
    "category_id": 3,
    "category": "神学",
    "title": "誰でも心から正直に『ラー・イラーハ・イッラッラーフ、ムハンマドッラスールッラーヒ （アッラーの他に真に崇拝すべきものはなく、ムハンマドはそのアッラーの使徒である）』と証言する僕は、アッラーによって地獄を禁じられる。",
    "hadeeth": "アナス（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの平安と祝福あれ）は鞍の上でムアーズを後ろに乗せ、こう言った：「ムアーズよ。」彼は言った：「はい、アッラーの使徒よ、何でしょう。」そしてまた、こう言った：「ムアーズよ。」彼は言った：「はい、アッラーの使徒よ、何でしょう。」更にまた、３度目にこう言った：「ムアーズよ。」彼は言った：「はい、アッラーの使徒よ、何でしょう。」預言者は言った：「誰でも心から正直に『ラー・イラーハ・イッラッラーフ、ムハンマドッラスールッラーヒ （アッラーの他に真に崇拝すべきものはなく、ムハンマドはそのアッラーの使徒である）』と証言する僕は、アッラーによって地獄を禁じられる。」彼（ムアーズ）は言った：「アッラーの使徒よ、人々にこのことを伝えてもよろしいでしょうか？彼らが喜ぶでしょう。」預言者は言った：「そうすれば、彼らは頼り切ってしまうだろう。」こうしてムアーズは罪を恐れて、自らの死の折にそのことを伝えた。",
    "explanation": "ムアーズ（彼にアッラーのご満悦あれ）は、預言者（彼にアッラーからの平安と祝福あれ）の後ろに同乗していた。預言者（彼にアッラーからの平安と祝福あれ）は、こう言った：「ムアーズよ。」彼は言った：「はい、アッラーの使徒よ、何でしょう。」これは原文では、「ラッバイカ・サァダイカ」という表現であり、そもそも「ラッバイカ」には「あなたにいつでも答え、服従します」という意味が、「サァダイカ」には「あなたへの服従にいつでも奉仕します」という意味が含まれている。それからまた、預言者は言った：「ムアーズよ。」彼は言った：「はい、アッラーの使徒よ、何でしょう。」更にまた、言った：「ムアーズよ。」彼は言った：「はい、アッラーの使徒よ、何でしょう。」そして預言者は言った：「誰でも心から正直に『ラー・イラーハ・イッラッラーフ、ムハンマドッラスールッラーヒ （アッラーの他に真に崇拝すべきものはなく、ムハンマドはそのアッラーの使徒である）』と証言する僕は、アッラーによって地獄を禁じられる。」つまり「心から正直に」とは、口先で唱えることだけではない。また、「地獄を禁じられる」とは、地獄への永遠の滞留を禁じられるということである。彼（ムアーズ）は言った：「アッラーの使徒よ、人々にこのことを伝えてもよろしいでしょうか？彼らを喜ばせたいのです。」すると預言者（彼にアッラーからの平安と祝福あれ）は言った：「いや、そうするのではない。そうすれば、彼らはそれに頼り切ってしまい、行いに励まなくなるから。」しかしムアーズは知識を隠蔽する罪を恐れ、自らの人生の最期に、そのことを伝えた。",
    "hints": [
          "そうすることによって禁止事項に触れてしまうような場合、またはより望ましい状態が失われてしまうような場合、ハディースを話さずにおくことが許される。",
          "乗り物用の家畜の上に、同乗することの合法性。ただし、その家畜に害を与えない限りにおいてである。",
          "アッラーの使徒（彼にアッラーからの平安と祝福あれ）のもとでのムアーズの地位と、彼への愛情。",
          "気になってしょうがない質問をすることの合法性。",
          "「ラー・イラーハ・イッラッラーフ、ムハンマドッラスールッラーヒ （アッラーの他に真に崇拝すべきものはなく、ムハンマドはそのアッラーの使徒である）」という証言の条件の一つが、それを口にする者に疑念や偽りがなく、正直であることである。",
          "タウヒード（アッラーの唯一性信仰）の民は、地獄に永遠には留まらない。罪ゆえにそこに入ることになっても、清められてからそこを出ることになる。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  10412: {
    "category_id": 3,
    "category": "神学",
    "title": "祝福にあふれた至高の私たちの主は毎晩、夜も最後の３分の１にさしかかった頃、天の最下層にまでご降臨なさる。そしてこう仰るのだ：「われに祈る者はだれか？それを叶えてやるぞ。われに頼み事をする者は誰か？それを与えてやるぞ。われに罪の赦しを乞う者は誰か？その罪を赦してやるぞ。」",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「祝福にあふれた至高の私たちの主は毎晩、夜も最後の３分の１にさしかかった頃、天の最下層にまでご降臨なさる。そしてこう仰るのだ：『われに祈る者はだれか？それを叶えてやるぞ。われに頼み事をする者は誰か？それを与えてやるぞ。われに罪の赦しを乞う者は誰か？その罪を赦してやるぞ。』」",
    "explanation": "祝福にあふれた至高のアッラーは毎晩、夜の最後の３分の１にさしかかると、天の最下層にまで降臨する。そしてこう仰る：「われに祈る者はだれか？それを叶えてやるぞ。われに頼み事をする者は誰か？それを与えてやるぞ。われに罪の赦しを乞う者は誰か？その罪を赦してやるぞ」と。つまりアッラーは夜のこの時間になると、自分に対して僕たちに祈るように求め、それを奨励するのだ。かれは祈る者にお答えになる。また、かれに望むものを乞うよう、かれらに求める。かれは望むものを与えるお方なのだ。また、かれに罪の赦しを乞うよう求める。かれは信仰者である僕たちの罪を、お赦しになるお方なのである。ここで「求める」というのは、推奨や勧めの意味である。\n尚、この「降臨」は、実際の降臨であるが、被造物の動作には似ていない、その崇高さと完全さに相応しい形によるものである。この降臨を、「慈悲の降臨」とか「天使たちの降臨」といったように解釈することは正しくない。アッラーがその崇高さに相応しい形で最下層の天に降臨されるということを、別の意味に解釈したり、無効化したり、それはどのような様子なのかと考えたり、被造物に似せたりすることなく信じることが義務なのであり、それがスンナ派の手法なのである。",
    "hints": [
          "アッラーが夜の最後の３分の１に、その崇高さに相応しい形で、天の最下層にまで降臨することの信仰。この「降臨」を、別の意味に解釈したり、無効化したり、それはどのような様子なのかと考えたり、被造物に似せたりすることをしてはならない。",
          "夜の最後の３分の１は、祈りが叶えられる時間帯である。",
          "このハディースを聞いた者は、祈りが叶えられる時間帯の活用について、強い熱意を抱くべきである。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  10647: {
    "category_id": 3,
    "category": "神学",
    "title": "墓に向かって礼拝するな。また、そこに座るのではない。",
    "hadeeth": "マルサド・アル＝ガナウィー（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの平安と祝福あれ）は言った：「墓に向かって礼拝するな。また、その上に座るのではない。」",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）は、墓に向かって礼拝することを禁じた。また、そこに座ることも禁じた。その中には墓を足で踏みつけたり、そこで排便したりといった、墓を貶めるような物事も含まれ、それらもまた禁じられる。",
    "hints": [
          "墓に向かって礼拝することの禁止。禁止されているということは、その物事が無効となるということである。",
          "シルクにつながるあらゆる扉を閉ざしてしまうこと。",
          "墓の上に座ることの禁止。それは、墓に入っている者への蔑みにつながる行為であるからである。",
          "墓を過度に敬うことの禁止と、墓を蔑むことの禁止の間に矛盾はない。墓に向かって礼拝することは、墓の偉大視や墓に対する過度の経緯につながるが、墓の上に座ることはそれを蔑むことにつながる。こうしてイスラームは両極端に偏ることなく、過度の敬意と蔑みのいずれも禁じている。",
          "死んだムスリムの尊厳は死後も続く。それは預言者（彼にアッラーからの平安と祝福あれ）の、「死者の骨を損壊することは、生者のそれを損壊するようなものである」という言葉にも示されている通りである。また、ここからも、遺体の一部を損壊したりすることによって死者の尊厳を損ねる者たちは、過ちを犯していると言える。なぜならそこには死者の尊厳の侵害と、死者への懲罰があるからである。法学者たちは、死者がたとえそのように遺言したとしても、遺体の一部を切り離してしまうことは禁じられるとしている。そのようなことは自分自身に対してでさえも、権利を有しないことであるためである。",
          "座るのではなく、墓に寄りかかることは合法である。ただし、人々の習慣によってそれが無礼であると見なされる場合、そうすべきではない。考慮されるべきはその形式であり、人々の習慣によってその形式が無礼と見なされる限り、それはたとえ合法であっても回避すべきだからである。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  10887: {
    "category_id": 3,
    "category": "神学",
    "title": "それらの人々は、彼らの内の正しい僕、または正しい男が死ぬと、その墓の上にマスジドを建て、その中にそれらの肖像を作ったのだ。それらの者たちはアッラーの御許で、最悪の被造物である。",
    "hadeeth": "アーイシャ（彼女にアッラーのご満悦あれ）によれば、ウンム・サラマは、エチオピアの地で彼女が目にしたマーリヤという名の教会についてアッラーの使徒（彼にアッラーからの平安と祝福あれ）に仄めかし、その中で肖像を見たということを伝えた。すると、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「それらの人々は、彼らの内の正しい僕、または正しい男が死ぬと、その墓の上にマスジドを建て、その中にそれらの肖像を作ったのだ。それらの者たちはアッラーの御許で、最悪の被造物である。」",
    "explanation": "アーイシャ（彼女にアッラーのご満悦あれ）によれば、ウンム・サラマ（彼女にアッラーのご満悦あれ）は、彼女がエチオピアの地に滞在していた時、肖像を置いている教会を見た。それで彼女はそれに驚き、その中で見た美しい装飾や像についてアッラーの使徒（彼にアッラーからの平安と祝福あれ）に語った。するとアッラーの使徒（彼にアッラーからの平安と祝福あれ）は、事の重大さと、それがタウヒード（アッラーの唯一性信仰）にもたらす危険性ゆえに頭を上げると、それらの肖像が置かれた原因について人々に説明した。それは、それらの人々の行為について彼の共同体に警告するためであり、こう言ったのである：「あなたが言っているそれらの人々は、彼らの内の正しい者が死ぬと、そこで礼拝するためにその墓の上にマスジドを建て、その中にそれらの肖像を作ったのである。」また、そのようなことをする者が、アッラーの御許で最悪の被造物である、と説明した。なぜならその行為は、アッラーに対するシルクへと導くものだからである。",
    "hints": [
          "墓の上にマスジドを建てること、あるいはマスジドに遺体を埋葬することの禁止。それはシルクへの道を阻み、偶像崇拝者たちに似ることから遠ざかるためである。",
          "墓の上にマスジドを建てたり、マスジドの中に肖像を設けたりすることは、ユダヤ教徒やキリスト教徒の行いである。その様なことをする者は彼らに相似するのであり、彼らに相応しい罰に値する。",
          "墓での礼拝はそれがマスジドの中か外かを問わず、シルクへとつながる道である。",
          "魂があるものの肖像の禁止。",
          "墓の上にマスジドを建て、その中に肖像を作る者は、アッラーの被造物の中で最悪の者である。",
          "タウヒード（アッラーの唯一性信仰）のための、イスラーム法による保護。イスラーム法は、シルクへとつながるあらゆる道筋を閉ざしたのである。",
          "墓の上に建てられたマスジドでの礼拝の無効性。なぜなら預言者（彼にアッラーからの平安と祝福あれ）はそれを禁じ、そのようなことをする者を呪ったからである。禁止は、禁じられた物事の無効性を伴う。",
          "預言者（彼にアッラーからの平安と祝福あれ）の、彼の共同体に対する関心。彼（彼にアッラーからの平安と祝福あれ）は死の床においてでさえも、ユダヤ教徒やキリスト教徒が彼らの預言者たちや正しい人々に対してしたことについて、彼の共同体に注意していたのである。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  10925: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "私は７つの骨をつけてサジダ（平伏礼）するよう、命じられた。つまり、額－自分の手で鼻を指した－、両手、両膝、両足先である。そして、衣服や髪の毛をまとめたりはしない。",
    "hadeeth": "イブン・アッバース（彼らにアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの平安と祝福あれ）は言った：「私は７つの骨をつけてサジダ（平伏礼）するよう、命じられた。つまり、額－自分の手で鼻を指した－、両手、両膝、両足先である。そして、衣服や髪の毛をまとめたりはしない。」",
    "explanation": "アル＝ブハーリーのハディース集の中には、「私は・・・命じられた」「私たちは・・・命じられた」「預言者（彼にアッラーからの平安と祝福あれ）は・・・命じた」という、３通りの伝承が収録されている。イスラーム法のルールによれば、預言者（彼にアッラーからの平安と祝福あれ）が命じられたことは、彼とその共同体に対する一般的命令である。\n「７つの骨をつけてサジダ（平伏礼）するよう、命じられた。」つまり、別の伝承に詳細にされているように、「７つの骨」とは、サジダをする時の部位のことである。続いて、その部位について説明されている。「額」とは、つまりサジダの際には額をつけること、そして「自分の手で鼻を指した」とある通り、鼻も一緒につけることを命じられたということである。ここでは、鼻が額と同じ一つの部位として示されている。「両手」これは両手の平のことが、一般的な形で取り上げられている。「両膝、両足先」つまり、両膝、両足の指先をつけてサジダすることを命じられたということである。礼拝の形に関するアブー・フマイド・アッ＝サーイディー（彼にアッラーのご満悦あれ）のハディースには、このように描写されている：「そして彼（預言者）は、両足の指をキブラ（マッカの方向）に向けた。」これは、サジダの際の様子のことである。\n「そして、衣服や髪の毛をまとめたりはしない。」これは、ルクーゥ（お辞儀をする形の礼拝の一動作）やサジダをする際には、衣服や髪の毛が広がらないように押さえたりまとめたりせず、そのまま地面につけ、全身と共にそれらもまた一緒にサジダするがままに任せておくということである。",
    "hints": [
          "礼拝の際、７つの骨をつけてサジダ（平伏礼）することの義務。命令は義務だというのが基本だからである。",
          "鼻をつけずに額だけ、または額をつけずに鼻だけでサジダするのでは、サジダしたことにならない。預言者（彼にアッラーからの平安と祝福あれ）は額を言及した際、鼻を指さしたからである。",
          "サジダの際、これらの部位を完全につけることの義務。一部だけでは十分ではない。額に関しては、可能なだけの部位を地面につけるだけでよい。",
          "ハディースの表面的理解によれば、これらの部位を露出する必要はない。これらのサジダの部位は、特に露出しなくてもそれらの名称で描写することが可能だからである。両膝についてはそれがアウラ（露わにすべきではない身体部位）の露出につながるため、その露出が義務ではないことに見解の相違はない。両足についても、同様である。礼拝の際に靴下を履いた状態で行うことは、許されている。",
          "礼拝中に衣服を押さえることは、忌避される。",
          "髪の毛を縛ったり、後頭部に結わえたりすることは、礼拝のためであれ、礼拝前にそれ以外の意味でそのようにし、必要性もなくしてその状態のまま礼拝する場合であれ、忌避されることである。",
        ],
    "grade": "真正",
    "attribution": "二大真正集収録の伝承",
  },
  10930: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "預言者（彼にアッラーからの平安と祝福あれ）は２つのサジダ（平伏礼）の間に、こう言っていた：「アッラーフンマ・グフィル・リー、ワ・ルハムニー、ワ・アーフィニー、ワ・フディニー、ワ・ルズクニー。」",
    "hadeeth": "イブン・アッバース（彼らにアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの平安と祝福あれ）は２つのサジダ（平伏礼）の間に、こう言っていた：「アッラーフンマ・グフィル・リー（わが主よ、私を赦して下さい）、ワ・ルハムニー（私を慈しんで下さい）、ワ・アーフィニー（私を無事安泰にして下さい）、ワ・フディニー（私を導いて下さい）、ワ・ルズクニー（私に糧をお恵み下さい）。」",
    "explanation": "イブン・アッバース（彼らにアッラーのご満悦あれ）は、このように伝えている：預言者（彼にアッラーからの平安と祝福あれ）は２つのサジダ（平伏礼）の間に、こう言っていた：「アッラーフンマ・グフィル・リー（わが主よ、私を赦して下さい）・・・」\nつまり、預言者は義務か任意かを問わず、礼拝における２つのサジダの間に、これらの祈りの言葉を唱えていた。礼拝は全てズィクル（念唱）と、クルアーンの読誦である。\n「アッラーフンマ・グフィル・リー」とは、「お咎めすべきところを大目に見て、私を（罪が露わになることから）かくまって下さい」という意味である。\n「ワ・ルハムニー」は、現世と来世の善を私にお恵み下さい、そして私の罪を隠し、私への問責を免除することで、私にあなたのご慈悲をおかけ下さい、という意味である。\n「ワ・アーフィニー」は、私の宗教においては悪や疑念を生じさせるような物事から、私の身体においては病気や不調から、私の理性においては低下や狂気から、私を安全で無事な状態にして下さい、という意味である。そして最大の病は、心の病である。それは迷妄へと至る、疑念を生じさせる物事によるものか、または破滅へと導く欲望によるものである。\n「ワ・フディニー（私を導いて下さい）」に関しては、導きには２種類ある：\n１つは、真理と正しさの道へと示し、教導する種類の導きである。これはムスリムにも、不信仰者にも起こり得るものである。アッラーは仰った：『またサムードはといえば、われらが彼らに導きを示した後、導きよりも（迷いという）盲目を好んだ。』 （クルアーン４１：１７）\n２つ目は、成功と受け入れの種類の導きである。これは信仰の徒に特化されたものであり、ここで言わんとしているのは、この種類の導きである。つまり、「私を真理へと導き、そこにおいて確立させて下さい」という意味である。\n「ワ・ルズクニー」の意味は、この世において、私が他人に乞うことを必要とさせないよう、私に十分な糧をお恵み下さい、そして来世においてはあなたが恩恵を授けられる僕たちに準備した、豊かな糧をお恵み下さい、というものである。",
    "hints": [
          "他の複数のハディースで確実になっているように、２つのサジダの間の座位において、少々休止を置くことの合法性。",
          "２つのサジダの間に祈り、「ラッビグフィル・リー（主よ、私をお赦し下さい）」または「アッラーフンマ・グフィル・リー」と唱えることの義務性。",
          "２つのサジダの間に、ハディースで伝えられている通りの祈りの言葉を唱えるのが最善である。もしそこに言葉の増減があっても、礼拝を無効にはしない。",
        ],
    "grade": "真正",
    "attribution": "イブン・マージャの伝承 - アッ＝ティルミズィーの伝承 - アブー・ダーウードの伝承",
  },
  10947: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "アッラーの使徒（彼にアッラーからの平安と祝福あれ）は礼拝から立ち去る際には、３度アッラーの赦しを求めて、こう言った：「アッラーフンマ・アンタッサラーム、ワ・ミンカッサラーム、タバーラクタ・ヤー・ザル＝ジャラーリ・ワル＝イクラーム。」",
    "hadeeth": "サウバーン（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は礼拝から立ち去る際には、３度アッラーの赦しを求めて、こう言った：「アッラーフンマ・アンタッサラーム（アッラーよ、あなたは平安のお方）、ワ・ミンカッサラーム（平安はあなたからのもの）、タバーラクタ・ヤー・ザル＝ジャラーリ・ワル＝イクラーム（崇高さと栄誉の主に称えあれ）。」",
    "explanation": "このハディースには、礼拝を終えた者が「アスタグフィルッラー（私はアッラーに赦しを乞う）、アスタグフィルッラー、アスタグフィルッラー」と唱え、それから「アッラーフンマ・アンタッサラーム（アッラーよ、あなたは平安のお方）、ワ・ミンカッサラーム（平安はあなたからのもの）、タバーラクタ・ヤー・ザル＝ジャラーリ・ワル＝イクラーム（崇高さと栄誉の主に称えあれ）」という祈りの言葉を述べることの勧めがある。\nこの他にも、他のハディースに収録された、礼拝後に唱えるべき祈りの言葉が存在する。",
    "hints": [
          "このハディースには、礼拝の後にはタクビール（アッラーは偉大なり、という言葉）を唱えるという説への反論がある。",
          "「アッ＝サラーム（平安のお方）」が、アッラーの美名の一つであり、属性であることの確証。アッラーはあらゆる欠点や短所から安全であり、現世と来世の害悪から（守り）、その僕たちに平安を授けるお方である。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  10951: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "立って礼拝せよ。もし出来なければ座って、そしてもし（それも）出来なければ、横になって行うのだ。",
    "hadeeth": "イムラーン・ブン・フサイン（彼らにアッラーのご満悦あれ）は、言った：私は痔を持っていたので、礼拝について預言者（彼にアッラーからの平安と祝福あれ）に尋ねた。彼は言った：「立って礼拝せよ。もし出来なければ座って、そしてもし（それも）出来なければ、横になって行うのだ。」",
    "explanation": "このハディースは、痔の病気がある者や、立つと痛みを覚える者など、正当な理由のある者たちの礼拝の仕方を明らかにしている。預言者（彼にアッラーからの平安と祝福あれ）は、元来礼拝は立って行うものだが、もしそれが出来ない状況なら座って礼拝し、もし座ってでさえも出来なければ、横になって礼拝するのだと述べた。",
    "hints": [
          "病人にとっての義務の礼拝の順番づけを、考慮する義務。可能ならば、礼拝は立って行わなければならない。なぜならそれは、義務の礼拝の基本部分であるためである。ゆえに、たとえ何かによりかかったり、杖や壁のような物で自分を支えたりでも、立って出来るならそうすべきである。",
          "立って礼拝出来ないか、またはそれが厳しければ、座って礼拝しなければならない。たとえ何かによりかかってでも、そうすべきである。この場合、ルクーゥ（お辞儀のような形の動作）やサジダ（平伏礼）は、出来る範囲で行う。もし座って礼拝することが出来ないか、それが厳しければ、横になって礼拝する。その場合、右側を下にして横になるのがよりよい。キブラ（マッカの方向）に向かって、仰向けに礼拝しても有効である。こういった場合、礼拝の動作は頭の仕草で示す。礼拝の基本動作に区別をつけるため、サジダの仕草は、ルクーゥの仕草よりもより深くする。本来、サジダはルクーゥより低く行う動作だからである。",
          "そうすることが不可能だったり、あるいはその状況、行為において困難だったりしない限り、次の段階には移行しないこと。なぜなら、ある段階から次の段階へ移行することは、そうすることを出来ないことが条件づけられているためである。",
          "義務の礼拝を座って行うことが可能となる困難性の程度は、それが礼拝におけるフシューゥ（心身の静寂を伴う畏怖の念）を失わせてしまうほどにまで達することである。それは、フシューゥこそが礼拝の最大の目指すべきものであるためである。",
          "義務の礼拝を座ったまま行うことが許される原因は沢山あり、病気に限定されるものではない。たとえば天井が低い空間で、そこから出れない状況や、船や車や飛行機内での礼拝が必要になり、起立できない状況もまた、その原因となる。",
          "礼拝は理性がある限り、免除されない。ゆえに病人は頭部によって礼拝動作の仕草が出来なければ、視線によってそうする。つまりルクーゥの際には視線を下げ、サジダの際にはそれよりも更に視線を下げる、といった具合である。また、もし舌で読誦できるのであればそうするが、もしそう出来なければ、心で読むようにする。そして視線でさえも礼拝動作を示すことが出来なければ、心の中でそうするのである。",
          "ハディースは非限定の形であるため、座った状態で礼拝する際には、どのような形の座り方でもよい。これはイジュマー（学者間の見解の一致するところ）だが、しかし学者の見解が異なるのは、何が最善の形かということである。大多数の学者は、本来立った状態、及びルクーゥから戻った時には、あぐらをかいた姿勢で礼拝し、サジダから戻った際には、通常の礼拝における座位姿勢（左足は横にして臀部の下に置き、右足はつま先を立てた状態）で行うのがよいとしている。",
          "アッラーの命令事項は、能力、可能性に応じて行う。アッラーは、人が耐えきれないほどのものを課すことはない。",
          "イスラームの教えの易しさ、寛容さ。アッラーは仰っている：『かれは、宗教においてあなた方にいかなる困難も課されなかったのだぞ。』（２２：７８）『アッラーは、あなた方（の負担）を軽減するよう望まれる。』（４：２８）僕たちに対するアッラーの慈悲は、広大なのである。",
          "ここで取り上げられているのは、義務の礼拝についての規定である。任意の礼拝については、理由なしに座位で行っても有効である。ただし、もしそうする正当な理由があれば、それによって完全なる褒美を得ることが出来るが、そうでなければ、本来立って行って得られたはずの褒美の半分しか獲得できない。このことは、他のハディースの中で明確にされている。",
        ],
    "grade": "真正",
    "attribution": "アル＝ブハーリーの伝承",
  },
  11287: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "預言者（彼にアッラーからの祝福と平安あれ）の許に、ある盲目の男がやって来て、こう言った：「アッラーの使徒よ。私には、私のことをマスジドに連れて行ってくれる人がおりません。」それから彼はアッラーの使徒（彼にアッラーからの祝福と平安あれ）に、家で（義務の）礼拝をしてもよいかと尋ね、その許可を得た。そして彼がそこを立ち去ろうとした時、アッラーの使徒は彼にこう尋ねた：「礼拝の呼びかけ（アザーン）は聞こえるか？」彼が「ええ」と答えると、彼は言った：「ならば、（呼びかけに）応じよ。」",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は言った：「預言者（彼にアッラーからの祝福と平安あれ）の許に、ある盲目の男がやって来て、こう言った：『アッラーの使徒よ。私には、私のことをマスジドに連れて行ってくれる人がおりません。』それから彼はアッラーの使徒（彼にアッラーからの祝福と平安あれ）に、家で（義務の）礼拝をしてもよいかと尋ね、その許可を得た。そして彼がそこを立ち去ろうとした時、アッラーの使徒は彼にこう尋ねた：『礼拝の呼びかけ（アザーン）は聞こえるか？』彼が『ええ』と答えると、彼は言った：『ならば、（呼びかけに）応じよ。』」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）の許に、ある盲目の男がやって来て、こう言った：「アッラーの使徒よ。私は目が見えませんが、５回の礼拝のために私のために手伝ってくれ、私の手を取ってマスジドに連れて行ってくれる人がおりません。」彼は預言者（彼にアッラーからの祝福と平安あれ）から、集団礼拝をしなくてもよいとの許可が欲しかったのだが、その許可を得た。そして彼がそこを立ち去ろうとした時、預言者は彼を呼び、こう言った：「礼拝の呼びかけ（アザーン）は聞こえるか？」彼が「ええ」と答えると、彼は言った：「ならば、礼拝へと呼びかける者に応じよ。」",
    "hints": [
          "集団礼拝の義務。なぜなら義務的なものしか、免除の許可の対象にはならないからである。また、預言者の言葉「ならば、（呼びかけに）応じよ」は命令であり、命令は元来義務に対するものである。",
          "目が見えない者にも、集団礼拝の義務があること。たとえマスジドへと連れて行ってくれる者がいなかったとしても、である。",
          "回答者は、性急に回答することを避け、回答する前に質問者の状態を尋ねるべきである、との教育。",
        ],
    "grade": "真正",
    "attribution": "ムスリムの伝承",
  },
  11310: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "礼拝にやって来た時、イマームが（礼拝中の）ある状態にあったなら、イマームが行うように行うのだ。",
    "hadeeth": "アリー・ブン・アビー・ターリブとムアーズ・ブン・ジャバル（彼らにアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの平安と祝福あれ）は言った：「礼拝にやって来た時、イマームが（礼拝中の）ある状態にあったなら、イマームが行うように行うのだ。」",
    "explanation": "礼拝にやって来た時、イマームが起立、ルクーゥ（お辞儀のような形態の動作）、サジダ（平伏礼）、座位など、礼拝中の動作にあったなら、起立やルクーゥなど、イマームと同じ動作に入るべきである。ある種の一般信徒がするように、イマームが起立するまで待っているようなことはしない。",
    "hints": [
          "遅れてやって来た礼拝者は、そこで見出した礼拝がいかなる段階にあったとしても、イマームの動作に倣って礼拝を開始すること。ルクーゥ、サジダ、座位など、それがどんな動作なのかは問わない。",
          "他のハディースが示しているように、後から礼拝に入る者にとってそれが１ラクアと数えられるかどうかは、そのラクアにおけるイマームのルクーゥに間に合ったかどうかによる。",
        ],
    "grade": "真正",
    "attribution": "アッ＝ティルミズィーの伝承",
  },
  58060: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "アッラーの使徒（彼にアッラーからの平安と祝福あれ）は私たちに、このような「必要のフトバ（説教）」を教えて下さった：「インナル・ハムド・リッラーヒ、ナスタイーヌフ、ワ・ナスタグフィルフ。ワ・ナウーズ・ビヒ・ミン・シュルーリ・アンフスィナー・・・」",
    "hadeeth": "アブドッラー・ブン・マスウード（彼にアッラーのご満悦あれ）は、言った：アッラーの使徒（彼にアッラーからの平安と祝福あれ）は私たちに、このような「必要のフトバ（説教）」を教えて下さった：「インナル・ハムド・リッラーヒ、ナスタイーヌフ、ワ・ナスタグフィルフ（まことにアッラーにこそ、称賛はあれ。私たちはかれにご助力を乞い、かれに赦しを乞います）。ワ・ナウーズ・ビヒ・ミン・シュルーリ・アンフスィナー（私たちはかれに、私たち自身の悪からのご加護を乞います）。マン・ヤフディッラーフ、ファ・ラー・ムディッラ・ラフ（かれが導いた者を迷わせる者はありません）。ワ・マン・ユドゥリル、ファ・ラー・ハーディヤ・ラフ（かれが迷わせた者を、導く者はありません）。ワ・アシュハド・アッラー・イラーハ・イッラッラーフ、ワ・アシュハド・アンナ・ムハンマダン・アブドゥフ・ワ・ラスールフ（私はアッラー以外に崇拝すべきいかなるものも存在しないことを証言し、ムハンマドがかれの僕であり使徒であることを証言します）。『ヤー・アイユハンナースッ・タクー・ラッバクムッラズィー・ハラカクム・ミン・ナフスィン・ワーヒダティン、ワ・ハラカ・ミンハー・ザウジャハー・ワ・バッサ・ミンフマー・リジャーラン・カスィーラン・ワ・ニサーアー（人々よ、あなた方を一人の者（アーダム）から創られ、彼からその妻を創られ、そしてその二人から多くの男女を（創り）広められた、あなた方の主を畏れるのだ）。ワッタクッラーハッラズィー・タサーアルーナ・ビヒ・ワルアルハーマ（そして、あなた方がかれにおいて頼みごとをし合うアッラーと、親戚の絆（の断絶）を畏れよ）。インナッラーハ・カーナ・アライクム・ラキーバー（本当にアッラーはもとより、あなた方（の一部始終）を見守られるお方である）。』（婦人章１）『ヤーアイユハッラズィーナ・アーマヌーッタクッラーハ・ハッカ・トゥカーティヒ（信仰する者たちよ、真の畏怖の念をもってアッラーを畏れよ）、ワ・ラー・タムートゥンナ・イッラー・ワ・アントゥム・ムスリムーン（そして服従する者（ムスリム）としてでしか、死んではならない）。』（イムラーン家章１０２）『ヤーアイユハッラズィーナ・アーマヌーッタクッラーハ・ワ・クールー・カウラン・サディーダン（信仰する者たちよ、アッラーを畏れ、まっとうな物言いをせよ）、ユスリフ・ラクム・アァマーラクム、ワ・ヤグフィルラクム・ズヌーバクム（（そうすれば）かれはあなた方のため、あなた方の行いを正して下さり、あなた方のためにその罪をお赦し下さろう）。ワ・マン・ユティイッラーハ・ワ・ラスーラフ、ファカド・ファーザ・ファウザン・アズィーマー（アッラーとその使徒に従う者は誰でも、確かに（現世と来世において、）偉大な勝利を獲得したのだ）。』（部族連合章７０－７１）」",
    "explanation": "このイブン・マスウード（彼にアッラーのご満悦あれ）の伝承は、アッラーへの讃美、かれのご助力の請願、悪からのかれへの避難、これらの尊いクルアーンの節の読誦を含むフトバ（説教）を伝えている。クルアーン、スンナ、法学について人々に語りかけようとしたり、訓戒を施したりする者は、その前にこのフトバを前文とすべきである。このフトバは結婚の契約のみならず、あらゆる必要事のためのものである。そうすることにより祝福が下り、その物事によい影響をもたらすのであり、同時にそれは強調されたスンナでもある。",
    "hints": [
          "必要事の際には、このフトバを前置きとすることが推奨される。この訓戒の祝福によって、それは成功するであろう。",
          "フトバは、以下の物事を含んでいるべきである：讃美。２つの信仰証言。クルアーンのいくつかの節。",
          "このハディースが必要のフトバと呼ばれるもので、クルアーン、スンナ、法学について人々に語りかけようとしたり、訓戒を施したりする際には、このフトバが推奨される。このフトバは結婚の契約のみならず、あらゆる必要事のためのものである。結婚はそういった必要事の一つでしかない。",
          "このハディースは、アッラーの讃美すべき属性、かれが讃美に値すること、かれがそのような属性を有していることの確証が含まれている。",
          "このハディースには、これから行おうとする用事におけるアッラーからのご助力と、それを容易にしてくれることの祈願が含まれている。特に結婚における負担や糧に関するものである。",
          "このハディースには、アッラーからの罪の赦しや、自らの欠点や罪を隠してもらうことの祈願、自らの至らなさの自覚、罪の抹消と赦しの請願が含まれている。",
          "このハディースには、悪へと傾きがちで、禁じられた物事を行うことと義務行為の放棄へと促す、心の悪からのご加護の請願が含まれている。アッラーがお守りになり、ご加護を与えて下さる者の他、そこから安全な者はいない。",
          "このハディースには、アッラーこそが被造物を自由に司るお方であり、心が導かれるのも迷わされるのもアッラー次第であることの確証が含まれている。",
          "このハディースには、２つの信仰証言が含まれている。それはイスラームの鍵であり、基本である。人はその証言を心の奥底から認めるまで、ムスリムになることはない。",
        ],
    "grade": "真正",
    "attribution": "イブン・マージャの伝承 - アッ＝ティルミズィーの伝承 - アン＝ナサーイーの伝承 - アブー・ダーウードの伝承 - アハマドの伝承",
  },
