    "title": "「後見人なしの結婚はない。」",
    "hadeeth": "アブー・ムーサー（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は言った： 「後見人なしの結婚はない。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、後見人が結婚の契約を行うことなしには女性の結婚が正しいものにならないことを、説明している。",
