          "後見人には、女性に最も近縁な男性がなる。より近縁な男性がいるのに、より遠縁の男性が後見人として結婚をさせてはならない。",
          "後見人には、以下の条件が求められる：宗教的責任。男性。結婚の福利に関する知識において分別があること。後見人の宗教と、自らが後見人となる女性の宗教との一致。これらの特徴があてはまらない者は、結婚の契約において後見人として相応しくない。",
