    "category": "諸々の徳と礼儀作法",
    "title": "少年よ、アッラーの名を唱えよ。右手で食べよ。自分の近くから食べるのだ。",
    "hadeeth": "ウマル・ブン・アビー・サラマ（アッラーのご満悦あれ）は言った： 私は子供で、アッラーの使徒（アッラーからの祝福と平安あれ）の後見下にあった。そして私の手は、皿の上をひっきりなしに動いていた。それでアッラーの使徒（アッラーからの祝福と平安あれ）は私に言った：「少年よ、アッラーの名を唱えよ。右手で食べよ。自分の近くから食べるのだ。」それ以来、それが私の食べ方になっているのである。",
    "explanation": "ウマル・ブン・アビー・サラマ（アッラーのご満悦あれ）は伝えている。彼は預言者（アッラーからの祝福と平安あれ）の妻ウンム・サラマ（アッラーのご満悦あれ）の連れ子で、預言者（アッラーからの祝福と平安あれ）の後見下にあった。ウマルの手は食事のとき、食べ物を選ぼうとして食器の上をあちらこちらと行き来していた。それを見た預言者（アッラーからの祝福と平安あれ）は、食事の礼儀作法の内の３つを彼に教えた。\n\n１つ目は食べる前に、「ビスミッラー（アッラーの名において）」と唱えることである。\n\n２つ目は、右手で食べること。\n\n３つ目は、自分の近いところから食べ物を食べることである。",
    "hints": [
