  58122: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「食べるときは右手で食べ、飲むときには右手で飲むのだ。悪魔が左手で食べ、左手で飲むのであるから。」",
    "hadeeth": "イブン・ウマル（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「食べるときは右手で食べ、飲むときには右手で飲むのだ。悪魔が左手で食べ、左手で飲むのであるから。」",
