  58218: {
    "category_id": 6,
    "category": "宣教と勧善懲悪",
    "title": "「（指導者への）服従を（拒んで）抜け出、集団から離別して死を迎えた者は、ジャーヒリーヤの死を迎えたのである",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は、こう言った： 「（指導者への）服従を（拒んで）抜け出、集団から離別して死を迎えた者は、ジャーヒリーヤの死を迎えたのである。また、正誤をわきまえない旗のもとで戦い、部族主義ゆえに怒り、部族主義へと招き、あるいは部族主義を援助して殺された者は、ジャーヒリーヤの死でもって殺されたのである。また、わがウンマに対して反旗を翻し、その中の善人と悪人を討ち、その中の信仰者に対して自重することもなく、契約の民の契約にも忠実でない者は、私の仲間でもないし、私が彼の仲間ということもない。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、このように説明している：指導者への服従を（拒んで）抜け出て、指導者のもとに一致するイスラームの集団から離別し、分裂と不服従のままの状態で死を迎えた者は、ジャーヒリーヤの民の死を迎えたのである。それらの民は指導者に従いもせず、一つの集団にまとまることもなく、分裂し、集団に分かれて互いに戦い合っていたのである。\n\nまた預言者（アッラーからの祝福と平安あれ）は、このようにも伝えている：正誤をわきまえない旗のもとで戦い、自らの宗教や真理のためではなく、部族や民族ゆえにこそ怒り、知識も英知もないままに偏狭さゆえに戦い合う者は、もしそのような状態のまま殺されたのだとしたら、ジャーヒリーヤの死でもって殺されたのである。\n\nまた、こうも言っている：預言者（アッラーからの祝福と平安あれ）のウンマに対して反旗を翻し、その中の善人と悪人を討ち、その中の信仰者に対して自重することもなく、その殺害の結末も恐れず、不信仰の人々からなる契約の民や統治者との契約にも忠実であることなく、それを破棄する（これらは大罪である）ような者は、この厳しい警告に値するのである、と。",
