    "category": "諸々の徳と礼儀作法",
    "title": "「アッラーが禁じたこの汚れた行いを避けよ。もし誰かがそのようなことをやってしまったなら、アッラーの覆いによってそれを隠し、アッラーに悔悟せよ。なぜなら、自分の罪を私たちに対して公にした者に、私たちはアッラーの書を適用するからである。」",
    "hadeeth": "アブドッラー・ブン・ウマル（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、アル＝アスラミーの者が石打ちにされた後、立ち上がってこう言った： 「アッラーが禁じたこの汚れた行いを避けよ。もし誰かがそのようなことをやってしまったなら、アッラーの覆いによってそれを隠し、アッラーに悔悟せよ。なぜなら、自分の罪を私たちに対して公にした者に、私たちはアッラーの書を適用するからである。」",
    "explanation": "アブドッラー・ブン・ウマル（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、マーイズ・ブン・マーリク・アル＝アスラミー（アッラーのご満悦あれ）が姦淫の刑で石打ちにされた後、人々に説教してこう言った： アッラーが禁じた、この汚れた、醜く罪深い行いを避けよ。そのようなことに陥ってしまった者には、２つのものが義務づけられる： １．アッラーの覆いによって隠し、その罪について口外しないこと。 ２．アッラーにすぐ悔悟し、そこに陥り続けないこと。その罪が公にされた者には、その罪に対してクルアーンで定められた刑が実行される。",
