  65000: {
    "category_id": 3,
    "category": "神学",
    "title": "「イスラームは５つのものの上に成立する",
    "hadeeth": "イブン・ウマル（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「イスラームは５つのものの上に成立する：アッラー以外に崇拝すべきいかなるものもない、ムハンマドはかれのしもべであり、使徒であるという証言。礼拝の遵守。喜捨の支払い。館へのハッジ。ラマダーンの断食。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はイスラームを、５本の柱に支えられた強固な建築物のようなものであり、それ以外のイスラームの特質は、その建築物を補完するようなものである、と例えている。 １番目の柱：２つのシャハーダ（信仰証言）。アッラーの他に崇拝すべきものはなく、ムハンマドはアッラーの使徒であるという証言のこと。この２つが互いに離れることのない、一つの柱を成している。ムスリムはアッラーの唯一性と、アッラーこそが崇拝に値する存在であり、他のいかなるものもそれには相応しくないことを認めつつこの言葉を証言し、それが要求するところのものに則って行い、預言者ムハンマド（アッラーからの祝福と平安あれ）のメッセージを信じ、彼に従うのである。 ２番目の柱：昼夜に行われる１日５回のサラーを遵守すること。それはファジュル、ズフル、アスル、マグリブ、イシャーのことであり、それらをその条件、根幹、義務を守りながら行うことである。 ３番目の柱：義務のザカー（浄財）。これはイスラーム法において定められた特定の額に達する財産に義務付けられ、その受給資格者へと支払われる、財産による崇拝行為である。 ４番目の柱：アッラーを崇拝するために、一連の宗教儀礼を行うためマッカを目指すハッジ巡礼のこと。 ５番目の柱：ラマダーンのサウム（断食）のこと。これはアッラーを崇拝することを意図して、ファジュルからマグリブまで、飲食などサウムを無効にする物事を慎むことである。",
    "hints": [
          "２つの信仰証言は一つの柱をなし、分離不可能である。",
          "２つの信仰証言は宗教の基礎であり、それなしにはいかなる言葉も行いも受け入れられない。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65001: {
    "category_id": 3,
    "category": "神学",
    "title": "「悪事を目にした者は、それを手でもって正せ。もしそう出来なければ、舌でもって正せ。そしてそれさえも出来なければ、心でもって正すのだ。そしてそれが最も弱いイーマーンである。」",
    "hadeeth": "アブー・サイード・アル＝フドゥリー（彼にアッラーのご満悦あれ）は言った：私はアッラーの使徒（アッラーからの平安と祝福あれ）がこう言うのを聞いた： 「悪事を目にした者は、それを手でもって正せ。もしそう出来なければ、舌でもって正せ。そしてそれさえも出来なければ、心でもって正すのだ。そしてそれが最も弱いイーマーンである。」",
    "explanation": "預言者（アッラーからの平安と祝福あれ）は可能な限り、悪事を正すように命じた。悪事とは、アッラーとその使徒が禁じた全ての物事のことである。 ゆえにもし悪事を目にし、そう出来るならば、それを手で正さなければならない。 もしそう出来ないのならば、その時には舌でもって正さなければならない。つまり、悪事を行う者を禁じ、その害悪を説明し、そのような悪の代わりに善へと導くことによってである。 そしてもしその段階も無理なのであれば、その時には心で正す。つまりその悪事を嫌い、もしそう出来るのならばそれを正すのだという決意を持つことである。 悪事を正すことにおいて、それを心で正すことは、イーマーンにおいて最も弱いランクである。",
    "hints": [
          "このハディースは、悪事を正すことのランクの説明における基本である。",
          "段階性をもって悪事を禁じることの命令。そしてその全ては、能力に応じたものとなる。",
          "悪事を禁じることは宗教における偉大な部門の一つであり、誰からも免除されることはない。そして全ムスリムはそこにおいて、その能力に応じた義務性を有するのである。",
          "善を命じ悪を禁じるのは、イーマーンの特質の一つである。そしてイーマーンは、増減する。",
          "悪事を禁じることにおいては、その行為が悪事であるという知識を有することが条件づけられる。",
          "悪事を禁じることにおいては、そうすることによってより大きな悪事が引き起こされないということが条件づけられる。",
