          "悪事を禁じることにおいては、イスラーム的政策、知識、炯眼が必要になる。",
          "心によっても悪事を否認できないことは、イーマーンの弱さを示している。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65002: {
    "category_id": 3,
    "category": "神学",
    "title": "イスラームにおいて善を尽くした者が、ジャーヒリーヤにおいて行なったことでお咎めを受けることはない。だがイスラームにおいて悪かった者は、先のものと後のものでお咎めを受けることになる。」",
    "hadeeth": "イブン・マスウード（アッラーのご満悦あれ）によれば、 ある男が言った：「アッラーの使徒よ、私たちはジャーヒリーヤ（無明）時代に私たちが行なっていたことで、お咎めを受けるのでしょうか？」預言者は言った：「イスラームにおいて善を尽くした者が、ジャーヒリーヤにおいて行なったことでお咎めを受けることはない。だがイスラームにおいて悪かった者は、先のものと後のものでお咎めを受けることになる。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、イスラームに入ることの徳を説明した。 イスラームを受け入れ、そのイスラームの実践の状態が良くなり、真摯で正直だった者は、ジャーヒリーヤで行なってしまった罪に関してお咎めを受けることはない。 しかし偽信者となったり、棄教したりといった風に、イスラーム改宗の後の状態が悪かった者については、不信仰だった時の行いとイスラーム改宗以後の行いの両方でお咎めを受けることになる。",
