  65003: {
    "category_id": 3,
    "category": "神学",
    "title": "仰って下さい。もし義務のサラー(礼拝)を礼拝し、ラマダーンをサウム(断食)し、ハラールなものをハラールとし、ハラームなものをハラームとすれば",
    "hadeeth": "ジャービル（アッラーのご満悦あれ）によれば、 アッラーの使徒（アッラーからの祝福と平安あれ）にある男が尋ねた:「仰って下さい。もし義務のサラー(礼拝)を礼拝し、ラマダーンをサウム(断食)し、ハラールなものをハラールとし、ハラームなものをハラームとすれば、それ以上のことをしなくても、私は天国に入るでしょうか？」アッラーの使徒（アッラーからの祝福と平安あれ）は言った:「ええ。」男は言った:「アッラーに誓って。私はそれ以上のことはしません。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、こう説明している:5つの義務のサラー(礼拝)は礼拝するが、それ以外の任意のサラーはせず、ラマダーンのサウム(断食)はするが、それ以外の任意のサウムはせず、ハラールなものをハラールと信じてそれに則って行い、ハラームなものをハラームと信じて回避する者は、天国に入る。",
    "hints": [
          "義務の遂行と禁じられた物事の回避、目的を天国とすることにおけるムスリムの関心。",
          "ハラールなものをハラールと信じてそれに則って行い、ハラームなものをハラームと信じて回避することの重要性。",
          "義務の遂行と禁じられた物事の回避が、天国に入ることの原因であること。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65004: {
    "category_id": 3,
    "category": "神学",
    "title": "「清浄さはイーマーンの半分である 。そして「アルハムドリッラー」は秤を満たし、「スブハーナッラー」と「アルハムドリッラー」は天地を充溢させる",
    "hadeeth": "アブー・マーリク・アル＝アシュアリー（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの平安と祝福あれ）は言った： 「清浄さはイーマーンの半分である 。そして「アルハムドリッラー」は秤を満たし、「スブハーナッラー」と「アルハムドリッラー」は天地を充溢させる。そしてサラー（礼拝）は光であり、サダカ（施し）は明証である。また忍耐は輝きであり、クルアーンはあなたにとっての証人、あるいはあなたに対しての証人である。全ての者は行いに励み、自らの魂を取引する。それである者は自らを救い、またある者は自らを滅ぼすのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は伝える:外面的清浄は、ウドゥーとグスルによってなされる。それはサラーの条件である。 「アルハムドリッラーは秤を満たす」という言葉は、崇高なアッラーへの賛美と、かれを完全なる属性によって描写することにより、審判の日に善行の秤が満たされるということである。 「スブハーナッラー」と「アルハムドリッラー」は、アッラーへの愛情と偉大視と共に、かれをあらゆる欠陥から無縁とし、かれに相応しい完全なる属性によって描写することであり、それによって天地が充溢するということである。 しもべの心、顔、墓、復活への招集の場において、「サラー（礼拝）は光」となる。 「サダカ（施し）は明証である」というのは、それが信仰者の信仰を実証し、そこにおいて約束されたものを信じないためにそれを行わない偽信者との違いを明らかにするものである、ということである。 忍耐とは、動揺や嫌気がさした状態に陥ることから自分自身を抑えることである。それは太陽の輝きのような熱が生じる光である。なぜならばそれは困難を伴うものであり、自分の心を抑える努力を必要とするものであり、人はそれによって正しい道を導き照らされ、歩き続けることができるからである。忍耐とは、アッラーへの服従におけるものであり、アッラーへの反抗から自身を抑制するものであり、この世における災難や諸々の好ましくない出来事が起こってしまった状況における忍耐である。 その読誦、内容の実践により、「クルアーンはあなたにとっての証人」となるが、実践も読誦も放棄すれば、「あなたに対しての証人」つまり反証にもなる。 また、預言者（アッラーからの祝福と平安あれ）は、全ての人間はそれぞれの異なる行いのために努力し、奔走し、寝床から起き、家を外出するものだ、と語る。 そのような中、ある者はアッラーへの服従に勤しむことによって自らを地獄から救い、またある者はそこから逸脱して罪深い行いに陥り、自らを滅ぼして地獄に入るのである。",
    "hints": [
          "清浄には２種類ある。外面的清浄は、ウドゥーとグスルによってなされ、内面的清浄はタウヒード（唯一神信仰）、信仰、正しい行いによってなされる。",
          "サラー（礼拝）を遵守することの重要性。それは現世と審判の日における、しもべにとっての光である。",
          "サダカ（施し）は信仰を実証する証拠である。",
          "審判の日に自らの反証とならないためにも、クルアーンに基づいて行い、それを信仰することの重要性。",
          "人間の魂はアッラーへの服従行為に勤しめなければ、アッラーへの反抗に勤しむことになる。",
          "全ての人間は何らかの行いを行う。そしてアッラーに対する服従行為によって自らを解放するか、アッラーへの反抗によって自らを滅ぼすかのどちらかなのである。",
          "忍耐は、よいものを望んで耐え忍ぶことである。そこには困難がある。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65005: {
    "category_id": 2,
    "category": "ハディースとその諸学",
    "title": "”私からハディースが届き、ソファーにもたれかかった状態で、このように語る男がいるかもしれない：「私たちとあなた方との間にあるのはクルアーンのみ",
    "hadeeth": "アル＝ミクダーム・ブン・マァディーカリバ（彼にアッラーのご満悦あれ）は言った：「アッラーの使徒（彼にアッラーからの平安と祝福あれ）はこう言った： ”私からハディースが届き、ソファーにもたれかかった状態で、このように語る男がいるかもしれない：「私たちとあなた方との間にあるのはクルアーンのみ。そこにおいてハラールと見出したものを、私たちはハラールとする。また、そこにおいてハラームと見出したものを、私たちはハラームとする。」実際のところ、アッラーの使徒（彼にアッラーからの平安と祝福あれ）がハラームとしたものは、アッラーがハラームとしたもの同様なのである。”」",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）は言っている：このような種類の人間が出現する時は近い。つまり、寝床にもたれかかった状態で座り、預言者（彼にアッラーからの平安と祝福あれ）からのハディースが届いた時に、このようなことを語る者のことである：「私たちとあなた方の間の物事に裁決を下すのはクルアーンのみであり、私たちにはそれだけで十分である。そこにおいてハラールと見出したものを、私たちは用い、そこにおいてハラームと見出したものについては、私たちはそれを回避するのである。 それから預言者（彼にアッラーからの平安と祝福あれ）は、こう説明した：預言者がそのスンナにおいてその法規定をハラームとし禁じたものは、アッラーがクルアーンの中でハラームとしたもの同様である。なぜなら彼は、アッラーからそれを伝える者だからである。",
    "hints": [
          "クルアーンを偉大視するようにスンナも偉大視し、それに依拠すること。",
          "アッラーの使徒に服従することはアッラーに服従することを意味し、アッラーの使徒に反抗することはアッラーへの反抗を意味する。",
          "スンナがイスラームの教えの根拠であることの確証と、スンナに反駁しそれを否定する者に対する反論。",
          "スンナに背を向け、クルアーンだけで十分と主張する者は、そのいずれにも背を向けているのであり、クルアーンへの服従の主張においても嘘をついていることになる。",
          "預言者（彼にアッラーからの平安と祝福あれ）が未来に起こる出来事について語り、それが実際に実現したことによる、彼の預言者性の根拠。",
        ],
    "grade": "صحيح",
    "attribution": "رواه أبو داود والترمذي وابن ماجه",
  },
  65006: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "アッラーの使徒よ、私は大小の罪深い物事で、やらなかったことはありません。」彼は３回、こう言った：「あなたはアッラー以外に崇拝すべきものはなく、ムハンマドはアッラーの使徒であると証言するのではないか？",
    "hadeeth": "アナス（彼にアッラーのご満悦あれ）は言った： ある男が預言者（彼にアッラーからの祝福と平安あれ）のところにやって来て、言った：「アッラーの使徒よ、私は大小の罪深い物事で、やらなかったことはありません。」彼は３回、こう言った：「あなたはアッラー以外に崇拝すべきものはなく、ムハンマドはアッラーの使徒であると証言するのではないか？」彼は言った：「はい（証言します）。」すると彼は言った：「それがそれらのためになるのである。」",
    "explanation": "ある男が預言者（彼にアッラーからの祝福と平安あれ）のところにやって来て、言った：「アッラーの使徒よ、私はあらゆる罪を犯しました。大小の罪で、私がやらなかったことはありません。それでも私は赦されるのでしょうか？」 それで預言者（彼にアッラーからの祝福と平安あれ）は、彼に言った：「あなたはアッラー以外に崇拝すべきものはなく、ムハンマドはアッラーの使徒であると証言するのではないか？」 彼は、そう３回くりかえした。 それで男は答えた：「はい、証言します。」 預言者（彼にアッラーからの祝福と平安あれ）は、二つの信仰証言の徳と、それが悪行への贖罪になるということ、そして悔悟が過去の罪を抹消するのだということを彼に伝えた。",
    "hints": [
          "信仰証言の偉大さと、それを心から誠実に口にした者にとっては、それが罪を乗り越えるものになるということ。",
          "イスラームは過去の罪を抹消する。",
          "誠実な悔悟は、過去の罪を抹消する。",
          "言葉を繰り返すことは、教育における預言者（彼にアッラーからの祝福と平安あれ）の手法である。",
          "信仰証言の徳と、それが地獄における永遠の罰からの救いとなること。",
        ],
    "grade": "صحيح",
    "attribution": "رواه أبو يعلى والطبراني والضياء المقدسي",
  },
  65007: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーのしもべに対する権利とは、彼らがアッラーを崇拝し、かれに何ものも並べたりしないことだ。そしてアッラーに対するしもべの権利とは、かれに何も並べて拝したりさえしなければ、罰されはしないことだ",
    "hadeeth": "ムアーズ（彼にアッラーの御満悦あれ）はこう伝えている： 「私はウファイルという名の 1 頭のロバに預言者（アッラーからの祝福と平安あれ）と同乗し、彼の後ろに乗っていた。彼（アッラーからの祝福と平安あれ）は言った：“ムアーズよ、アッラーのしもべに対する権利と、アッラーに対するしもべの権利について知っているか？”私は言った：“アッラーとその使徒がよく御存知です。”彼（アッラーからの祝福と平安あれ）は言った：“アッラーのしもべに対する権利とは、彼らがアッラーを崇拝し、かれに何ものも並べたりしないことだ。そしてアッラーに対するしもべの権利とは、かれに何も並べて拝したりさえしなければ、罰されはしないことだ。”私は言った：“アッラーの使徒よ、人々にこの吉報を伝えましょうか？”彼（アッラーからの祝福と平安あれ）は言った：“伝えないでおくのだ。彼らが頼り切ってしまわないように。”」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、アッラーのしもべに対する権利と、アッラーに対するしもべの権利について語り、アッラーのしもべに対する権利とは、彼らがアッラーを崇拝し、かれに何ものも並べたりしないことであると説明した。 また、アッラーに対するしもべの権利とは、かれに何も並べて拝しないタウヒードの徒を、かれが罰しないことであると説明した。 その後、ムアーズは言った：「アッラーの使徒よ、人々がこの素晴らしいことに喜ぶよう、この吉報を彼らに伝えましょうか？」 しかし預言者（アッラーからの祝福と平安あれ）は、彼らがそのことに頼り切ってしまうことを恐れ、それをムアーズに許さなかった。",
    "hints": [
          "アッラーのしもべに対する権利と、それが、彼らがアッラーを崇拝し、かれに何ものも並べたりしないことであるという説明。",
          "アッラーに対するしもべの権利が、彼らがかれに何も並べて拝したりしなければ天国に入り、罰されないということの説明。この権利はアッラーから彼らに、恩恵として与えられたものである。",
          "このハディースには、アッラーに何ものも並べたりしないタウヒードの徒の行き先が天国であるという、偉大な吉報が含まれている。",
          "ムアーズはこのハディースを自分が死ぬ前に語った。それは知識の隠蔽によって罪に陥ることを、恐れたためである。",
          "義務行為や、イスラーム法における刑罰に関するものでなければ、ある種のハディースをある種の人々に知らせないでおくことの示唆。それは彼らがその意味を理解できない恐れがある場合である。",
          "罪を犯すタウヒードの徒の末路は、アッラーの意思に委ねられる。アッラーが望めば彼らを罰し、アッラーが望めば彼らを赦し、その行き先は天国となる。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65008: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーに何も並べることなく死んだ者は天国に入り、アッラーに何かを並べた状態で死んだ者は地獄に入る。」",
    "hadeeth": "ジャービル（アッラーのご満悦あれ）は言った： 預言者（アッラーからの祝福と平安あれ）のところに一人の男がやって来て、言った：「アッラーの使徒よ、２つの義務付けられたこととは何ですか？」彼は言った：「アッラーに何も並べることなく死んだ者は天国に入り、アッラーに何かを並べた状態で死んだ者は地獄に入る。」",
    "explanation": "ある男が預言者（アッラーからの祝福と平安あれ）に、天国に入ることを義務付け、地獄に入ることを義務付ける２つの特徴について尋ねた。 預言者（アッラーからの祝福と平安あれ）は答えて言った：天国入りを義務付けるものとは、アッラーに何も並べることなく崇拝した状態で人が死ぬことである。 地獄入りを義務付けるものとは、アッラーに何かを並べた状態で人が死ぬことである。つまり、アッラーの神性、主性、その美名と属性において、アッラー以外の共同者や同類を設けることである。",
    "hints": [
          "タウヒードの徳。アッラーに何も並べることなく信仰者として死んだ者が、天国に入るということ。",
