  65009: {
    "category_id": 3,
    "category": "神学",
    "title": "彼は1日も、”わが主よ、報いの日、私の罪をお赦し下さい”とは言わなかった。」",
    "hadeeth": "アーイシャ（アッラーのご満悦あれ）は言った： 私は言った：「アッラーの使徒よ、ジュドゥアーンの息子はジャーヒリーヤ時代、親戚関係を良好に保ち、恵まれない者に食を施していました。そのことは役に立つのでしょうか？」彼は言った：「彼は1日も、”わが主よ、報いの日、私の罪をお赦し下さい”とは言わなかった。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、アブドッラー・ブン・ジュドゥアーンについて語った。彼はイスラーム以前の時代、クライシュ族のリーダーの一人だった。 彼にはよい行いがあり、親戚関係を良好に維持し、善行を施し、恵まれない人に食べさせるなど、イスラームが勧める高徳の行いを実践していた。しかし彼の行いは来世において、彼の役に立つものとはならない。それはアッラーに対する彼の不信仰のためであり、彼が1日たりとも「わが主よ、報いの日、私の罪をお赦し下さい」とは言わなかったためである。",
    "hints": [
          "信仰の徳と、それが行いが受け入れられるための条件であること。",
          "不信仰の災いと、それが善行を無駄にしてしまうということの説明。",
          "不信仰者はアッラーと来世を信じていないことにより、その行いが来世において役立つことはない。",
          "不信仰の状態にあった時の善行は、イスラームを受け入れることを条件に記録され、報われることになる。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65010: {
    "category_id": 3,
    "category": "神学",
    "title": "あなた方の主が何と仰ったか知っているか？」彼らは言った：「アッラーとその使徒がよくご存じです。」彼は言った：「朝を迎えたわがしもべたちの内、われを信仰した者と、不信仰の者がいる",
    "hadeeth": "ザイド・ブン・ハーリド・アル＝ジュハニー（アッラーのご満悦あれ）は言った： アッラーの使徒（アッラーからの平安と祝福あれ）は雨が降った夜の後、フダイビヤで私たちのためにファジュルの礼拝を率いた。そして彼は言った：「あなた方の主が何と仰ったか知っているか？」彼らは言った：「アッラーとその使徒がよくご存じです。」彼は言った：「朝を迎えたわがしもべたちの内、われを信仰した者と、不信仰の者がいる。”アッラーの恩寵と慈悲によって、私たちは雨を恵まれた”と言った者は、われを信じ、星を否定した者である。一方、”これこれの星のおかげ（で、雨を恵まれた）”と言った者は、われを否定し、星を信仰したのである。」",
    "explanation": "アッラーの使徒（アッラーからの平安と祝福あれ）は雨が降った夜の後、フダイビヤでファジュルの礼拝を行った。フダイビヤはマッカの近郊の村である。 彼は礼拝を終えると、人々の方に向き直って、こう尋ねた：「あなた方の主が何と仰ったか知っているか？」 彼らは答えた：「アッラーとその使徒がよくご存じです。」 彼は言った：「至高のアッラーは、雨が降った際に人々は２種類に分かれる。それはアッラーを信じる者たちと、アッラーを否定する者たちである。 ”アッラーの恩寵と慈悲によって、私たちは雨を恵まれた”と言い、雨をアッラーに結びつけた者は、この世を創造し司るアッラーを信じ、星を否定した者である。 一方、”これこれの星のおかげで、雨を恵まれた”と言った者は、アッラーを否定し、星を信仰したのである。」降雨の原因を星に結びつけることは、小さな不信仰である。アッラーは法則という意味でも、定めという意味でも、星を降雨の原因とはしなかったからである。 また、降雨やその他の地上における現象を星の出現や入りなどの動きと関連付け、かつ星自体が真の行為者であると考えるのであれば、大きな不信仰を犯した不信仰者となってしまう。",
    "hints": [
          "降雨にあたり、「アッラーの恩寵と慈悲によって、私たちは雨を恵まれた」と言うことの勧め。",
          "降雨やそれ以外の恵みを星に起因するものとし、更にはそれが雨を創造し、存在させたと考える者は大きな不信仰を犯している。もし、それを原因とするに留めるのであれば、小さな不信仰を犯していると見なされる。というのも星は降雨における宗教的、または物質的原因ではないためである。",
          "恩恵は否定すれば不信仰の原因に、感謝すれば信仰の原因になる。",
          "たとえそれが季節を意図するものであったとしても、「これこれの星のおかげで、雨を恵まれた」と言うことの禁止。それはシルクの防止に対する予防策である。",
          "恩恵を引き寄せ、害悪を遠ざけることにおいて、心がアッラーに結びついていることの義務性。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65011: {
    "category_id": 3,
    "category": "神学",
    "title": "私たちは、口に出すのもはばかられるようなことを、自分自身の内に見出すことがあるのです。」彼は言った：「そのようなものを見出したのか？」彼らは言った：「はい。」彼は言った：「それが明晰なる信仰なのだ。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）は言った： 預言者（アッラーからの祝福と平安あれ）の教友たちからなる人々がやって来て、彼にこう尋ねた：「私たちは、口に出すのもはばかられるようなことを、自分自身の内に見出すことがあるのです。」彼は言った：「そのようなものを見出したのか？」彼らは言った：「はい。」彼は言った：「それが明晰なる信仰なのだ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）の教友の一団がやって来て、彼にこういったことについて尋ねた：彼らは、その醜悪さ、嫌悪感から、口に出すのもはばかられるような罪深いことを、彼ら自身の内に見出すことがあるのだと。 それで預言者（アッラーからの祝福と平安あれ）は、言った：「あなた方が見出したものこそは、明晰なる信仰と確信である。それこそが、シャイターンが心の中に投げ入れる物事を拒ませ、そのようなことを口にすることから禁じ、自分自身の内において甚だしい物事と見なさせるのである。シャイターンはあなた方の心を制圧できなかったのであり、むしろそのようなことを押し戻すことが出来なかった者こそがシャイターンに制圧された者なのである。」",
    "hints": [
          "信仰者に対するシャイターンの脆弱さの説明。彼らはせいぜい囁きかけるくらいのことしか出来ない。",
          "囁きかけによる心の誘惑を信じ、受け入れないこと。それはシャイターンからのものである。",
          "シャイターンの囁きは信仰者を害しないが、そこからのご加護をアッラーに求め、それを助長するようなことは止めるべきである。",
          "宗教に関する物事で問題があったら、ムスリムはそこにおいて沈黙すべきではない。むしろ質問すべきである。",
