  65012: {
    "category_id": 3,
    "category": "神学",
    "title": "その策略を囁きかけに減じて下さったアッラーに、讃えあれ。」",
    "hadeeth": "イブン・アッバース（彼にアッラーのご満悦あれ）は言った： ある男が預言者（彼にアッラーからの祝福と平安あれ）のもとにやって来て、言った：「アッラーの使徒よ、私たちの内のある者は、それ（このように間接的に表現した）を口外するよりは灰になってしまった方がよいと思うほどのものを、自分の中に見出すのです。」彼は言った：「アッラーは偉大なり、アッラーは偉大なり。その策略を囁きかけに減じて下さったアッラーに、讃えあれ。」",
    "explanation": "ある男が預言者（彼にアッラーからの祝福と平安あれ）のもとにやって来て、言った：「アッラーの使徒よ、私たちの内のある者は自らの内に何か思い浮かべることがありますが、それは口にすることも甚だしいものです。それを口外するよりは、灰になってしまった方がよいと思うほどのものなのです。 預言者（アッラーからの祝福と平安あれ）は２回「アッラーは偉大なり」と言うと、シャイターンの策略を単なる囁きかけにして跳ね返して下さったアッラーを讃えた。",
    "hints": [
