          "シャイターンは信仰者に対し、囁きかける程度のことしかできない弱い存在であることの説明。",
          "信仰者はシャイターンの囁きに背を向け、それを跳ね返さなければならない。",
          "何かよいことを見出したり、嬉しいことがあったり、それに類似することあったりした際には、タクビール（アッラーは偉大なりという言葉）を唱えるということ。",
          "不明点については何でも、知識あるムスリムに質問すること。",
