  65013: {
    "category_id": 3,
    "category": "神学",
    "title": "「シャイターンはあなた方の内の者のところにやって来て、こう言う：”このように創造したのは誰か？このように創造したのは誰か？”そしてついには、こう言うのである：”お前の主を創造したのは誰か？”ゆえにそこまで達したら、アッラーにご加護を乞い、終了するのだ。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、言った： 「シャイターンはあなた方の内の者のところにやって来て、こう言う：”このように創造したのは誰か？このように創造したのは誰か？”そしてついには、こう言うのである：”お前の主を創造したのは誰か？”ゆえにそこまで達したら、アッラーにご加護を乞い、終了するのだ。」",
    "explanation": "アッラーの使徒（アッラーからの祝福と平安あれ）は、シャイターンが信仰者に囁きかける自問の数々に対する効果的治療法について、伝えている。 シャイターンは言う：「このように創造したのは誰か？このように創造したのは誰か？天を創造したのは誰か？大地を創造したのは誰か？」 信仰者は宗教と天性と理性によって、こう答える：「アッラーだ。」 だがシャイターンの囁きはそこまでに留まらない。ついには、こう言うのである：「お前の主を創造したのは誰か？」 そこまで達したら、信仰者は３つのことによってこの囁きを追いやる。　\n\nアッラーへの信仰。\n\nシャイターンに対する加護をアッラーに乞うこと。\n\nシャイターンのささやきに身を任せることに、終止符を打つこと。",
    "hints": [
