  65014: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「行いは６つであり、人は４種である：２つの義務づけるもの。同等のもの。１０倍の善行。７００倍の善行",
    "hadeeth": "フライム・ブン・ファーティク（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「行いは６つであり、人は４種である：２つの義務づけるもの。同等のもの。１０倍の善行。７００倍の善行。そして２つの義務づけるものというのは、アッラーに何も並べることなく死んだ者が天国に入り、アッラーに何か並べた状態で死んだ者が地獄に入るということ。同等のものとは、一つの善行を行おうと思い、それを心で感じ、それをアッラーがご存じになったら、その者のために一つの善行として記録されるということであり、一つの悪行を行った者にはそれが一つのものとして記録されるということである。また、一つの善行を行った者には、その１０倍のものがある。また、アッラーの道において何かを費やせば、それは７００倍の善行となる。一方人はといえば、現世では裕福だが、来世においては貧しい者。現世においては貧しいが、来世においては裕福な者。現世と来世において貧しい者。現世と来世において裕福な者である。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は以下のように言っている：行いには６種類、人間には４種類ある。６種類の行いとは、次のとおりである：\n\n１．アッラーに何も並べることなく死んだ者には、天国が義務づけられる。\n\n２．アッラーに何か並べた状態で死んだ者には、永遠の地獄が義務づけられる。\n\nこの２つが、「２つの義務づけられること」である。\n\n３．意図された善行。一つの善行を行おうと意図し、それを心で感じるまでに意図が誠実なものとなり、その意図をアッラーがご存じになった後、何らかの理由でそれを行えなかった場合、その者のためにそれが一つの完全な善行として記録される。\n\n４．意図された悪行。一つの悪行を行った者には、それが一つの悪行として記録される。\n\n以上の２つが、倍増されることのない同等のものである。\n\n５．１０倍になる善行。これは一つの善行を意図して行った場合であり、それはその１０倍のものとして記録される。\n\n６．７００倍になる善行。これはアッラーの道において、何か一つでも費やせば、それが７００倍の善行となるということである。これはアッラーからしもべに対するお恵みであり、栄誉によるものである。\n\n一方、人には４種類ある：\n\n１．現世では裕福な糧を所有しており、望むものが何でも手に入る状況だが、来世においては貧しい者。つまり地獄行きである者である。これは裕福な不信仰者のことである。\n\n２．現世においては十分な糧を所有してはいないが、来世においては裕福な者。つまり天国行きの者である。これは貧しい信仰者のことである。\n\n３．現世と来世において貧しい者。これは貧しい不信仰者である。\n\n４．現世と来世において裕福な者。これは裕福な信仰者である。",
    "hints": [
          "しもべに対するアッラーの恩恵の偉大さと、善行の倍増。",
          "アッラーの公正さと気前の良さ。なぜならアッラーは悪行については、一つのものに対し一つの報いという公正さで対処して下さるからである。",
          "アッラーに対してシルクを犯すことの重大さ。それをすれば天国から阻まれてしまう。",
          "アッラーの道において費やすことの徳。",
          "アッラーの道において費やすことの褒美の倍増。それは７００倍以上に達する。なぜならそれはアッラーのお言葉を上げることにつながるからである。",
          "人間の種類とその相違に関する説明。",
          "現世の豊かさは信仰者にもそうではない者にも開かれている。しかし来世の豊かさは信仰者にしか開かれない。",
        ],
    "grade": "حسن",
    "attribution": "رواه أحمد",
  },
  65015: {
    "category_id": 3,
    "category": "神学",
    "title": "「アッラーは善行において信仰者に不正を働かない。彼はそれゆえに現世において与えられ、来世において報われるのだ",
    "hadeeth": "アナス・ブン・マーリク（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの平安と祝福あれ）は言った： 「アッラーは善行において信仰者に不正を働かない。彼はそれゆえに現世において与えられ、来世において報われるのだ。一方、不信仰者は現世においてアッラーのために行った善行ゆえに食を与えられはするものの、やがて来世へと到着すれば、それでもって報われる善行はない。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は信仰者に対するアッラーの恩寵と、不信仰者に対する公正さについて説明する。 信仰者は、行った善行の褒美を減らされることがない。彼はその服従において、現世においてよいものを与えられ、来世においてはそれゆえに報われる。場合によっては、その報いが来世にまで全て取っておかれることもある。 一方、不信仰者は現世において行った善行の報いを、現世の善の形でアッラーから受け取ることになる。やがて来世へと到着しても、それでもって報われる褒美はない。なぜなら現世と来世の両方において役立つ善行は、それを行う行為者が信仰者である必要があるためである。",
    "hints": [
