    "hadeeth": "スフヤーン・ブン・アブドッラー・アッ＝サカフィー（アッラーのご満悦あれ）は言った： 私は言った。「アッラーの使徒よ、あなた以外の誰にも尋ねることのできないような、イスラームに関する言葉を私におっしゃって下さい。」するとこう言った：「私はアッラーを信じますと言い、それから行ないを正すのだ。」",
    "explanation": "スフヤーン・ブン・アブドッラー（アッラーのご満悦あれ）は、アッラーの使徒（アッラーからの祝福と平安あれ）にこう尋ねた：あなた以外には聞くことの出来ないような、イスラームの意味についてまとめた言葉を私に教えてください。私はそれを守りたいと思います。 するとアッラーの使徒（アッラーからの祝福と平安あれ）は、彼に言った：アッラーをわが主、わが神、わが創造主、他に並べるものがないわが崇拝対象として、唯一の存在として信じます、と言いなさい。 それからアッラーが義務付け、禁止したことを守ることによって、アッラーに従うのだ。それを継続せよ。",
