    "title": "「太陽が西から昇るまで、審判の日は起こらない。そして人々はそれを見た時、皆信じるのである",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「太陽が西から昇るまで、審判の日は起こらない。そして人々はそれを見た時、皆信じるのである。しかし、”あなたの主の御徴の一部が到来する（復活の）日、（それ）以前に信仰してはいなかった、あるいはその信仰において善を稼ぐことのなかった者の信仰が、自らを益することはない。”（クルアーン6:158）審判の日が起こる時、衣服を広げている二人の男は売買もしなければ、それを畳むこともない。審判の日が起こる時、雌ラクダの乳を搾った男がそれを口にすることはない。審判の日が起こる時、水飲み場を修繕している男がそこから水を飲むことはない。審判の日が起こる時、あなた方の内の者は口元まで食べ物を持って行くが、それを口にすることはない。」",
