    "title": "「私はわが水辺におり、あなた方の内で私のもとにやって来る者たちを見ることになる。そこである人々は私から遠ざけられてしまうため、私はこう言う：”わが主よ、私の内の者であり、わが共同体の内の者たちです。”",
    "hadeeth": "アスマー・ビント・アビーバクル（アッラーのご満悦あれ）によれば、預言者（アッラーからの祝福と平安あれ）は言った： 「私はわが水辺におり、あなた方の内で私のもとにやって来る者たちを見ることになる。そこである人々は私から遠ざけられてしまうため、私はこう言う：”わが主よ、私の内の者であり、わが共同体の内の者たちです。”すると、こう言われる：”彼らがあなたの後で何をしたか知っているのか？アッラーにかけて、彼らは踵をひるがえし続けたのである。”」",
