  65032: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーの使徒よ、水辺の容器はどんなものですか？」彼は言った：「ムハンマドの魂がその手にあるお方にかけて。その容器は、雲のない闇夜における天の星々や惑星よりも多い",
    "hadeeth": "アブー・ザッル（アッラーのご満悦あれ）は、言った： 私は言った：「アッラーの使徒よ、水辺の容器はどんなものですか？」彼は言った：「ムハンマドの魂がその手にあるお方にかけて。その容器は、雲のない闇夜における天の星々や惑星よりも多い。天国の容器から飲んだ者はそれを最後に、喉が渇くことはない。天国からは二本のじょうごが渡されており、そこから飲む者の喉が渇くことはない。その幅と長さは同じくらいで、アンマンとアイラほどの距離がある。その水は乳よりも白く、蜜よりも甘い。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、審判の日の水辺の容器の数は天の星や惑星の数よりも多いのだと、誓って言った。 それは月のない闇夜におけるようなものである。というのも月明りの夜、星は月の光に隠れてしまい、あざやかに見えないためである。また、それは雲のない夜におけるようなものである。雲によって星々は見えにくくなるためである。 天国の容器からその水を飲んだ者は、その時の渇きを最後に、決して喉が渇くことはない。 水辺には、天国からの二本のじょうごが渡されており、水辺の幅と長さは同じくらいである。 水辺はその形が均整のとれたものであり、その長さはシャーム地方バルカー付近の町アンマンと、シャーム地方の縁辺に位置する町アイラほどの距離がある。 水辺の水は乳よりも白く、その味は蜜よりも甘い。",
    "hints": [
