  65033: {
    "category_id": 3,
    "category": "神学",
    "title": "「アッラーは審判の日、私の共同体から一人の男を全ての被造物の前に露わにする",
    "hadeeth": "アブドッラー・ブン・アムル・ブン・アル＝アース（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「アッラーは審判の日、私の共同体から一人の男を全ての被造物の前に露わにする。それから彼に対し、９９の帳簿が広げられ、その一冊一冊は見渡す限りの大きさである。それから仰る：”ここにあるものの何かを、否認するか？記録者であるわが筆録者たちは、あなたに不正を働いたか？”彼は言う：”いいえ、わが主よ。”かれは仰る：「では、あなたには何か、言い訳はあるか？」彼は言う：「いいえ、わが主よ。」するとかれは仰る：”いや。あなたにはわれらのもとに、一つの善行がある。この日は、あなたに対するいかなる不正もないのだ。”こうして”私はアッラー以外に崇拝すべきいかなるものもないことを証言し、ムハンマドがかれのしもべであり使徒であることを証言する”というカードが出される。かれは仰る：”あなたの秤を持って来るがよい。”すると彼は言う：”わが主よ、これらの帳簿に対して、このカードが何になるのでしょうか？”かれは仰る：”あなたが不正を受けることはない。”こうしてそれらの帳簿が秤の一方に、そのカードがもう一方に置かれ、帳簿は軽くなり、カードが重くなる。アッラーのお名前より何かが重くなるということはないのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はこのように語った：アッラーは審判の日、彼の共同体から一人の男を清算のため、全ての被造物の前に選び出して呼びつける。それから彼に対し、９９の帳簿を広げる。それらは彼が現世で行っていた悪行の帳簿であり、その一冊一冊の長さは見渡す限りほどのものである。 それからアッラーはこの男に、こう仰る：「この帳簿に記録されているものの内、何か否認するものはあるか？ 記録者であり筆録者であるわが天使たちは、あなたに不正を働いたか？」 男は言う：「いいえ、わが主よ。」 するとアッラーは仰る：「では、現世であなたがやってしまった行いに関し、あなたには何か言い訳があるか？うっかりやってしまったとか、間違ってしてしまったとか、無知から行なってしまったとか？」 彼は言う：「いいえ、わが主よ。言い訳はありません。」 するとアッラーは仰る：「いや。あなたにはわれらのもとに、一つの善行がある。この日は、あなたに対するいかなる不正もない。」 こうして「私はアッラー以外に崇拝すべきいかなるものもないことを証言し、ムハンマドがかれのしもべであり使徒であることを証言する」と記されたカードが出される。 それからアッラーはこの男に仰る：「あなたの秤を持って来るがよい。」 すると彼は驚いて言う：「わが主よ、これらの帳簿の重さに対して、このカードの重さが一体何になるのでしょうか？」 アッラーは仰る：「あなたが不正を受けることはない。」 こうしてそれらの帳簿が秤の一方に、そのカードがもう一方に置かれ、帳簿の置かれた方は軽くなり、カードの置かれた方が重くなる。こうしてアッラーはその男を赦されたのである。",
    "hints": [
          "アッラー以外に崇拝すべき何ものもないという証言である、タウヒードの言葉の偉大さ。その秤の上における重さ。",
          "アッラー以外に崇拝すべき何ものもない、と言葉で唱えるだけでは十分ではない。その意味に関する知識と、それが要求する行いも必要なのである。",
          "真摯さとタウヒードの強さは、罪の赦しの要因である。",
          "信仰心は心の真摯さに応じて異なる。ある種の者たちはこの言葉を口にはしていても、その罪に応じて罰されることになる。",
        ],
    "grade": "صحيح",
    "attribution": "رواه الترمذي وابن ماجه",
  },
  65034: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーは天国と地獄を創った時、ジブリール（かれに平安あれ）を天国に遣わして、こう仰った",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によると、アッラーの使徒（アッラーからの平安と祝福あれ）は言った： アッラーは天国と地獄を創った時、ジブリール（かれに平安あれ）を天国に遣わして、こう仰った：「それと、その民のためにわれが用意したものを見るがよい。」それでかれはそれを見て戻り、こう言った：「あなたのご威光にかけて。それについて聞いた者は、誰でもそこに入りたがるでしょう。」そこでかれ（アッラー）は命じて、それ（天国）を嫌な物事で包囲させた。そして仰った：「行って、それと、その民のためにわれが用意したものを見るがよい。」それでかれがそれを見たところ、それは嫌な物事で包囲されていた。それでかれは、言った：「あなたのご威光にかけて。私は、そこに誰も入らないのではないかと恐れます。」かれは仰った：「行って、地獄と、その民のためにわれが用意したものを見るがよい。」それでかれがそれを見たところ、それは何層にも重なり合っていた。かれは戻ると、言った：「あなたのご威光にかけて。誰もそこには入りません。」そこでかれ（アッラー）は命じて、それ（地獄）を欲望で包囲させた。そして仰った：「行って、それを見るがよい。」それでかれがそれを見たところ、それは欲望で包囲されていた。かれは戻ると、言った：「あなたのご威光にかけて。私は、誰も逃れられず、そこに入ってしまうのではないかと恐れます。」",
    "explanation": "預言者（アッラーからの平安と祝福あれ）は、このように言った：アッラーが天国と地獄を創った時、ジブリール（かれに平安あれ）にこう仰った：「天国に行って、それを見るがよい。」それでかれは行き、それを見て戻った。 ジブリールは言った：「主よ、あなたのご威光にかけて。それと、そこにある恩恵と高貴さと善について聞いた者は誰でも、そこに入りたがり、そこに入るために努力したことでしょう。」 それからアッラーは天国を、命令の実行や禁止行為の回避といった、嫌な物事や困難によって包囲させ、そこに入りたいと望む者にそれらの嫌な物事を行うことを義務づけた。 それからアッラーは、天国を嫌な物事で包囲した後、仰った：「ジブリールよ、行って、天国を見るがよい。」 それでかれは行き、それを見た。そして戻ってきて、こう言った：「主よ、あなたのご威光にかけて。私は、そこに行く途上にある困難と厳しさのため、誰もそこに入らないのではないかと恐れます。」 また、アッラーは地獄を創り、こう仰った：「ジブリールよ、行って、それを見るがよい。」それでかれは行き、それを見た。 それからかれは戻って来ると、言った：「主よ、あなたのご威光にかけて。そこにある罰と憂鬱さと苦痛について聞いた者は誰でも、そこに入ることを嫌がり、そこに入る原因となる物事から遠ざかったことでしょう。」 それからアッラーは地獄を包囲し、そこへと到達する道を欲望と享楽とした。そして仰った：「ジブリールよ、行って、それを見るがよい。」 それでジブリールは行き、それを見て戻ってきた。そして言った：「主よ、あなたのご威光にかけて。私は、そこを包囲している欲望と享楽のために、誰もそこから逃れられないのではないかと恐れ、心配します。」",
    "hints": [
          "今、天国と地獄が存在しているという信仰。",
          "アッラーとその使徒（アッラーからの平安と祝福あれ）が伝える、あらゆる不可視の領域のことを信じる義務。",
          "嫌に感じる物事において忍耐することの重要性。なぜなら、それが天国へと至る道だからである。",
          "禁止行為を回避することの重要性。なぜなら、それが地獄へと至る道だからである。",
          "天国が嫌な物事で、地獄が欲望で包囲されているということは、この世の生活が試練ということである。",
          "天国への道は難しく険しいため、忍耐と、信仰心を伴う苦労が必要である。一方、地獄への道はこの世の快楽や欲望で満たされている。",
        ],
    "grade": "حسن",
    "attribution": "رواه أبو داود والترمذي والنسائي",
  },
  65035: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "「死は、黒い模様がついた白い牡羊の形で連れて来られる",
    "hadeeth": "アブー・サイード・アル＝フドゥリー（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「死は、黒い模様がついた白い牡羊の形で連れて来られる。そして呼びかける者が呼びかける：”天国の住人よ！”すると彼らは首を伸ばして見回す。その者は言う：”あなた方はこれを知っているか？”彼らは言う：”はい、これは死です。”こうして彼らの全員がそれを目にする。それからまた呼びかける：”地獄の住人よ！”すると彼らは首を伸ばして見回す。その者は言う：”あなた方はこれを知っているか？”彼らは言う：”はい、これは死です。”こうして彼らの全員がそれを目にする。それからそれは屠られ、その者は言う：”天国の住人よ、永遠に。もはや死はない。そして地獄の住人よ、永遠に。もはや死はない。”それから読誦した：”迂闊であった彼らに、ことが決定される悔恨の日について警告を告げよ。”（クルアーン19:39）彼らは現世の民であり、迂闊な状態にあった。そして”信仰することもなかった”（クルアーン19:39）のである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、伝えている：審判の日、死は、黒い模様がついた白い牡羊の形で連れて来られる。 そして、このように呼びかけられる：「天国の住人よ！」すると彼らは首を伸ばして見回す。 呼びかける者は言う：「あなた方はこれを知っているか？」 彼らは言う：「はい、これは死です。」こうして彼らの全員がそれを目にし、そのことを知る。 それからまた、呼びかける者が呼びかける：「地獄の住人よ！」すると彼らは首を伸ばして見回す。 呼びかける者は言う：「あなた方はこれを知っているか？」 彼らは言う：「はい、これは死です。」こうして彼らの全員がそれを目にし、そのことを知る。 それからそれは屠られ、呼びかける者は言う：「天国の住人よ、あなた方は永遠に生きる。もはや死はない。そして地獄の住人よ、あなた方も永遠に生きる。もはや死はない。」 このように言われるのは、信仰者にとってはその安寧がより大きなものとなり、不信仰者にとってはその罰がより厳しいものとなるためである。 それから預言者（アッラーからの祝福と平安あれ）は読誦した： 「そして（使徒よ）、迂闊であり、信仰することのない彼らに、ことが決定される悔恨の日について警告を告げよ。」 こうして審判の日には天国の民と地獄の民の間が分けられ、それぞれが自分の居場所へと入り、そこで永遠に過ごすことになるのである。 現世で悪行を行っていた者は、善行を行わなかったことを後悔する。いい加減だった者は、善行をもっと行えばよかった、と後悔することになる。",
    "hints": [
          "来世における人間の行き先は、永遠の天国か地獄である。",
          "審判の日の凄惨さに対する厳しい警告。それは後悔と悔恨の日である。",
          "天国の民の喜びと、地獄の民の悲しみの永続についての説明。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65036: {
    "category_id": 3,
    "category": "神学",
    "title": "「あなた方の火は、地獄の火の70分の1である。",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「あなた方の火は、地獄の火の70分の1である。」すると、このように尋ねられた：「アッラーの使徒よ、それだけでも十分ですのに。」預言者は言った：「それ（地獄の火）はその69個分より勝っており、しかもその一つ一つがそれと同様の熱さなのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は言った：「現世の火は、地獄の火の70分の1である。」 つまり、来世の火は現世の火の69個分以上の熱さなのであり、しかもその一つ一つが現世の火と同様の熱さなのである。 すると、このように尋ねられた：「アッラーの使徒よ、現世の火だけでも、そこに入る者にとっては十分な罰となりますのに！」 預言者は言った：「それ（地獄の火）はその69個分より勝っており、しかもその一つ一つがそれと同様の熱さなのである。」",
    "hints": [
          "人々を地獄の原因となる行いから遠ざけるための警告。",
          "地獄の火とその罰の厳しさと、その灼熱。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65037: {
    "category_id": 3,
    "category": "神学",
    "title": "アッラーの使徒（アッラーからの祝福と平安あれ）は私たちに言った：つねに真実を語り、その言葉が正しいと信じられていたアッラーの御使い―アッラーよ彼に祝福と平安を与えたまえ―は、つぎのように述べた。お前たちが創られるおりには、母親の腹の中で40日間精子が宿り",
    "hadeeth": "アブドッラー・ブン・マスウード（アッラーのご満悦あれ）は言った： アッラーの使徒（アッラーからの祝福と平安あれ）は私たちに言った：つねに真実を語り、その言葉が正しいと信じられていたアッラーの御使い―アッラーよ彼に祝福と平安を与えたまえ―は、つぎのように述べた。お前たちが創られるおりには、母親の腹の中で40日間精子が宿り、それから同じ期間凝血となり、ついで同じ期間肉塊となる。その後天使が遣わされて魂を吹きこむが、この天使はさらに4つの仕事 をするよう命じられている。つまり〔生れてくる者の〕糧、寿命、行い、幸・不幸を書きとめることである。ところで唯一無二の神であるアッラーに誓って言うが、お前たちのある者は天国まであと一腕尺というところまで天国の徒の行いにいそしむが、そこで帳簿に記されたことに災いされ、地獄の徒の行いを行って地獄におちる。だがまたある者は、地獄まであと一腕尺というところまで地獄の徒の行いにいそしむが、そこで帳簿に記されたことが幸いし、天国の徒の行いを行って天国に入る。",
    "explanation": "イブン・マスウード（アッラーのご満悦あれ）は言った：アッラーの使徒（アッラーからの祝福と平安あれ）は私たちに言った：言葉で真実を語り、アッラーによってその言葉が正しいと確証されたアッラーの御使いは、私たちにこのように述べた： お前たちが創られるおりには、男性が妻と交わることで、分かれていた精液が女性の腹の中で結びつき、40日の間精液の状態となる。 それから今度は凝血となる。これは血液が濃く固まった状態のものであり、さらに40日間このままの状態となる。 それから今度は、肉塊となる。これはちょうど噛めるくらいの大きさの肉の塊であり、この状態もやはり40日間続く。 その後そこに天使が遣わされて、3回目の40日間が終了後に、魂を吹きこむ。 この天使はさらに4つの言葉を書き留めるよう命じられる。まずは糧であるが、これはその者が人生において授かる恩恵のことである。 そして寿命。つまり現世にとどまる期間のことである。 そして行いがどのようなものであるか。また、その者が不幸になるか、幸せになるか、である。 それから預言者（アッラーからの祝福と平安あれ）は誓って言う。ある者は、天国の徒の行い、つまり正しい行いに見える行いを、天国まであと一腕尺というところまで行い続ける。しかし、そこで帳簿に記され定められたことに災いされ、地獄の徒の行いを行い、それによって行いを締めくくることで地獄におちる。 というのも行いが受け入れられるには、そこにおける確立が条件づけられるからである。一方、別の者は、地獄まであと一腕尺というところまで地獄の徒の行いにいそしむが、そこで帳簿に記され定められたことが幸いし、天国の徒の行いを行って天国に入る。",
    "hints": [
          "物事の結末はそもそも定められていた定命へと行き着くということ。",
          "行いの表面に気をとらわれることへの注意。行いというものはその最後の締めくくりによって決定づけられるからである。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65038: {
    "category_id": 3,
    "category": "神学",
    "title": "「アッラーは天地を創られる 50,000 年前に、被造物に関する定めをお書きになられた。",
    "hadeeth": "アブドッラー・ブン・アムル・ブン・アル＝アース（アッラーのご満悦あれ）は言った：私はアッラーの使徒（アッラーからの祝福と平安あれ）が、こう言うのを聞いた： 「アッラーは天地を創られる 50,000 年前に、被造物に関する定めをお書きになられた。」彼は言った：「そして（その時）かれの玉座は水の上にあった。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は伝えている：アッラーは天地を創られる 50,000 年前に、生死や糧についてなど、被造物に起こることになる定めを詳細に、守られし碑板の中にお書きになられた。そしてそれらはアッラーがお決めになった通りに起きるのである。 起きる全ての物事は、アッラーの定めとご決定による。 しもべに起きたことは免れ得なかったのであり、免れたことは起きるべくもなかったのである。",
