  65039: {
    "category_id": 3,
    "category": "神学",
    "title": "全ての物事は定められている。気乗りのしない状態も、乗り気の状態でさえも。あるいは、”乗り気の状態も、気乗りのしない状態でさえも。”」",
    "hadeeth": "ターウースは言った：「私は、”全ての物事は定められている”と言うアッラーの使徒（アッラーからの祝福と平安あれ）の教友の内の人々と出会った。また、アブドッラー・ブン・ウマル（アッラーのご満悦あれ）がこう言うのを聞いた：”アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 全ての物事は定められている。気乗りのしない状態も、乗り気の状態でさえも。あるいは、”乗り気の状態も、気乗りのしない状態でさえも。”」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、全ての物事が既に定められていると説明した。 それは、気乗りのしない状態でも同様である。つまり現世のことであれ来世のことであれ、やらなければならないことを放棄したり、先送りにしたり、期限を遅らせたりすることである。 また、乗り気の状態でも同様である。つまりそれは現世のことであれ来世のことであれ、やる気があり、関心がある状態のことである。 アッラーは、気乗りのない状態も、乗り気の状態も、全ての物事に対して定命を定めた。アッラーの知識と意思が先んずることなくして、この世に何かが起こるということはないのである。",
    "hints": [
          "教友たち（アッラーのご満悦あれ）の定命に対する信仰。",
          "気乗りのない状態も、乗り気の状態も、全ての物事はアッラーの定命によって起こる。",
          "アッラーの使徒（アッラーからの祝福と平安あれ）のハディースを伝達することにおける、教友たち（アッラーのご満悦あれ）の精査に対する関心と慎重さ\n\n。",
          "よいこと悪いこと全てにおいて定命を信じること。",
