  65040: {
    "category_id": 3,
    "category": "神学",
    "title": "「アッラーがしもべに対し、ある場所で死ぬことを定めた時、その者にそこにおける何らかの用事を作るのである。」",
    "hadeeth": "マタル・ブン・ウカーミス（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「アッラーがしもべに対し、ある場所で死ぬことを定めた時、その者にそこにおける何らかの用事を作るのである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、このように言っている：アッラーがしもべに対し、彼が今滞在しているわけではない場所で死ぬことを定めた時、彼にそこにおける何らかの用事を作る。こうして彼はそこへと赴き、そこで魂を召されるのである。",
