  65044: {
    "category_id": 3,
    "category": "神学",
    "title": "私はサァド・ブン・バクル族の兄弟、ディマーム・ブン・サァラバです。」",
    "hadeeth": "アナス（アッラーのご満悦あれ）は言った： 私たちが預言者（アッラーからの祝福と平安あれ）と一緒にマスジドで座っていると、ラクダに乗った男が入って来た。彼はラクダを座らせると、それをつなぎ止め、それから彼らに言った：「ムハンマドは誰か？」預言者（アッラーからの祝福と平安あれ）は彼らの中で、よりかかりながら座っていた。私たちは言った：「このよりかかっている肌の白い人です。」すると男は彼に向かって言った：「アブドルムッタリブの息子よ。」預言者（アッラーからの祝福と平安あれ）は彼に言った：「あなたに応じていますよ。」男は預言者（アッラーからの祝福と平安あれ）に言った：「私はあなたに問う。そしてあなたに対して厳しい質問をする。だから私に対して嫌にならないでほしいのだが？」預言者は言った：「質問したいことを質問しなさい。」男は言った：「あなたの主と、あなた以前の者たちの主にかけて問う。アッラーはあなたを全ての人々に向けて遣わしたのか？」預言者は言った：「アッラーにかけて、そうです。」男は言った：「アッラーにかけてあなたに問う。アッラーは、私たちが昼夜５回のサラー（礼拝）をすることをあなたに命じたのか？」預言者は言った：「アッラーにかけて、そうです。」男は言った：「アッラーにかけてあなたに問う。アッラーは、私たちが1年のこの月にサウム（断食）をすることをあなたに命じたのか？」預言者は言った：「アッラーにかけて、そうです。」男は言った：「アッラーにかけてあなたに問う。アッラーは、これらのサダカ（浄財）を私たちのうちの裕福な者たちから取り、私たちのうちの貧しい者に分配することをあなたに命じたのか？」預言者は言った：「アッラーにかけて、そうです。」すると男は言った：「私はあなたがもたらしたものを信じました。私は私の後ろで待っている私の民からの使いです。私はサァド・ブン・バクル族の兄弟、ディマーム・ブン・サァラバです。」",
    "explanation": "アナス・ブン・マーリク（アッラーのご満悦あれ）は伝えている：教友たちが預言者（アッラーからの祝福と平安あれ）と一緒にマスジドで座っていると、ラクダに乗った男が入って来た。彼はラクダを座らせると、それをつなぎ止めた。 それから彼らに尋ねて言った：「ムハンマドは誰か？」 預言者（アッラーからの祝福と平安あれ）は彼らの中で、よりかかりながら座っていた。私たちは言った：「このよりかかっている肌の白い人です。」 すると男は彼に向かって言った：「アブドルムッタリブの息子よ。」 預言者（アッラーからの祝福と平安あれ）は彼に言った：「あなたの言うことを聞いています。質問しなさい、答えましょう。」 男は預言者（アッラーからの祝福と平安あれ）に言った：「私はあなたに問う。そしてあなたに対して厳しい質問をする。だから私に対して嫌にならないでほしいのだが？」 −つまり、私に対して怒ったり、気を悪くしないでほしいということである−。 預言者は言った：「質問したいことを質問しなさい。」 男は言った：「あなたの主と、あなた以前の者たちの主にかけて問う。アッラーはあなたを人々へと遣わしたのか？」 預言者はその正しさを強調し、言った：「アッラーにかけて、そうです。」 男は言った：「アッラーにかけてあなたに問う。アッラーは、私たちが昼夜５回のサラー（礼拝）をすることをあなたに命じたのか？」−これはつまり、義務のサラーのことである−。 預言者は言った：「アッラーにかけて、そうです。」 男は言った：「アッラーにかけてあなたに問う。アッラーは、私たちが1年のこの月にサウム（断食）をすることをあなたに命じたのか？」–これはつまり、ラマダーン月のことである–。 預言者は言った：「アッラーにかけて、そうです。」 男は言った：「アッラーにかけてあなたに問う。アッラーは、これらのサダカ（浄財）を私たちのうちの裕福な者たちから取り、私たちのうちの貧しい者に分配することをあなたに命じたのか？」−これはつまり、ザカーのことである–。 預言者は言った：「アッラーにかけて、そうです。」 こうしてディマームはイスラームを受け入れ、自分の民をイスラームへと招くことを預言者（アッラーからの祝福と平安あれ）に伝えた。それから自己紹介をし、彼がサァド・ブン・バクル族の兄弟、ディマーム・ブン・サァラバであることを知らせた。",
    "hints": [
          "預言者（アッラーからの祝福と平安あれ）の謙虚さ。男は彼を教友の中から見分けることができなかった。",
          "預言者（アッラーからの祝福と平安あれ）のよい品性。彼は質問者に対してやさしく対応している。このようによい対応をすることは、宣教が受け入れられる理由となる。",
          "人を白いとか赤いとか、背が高いとか低いとかいった風に、その者を貶めることを意図せず、本人もそれを嫌がらない限り、その者の特徴によって紹介することの合法性。",
          "必要があれば非ムスリムがマスジドに入ることが許されること。",
          "このハディースにはハッジが言及されていないが、それはこの時点でそれがまだ義務付けられてはいなかったためである。",
          "人々をイスラームへと招くことに関する教友たちの熱心さ。ディマームはイスラームを受け入れるや否や、自分の民をそこへと招くことにおいて関心を高めたのである。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65045: {
    "category_id": 3,
    "category": "神学",
    "title": "預言者（アッラーからの祝福と平安あれ）は何かに言及して、こう言った：「それは知識がなくなる時においてである。",
    "hadeeth": "ズィヤード・ブン・ラビード（アッラーのご満悦あれ）は言った： 預言者（アッラーからの祝福と平安あれ）は何かに言及して、こう言った：「それは知識がなくなる時においてである。」私は言った：「アッラーの使徒よ、どのようにして知識がなくなるのですか？私たちはクルアーンを読み、それを私たちの子供らに読ませ、私たちの子供らはそのまた子供らに審判の日までそれを読ませるというのに？」彼は言った：「ズィヤード、あなたの母親があなたに先立たれてしまうように。私はあなたが、マディーナで最も宗教理解に秀でた者だと思っていたのに。ユダヤ教徒とキリスト教徒はトーラーとインジールを読みながらも、そこにある物事を実践していないではないか？」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は教友たちの間に座っており、このように言った：「これこそが、人々から知識が取り上げられ、阻まれてしまう時である。」 それでズィヤード・ブン・ラビード・アル＝アンサーリー（アッラーのご満悦あれ）は驚き、預言者（アッラーからの祝福と平安あれ）に尋ねた： 「どのようにして知識が取り上げられ、私たちのもとから失われてしまうのですか？私たちはクルアーンを読み、暗記しています。アッラーに誓って、私たちはそれを読み、またそれを自分たちの女性や子供たち、そのまた子供たちに読ませています。」 預言者（アッラーからの祝福と平安あれ）は驚いて言った：「ズィヤード、あなたの母親があなたを失ってしまうように！私はあなたをマディーナの学者の一人と見なしていたのに！」 その後、預言者（アッラーからの祝福と平安あれ）は彼に説明した：知識の喪失はクルアーンが失われることではなく、その知識に沿った行いが失われることによって喪失することなのである、と。 ユダヤ教徒とキリスト教徒のもとには、トーラーとインジールがある。しかしそれらが彼らの役に立つことはなかったし、それらが目指すものから利益を得ることもなかった。つまり、知識を得てもそれを実践しなかったのである。",
    "hints": [
          "人々のもとにクルアーンや書籍があったところで、それらに基づいて行わないのならば、それらは無意味である。",
          "知識の喪失の要因はいくつかある：預言者（アッラーからの祝福と平安あれ）の死、学者らの死、そして知識に基づいて行わないこと。",
          "審判の日の予兆の一つに、知識の喪失、知識に基づいて行わないということがある。",
          "知識に基づいて行うことの勧め。行いこそは知識の目的である。",
        ],
    "grade": "صحيح لغيره",
    "attribution": "رواه ابن ماجه",
  },
  65046: {
