    "category": "クルアーンとその諸学",
    "title": "啓典の民を信じることも、嘘呼ばわりすることもするな。しかし、こう言うのだ：”私たちはアッラーと、私たちに下されたもの（クルアーン",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）は、言った： 啓典の民はトーラーをヘブライ語で読み、それをアラビア語でムスリムに解説したものだった。それでアッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った：「啓典の民を信じることも、嘘呼ばわりすることもするな。しかし、こう言うのだ：”私たちはアッラーと、私たちに下されたもの（クルアーン）を信じる。”」(雌牛章136)",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、啓典の民が彼らの書物から伝えることに惑わされないよう、自らの共同体に警告した。 預言者（アッラーからの祝福と平安あれ）時代、ユダヤ教徒はトーラーを彼らの言葉であるヘブライ語で読み、アラビア語で解説したものだった。 それでアッラーの使徒（アッラーからの祝福と平安あれ）は、言った：「啓典の民を信じることも、嘘呼ばわりすることもするな。」これは、正しいのか嘘なのか分からないことに関してである。 というのもアッラーは私たちに、私たちに下されたクルアーン、そして彼らに下された啓典を信じるよう命じているからである。ただし私たちには、彼らがそれらの啓典から伝えているものが正しいのかそうではないのか、判別する手段がない。というのも私たちの教えには、その正しさと誤りを明らかにする根拠がないからである。 ゆえに私たちはそこで踏み込まず、彼らを信じることも、嘘呼ばわりもしないようにする。それは彼らが歪曲したものにおいて共犯者となることもなく、正しいものを嘘呼ばわりしてしまうことで、本来私たちが信じることを命じられていることを否定もしないようにするためである。 預言者（アッラーからの祝福と平安あれ）は、私たちにこう言うように命じている： 「（信仰者たちよ、）言ってやるがいい。”私たちはアッラーと、私たちに下されたもの（クルアーン）、またイブラーヒーム、イスマーイール、イスハーク、ヤァクーブ及び諸支族に下されたもの、またムーサーとイーサーに授けられたものと、預言者たちが彼らの主から授けられたものを信じる。私たちは彼らの内の誰も分け隔てせず、かれ（アッラー）だけに服従する者（ムスリム）である”。」 （雌牛章136）",
    "hints": [
          "啓典の民が伝えることは３種類である：まず、クルアーンとスンナに一致する類いのもので、これは正しいとされる。次いで、クルアーンとスンナに反する類いのもの。これは虚偽であり、嘘としなければならない。３つ目はクルアーンとスンナの中に、その正しさや誤りを示す根拠を見出すことができない類いのもの。これは伝承することが許されるが、正しいものとも嘘とも断言することはできない。",
