    "hadeeth": "ジャービル・ブン・アブドッラーによれば、預言者（アッラーからの祝福と平安あれ）は言った： 「学者たちの前でひけらかしたり、愚かな者たちと議論したりするために、知識を学んではならない。また、集まりの場で優越するためにも（そうしてはならない）。そのようなことをする者は、地獄、地獄である。」",
