  65049: {
    "category_id": 5,
    "category": "諸々の徳と礼儀作法",
    "title": "「アッラーは、まっすぐな道をたとえとして挙げられた",
    "hadeeth": "アン＝ナウワース・ブン・サムアーン・アル＝アンサーリー（アッラーのご満悦あれ）によると、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「アッラーは、まっすぐな道をたとえとして挙げられた。その道の両脇には壁があり、その壁にはいくつもの開き放たれた扉がついている。そしてそれらの扉には、垂らされたカーテンがかかっている。道の扉の上には呼びかける者がおり、こう言っている：”人々よ、みな道に入るのだ。そこから反れ去ってはならない。”また、道の上の方では、別の呼びかける者がおり、それらの扉を開けようとすると、このように言う：”何たることか、それを開くのではない。それを開けば、あなたはそこに入ってしまう。”この道こそはイスラームであり、両脇の壁はアッラーの境界線、開かれた扉はアッラーが禁じたこと、道の向こうで呼びかける者はアッラーの書、道の上の方から呼びかける者は、全てのムスリムの心の中にあるアッラーの訓戒である。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はこう説明する：アッラーは、曲がることなくまっすぐに伸びた道を、イスラームに対するたとえとして挙げられた。この道の両脇には壁があり、道を両側から囲っている。これらの壁が、アッラーの境界線である。これらの２つの壁の所々には開かれた扉があるが、それらがアッラーが禁じた物事である。これらの扉の上にはカーテンがかけられており、道の通行人にはその中が見えないようになっている。道の手前には人々を案内する呼びかけ人がおり、このように言っている：「脇にそれることなく、道をまっすぐ進みなさい。」この呼びかける者が、アッラーの書である。また、道の途上にはもう一人の呼びかける者がいて、道の通行人が扉のカーテンを少しだけ開けようとするたび、それを諫めてこのように言う：「何たることか、それを開くのではない。それを開けば、あなたはそこに入ってしまう。あなたはそこに入らずにはいられなくなるのだ。」この呼びかける者は、全てのムスリムの心の中にあるアッラーの訓戒である。",
    "hints": [
