  65057: {
    "category_id": 2,
    "category": "ハディースとその諸学",
    "title": "私はあなた方に、偉大なるアッラーへの敬虔さを勧める。そして、たとえ奴隷があなた方の長となったとしても、聞き、従うことを忠告する。あなた方は私のなき後、激しい相違を見出すだろう。ゆえに、わがスンナと正しく導かれたカリフたちのスンナを守れ",
    "hadeeth": "アル＝イルバード・イブン・サーリヤ（アッラーのご満悦あれ）は、言った： アッラーの使徒（アッラーからの祝福と平安あれ）はある日、私たちの前に立ち、私たちの心が慄き、目が（涙で）溢れるような訓戒をたれた。それで誰かが言った：「アッラーの使徒よ、それはあたかも別れの訓戒のようです。私たちに忠告してください。」彼は言った：「私はあなた方に、偉大なるアッラーへの敬虔さを勧める。そして、たとえ奴隷があなた方の長となったとしても、聞き、従うことを忠告する。あなた方は私のなき後、激しい相違を見出すだろう。ゆえに、わがスンナと正しく導かれたカリフたちのスンナを守れ。それに奥歯で噛みついているのだ。また、（宗教的物事の）新たな作りごとを避けよ。というのも全てのビドゥアは迷いだからである。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は教友たちの心が慄き、目が（涙で）溢れるような訓戒をたれた。 預言者（アッラーからの祝福と平安あれ）の厳しい戒めの言葉を聞いて、彼らは言った：「アッラーの使徒よ、それはあたかも別れの訓戒のようです。」そう言って、彼のなき後に彼らが守るための忠告を彼に求めた。 彼は言った：私はあなた方に、義務行為を遂行し、禁止行為を放棄することによって、偉大なるアッラーに対して敬虔であることを勧める。 そして統治者に聞き、従うことを勧めた。たとえ奴隷、つまり最も地位の低い者があなた方の長となり、統治者となったとしても、それを敬遠したりすることなく、彼らに服従しなければならない。それは試練を恐れてのことであり、あなた方のうちで長生きする者は、多くの相違を見出すことになるだろう。 それから、その見解の相違からの逃げ道を説明した。それは預言者（アッラーからの祝福と平安あれ）のスンナと、彼の後の正しく導かれたカリフたち、つまりアブーバクル、ウマル、ウスマーン、アリーら（アッラーのご満悦あれ）のスンナを固守することによってである。それに奥歯で噛みついているのだ。つまり、それにしっかりとしがみついていよ。 また、宗教的物事の新たな作りごとを避けるよう、注意した。全てのビドゥアは迷いだからである。",
    "hints": [
          "スンナを固守し、踏襲することの重要性。",
          "訓戒と、心を柔らかくする物事に関心を持つこと。",
          "正しく導かれた4人のカリフたちに服従することの命令。彼らはアブー・バクル、ウマル、ウスマーン、アリー(アッラーのお喜びあれ)のことである。",
          "宗教におけるビドゥア(イスラームの教えではない宗教的物事をイスラームの教えのものとすること)の禁止。全てのビドゥアは迷いである。",
          "罪とはならない物事において、信仰者らの諸事の指導を担う者たちに聞き従うこと。",
          "あらゆる時と状況においてアッラーを畏れることの重要性。",
          "イスラームの共同体に意見の相違は出現する。その折にはアッラーの使徒（アッラーからの祝福と平安あれ）と導かれたカリフたちのスンナへと、立ち返ることが必要である。",
