    "title": "アッラーの使徒（アッラーからの祝福と平安あれ）から１０アーヤ（節）を聞いては、そこに含まれる知識と行いを学ぶまで、他の１０アーヤに移ることがなかった",
    "hadeeth": "アブー・アブドッラフマーン・アッ＝スラミー（アッラーのご満悦あれ）は言った： 預言者（アッラーからの祝福と平安あれ）の教友たちのうち、私たちにクルアーンを読み聞かせていた者たちは、アッラーの使徒（アッラーからの祝福と平安あれ）から１０アーヤ（節）を聞いては、そこに含まれる知識と行いを学ぶまで、他の１０アーヤに移ることがなかった。彼らは言った：「こうして私たちは知識と行いを学んだのである。」",
