  65059: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "アブー・アル＝ムンズィルよ、あなたが知っているアッラーの書の内、どのアーヤ（節）が最も偉大か知っているか？」私は言った：「アッラーは、かれの外に（真に）崇拝すべきものがなく、永世するお方、全てを司るお方。」（クルアーン２：２５５）すると彼は私の胸を叩き、こう言った：「アッラーにかけて、アブー・アル＝ムンズィルよ、知識があなたにとって心地よいものとなるよう。」",
    "hadeeth": "ウバイ・ブン・カァブ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「アブー・アル＝ムンズィルよ、あなたが知っているアッラーの書の内、どのアーヤ（節）が最も偉大か知っているか？」私は言った：「アッラーとその使徒がよくご存知です。」彼は言った：「アブー・アル＝ムンズィルよ、あなたが知っているアッラーの書の内、どのアーヤ（節）が最も偉大か知っているか？」私は言った：「アッラーは、かれの外に（真に）崇拝すべきものがなく、永世するお方、全てを司るお方。」（クルアーン２：２５５）すると彼は私の胸を叩き、こう言った：「アッラーにかけて、アブー・アル＝ムンズィルよ、知識があなたにとって心地よいものとなるよう。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、アッラーの書のなかで最も偉大なアーヤについて、ウバイ・ブン・カァブ（アッラーのご満悦あれ）に尋ねた。ウバイは返答をためらった後、こう言った：「それはアーヤトルクルスィー（玉座の節）”アッラーは、かれの外に（真に）崇拝すべきものがなく、永世するお方、全てを司るお方”です。」すると預言者（アッラーからの祝福と平安あれ）はそれに同意し、彼の知識と英知を示唆する意味で彼の胸を叩くと、彼が知識によって幸福となり、知識の修得が容易いものとなるよう、彼のために祈った。",
    "hints": [
          "ウバイ・ブン・カァブ（アッラーのご満悦あれ）の偉大な地位。",
          "アーヤトルクルスィー（玉座の節）は、アッラーの書のなかで最も偉大なアーヤである。ゆえにそれを暗記し、その意味を熟考し、それに則って行わなければならない。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65060: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "預言者（彼にアッラーからの祝福と平安あれ）は毎晩就寝する時には、両手を合わせてそこに息を吹き込み、それからその中に向かって、「言え。”かれはアッラー、唯一なるお方”」と「言え。”私は黎明の主に、ご加護を乞う” 」と「言え。”「私は人々の主に、ご加護を乞う”」",
    "hadeeth": "アーイシャ（アッラーのご満悦あれ）は言った： 預言者（彼にアッラーからの祝福と平安あれ）は毎晩就寝する時には、両手を合わせてそこに息を吹き込み、それからその中に向かって、「言え。”かれはアッラー、唯一なるお方”」と「言え。”私は黎明の主に、ご加護を乞う” 」と「言え。”「私は人々の主に、ご加護を乞う”」を唱え、それからその両手でもって頭、顔に始まり、体の前部というふうに、体のできる範囲の箇所を撫でた。それを３回繰り返したものだった。",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）の手法として、このようなものがあった：彼は就寝するために寝床につく時、ちょうど祈るときのように両手を合わせてそれを上げ、そこに少し唾が含まれる程度に口でやさしく息を吹き込み、それから「言え。”かれはアッラー、唯一なるお方”」と「言え。”私は黎明の主に、ご加護を乞う” 」と「言え。”「私は人々の主に、ご加護を乞う”」という３つのスーラ（章）を読んだものだった。それからその両手でもって頭、顔に始まり、体の前部というふうに、体のできる範囲の箇所を撫でた。それを３回繰り返したものだった。",
    "hints": [
