  65062: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "だから、（クルアーンの）意味が紛らわしい部分に従う者たちを見たら、それらの者たちこそがアッラーが言っている者たちである。彼らに気をつけよ。",
    "hadeeth": "アーイシャ（アッラーのご満悦あれ）は言った： アッラーの使徒（アッラーからの祝福と平安あれ）はこのアーヤ（節）を読んだ：「かれは、この啓典（クルアーン）をあなたに下されたお方。その中には、啓典の母である明確なアーヤと、（それとは）別の紛らわしいアーヤがある。心に歪みがある者たちは（人々の）誘惑を望み、（好き勝手な）解釈を求めて、意味が紛らわしい部分に従うのだ。アッラーと、”私たちはこれ（クルアーン）を信じた。（これは）全て我らが主の御許からのものである”と言う、知識が深く根ざした者たちの外、その（真の）解釈を知るものはないというのに。澄んだ知性の持ち主以外、教訓を受けることはないのだ。」（クルアーン３：７）アッラーの使徒（アッラーからの祝福と平安あれ）は言った：「だから、（クルアーンの）意味が紛らわしい部分に従う者たちを見たら、それらの者たちこそがアッラーが言っている者たちである。彼らに気をつけよ。」",
    "explanation": "アッラーの使徒（アッラーからの祝福と平安あれ）はこのアーヤ（節）を読んだ：「かれは、この啓典（クルアーン）をあなたに下されたお方。その中には、啓典の母である明確なアーヤと、（それとは）別の紛らわしいアーヤがある。心に歪みがある者たちは（人々の）誘惑を望み、（好き勝手な）解釈を求めて、意味が紛らわしい部分に従うのだ。アッラーと、”私たちはこれ（クルアーン）を信じた。（これは）全て我らが主の御許からのものである”と言う、知識が深く根ざした者たちの外、その（真の）解釈を知るものはないというのに。澄んだ知性の持ち主以外、教訓を受けることはないのだ。」（クルアーン３：７）このアーヤの中でアッラーは、以下のことを伝えている：アッラーがその預言者にクルアーンを下したお方であること。その中には意味が明らかで、その規定も明白で疑念の余地もないアーヤがあるが、それが啓典の母であり、立ち返るべき典拠であり、相違点があった際の根拠である。他方、クルアーンの中には複数の意味に解釈できるものもあり、ある種の人々にとってその意味が分かりにくいようなものもある。アッラーはこれらのアーヤに関する人々の対応の仕方を説明し、心が真理から逸れている者たちは疑念を生じさせ、人々を迷わせることを望み、自分たちの私欲に応じた形に解釈するために、明確なアーヤではなく意味が紛らわしく見えるアーヤに依拠する、としている。一方で確固とした知識を持つ者たちは、このような紛らわしく見えるアーヤがあればそれを明確なアーヤによって判断し、それを信じ、それがアッラーの御許からのものであること、そこに何の疑念も矛盾もないことを信じるのである。しかしそのような熟考を得るのは、健全な理性を備えた者たちだけである。それから預言者（アッラーからの祝福と平安あれ）は信仰者たちの母アーイシャ（アッラーのご満悦あれ）に、こう言ったのである：だから、（クルアーンの）意味が紛らわしい部分に従う者たちを見たら、それらの者たちこそがアッラーが言っている者たちである。彼らに気をつけ、彼らの言うことを聞くのではない。",
    "hints": [
          "クルアーンの明確なアーヤとは、その意味が明らかなもの。紛らわしいアーヤとは、複数の意味に解釈できる余地があり、検証と理解が必要な類いのもの。",
          "心に歪みがある者たち、ビドゥア（宗教的に正当な根拠のないものを宗教の一部だとすること）の徒、人々を迷わせ疑念に陥らせるために問題を起こすような者たちと付き合うことへの注意。",
          "このアーヤの最後「澄んだ知性の持ち主以外、教訓を受けることはないのだ」には、逸脱した者たちへの非難と、確固とした者たちへの賞賛がある。つまり、熟考もせず訓戒も受けず、私欲に追従する者は、「澄んだ知性の持ち主」ではない。",
          "紛らわしいアーヤに従うことは、心の歪みの原因である。",
          "意味が分からない紛らわしいアーヤがあったら、それを明確なアーヤと照らし合わせることの義務。",
          "アッラーはクルアーンの一部を明確なものとし、別の一部を紛らわしいものとした。それは信仰の徒と迷妄の徒を判別すべく、人々を試練にかけるためである。",
          "クルアーンの中に紛らわしいアーヤがあることにより、学者のそれ以外の者に対する徳や、知性の限界の認識が明らかになる。知性は創造主に降伏し、自らの無力を認めるのである。",
          "確固とした知識の徳と、そこにおいて確立することの必要性。",
          "クルアーン解釈学者らは、アーヤの中の「アッラーと、”私たちはこれ（クルアーン）を信じた。（これは）全て我らが主の御許からのものである”と言う、知識が深く根ざした者たちの外、その（真の）解釈を知るものはないというのに」という箇所で、どこで区切るべきかということについて２つの意見に分かれている。上述の解釈の場合、ここで言う「解釈」は文字通りのアーヤの解釈、説明という意味であり、アッラーはもちろんのこと、知識が深く根ざした者たちも知り得ることである。彼らはそのアーヤを信じ、明確なアーヤに照らし合わせて理解するのである。他方、アラビア語原文の文章の区切り方によっては、このアーヤは「アッラー以外、その（真の）解釈を知るものはないというのに。知識が深く根ざした者たちは、”私たちはこれ（クルアーン）を信じた。（これは）全て我らが主の御許からのものである”と言う」という意味にもなりえる。この場合、ここで言われている「解釈」は、魂や復活の日の到来に関することなど、アッラーだけにその知識が属し、それ以外の者たちにはその真の知識、本質の理解が到達不可能なものであるようなことである。そしてこの場合、知識が深く根ざした者たちはそのアーヤを信じるが、その真実についてはアッラーに委ね、服従し、委任するのである。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65068: {
    "category_id": 3,
    "category": "神学",
    "title": "現世において彼を両足の上に歩ませたお方は、審判の日に彼を顔から逆さまの状態で歩ませることがお出来ではないのかね？",
    "hadeeth": "カターダ（アッラーのご慈悲あれ）によれば、 アナス・ブン・マーリク（アッラーのご満悦あれ）は、ある男がこのように言ったと伝えた：「アッラーの預言者よ、不信仰者はどのようにして顔から逆さまの状態で召集されるのですか？」彼（預言者）は、言った：「現世において彼を両足の上に歩ませたお方は、審判の日に彼を顔から逆さまの状態で歩ませることがお出来ではないのかね？」カターダは言った：「私たちの主の威厳にかけて、お出来になります。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はある時、このように尋ねられた：「審判の日、不信仰者はどのようにして顔から逆さまの状態で召集されるのですか？」それで預言者（アッラーからの祝福と平安あれ）は、言った：「現世において彼を両足の上に歩ませたお方は、審判の日に彼を顔から逆さまの状態で歩ませることがお出来ではないのかね？アッラーはあらゆることがお出来のお方なのだ。」",
    "hints": [
          "審判の日における、不信仰者の屈辱。彼は顔から逆さまの状態で歩くことになる。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65069: {
