    "category": "神学",
    "title": "ラー・イラーハ・イッラッラー（アッラー以外に崇拝すべきいかなるものもなし）と言って下さい。私が審判の日、あなたのためにそれを証言しますから。",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、 アッラーの使徒（アッラーからの祝福と平安あれ）は、彼の叔父にこう言った：「ラー・イラーハ・イッラッラー（アッラー以外に崇拝すべきいかなるものもなし）と言って下さい。私が審判の日、あなたのためにそれを証言しますから。」彼（叔父）は言った：「クライシュ族が私を咎め、”彼は恐怖ゆえにそうしたのだ”と言うのでなければ、私はそうすることであなたを喜ばせることが出来たのだが。」それでアッラーはこのように啓示した：「（使徒よ、）本当にあなたが、自分の好む者を導くのではない。しかしアッラーが、かれのお望みになる者をお導きになるのである。」（クルアーン２８：５６）",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、彼の叔父アブー・ターリブが死の間際にある時、彼が「ラー・イラーハ・イッラッラー（アッラー以外に崇拝すべきいかなるものもなし）」と証言するよう頼んだ。そうすれば彼が審判の日、そのことによって彼のために執り成し、彼のイスラーム改宗を証言するためである。しかし彼（叔父）は、クライシュ族から悪く言われたり、「彼は死への恐怖と彼の弱さゆえに、改宗したのだ」と言われたりすることを恐れ、信仰証言を拒んだ。彼は預言者（アッラーからの祝福と平安あれ）に、そのようなことさえなければ、信仰証言を行なってあなたを喜ばせる、あなたの望みを叶えて満足させることが出来たのだが、と述べた。それでアッラーは、預言者（アッラーからの祝福と平安あれ）にさえも人を最終的にイスラームへと導く力はないのであり、アッラーだけが望む者をお導きになるのだということを示すべく、クルアーンを下したのである。預言者（アッラーからの祝福と平安あれ）といえども、ただ、人々を根拠、説明、唱導、宣教によって真っ直ぐな道へと導く努力をするだけなのである。",
