  65071: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "「あなたが言い、招いているものは、よいものです。私たちがやってしまったことに対する償いを教えてくれませんか？」",
    "hadeeth": "イブン・アッバース（彼にアッラーのご満悦あれ）によれば、 殺人を散々行い、姦淫を散々行っていたシルクの民が預言者（彼にアッラーからの平安と祝福あれ）のところにやって来て、言った：\n「あなたが言い、招いているものは、よいものです。私たちがやってしまったことに対する償いを教えてくれませんか？」\nそこで、こう啓示された。「また、アッラーと並べて別の神を祈らず、アッラーが禁じられた者を正当な権利なしには殺さず、姦通しない者たち。」（識別章68）また、こう啓示された。「自分自身に対し、（罪という重荷を）背負いに背負った、わが僕たちよ。アッラーのご慈悲に絶望するのではない。」（集団章53）",
    "explanation": "殺人や姦淫を散々やっていたシルクの民の男たちが、預言者（彼にアッラーからの平安と祝福あれ）のところにやって来て言った：「あなたが招いているイスラームとその教えは、よいものです。私たちが陥っているシルクや大罪に関して、償いはあるのでしょうか？」\n\nすると、２つのアーヤが下った。それらは、アッラーが、多くの甚大な罪を犯した人々の悔悟を受け入れることを示すものだった。もしそれがなかったとしたら、彼らは不信仰と放逸さの中に留まり続け、この宗教に入ることがなかっただろう。",
    "hints": [
