          "僕に対するアッラーの慈悲の偉大さと罪の赦し。",
          "シルク、正当な権利のない殺人、姦淫の禁止。そしてそのような罪を犯す者への警告。",
          "真摯な意図、善行を伴う誠実な悔悟は、あらゆる大罪に対する償いとなる。そこにはアッラーに対する不信仰も含まれる。",
