    "category": "神学",
    "title": "彼のところに言って、彼にこう言うのだ：”あなたは地獄の民などではない。しかし天国の民なのである”と。」",
    "hadeeth": "アナス（彼にアッラーのご満悦あれ）によれば、 預言者（アッラーからの祝福と平安あれ）がサービト・ブン・カイスの安否を尋ねている時、ある男がこう言った：「アッラーの使徒よ、私が彼についての情報をあなたに持って来ましょう。」こうして男が彼のもとを訪れると、彼が自分の家の中でうなだれて座っているのを見出した。男は彼に言った：「どうしたのか？」彼は言った：「悪いことだ。彼は預言者（アッラーからの祝福と平安あれ）の声に対してそれよりも大きな声を上げたために、行いが泡となり、地獄の民の一人となってしまったのだ。」男は預言者のところに戻り、「彼はこのように言っています」と伝えた。それから大きな吉報と共にまた彼のところに戻ると、こう言った：「彼のところに言って、彼にこう言うのだ：”あなたは地獄の民などではない。しかし天国の民なのである”と。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はある時、サービト・ブン・カイスの安否を尋ねていた。すると、ある男がこう言った：「彼がなぜ姿を見せないのか、私が彼の情報を持って来ましょう。」こうして男が彼のもとを訪れると、彼が自宅でうなだれて悲しそうにしているのを見出した。男は彼に尋ねた：「どうしたのか？」それで彼は、彼の悪い状態について説明した。彼は預言者（アッラーからの祝福と平安あれ）の声に対してそれよりも大きな声を上げたために、行いが泡となり、地獄の民の一人となってしまったのだ、と。\n\n男は預言者（アッラーからの祝福と平安あれ）のところに戻り、そのことを伝えた。すると預言者（アッラーからの祝福と平安あれ）は彼に、サービトのところに行って、彼が地獄の民などではなく天国の民だという吉報を伝えなさい、と言った。それは彼の声が元々預言者の声より大きく、彼がアッラーの使徒（アッラーからの祝福と平安あれ）の説教者であり、アンサールの説教者であったためである。",
