          "教友たち（彼らにアッラーのご満悦あれ）における、自分の行いが無駄になってしまうことに対する恐怖の念の強さ。",
          "預言者（アッラーからの祝福と平安あれ）の生前において、彼に話をする時の礼儀作法と、彼の死後にはそのスンナを聞く時に声を低めることの義務。",
