  65074: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "人々よ、アッラーはあなた方からジャーヒリーヤの傲慢さと、父祖を偉大視して驕慢になる気持ちを解き放った",
    "hadeeth": "イブン・ウマル（アッラーのご満悦あれ）によれば、 アッラーの使徒（アッラーからの祝福と平安あれ）はマッカ開放の際、人々に説教してこう言った：「人々よ、アッラーはあなた方からジャーヒリーヤの傲慢さと、父祖を偉大視して驕慢になる気持ちを解き放った。人は善良で敬虔でアッラーにとって貴い者か、放埒で不幸でアッラーにとって卑小な者かのいずれかなのだ。人々はアーダムの子孫であり、アーダムは土から創られたのである。アッラーは仰った：”人々よ、本当にわれらは、あなた方を一人の男性と一人の女性から創り、あなた方が知り合うべく、あなた方をいくつもの民族や部族とした。実にあなた方の内、アッラーの御許で最も高貴な者とは、最も敬虔な者なのである。アッラーこそは全知者、通暁されるお方。”」（部屋章13）",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はマッカ解放の日、説教してこう言った：「人々よ、アッラーはあなた方からジャーヒリーヤの傲慢さと自尊心、父祖を引き合いに威張ることを解消した。人間は２種類である：\n\n信仰者で、善良で、敬虔で、アッラーに従順な崇拝者であるような者。これはたとえ人々の目に地位や家系に優れた者ではなかったとしても、アッラーのもとで貴い者なのである。\n\nまたは、不信仰者で、放埒で、不幸な者。これはアッラーのもとで卑小で取るに足らない者であり、何の価値もない。たとえ血筋や地位や権力があったとしてもである。\n\n人々は皆アーダムの子孫であり、アッラーはアーダムは土から創られたのだ。土から創られた者が威張ったり自惚れたりすることは、相応しくないことなのである。アッラーのこの言葉が、そのことをよく示している\n：”人々よ、本当にわれらは、あなた方を一人の男性と一人の女性から創り、あなた方が知り合うべく、あなた方をいくつもの民族や部族とした。実にあなた方の内、アッラーの御許で最も高貴な者とは、最も敬虔な者なのである。アッラーこそは全知者、通暁されるお方。”」（部屋章13）",
    "hints": [
          "血筋や評判について威張ることの禁止。",
        ],
    "grade": "صحيح",
    "attribution": "رواه الترمذي وابن حبان",
  },
