    "hadeeth": "アッ＝ズバイル・ブン・アル＝アウワーム（アッラーのご満悦あれ）は、言った： 「それから、あなた方は（復活の）その日、必ずや安寧について尋ねられよう」（クルアーン102:8）が啓示された時、アッ＝ズバイルは言った：「アッラーの使徒よ、私たちはどんな安寧について尋ねられるのですか？それは２つの黒いもの、つまりデーツと水のことですか？」彼は言った：「それもその内のものとなろう。」",
    "explanation": "このアーヤが下った時： 「それから、あなた方は（復活の）その日、必ずや安寧について尋ねられよう。」（クルアーン102:8）〜つまり、アッラーがあなた方に恵んでくれた恩恵に対し、感謝をしたかどうかをあなた方は尋ねられることになるだろう、という意味である〜。アッ＝ズバイル・ブン・アル＝アウワーム（アッラーのご満悦あれ）は言った：「アッラーの使徒よ、私たちはどんな安寧について尋ねられるのですか？私たちが授かっているのは２つの黒いもの、つまりデーツと水だけであり、尋ねられるようなものでもありません。」\n\n預言者（アッラーからの祝福と平安あれ）は言った：「あなた方は、あなた方がいるその状況に応じて、安寧について尋ねられることになる。それら２つはアッラーの恩恵のうちでも、偉大な恩恵なのだから。\n」",
    "hints": [
