    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「わが共同体の最後の者たちの内から、あなた方もあなた方の祖先も聞いたことのないようなことをあなた方に語る人々が出現しよう。彼らには十分気をつけるがよい。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、彼の共同体の最後の者たちの内から、嘘をでっち上げ、あなた方以前の誰も言ったことのないようなことを言い、捏造した偽りの話を語るような者たちが出現する、と言った。彼（アッラーからの祝福と平安あれ）は、私たちがそのような者たちから遠ざかり、同席することも話を聞くこともないように、と命じた。それはそのような捏造の話が心に根を下ろし、そこから逃れられなくなってしまわないようにするためである。",
