  65077: {
    "category_id": 2,
    "category": "ハディースとその諸学",
    "title": "書きなさい。わが魂がその御手にあるお方にかけて、ここからは真理しか出ないのだから。」",
    "hadeeth": "アブドッラー・ブン・アムル（アッラーのご満悦あれ）は、言った： 私は、私がアッラーの使徒（アッラーからの祝福と平安あれ）から聞くこと全てを覚えておくために書き留めていた。するとクライシュ族は、私にそれを禁じて言った：「あなたはアッラーの使徒（アッラーからの祝福と平安あれ）から聞くこと全てを書き留めるのか？アッラーの使徒（アッラーからの祝福と平安あれ）は人間で、怒りや喜びの状態にある時にも話すというのに。」それで私は筆記をやめたのだが、そのことがアッラーの使徒（アッラーからの祝福と平安あれ）に伝わると、彼は自分の口を指で指してこう言った：「書きなさい。わが魂がその御手にあるお方にかけて、ここからは真理しか出ないのだから。」",
    "explanation": "アブドッラー・ブン・アムル（アッラーのご満悦あれ）は言った：私は、私がアッラーの使徒（アッラーからの祝福と平安あれ）から聞くこと全てを覚えておくために書き留めていた。するとクライシュ族の者たちは、私にそれを禁じて言った：「アッラーの使徒（アッラーからの祝福と平安あれ）は人間で、怒りや喜びの状態にある時にも話すし、もしかすると間違えるかもしれない。」それで私は筆記をやめた。\n\n私は彼らが言ったことを、預言者（アッラーからの祝福と平安あれ）に伝えた。すると、彼は自分の口を指で指してこう言った：「書きなさい。わが魂がその御手にあるお方にかけて、喜びの時も怒りの時も、ここからは常に真理しか出ないのだから。」\n\nアッラーは預言者（アッラーからの祝福と平安あれ）について、こう仰った： 「また、彼は私欲で語っているのでもない。 それは、下される啓示以外の何ものでもないのだ。」（クルアーン53:3−4）",
