    "hadeeth": "アムル・ブン・アーミル（アッラーのご満悦あれ）によれば、アナスは言った： 「預言者（アッラーからの祝福と平安あれ）は各サラー（礼拝）のためにウドゥーをしたものだった。」私は言った：「あなた方はどうしていましたか？」彼は言った：「汚れの状態にならなければ、ウドゥーは不要としたものだった。」",
