  65083: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「あなた方が腹部に何かを見出して苦しくなり、（排泄口から）何か出てしまったのではないかと疑念を抱いたとしても、音を聞いたり臭いを嗅いだりしたりするまでは（礼拝を中断して）モスクを出てはならない。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「あなた方が腹部に何かを見出して苦しくなり、（排泄口から）何か出てしまったのではないかと疑念を抱いたとしても、音を聞いたり臭いを嗅いだりしたりするまでは（礼拝を中断して）モスクを出てはならない。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、礼拝する者が腹部に何かを見出して苦しくなり、排泄口から何か出てしまったのではないかと疑念を抱いたとしても、おならの音を聞いたり臭いを嗅いだりしたりすることによって、ウドゥーがなくなったこと確信するまでは、ウドゥーするために礼拝を中断してはならない。なぜなら疑念は確信を無効化することななく、その者にとって清浄な状態は確信されたものであり、穢れの状態は疑念があるところだからである。",
    "hints": [
          "このハディースはイスラームの基盤の一つであり、法学のルールの一つである。それは疑念が確信を無効化することはなく、物事の状態というものはそれと異なる状態が確信されるまで、それまでの状態を引き続き継続するということである。",
          "疑念は清浄さに影響しない。礼拝者は穢れの状態を確信するまで、清浄な状態にとどまる。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65084: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「毎7日間に1日はグスルをし、頭と体を洗うのが、全ムスリムの義務である。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「毎7日間に1日はグスルをし、頭と体を洗うのが、全ムスリムの義務である。」",
    "explanation": "アッラーの使徒（アッラーからの祝福と平安あれ）は言っている:毎7日間に1日、つまり週1回は清潔さと清めのためにグスルをし、頭と体を洗うのが、正常な理性を備えた全成人ムスリムに対する、強調された義務である。そしてそれらの日々で最も優先されるのが金曜日であるということが、他のいくつかの伝承から理解されることである。たとえ木曜日にグスルしていたとしても、金曜日の合同のサラー前に行うグスルは強調されたスンナなのである。それが義務ではないことは、アーイシャ（アッラーのご満悦あれ）の次の伝承でも、明白である：「人々は労働していたものであり、金曜のサラーに行く時には、そのままの格好で行ったものだった。それで彼らに、こう言われたのだ：”グスルをしてきたら良かったのに。”」（アル＝ブハーリーの伝承）別の伝承には、こうある：「彼らからは臭いが漂っていた。」つまり汗などの臭いのことである。それにも関わらず、彼らに言われたのは「グスルをしてきたら良かったのに」という言葉だった。彼らのような状態にはなかった者たちにとって、それがより優先されるわけではないことは、明らかである。",
    "hints": [
          "清潔さ、清浄さに対するイスラームの関心。",
          "金曜のサラーのためのグスルが、強調されたスンナであること。",
          "頭が身体の一部であるにも関わらず、特別に言及されていることは、そこに特別な重きが置かれている印である。",
          "他人に嫌がられるような悪臭がある者は、グスルしなければならない。",
          "グスルが最優先される日は、金曜日である。それはそこに特別な徳があるためである。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65085: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「私はイスラームへの改宗を望んで、預言者（アッラーからの祝福と平安あれ）のもとにやって来た。すると彼は、水とスィドゥルを用いてグスルするよう、私に命じた。」",
    "hadeeth": "カイス・ブン・アースィム（彼にアッラーのご満悦あれ）は言った： 「私はイスラームへの改宗を望んで、預言者（アッラーからの祝福と平安あれ）のもとにやって来た。すると彼は、水とスィドゥルを用いてグスルするよう、私に命じた。」",
    "explanation": "カイス・ブン・アースィム（彼にアッラーのご満悦あれ）はイスラームへの改宗を望んで、預言者（アッラーからの祝福と平安あれ）のもとにやって来た。すると彼は、水とスィドゥルの木を用いてグスルするよう、彼に命じた。スィドゥルの葉には芳香があり、洗浄に用いられるためである。",
    "hints": [
          "非ムスリムがイスラームに改宗する際、グスルすること。",
          "心身両面に対するイスラームの関心と重要視。",
          "水に清浄な物質を混ぜても、その清浄性は変わらないこと。",
          "石鹸などの新しい類いの洗剤を、スィドゥルに代用することも可能である。",
        ],
    "grade": "صحيح",
    "attribution": "رواه أبو داود والترمذي والنسائي",
  },
  65086: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "ムアッズィンが「アッラーフ　アクバル（アッラーは偉大なり）」と言ったら、「アッラーフ　アクバル（アッラーは偉大なり）」と言い",
    "hadeeth": "ウマル・ブン・アル＝ハッターブ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った: ムアッズィンが「アッラーフ　アクバル（アッラーは偉大なり）」と言ったら、「アッラーフ　アクバル（アッラーは偉大なり）」と言い、「アシュハドゥ　アッラー　イラーハ　イッラッラー（私はアッラーのみが崇拝に値すると証言する）」と言ったら、「アシュハドゥ　アッラー　イラーハ　イッラッラー（私はアッラーのみが崇拝に値すると証言する）」と言い、「アシュハドゥ　アンナ　ムハンマダッラスールッラー（私はムハンマドがアッラーの使徒であると証言する）」と言ったら、「アシュハドゥ　アンナ　ムハンマダッラスールッラー（私はムハンマドがアッラーの使徒であると証言する）」と言い、「ハイヤー　アラッサラー（礼拝に来たれ）」と言ったら、「ラー　ハウラ　ワラー　クウワタ　イッラー　ビッラー（アッラー以外にいかなる偉力もなし）」と言い、「ハイヤー　アラルファラーハ（成功に来たれ）」と言ったら、「ラー　ハウラ　ワラー　クウワタ　イッラー　ビッラー（アッラー以外にいかなる偉力もなし）」と言い、「アッラーフ　アクバル（アッラーは偉大なり）」と言ったら、「アッラーフ　アクバル（アッラーは偉大なり）」と言い、「ラー　イラーハ　イッラッラー（アッラー以外に崇拝に値するものはない）」と言ったら、「ラー　イラーハ　イッラッラー（アッラー以外に崇拝に値するものはない）」と心から言うものは、天国に入る。",
    "explanation": "アザーンとは、義務のサラー（礼拝）の時間に入ったことを人びとに知らせる、呼びかけのことである。アザーンの言葉は、信仰箇条をまとめた内容となっている。\n\nこのハディースでアッラーの使徒（アッラーからの祝福と平安あれ）は、アザーンを聞いた時にはムアッズィンと同じように唱えることが、イスラームの教えであることを説明している。ムアッズィンが「アッラーフ　アクバル（アッラーは偉大なり）」と言ったら、それを聞いた者も「アッラーフ　アクバル（アッラーは偉大なり）」と言う、といった具合である。ただし、ムアッズィンが「ハイヤー　アラッサラー（礼拝に来たれ）」と「ハイヤー　アラルファラーハ（成功に来たれ）」と言った時だけは別で、それを聞いた者は「ラー　ハウラ　ワラー　クウワタ　イッラー　ビッラー（アッラー以外にいかなる偉力もなし）」と言う。\n\n預言者（アッラーからの祝福と平安あれ）は、ムアッズィンが言うことを心から純粋に復唱する者は天国に入る、と言っている。\n\nアザーンの言葉の意味は以下の通りである： 「アッラーフ　アクバル（アッラーは偉大なり）」：アッラーこそはいかなるものよりも偉大で、荘厳で、大きなお方。\n\n「アシュハドゥ　アッラー　イラーハ　イッラッラー（私はアッラーのみが崇拝に値すると証言する）」：アッラー以外には、真に崇拝するに値するものは存在しない、ということ。\n\n「アシュハドゥ　アンナ　ムハンマダッラスールッラー（私はムハンマドがアッラーの使徒であると証言する）」：私は自分の口と心によって、ムハンマドが偉大なるアッラーから遣わされた使徒であり、彼に従うことが義務であるということを認め、証言します、ということ。\n\n「ハイヤー　アラッサラー（礼拝に来たれ）」：サラー（礼拝）に来なさい、という意味。\n「ラー　ハウラ　ワラー　クウワタ　イッラー　ビッラー（アッラー以外にいかなる偉力もなし）」：アッラーへの服従行為から妨げるものに対して、自分自身にはそこから逃れるためのいかなる力もなく、アッラーへの服従行為その他の物事を行うことに対して、自分自身にはいかなる力も属しておらず、全ては至高なるアッラーのお力と定めによるものである、ということ。\n\n「ハイヤー　アラルファラーハ（成功に来たれ）」：成功するための物事へと来なさい、ということ。成功とは天国の獲得と地獄からの救いのことである。",
    "hints": [
          "ムアッズィンが言う言葉に応じて、同じように唱えることの徳。ただし「ハイヤー　アラッサラー（礼拝に来たれ）」と「ハイヤー　アラルファラーハ（成功に来たれ）」の時は別で、「ラー　ハウラ　ワラー　クウワタ　イッラー　ビッラー（アッラー以外にいかなる偉力もなし）」と言う。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65087: {
    "category_id": 3,
    "category": "神学",
    "title": "「ムアッズィン（アザーンする者）を聞いたら、彼が言うのと同じことを言え。それから私に祝福を祈願するのだ",
    "hadeeth": "アブドッラー・ブン・アムル・ブン・アル＝アース（アッラーのご満悦あれ）は、預言者（アッラーからの祝福と平安あれ）がこう言うのを聞いた： 「ムアッズィン（アザーンする者）を聞いたら、彼が言うのと同じことを言え。それから私に祝福を祈願するのだ。私に一回祝福を祈願する者に対し、アッラーは10回祝福を与えて下さるのだから。それからアッラーに対して、私へのワスィーラを求めよ。それは天国における地位であり、アッラーのしもべの内、ただ1人の者にしか相応しくはないものなのだ。そして私は、私がそれであることを願う。私がワスィーラを授かることを求める者には、執り成しが与えられよう。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、以下のことを指導している：ムアッズィン（アザーンする者）がサラーに呼びかけるのを聞いたら、彼について彼が言うのと同じことを言うようこと。ただし「ハイヤー・アラッ＝サラー」と「ハイヤー・アラル＝ファラーハ」の箇所だけは、その後に「ラー・ハウラ・ワ・ラー・クウワタ・イッラー・ビッラー（アッラーによる以外に、いかなる変転も力もない）」と唱える。そしてアザーンが終わったら、預言者（アッラーからの祝福と平安あれ）に祝福を祈願する。彼に一回祝福を祈願する者に対し、アッラーは10回祝福を与えて下さる。この「アッラーからしもべに対する祝福」とは、アッラーがその者を天使たちのところで褒め称えて下さることである。\n\nそれから預言者（アッラーからの祝福と平安あれ）がワスィーラを得ることが出来るよう、アッラーに願うことを命じた。ワスィーラとは天国における最高の地位であり、アッラーのしもべの内でただ一人にしか与えられない。預言者（アッラーからの祝福と平安あれ）は、「私がそれであることを願う」と言った。しかしこの言葉は、預言者（アッラーからの祝福と平安あれ）が謙遜して語ったものである。というのも、それがただ1人の者にしか許されない高い地位なのであれば、それは最良の被造物である預言者（アッラーからの祝福と平安あれ）以外にはないからである。\n\nそれから預言者（アッラーからの祝福と平安あれ）は、彼がワスィーラを授かることを求める者には、預言者（アッラーからの祝福と平安あれ）からの執り成しがある、と説明した。",
    "hints": [
          "ムアッズィンの言葉に応じることの勧め。",
          "ムアッズィンの言うことに応じた後、預言者（アッラーからの祝福と平安あれ）に祝福を祈ることの徳。",
          "預言者（アッラーからの祝福と平安あれ）に祝福を祈った後、彼にワスィーラが授けられることを願うことの勧め。",
          "ワスィーラの意味とその偉大な地位についての説明。それはただ一人のしもべにしか授けられることがない。",
          "預言者（アッラーからの祝福と平安あれ）がワスィーラという高い地位を特別に授かることによる徳についての説明。",
          "預言者（アッラーからの祝福と平安あれ）がワスィーラを授かることをアッラーに願う者には、預言者（アッラーからの祝福と平安あれ）からの執り成しがある。",
          "預言者（アッラーからの祝福と平安あれ）の謙虚さ。彼は、自らにその地位が与えられることになるにも関わらず、自らのウンマに対してそれを祈ることを求めた。",
          "アッラーの恩寵と慈悲の偉大さ。アッラーは一つの善行を10倍にして下さる。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65088: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「サラー（礼拝）を忘れた者は、それを思い出した時に行え。それ以外にその罪滅ぼしはないのだ。",
    "hadeeth": "アナス・ブン・マーリク（彼にアッラーのご満悦あれ）によれば、預言者（彼にアッラーからの祝福と平安あれ）は言った： 「サラー（礼拝）を忘れた者は、それを思い出した時に行え。それ以外にその罪滅ぼしはないのだ。“われを唱念すべく礼拝を遵守せよ。（クルアーン20:14）”」",
    "explanation": "預言者（彼にアッラーからの祝福と平安あれ）は、このように説明している：義務のサラー（礼拝）をその時間帯に行うことを忘れてしまった者は、それを思い出した時にすぐそれを行わなければならない。それを出来なかったことの罪滅ぼしは、それを思い出した時に行うこと以外にはない。アッラーはクルアーンの中で仰っている：「われを唱念すべく礼拝を遵守せよ。」（20:14）つまり、忘れて出来なかったサラーを思い出した時に行え、ということである。",
    "hints": [
          "サラー（礼拝）の重要性。それを時間内に行い、そうできなければその後にでも遂行することをなおざりにしないこと。",
          "サラーを正当な理由もなく、その時間帯が終了するまで故意に遅らせることは、許されない。",
          "サラーを忘れた者がそれを思い出した時に、寝過ごした者が起きた時に、それを行うことの義務。",
          "その時間帯にできなかったサラーを、すぐに行うことの義務。たとえそれが、本来はサラーが禁止されている時間帯であっても、である。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65089: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "”アッラーゆえにマスジドを建てた者に、アッラーは同様のものを天国で建てて下さる。”」",
    "hadeeth": "マフムード・ブン・ラビード（アッラーのご満悦あれ）によると、 ウスマーン・ブン・アッファーン（アッラーのご満悦あれ）はマスジドを建てようとしたが、人々はそのことを嫌がり、それをそのままの状態にしておくことを望んだ。それで彼は言った：「私はアッラーの使徒（アッラーからの祝福と平安あれ）が、こう言うのを聞いた：”アッラーゆえにマスジドを建てた者に、アッラーは同様のものを天国で建てて下さる。”」",
    "explanation": "ウスマーン・ブン・アッファーン（アッラーのご満悦あれ）は預言者（アッラーからの祝福と平安あれ）のマスジドを、最初の形よりも優れた形で再建しようとしたが、預言者（アッラーからの祝福と平安あれ）時代の建物に変更が生じることから、人々はそのことを嫌がった。それはレンガで造られ、その屋根はナツメヤシの葉で出来ていたが、ウスマーンはそれを石と漆喰で再建しようとしたのだった。ウスマーン（アッラーのご満悦あれ）は、彼がアッラーの使徒（アッラーからの祝福と平安あれ）から、このように聞いたと彼らに言った：見栄や評判のためではなく、アッラーのお喜びゆえにマスジドを建てた者に、アッラーはその行為と同種のもので報いて下さる。そしてそれは、天国でその者に同様のものを建てて下さるという報いである。",
    "hints": [
          "マスジドの建設の勧めとその徳。",
          "マスジドの拡張、新調工事は、建設の徳の一部と見なされること。",
          "あらゆる物事におけるアッラーへの真摯さの重要性。",
        ],
