  65096: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "人々よ、私がこのようにしたのは、あなた方がイマームに続いて行い、あなた方が私の礼拝を学ぶためである。\n」",
    "hadeeth": "アブーハーズィム・ブン・ディーナールによれば： 説教壇がどんな木から作られているのかについて議論していた者たちが、サハル・ブン・サァド・アッ＝サーイディーのもとにやって来て、そのことについて尋ねた。彼は言った：「アッラーに誓って。私はそれが何製かを確かに知っている。私はそれが置かれた最初の日も、アッラーの使徒（アッラーのご満悦あれ）がそこに最初に腰掛けた日も、目撃したのである。アッラーの使徒（アッラーからの祝福と平安あれ）はある女性−アンサールの女性で、サハルは彼女の名に言及した−のもとに人を遣わし、こう言った：「大工である、あなたの下働きの者に、私のために木工の用品を作らせなさい。人々に話をする時に、そこに腰掛けますから。」それで彼女は彼に命じ、アル＝ガーバのタマリスクの木でそれを作らせた。それから彼がそれを持って来たので、彼女はそれをアッラーの使徒（アッラーからの祝福と平安あれ）に送った。彼は命じてそれをここに置かせたのだ。私はアッラーの使徒（アッラーからの祝福と平安あれ）がそこで礼拝し、その上でタクビールをし、その上でルクーゥをし、それから後ずさりをして降り、説教壇の下でサジダをし、またその上に戻るのを見た。そして礼拝を終えると、人々の方を向いて、このように言った：「人々よ、私がこのようにしたのは、あなた方がイマームに続いて行い、あなた方が私の礼拝を学ぶためである。\n」",
    "explanation": "アッラーの使徒（アッラーのご満悦あれ）が説教壇としたものが何で出来ているのかを尋ねるため、ある教友のもとに人々がやって来た。彼らはそのことについて、議論をしていたのだった。そこでその教友は、彼らに言った。アッラーの使徒（アッラーのご満悦あれ）は、大工の下働きがいるアンサールの女性のもとに人を遣わし、こう言ったのだと：「あなたの下働きの者に、私のための説教壇を作らせなさい。人々に話をする時に、そこに腰掛けますから。」それで彼女はそれに応じ、彼に命じて、タマリスクの木で説教壇を作らせた。そしてそれが出来上がると、彼女はそれを預言者（アッラーからの祝福と平安あれ）に送った。彼は命じて、それをマスジドのその場所に置かせた。それから預言者（アッラーからの祝福と平安あれ）はそこで礼拝し、その上でタクビールをし、その上でルクーゥをし、それから後方を振り返ることなく後ずさりをして降り、説教壇の下でサジダをし、またその上に戻った。そして礼拝を終えると、人々の方を向いて、このように言った：「人々よ、私がこのようにしたのは、あなた方がイマームに続いて行い、あなた方が私の礼拝を学ぶためである。」",
    "hints": [
          "説教壇を置き、説教する者がそこに上がることの勧め。それは声をよく聞かせ、伝達 するためである。",
          "教える目的のために説教壇で礼拝すること、および必要性があれば、礼拝で導かれる者たちよりもイマームが高い場所に上がることの合法性。",
          "ムスリムの用事において、物作りを生業とする人々の力を借りることの合法性。",
          "礼拝中でも必要性があれば、少し余計な動作をすることの合法性。",
          "礼拝中、先導される者たちが学習目的でイマームを見ることの合法性。そのことは礼拝中の畏れの念とは抵触しない。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65097: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「礼拝をするなら、あなた方の列をまっすぐにしなさい。それから、あなた方の内の誰かにあなた方を先導させ、彼がタクビールしたら、タクビールしなさい",
    "hadeeth": "ヒッターン・ブン・アブドッラー・アッ＝ラカーシーは言った：私はアブームーサー・アル＝アシュアリーの後ろで礼拝した。そしてタシャッフドの時、人々の中のある男が言った：「礼拝は善行と浄財と共に、義務となった。」礼拝が終わり、タスリームすると、アブームーサーは向き直って言った：「これこれのことを言った者は、あなた方の内の誰か？」人々は沈黙した。そして、言った：「これこれのことを言った者は、あなた方の内の誰か？」また人々は沈黙した。それから言った：「ヒッターンよ、もしかしてお前が言ったのか？」彼は言った：「私が言ったのではありません。私はあなたがそのことで私を責めるのではないかと、恐れていました。」すると、人々の内のある男が言った：「私が言いました。私は良かれと思って言っただけです。」アブームーサーは言った：「あなた方は礼拝の中でどのように言うのか、知らないのか？アッラーの使徒（アッラーからの祝福と平安あれ）は私たちに説教し、私たちのスンナについて私たちに説明し、私たちの礼拝について教え、こう言ったのである： 「礼拝をするなら、あなた方の列をまっすぐにしなさい。それから、あなた方の内の誰かにあなた方を先導させ、彼がタクビールしたら、タクビールしなさい。そして彼が『つまり、（あなたの）お怒りを受けるでもなく、迷うでもない者たちの道へ』（クルアーン1：7）と言ったなら、『アーミーン』と言いなさい。そうすればアッラーはあなた方に応えるでしょう。また、彼がタクビールし、ルクーゥしたら、タクビールし、ルクーゥしなさい。イマームがあなた方より先にルクーゥし、あなた方より先にそこから戻るのです。」こうしてアッラーの使徒（アッラーからの祝福と平安あれ）は、言った：「その時が、その時のためのものです。そして彼が『アッラーは、かれを讃える者を聞き給う』と言ったら、『アッラーよ、我らの主よ、あなたにこそ賛美はあります』と言いなさい。そうすればアッラーは、あなた方をお聞きになるでしょう。というのも至高なるアッラーは、その預言者（アッラーからの祝福と平安あれ）の言葉によって、『アッラーは、かれを讃える者を聞き給う』と仰ったからなのです。また、彼がタクビールし、サジダしたら、タクビールし、サジダしなさい。イマームがあなた方より先にサジダし、あなた方より先にそこから戻るのです。」こうしてアッラーの使徒（アッラーからの祝福と平安あれ）は、言った：「その時が、その時のためのものです。そしてタシャッフドの段になったら、あなた方の最初の言葉をこれにしなさい：『挨拶とよきものと礼拝は、アッラーに。預言者よ、あなたに平安とアッラーのご慈悲と祝福あれ。私たちと、アッラーの正しい僕たちに平安あれ。私はアッラー以外に崇拝すべきいかなるものもなく、ムハンマドがかれの僕であり使徒であることを証言する』と。」",
    "explanation": "アブームーサー・アル＝アシュアリー（アッラーのご満悦あれ）が礼拝し、タシャッフドのための座位姿勢にあった時、礼拝者の中のある男が後方で言った：「礼拝はクルアーンの中で、善行と浄財と共に並べられている。」それでアブームーサー（アッラーのご満悦あれ）は礼拝が終わると、礼拝者の方へ向き直って、尋ねた：「『礼拝はクルアーンの中で、善行と浄財と共に並べられている』という言葉を言った者は、あなた方の内の誰か？」すると人々は沈黙し、誰も口を開かなかった。そして、もう一度その質問を繰り返したが、やはり誰も答えなかった。それでアブームーサー（アッラーのご満悦あれ）は言った：「ヒッターンよ、もしかしてお前が言ったのか？」それはヒッターンが大胆で、アブームーサーと血縁上も関係上も近い間柄であり、そのように言うことが大きな問題とならなかったためであり、また、張本人が白状するのを促すためでもあった。ヒッターンはそれを否定し、言った：「私はあなたが、そう言ったのは私ではないかと思って、私を責めるのではないかと恐れていました。」そこで、人々の中のある男が言った：「私が言いました。私は良かれと思って言っただけです。」アブームーサー（アッラーのご満悦あれ）はそこで、彼に教示してこう言った：「あなた方は礼拝の中でどのように言うのか、知らないのか？」これは彼からの非難の言葉であった。それからアブームーサーは、預言者（アッラーからの祝福と平安あれ）がある時彼らに説教し、そこでイスラームの教えについて説明し、礼拝について教え、こう言ったのだと語ったのである：\n\n「礼拝をするなら、あなた方の列をまっすぐに揃えなさい。それから、あなた方の内の誰かにあなた方を先導させ、イマームが礼拝開始のタクビールをしたら、同様にタクビールしなさい。そして彼がアル＝ファーティハを読み、『つまり、（あなたの）お怒りを受けるでもなく、迷うでもない者たちの道へ』（クルアーン1：7）という箇所に差しかかったなら、『アーミーン』と言いなさい。そうすればアッラーはあなた方の祈りに応えるでしょう。また、彼がタクビールし、ルクーゥしたら、タクビールし、ルクーゥしなさい。イマームがあなた方より先にルクーゥし、あなた方より先にそこから戻るのであり、彼に先駆けてはなりません。イマームがルクーゥする時にあなた方に先駆けるその時間は、ルクーゥから戻る時にあなた方が彼に遅れるその時間によって、償われます。その時の時間が、その時のための時間となり、あなた方のルクーゥの長さは、彼のルクーゥの長さと同様となるのです。そしてイマームが『アッラーは、かれを讃える者を聞き給う』と言ったら、あなた方は『アッラーよ、我らの主よ、あなたにこそ賛美はあります』と言いなさい。礼拝者がそう言えばアッラーは、彼らの言葉と祈りをお聞きになるでしょう。というのも至高なるアッラーは、その預言者（アッラーからの祝福と平安あれ）の言葉によって、『アッラーは、かれを讃える者を聞き給う』と仰ったからなのです。また、イマームがタクビールし、サジダしたら、礼拝者たちもタクビールし、サジダしなさい。イマームがあなた方より先にサジダし、あなた方より先にそこから戻るのです。その時の時間が、その時のための時間となり、あなた方のサジダの長さは、彼のサジダの長さと同様となります。そしてタシャッフドの段になったら、礼拝者たちの最初の言葉をこれにしなさい：『挨拶とよきものと礼拝は、アッラーに。』つまり、王権、永遠、偉大さといったものは、アッラーにこそ相応しい。『預言者よ、あなたに平安とアッラーのご慈悲と祝福あれ。私たちと、アッラーの正しい僕たちに平安あれ。』つまり、あらゆる欠陥、害悪、不足といったことからの無事を、アッラーに祈りなさい。そしてまず預言者（アッラーからの祝福と平安あれ）に対する特別な平安を祈り、次いで自分たちへの平安を祈り、次いでアッラーに対する義務と人々に対する義務を遵守する、アッラーの正しい僕たちへの平安を祈ります。それから、アッラー以外に崇拝すべきいかなるものもなく、ムハンマドがかれの僕であり使徒であることを証言するのです。」",
    "hints": [
          "タシャッフドの一形式の説明。",
          "礼拝における言葉や動作は必ず、預言者（アッラーからの祝福と平安あれ）から確実な形で伝わるものでなければならない。スンナにおいて確かではない言葉や動作をそこにおいて採用することは、誰にも許されない。",
          "礼拝においてイマームに先駆けたり、遅れすぎたりすることは許されない。礼拝において先導される者は、その動作においてイマームに続か なければならない。",
          "イスラームの教えを伝達し、その共同体への教育における、預言者（アッラーからの祝福と平安あれ）の関心の高さ。",
          "イマームは、礼拝において先導される者たちにとっての模範である。サラーの動作において、イマームに先駆けたり、同時に行ったり、あるいは完全に遅延したりしまうことは許されない。そうではなく、イマームが行おうとしている動作に入ったことを確認してから、彼に続くのである。イマームの踏襲 がスンナである。",
          "礼拝において列をまっすぐにすること。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65098: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "私の魂がその手に委ねられたお方に誓って。私はあなた方の内で、最もアッラーの使徒（アッラーからの祝福と平安あれ）のサラーに近い者である。これが、現世を立ち去る時まで彼がやっていたサラーなのだ。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、 義務のサラー（礼拝）であれ、それ以外のサラーであれ、また、ラマダーンであれ、それ以外の時期であれ、全てのサラーでタクビールしたものだった。つまり立ち上がる時にも、ルクーゥする時にも、タクビールをした。そしてその後に「サミアッラーフ・リマン・ハミダフ（アッラーはかれを称える者をお聞きになる）」と言い、それからサジダする前に「ラッバナー・ワ・ラカルハムド（我らの主よ、あなたにこそ賞賛はあります）」と唱えた。サジダへと移る時にも、「アッラーフ・アクバル（アッラーは偉大なり）」と言い、サジダから頭を起こす時にもタクビールをした。またサジダする時にはタクビールし、そこから頭を起こす時にもタクビールをした。座った状態から２ラクア目のために立ち上がる時にもタクビールをし、サラーを終えるまで全てのラクアにおいてそのようにした。そして終えた後に、こう言った：「私の魂がその手に委ねられたお方に誓って。私はあなた方の内で、最もアッラーの使徒（アッラーからの祝福と平安あれ）のサラーに近い者である。これが、現世を立ち去る時まで彼がやっていたサラーなのだ。」",
    "explanation": "アブー・フライラ（アッラーのご満悦あれ）からは、彼が預言者（アッラーからの祝福と平安あれ）のサラーのやり方について、このようにしたことが伝わっている：彼がサラーに立つ時には、サラー開始のタクビールをした。それからルクーゥへと移る時、サジダする時、サジダから頭を起こす時、二度目のサジダをする時、そこから頭を起こす時にもタクビールをした。また、３ラクアまたは４ラクアあるサラーの時には、最初のタシャッフドのための座った状態から次のラクアのために立ち上がる時にもタクビールをした。サラーを終えるまで全てのラクアにおいて、そのようにした。また、ルクーゥから起立姿勢に戻る時には「サミアッラーフ・リマン・ハミダフ（アッラーはかれを称える者をお聞きになる）」と言い、その後起立姿勢になった時には「ラッバナー・ワ・ラカルハムド（我らの主よ、あなたにこそ賞賛はあります）」と唱えた。\n\nそれからアブー・フライラはサラーを終えた後、こう言った：「私の魂がその手に委ねられたお方に誓って。私はあなた方の内で、最もアッラーの使徒（アッラーからの祝福と平安あれ）のサラーに近い者である。これが、現世を立ち去る時まで彼がやっていたサラーなのだ。」",
    "hints": [
          "タクビールはルクーゥの時以外、身体が上がったり下がったりする度に行う。ルクーゥの時には、「サミアッラーフ・リマン・ハミダフ（アッラーはかれを称える者をお聞きになる）」と言う。",
          "預言者（アッラーからの祝福と平安あれ）の模倣とスンナの固守における、教友たちの熱心さ。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65099: {
    "category_id": 1,
    "category": "クルアーンとその諸学",
    "title": "アッラーは仰った：「サラー（礼拝）はわれと、わが僕の間で２つに分けられた。そしてわが僕には、彼が願うものがある",
    "hadeeth": "アブー・フライラ（彼にアッラーのご満悦あれ）は言った：「私はアッラーの使徒（彼にアッラーからの平安と祝福あれ）がこう言うのを聞いた： アッラーは仰った：「サラー（礼拝）はわれと、わが僕の間で２つに分けられた。そしてわが僕には、彼が願うものがある。僕が“アルハムドゥリッラーヒ・ラッビル・アーラミーン（全創造物の主、アッラーに称賛あれ）”と唱えれば、アッラーは仰る：“わが僕はわれを称賛した。”そして彼が“アッラフマーニ・ッラヒーム（慈悲あまねく慈愛深きお方）”と唱えれば、こう仰る：“わが僕はわれを讃えた。”そして彼が“マーリキ・ヤウミッディーン（報いの日の支配者）”と唱えれば、こう仰る：“わが僕はわれを褒め称えた。”または別にこう仰る：“わが僕はわれに委任した。”そして彼が“イイヤーカ・ナァブドゥ・ワ・イイヤーカ・ナスタイーン（私たちはあなただけを崇拝し、あなただけにお力添えを乞います）”と唱えれば、こう仰る：“これはわれと、わが僕の間のこと。わが僕には彼が願うものがある。”そして彼が“イヒディナッ・スィラータル・ムスタキーム、スィラータ・ッラズィーナ・アンアムタ・アライヒム、ガイリル・マグドゥービ・アライヒム・ワラッダーッリーン（私たちを、まっすぐな道へとお導きください。あなたが恩恵をお授けになった者たち、つまり、（あなたの）お怒りを受けるでもなく、迷うでもない者たちの道へ）”と唱えれば、こう仰る：“これはわれと、わが僕の間のこと。わが僕には彼が願うものがある。”」",
    "explanation": "預言者（彼にアッラーからの平安と祝福あれ）は、アッラーが聖なるハディースの中で、このように仰ったと伝えている：「サラーの中で、アル＝ファーティハ章はわれとわが僕の間で、2つに分けられた。われに半分、そして彼にもう半分という風に。」\n\n最初の半分は、アッラーを称賛し、讃え、褒め称えることであり、それに対してわれは彼に最善のご褒美をつかわす。\n\nもう半分は、身を低めて祈ることであり、われはそのことでかれに応じ、願うものを与えてやる。\n\nサラーをする者が「アルハムドゥリッラーヒ・ラッビル・アーラミーン（全創造物の主、アッラーに称賛あれ）」と唱えれば、アッラーは仰る：“わが僕はわれを称賛した。”そして彼が“アッラフマーニ・ッラヒーム（慈悲あまねく慈愛深きお方）”と唱えれば、アッラーは仰る：“わが僕はわれを讃えた。”つまり、被造物に対するあらゆる恩恵について、われを讃えた。そして彼が“マーリキ・ヤウミッディーン（報いの日の支配者）”と唱えれば、こう仰る：“わが僕はわれを褒め称えた。”つまり、われを大いなる栄誉の主として褒め称えた、ということである。\n\nまた、「イイヤーカ・ナァブドゥ、ワ・イイヤーカ・ナスタイーン（私たちはあなただけを崇拝し、あなただけにお力添えを乞います）」と唱えれば、アッラーは仰る：”これはわれと、わがしもべの間のことである。\n”\n\nつまり、このアーヤの前半部分「イイヤーカ・ナァブドゥ（私たちはあなただけを崇拝し）」はアッラーへのものである。アッラーの神性を認め、それに対して崇拝行為で応じることであり、これによってアッラーに対するこのアーヤの半分は終わる。\n\nこのアーヤの後半部分「イイヤーカ・ナスタイーン（あなただけにお力添えを乞います）」は僕へのものである。これはアッラーからの援助を乞うものであり、アッラーはそれに応じることを約束している。\n\nまた、「イヒディナッ・スィラータル・ムスタキーム、スィラータ・ッラズィーナ・アンアムタ・アライヒム、ガイリル・マグドゥービ・アライヒム・ワラッダーッリーン（私たちを、まっすぐな道へとお導きください。あなたが恩恵をお授けになった者たち、つまり、（あなたの）お怒りを受けるでもなく、迷うでもない者たちの道へ）」と唱えれば、アッラーはこう仰る：“これはわが僕がわれに縋りつき、祈るものである。わが僕には彼が願うものがあり、われはその祈りに応じた\n。”」",
    "hints": [
          "アル＝ファーティハ章の偉大さ。アッラーはそれを「サラー（礼拝）」と名付けられた。",
          "アッラーの、その僕に対するご配慮の説明。僕がアッラーを称賛し、賛美し、褒め称えることで、彼を称え、彼が願うものを与えると約束されているのである。",
          "この重要なスーラは、以下のような点を含んでいる：アッラーへの賛美。終着点の想起。アッラーへの祈願。かれに対する崇拝行為における真摯さ。まっすぐな道への導きを祈ること。虚妄の道に対する警告。",
          "サラーする者は、アル＝ファーティハ章を読む時にこのハディースを想起することで、サラーにおける畏敬の念を増やすことができる。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65100: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "「最も悪質な泥棒とは、自分のサラーを盗む者である。」人々は言った：「どうやって自分のサラーを盗むのですか？」彼は言った：「ルクーゥとサジダを完遂しないことだ。」",
    "hadeeth": "アブー・フライラ（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は、こう言った： 「最も悪質な泥棒とは、自分のサラーを盗む者である。」人々は言った：「どうやって自分のサラーを盗むのですか？」彼は言った：「ルクーゥとサジダを完遂しないことだ。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、最もひどい盗みをする者が、自分のサラーを盗む者であると説明した。それは、他人の財産を盗む者がそれによって現世で役立てる一方、こちらは自らを報奨から阻んでしまうことによる。人々は言った：「アッラーの使徒よ、どうやって自分のサラーを盗むのですか？」彼は言った：「ルクーゥとサジダを完遂しないことだ。」つまり、ルクーゥやサジダを急いでやり、きちんとした形で行わないことである。",
    "hints": [
          "サラーを、その根幹をおさえ、ゆっくりと畏怖の念をもってきちんと行うことの重要性。",
          "ルクーゥとサジダをきちんと行わない者が泥棒だと表現することは、それが禁止されていることを表すと同時に、人々に対してそれを嫌がらせて回避させる効果もある。",
          "サラーにおいてルクーゥとサジダをきちんと行い、そこで姿勢を安定させることの義務。",
        ],
    "grade": "صحيح",
    "attribution": "رواه ابن حبان",
  },
  65101: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "アッラーの使徒（アッラーからの祝福と平安あれ）は、ルクーゥから背中を戻す時には「サミアッラーフ・リマン・ハミダフ（アッラーはかれを称える者をお聞きになる）",
    "hadeeth": "イブン・アビー・アウファー（アッラーのご満悦あれ）は言った： アッラーの使徒（アッラーからの祝福と平安あれ）は、ルクーゥから背中を戻す時には「サミアッラーフ・リマン・ハミダフ（アッラーはかれを称える者をお聞きになる）、アッラーフンマ・ラッバナー・ラカルハムド（アッラーよ、我らの主よ、あなたにこそ賞賛はあります）。ミルアッサマーワーティ・ワ・ミルアル・アルディ、ワ・ミルア・マー・シゥタ・ミン・シャイイン・バァド（あなたへの讃美は天一杯、大地一杯、そしてあなたの望むその他全ての物を満たします）」と唱えたものだった。",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は、サラーでルクーゥから背中を戻す時、「サミアッラーフ・リマン・ハミダフ」と唱えた。これは、アッラーはかれを称える者をお聞きになり、応じ、その賞賛を受け入れ、それに対して報奨を与えて下さる、ということである。それからアッラーを讃え、「アッラーフンマ・ラッバナー・ラカルハムド。ミルアッサマーワーティ・ワ・ミルアル・アルディ、ワ・ミルア・マー・シゥタ・ミン・シャイイン・バァド」と唱えた。つまり、天一杯、大地一杯、その間のもの、そしてアッラーが望むその他全ての物を満たすほどの賛美でもって称えるということである。",
    "hints": [
          "ルクーゥから頭を上げた際、サラーをする者が言うことを推奨されている言葉の説明。",
          "ルクーゥから戻る時、しっかりと姿勢を安定させることの義務。というのも、しっかりと姿勢が安定していなければ、この言葉を唱えることもできないからである。",
          "この言葉は義務か任意かを問わず、全てのサラーの中で唱えることが可能である。",
        ],
    "grade": "صحيح",
    "attribution": "رواه مسلم",
  },
  65102: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "預言者（アッラーからの祝福と平安あれ）はあらゆる義務のサラーの終わりに、このように言っていた",
    "hadeeth": "アル＝ムギーラ・ブン・シュゥバの筆記人ワッラードは、言った：アル＝ムギーラ・ブン・シュゥバはムアーウィヤに向けて、私にこのように書き取らせた： 預言者（アッラーからの祝福と平安あれ）はあらゆる義務のサラーの終わりに、このように言っていた：「ラー イラーハ イッラッラーフ ワハダフ ラーシャリーカ ラフ､ラフルムルク ワ ラフルハムドゥ ワ フワ アラー クッリシャイイン カディール｡アッラーフンマ ラー マーニアリマーアァタイタ､ワ ラー ムゥティヤリマーマナァタ､ワ ラー ヤンファウ ザルジャッディミンカルジャッドゥ。」（唯一で並ぶ者無きお方､アッラー以外に真に崇拝すべきものはいません｡主権と讃美はかれの御許にあり､かれは全能のお方です｡アッラーよ､あなたが与えたものを禁じる者はなく､あなたが禁じれば他に与える者はおりません｡(現世における)どんな優れた境遇も､あなたの御許での真の幸福を益することはありません。）",
    "explanation": "預言者（アッラーからの祝福と平安あれ）はあらゆる義務のサラーの終わりに、このように言っていた：「ラー イラーハ イッラッラーフ ワハダフ ラーシャリーカ ラフ､ラフルムルク ワ ラフルハムドゥ ワ フワ アラー クッリシャイイン カディール｡アッラーフンマ ラー マーニアリマーアァタイタ､ワ ラー ムゥティヤリマーマナァタ､ワ ラー ヤンファウ ザルジャッディミンカルジャッドゥ。」（唯一で並ぶ者無きお方､アッラー以外に真に崇拝すべきものはいません｡主権と讃美はかれの御許にあり､かれは全能のお方です｡アッラーよ､あなたが与えたものを禁じる者はなく､あなたが禁じれば他に与える者はおりません｡(現世における)どんな優れた境遇も､あなたの御許での真の幸福を益することはありません。）\n\nこれはつまり、こういう意味です：私は「ラー イラーハ イッラッラーフ」（アッラー以外に真に崇拝すべきものはいません）というタウヒードの言葉を認めます。私は真の崇拝をアッラーにのみ認め、それ以外のものに対する崇拝を否定します。また、真の主権はアッラーにこそ属し、天地の存在による全ての称賛は、アッラーにのみふさわしいことを認めます。アッラーこそが全能であり、アッラーが与えたり禁じたりすることを定めれば、それに誰も反することはできません。アッラーのもとでは人の財産が役立つことはなく、善行こそが役立ちます。",
    "hints": [
          "タウヒードや称賛の言葉が含まれたこのズィクルの言葉を、各礼拝後に唱えることの勧め。",
          "率先してスンナを踏襲し、広めることの勧め。",
        ],
    "grade": "صحيح",
    "attribution": "متفق عليه",
  },
  65104: {
    "category_id": 4,
    "category": "法学と法源学",
    "title": "預言者（アッラーからの祝福と平安あれ）は２つのサジダの間に、このように言っていた：「ラッビグフィルリー、ラッビグフィルリー。」（わが主よ、私をお赦しください。わが主よ、私をお赦しください。）",
    "hadeeth": "フザイファ（アッラーのご満悦あれ）によれば、 預言者（アッラーからの祝福と平安あれ）は２つのサジダの間に、このように言っていた：「ラッビグフィルリー、ラッビグフィルリー。」（わが主よ、私をお赦しください。わが主よ、私をお赦しください。）",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は２つのサジダの間で座位姿勢にある時、このように繰り返し言っていた：「ラッビグフィルリー、ラッビグフィルリー。」（わが主よ、私をお赦しください。わが主よ、私をお赦しください。）\n\n「ラッビグフィルリー」には、僕がその主に罪の抹消と、自らの落ち度を覆ってくれることを乞う祈りの意味が含まれている。",
    "hints": [
          "義務か任意かを問わず、サラーの中の２つのサジダの間に、この祈願を唱えるという教示。",
          "「ラッビグフィルリー」と繰り返し唱えることの勧め。少なくとも一度は唱えることの義務性。",
        ],
    "grade": "صحيح",
    "attribution": "رواه أبو داود والنسائي وابن ماجه وأحمد",
  },
  65105: {
    "category_id": 3,
    "category": "神学",
    "title": "それはヒンザブというシャイターンである。その者を感じたら、アッラーにその者からのご加護を乞うのだ。そしてあなたの左側に３回、唾を飛ばすが良い。",
    "hadeeth": "ウスマーン・ブン・アビー・アル＝アース（アッラーのご満悦あれ）によれば、 彼は預言者（アッラーからの祝福と平安あれ）のもとにやって来て、こう言った：「アッラーの使徒よ、シャイターンが私を、私のサラーと私の読誦から阻み、私に疑念を抱かせるのです。」アッラーの使徒（アッラーからの祝福と平安あれ）は言った：「それはヒンザブというシャイターンである。その者を感じたら、アッラーにその者からのご加護を乞うのだ。そしてあなたの左側に３回、唾を飛ばすが良い。」彼（ウスマーン）は言った：「それで私はそのようにした。こうしてアッラーは私からその者を追いやってくれたのである。」",
