    "hadeeth": "アブドッラー・ブン・アムル（アッラーのご満悦あれ）によれば、アッラーの使徒（アッラーからの祝福と平安あれ）は言った： 「4つのことが該当した者は完全なニファークに陥る者である。その内のいずれの特徴でもあてはまる者は、それを放棄するまでニファークの特徴を備えているのである:話せば嘘をつき、契約すれば裏切り、約束すれば破り、議論すれば激昂する。」",
    "explanation": "預言者（アッラーからの祝福と平安あれ）は4つの特徴に注意した。それが全て揃ってしまったムスリムは、ニファークに陥っている者に酷似してしまうことになる。これは、これらの特徴が優勢になった者のことであり、時にそれが現れるような者については、この限りではない。これらの特徴とは、以下の通りである:\n\n1.話せば嘘をつくこと。言葉が正直ではないこと。\n\n2.契約すればそれを遵守せず、相手を裏切ること。\n\n3.約束すればそれを守らず、破ること。\n\n4.誰かと議論すれば激しく争い、真理から逸れ、相手に反論し否定するためにずるい手段を用い、虚妄や嘘の言葉を使うこと。\n\nニファークとは、内面にあるものとは違うものを外面に表すことである。これらの特徴が揃った者に、この意味が該当する。話、約束、委託、議論、契約といったことにおけるニファークは、イスラームにおける偽の信仰、つまり不信仰を秘めつつイスラームを標榜することではない。これらの特徴が一つでもあてはまった者には、それを放棄するまでニファークの特徴が該当していることになる。",
