          "アル＝ガザーリーは言う：「宗教の基礎は３つの物事に絞られる：言葉、行い、意図である。それで言葉における誤りとして嘘が、行いにおける誤りとして裏切りが、意図における誤りとして約束の破棄が挙げられている。約束の破棄は、約束と同時にその意図が伴った場合のみに問題が生じる。それを遂行する意思がありつつも、それを妨げる何らかの要因が出現したり、または別の意見が生じたという場合、それはニファークとは見なされない。」",
